/* Wyjaśnienia i przykłady autorskie do schematu COBIT 5. */
window.OPISY={"a1":{"kw":["struktury ramowe","zasady, polityki","polityk"],"pulapka":"Na egzaminie „Zasady, Polityki i Struktury ramowe” (podręcznik: Zasady, polityki i metodyki); polityki realizuje się przede wszystkim przez praktyki i działania procesów.","zycie":"Rodzina uznaje wzajemny szacunek za zasadę. Polityka mówi, że po posiłku każdy sprząta swoje miejsce, a spójny zestaw reguł określa ich zakres, wyjątki i odpowiedzialności."},"a2":{"kw":["procesy","37 procesów"],"pulapka":"Procesy to tylko jeden z 7 aktywatorów, choć COBIT 5 opisuje ich 37 (5 Ładu i 32 Zarządzania); „37” nie jest odpowiedzią na pytanie o liczbę aktywatorów.","zycie":"Przygotowanie sernika ma uzgodnione praktyki, wejścia, takie jak składniki, oraz oczekiwany wynik. Przepis podpowiada sposób wykonania; sam proces obejmuje rzeczywiste przygotowanie ciasta."},"a3":{"kw":["struktury organizacyjne","decyzj","eskalacj"],"pulapka":"Struktury organizacyjne to kluczowe jednostki decyzyjne; ich produktem pracy są decyzje, a dobre praktyki to m.in. zasady operacyjne, zakres kontroli i procedury eskalacji.","zycie":"W rodzinie rada domowa decyduje o wakacjach, a mama sama o obiedzie; wiadomo, kto o czym rozstrzyga."},"a4":{"kw":["kultura, etyka","zachowani","obwiniania"],"pulapka":"Kultura, Etyka i Zachowanie są często niedoceniane. Zachowania i zachęty mogą wspierać albo osłabiać stosowanie polityk oraz procesów bezpieczeństwa.","zycie":"W drużynie nikt nie musi czytać regulaminu, żeby wiedzieć, że po przegranym meczu nie zrzuca się winy na bramkarza."},"a5":{"kw":["informacj","zasob"],"pulapka":"Informacja to aktywator i jednocześnie zasób (Rysunek 12); polityki też są informacją, więc dobre praktyki dotyczące informacji obejmują również polityki.","zycie":"Lista zakupów, paragony i stan konta: bez nich nie wiesz, co kupić i czy cię na to stać."},"a6":{"kw":["usługi, infrastruktura i aplikacje","zdolności usługow","poziomy usług"],"pulapka":"Usługi, Infrastruktura i Aplikacje zapewniają zdolności usługowe. Dobre praktyki obejmują zasady i modele architektury, punkty widzenia oraz repozytorium. Zasady operacyjne są osobno omówione jako praktyka struktur organizacyjnych.","zycie":"Prąd, woda, internet i lodówka: sprzęt i usługi, bez których w domu nikt nie ugotuje obiadu ani nie odrobi lekcji."},"a7":{"kw":["ludzie, umiejętności","kategorie umiejętności","rotacj"],"pulapka":"Ludzie, Umiejętności i Kompetencje to zasób; jego praktyką są kategorie umiejętności (Rysunek 39), a rotacja i dostępność personelu to cele jakości kontekstowej.","zycie":"Do budowy domu potrzebujesz murarza, elektryka i hydraulika z uprawnieniami, a nie tylko projektu i cegieł."},"akt":{"kw":["siedem kategorii","aktywator","rysunek 12"],"pulapka":"Kategorii aktywatorów jest 7 (5 to zasady, 4 to wymiary, 37 to procesy); trzy z nich są też zasobami: Informacja; Usługi, Infrastruktura i Aplikacje; Ludzie, Umiejętności i Kompetencje.","zycie":"Restauracja potrzebuje reguł, sposobu przygotowania posiłków, ról decyzyjnych, odpowiedniej kultury, informacji, sprzętu i kompetentnych ludzi. Elementy wspierają się wzajemnie; brak jednego może osłabić pozostałe."},"bk_3pytania":{"kw":["kto odnosi korzyści","kto ponosi ryzyko","jakie zasoby"],"pulapka":"Trzy pytania to: kto odnosi korzyści, kto ponosi ryzyko, jakie zasoby są wymagane; pytanie „kto jest rozliczany” pochodzi z RACI, nie z tej listy.","zycie":"Przed kupnem psa rodzina pyta: kto się ucieszy, kto będzie sprzątał, gdy coś pójdzie źle, i ile to kosztuje czasu i pieniędzy."},"bk_a1_cykl":{"kw":["cykl życia polityki","aktualn","polityk"],"pulapka":"Kluczowy aspekt cyklu życia polityk to aktualność: czy i kiedy się je aktualizuje, jak informuje się pracowników o zmianach, dostęp do najnowszej wersji i archiwizacja starych.","zycie":"Domowy regulamin trzeba co jakiś czas odświeżyć, powiedzieć wszystkim o zmianie i zdjąć starą kartkę z lodówki."},"bk_a1_def":{"kw":["zasady, polityki","polityk","metodyk"],"pulapka":"Zasady, polityki i metodyki przekładają pożądane zachowania na praktyczne wytyczne codziennego zarządzania; nie myl ich z aktywatorem Kultura, etyka i zachowanie.","zycie":"Polityka porządku mówi, że po jedzeniu każdy sprząta swoje miejsce. Rozwija ogólną zasadę wzajemnego szacunku i wspólnej odpowiedzialności."},"bk_a1_dp_4el":{"kw":["zakres i ważność","obsługa wyjątków","konsekwencje nieprzestrzegania"],"pulapka":"Struktura polityk opisuje 4 elementy: zakres i ważność, konsekwencje nieprzestrzegania, obsługę wyjątków oraz kontrolę zgodności; cel biznesowy nie jest jednym z nich.","zycie":"Regulamin wypożyczalni rowerów mówi, kogo dotyczy i do kiedy, jaka jest kara za spóźnienie, jak dostać wyjątek i kto sprawdza rowery."},"bk_a1_dp_hier":{"kw":["hierarch","struktura ramowa polityk","polityk"],"pulapka":"Dobra praktyka: polityki są częścią hierarchicznej struktury ramowej Ładu i Zarządzania, każda ma swoje miejsce i wyraźnie odnosi się do podstawowych zasad.","zycie":"W szkole statut jest na górze, a regulaminy stołówki i biblioteki pod nim; każdy z nich musi się do statutu odwoływać."},"bk_a1_dp_ryzyko":{"kw":["apetyt na ryzyko","restrykcyjn"],"pulapka":"Organizacja niechętna ryzyku ma bardziej restrykcyjne polityki niż skłonna do ryzyka; polityki odzwierciedlają apetyt na ryzyko i trzeba je regularnie aktualizować.","zycie":"Ostrożni rodzice wprowadzają surowe zasady wychodzenia z domu, a odważni pozwalają na więcej. Reguły pokazują, ile ryzyka akceptują."},"bk_a1_inter":{"kw":["interesariusze","polityk"],"pulapka":"Interesariusze polityk mają dwojakie interesy: jedni polityki definiują, inni muszą zapewnić zgodność z nimi; są wśród nich też zewnętrzni, np. dostawcy, klienci i regulatorzy.","zycie":"Regulamin basenu piszą zarząd i ratownicy, a przestrzegać go muszą pływacy. Jedni ustalają reguły, drudzy się do nich stosują."},"bk_a1_kom":{"kw":["zasady, polityki","polityk","komunik"],"pulapka":"Zasady i polityki komunikują wytyczne organu Ładu oraz kierownictwa, a praktyki i działania procesów przekładają je na wykonanie. Procesy także mogą obejmować czynności komunikowania; nie jest to wyłączny kanał jednej kategorii aktywatora.","zycie":"Kartka na lodówce „W tym domu mówimy prawdę i sprzątamy po sobie” przekazuje wszystkim domownikom, czego oczekują rodzice."},"bk_a1_rel":{"kw":["polityk","relacj","aktywator"],"pulapka":"Najważniejszym środkiem realizacji polityk są praktyki i działania procesów; struktury definiują i wdrażają polityki, a polityki jako informacja podlegają dobrym praktykom aktywatora Informacja.","zycie":"Regulamin klubu wynika z jego wartości, realizuje się go na treningach, pilnuje go zarząd, a sam regulamin to też informacja do przechowywania."},"bk_a2_cykl":{"kw":["cykl życia procesu","cykl życia"],"pulapka":"Cykl życia procesu: definiowanie, tworzenie, obsługa, monitorowanie i dostosowanie/aktualizacja lub wycofanie; typowe praktyki ISO/IEC 15504 pomagają go optymalizować.","zycie":"Szkolny turniej: ktoś go wymyśla, organizuje, prowadzi, obserwuje, poprawia zasady na kolejny rok, a w końcu z niego rezygnuje."},"bk_a2_def":{"kw":["proces","praktyk i działań","uporządkowan"],"pulapka":"Proces obejmuje praktyki i działania, które przetwarzają wejścia w wyniki wspierające cele związane z IT. Sama nazwa pojedynczej czynności nie opisuje jeszcze przeznaczenia, wejść, praktyk i wyników całego procesu.","zycie":"Przepis na pierogi: kolejne kroki od zagniatania ciasta do gotowania, które dają gotowe danie."},"bk_a2_inter":{"kw":["raci","wolontariusz","interesariusze"],"pulapka":"Interesariuszy procesów i ich odpowiedzialność ujmuje diagram RACI; wolontariusze to interesariusze wewnętrzni, a regulatorzy, partnerzy i udziałowcy – zewnętrzni.","zycie":"Przy organizacji wesela są goście i dostawcy z zewnątrz oraz rodzina; każdy ma rolę: kto robi, kto decyduje, kogo pytać, kogo tylko zawiadomić."},"bk_a2_potencjal":{"kw":["poziom zdolności","zdolności procesu","15504"],"pulapka":"Poziom zdolności procesu (podręcznik: potencjał) mierzy zarówno osiąganie celów, jak i stosowanie dobrych praktyk; opiera się na ISO/IEC 15504, nie na modelu dojrzałości COBIT 4.1.","zycie":"Ocena kierowcy mówi i o tym, czy dojechał na czas, i o tym, czy jechał zgodnie z dobrymi zasadami jazdy."},"bk_a2_poziomy":{"kw":["szczegółowe działania","praktyki","działania"],"pulapka":"Szczegółowość rośnie: praktyki → działania → szczegółowe działania; praktyki są najogólniejsze, a szczegółowe działania pochodzą z innych standardów lub produktów COBIT.","zycie":"Przy organizacji posiłku ogólna praktyka wymaga ustalenia potrzeb gości. Rozwijają ją działania, np. zebranie informacji o liczbie osób, oraz szczegółowe kroki dostosowane do lokalu."},"bk_a2_rel":{"kw":["raci","relacj","kultur"],"pulapka":"Kultura i zachowanie decydują o skuteczności procesów; procesy wymagają informacji i ją dostarczają, a struktury i role przypisuje się przez diagram RACI.","zycie":"Gotowanie obiadu wymaga składników, kucharza z rolą, kuchenki, innych czynności jak zakupy, domowych reguł i chęci domowników."},"bk_a3_cele":{"kw":["umocowani","zasady operacyjne","decyzj"],"pulapka":"Cele struktury to właściwe umocowanie, dobrze zdefiniowane zasady operacyjne i inne dobre praktyki; wynikiem struktury są działania i decyzje, czyli jej produkty pracy.","zycie":"Komitet osiedlowy ma upoważnienie wspólnoty i spisany regulamin obrad, a jego efektem są konkretne decyzje, np. o naprawie dachu."},"bk_a3_def":{"kw":["struktury organizacyjne","decyzj"],"pulapka":"Struktury organizacyjne to kluczowe jednostki decyzyjne; nie myl ich z aktywatorem Ludzie, umiejętności i kompetencje, który dotyczy osób i ich kompetencji.","zycie":"Rada rodziny albo zarząd klubu: grupa, która podejmuje kluczowe decyzje."},"bk_a3_inter":{"kw":["struktury organizacyjne","interesariusz","decyzj"],"pulapka":"Interesariusze struktur to członkowie, inne struktury, organizacje, klienci, dostawcy i regulatorzy; ich role to podejmowanie decyzji, wywieranie wpływu i doradztwo, nie tylko głosowanie.","zycie":"Na zebraniu rady rodziców jedni decydują, inni namawiają, a jeszcze inni tylko doradzają; przychodzą też nauczyciele i dyrekcja."},"bk_a3_mandat":{"kw":["mandat","cykl życia struktury organizacyjnej"],"pulapka":"Mandat (powód i cel istnienia struktury) trzeba zdefiniować w chwili jej utworzenia, na początku cyklu życia; zasady operacyjne to osobna dobra praktyka.","zycie":"Komitet organizacyjny festynu powstaje z jasnym zadaniem, działa, zmienia skład i po festynie się rozwiązuje."},"bk_a3_rel":{"kw":["raci","mandat","zasady operacyjne"],"pulapka":"Mandat i zasady operacyjne struktur określa struktura polityk, skład odzwierciedla umiejętności, kultura decyduje o skuteczności, a RACI łączy struktury z praktykami procesów.","zycie":"Rada drużyny działa, gdy wiadomo, kto za co odpowiada, ludzie grają fair, członkowie znają się na rzeczy, a regulamin klubu określa jej zadania."},"bk_a3_sklad":{"kw":["skład","zakres kontroli","poziom uprawnień"],"pulapka":"Skład to dobra praktyka struktur: członkowie będący interesariuszami wewnętrznymi lub zewnętrznymi; nie myl go z zakresem kontroli (granice uprawnień) ani poziomem uprawnień.","zycie":"W jury konkursu na najładniejszy ogród zasiadają mieszkańcy osiedla i zaproszony ogrodnik z zewnątrz."},"bk_a3_wewy":{"kw":["decyzj","struktury organizacyjne"],"pulapka":"Wejściem struktury są zwykle informacje, a wyjściem decyzje, inne informacje lub żądania dodatkowych danych; decyzje to typowy produkt pracy struktur organizacyjnych.","zycie":"Rada rodzinna dostaje informacje o rachunkach i podejmuje decyzję albo prosi o więcej danych, np. o trzy oferty na nowy dach."},"bk_a4_cykl":{"kw":["kultur","czempion","zachęt"],"pulapka":"Cykl życia kultury zaczyna się od istniejącej kultury: organizacja identyfikuje wymagane zmiany i wdraża je narzędziami z dobrych praktyk, np. komunikowaniem, czempionami, zachętami.","zycie":"Rodzina, która chce mniej na siebie krzyczeć, zaczyna od tego, jak jest dziś, ustala, co zmienić, i krok po kroku wprowadza nowe nawyki."},"bk_a4_def":{"kw":["kultura, etyka","zachowani","niedocenian"],"pulapka":"Kultura, etyka i zachowanie to często niedoceniany czynnik sukcesu nadzoru i zarządzania; nie jest aktywatorem-zasobem.","zycie":"W rodzinie, w której wszyscy się szanują i mówią prawdę, działają nawet najprostsze zasady."},"bk_a4_def2":{"kw":["kultura, etyka","zachowa"],"pulapka":"Kultura, etyka i zachowanie dotyczą indywidualnych oraz zbiorowych wzorców zachowania. Zasady i polityki opisują oraz komunikują oczekiwane wytyczne, lecz ich samo istnienie nie dowodzi określonej kultury.","zycie":"To, jak cała rodzina zachowuje się przy stole i jak każdy z osobna, tworzy klimat domu, niezależnie od spisanych reguł."},"bk_a4_inter":{"kw":["interesariusz","kultura, etyka","hr"],"pulapka":"Wśród interesariuszy kultury jedni definiują i egzekwują wzorce zachowań (np. dział prawny, ryzyko, HR, rady wynagrodzeń), inni muszą ich przestrzegać; regulatorzy i audytorzy zewnętrzni są interesariuszami zewnętrznymi.","zycie":"W szkole dyrekcja i pedagog ustalają zasady zachowania, uczniowie mają się do nich stosować, a z zewnątrz pilnuje kuratorium."},"bk_a4_rel":{"kw":["kultur","zachowa","polityk"],"pulapka":"Skuteczność procesów i struktur silnie zależy od zachowania ludzi i kultury. Zasady oraz polityki pomagają komunikować wartości i pożądane zachowania, ale potrzebne jest ich rzeczywiste stosowanie.","zycie":"Najlepszy grafik sprzątania i najmądrzejsza narada domowa nic nie dadzą, jeśli domownicy po prostu nie chcą sprzątać."},"bk_a4_zachety":{"kw":["zachęty i nagrody","zachęt","wynagradzan"],"pulapka":"Zachęty i nagrody to dobra praktyka aktywatora Kultura; istnieje wyraźny związek między zachowaniem pracowników a systemem wynagradzania działu HR, co pokazuje Przykład 11.","zycie":"Gdy dziecko dostaje nagrodę wyłącznie za szybkość odrobienia lekcji, może zacząć pomijać staranność. Sposób nagradzania może wzmacniać zachowanie inne od oczekiwanego."},"bk_a5_def":{"kw":["informacj","produkt"],"pulapka":"Informacja obejmuje wszystkie informacje wytwarzane i używane w przedsiębiorstwie; na poziomie operacyjnym często jest jego kluczowym produktem.","zycie":"Dla biura podróży gotowy plan wycieczki to towar, który sprzedaje; informacja jest tu produktem."},"bk_a5_zakres":{"kw":["nieustrukturyzowan","zautomatyzowan","informacj"],"pulapka":"Aktywator Informacja obejmuje wszystkie istotne informacje, nie tylko zautomatyzowane: ustrukturyzowane lub nie, sformalizowane lub nie; dotyczy głównie fazy informacji, ale ujmuje też dane i wiedzę.","zycie":"Wiedza rodziny to nie tylko pliki w komputerze, ale też karteczki na lodówce, przepisy babci w zeszycie i to, co mama pamięta."},"bk_a6_cele":{"kw":["poziomy usług","ekonomiczn"],"pulapka":"Cele zdolności usługowej to usługi i poziomy usług najbardziej ekonomiczne dla organizacji oraz ich wkład w skutecznie wspierane procesy biznesowe, a nie najwyższe możliwe parametry.","zycie":"Rodzina wybiera abonament na telewizję i internet, który wystarczy do nauki i pracy za rozsądną cenę, a nie najdroższy dostępny."},"bk_a6_def":{"kw":["usługi, infrastruktura","infrastruktur","aplikacj"],"pulapka":"Usługi, infrastruktura i aplikacje dają możliwości przetwarzania oraz usługi IT; to aktywator-zasób, a nie wyłącznie „sprzęt”.","zycie":"Prąd, woda, internet i sprzęty w domu dają możliwość gotowania, prania i oglądania filmów."},"bk_a6_inter":{"kw":["outsourc","dostawc","użytkowni"],"pulapka":"Dostawcami usług mogą być wewnętrzne działy IT, kierownicy operacji i dostawcy z outsourcingu, a użytkownikami wewnętrzni (biznes) i zewnętrzni (partnerzy, klienci, dostawcy).","zycie":"Ciepło w bloku dostarcza miejska ciepłownia albo własna kotłownia, a korzystają z niego mieszkańcy, sklep na parterze i goście."},"bk_a6_rel":{"kw":["zdolności usługow","kultur"],"pulapka":"Informacja sama jest jedną ze zdolności usługowych, kultura ukierunkowana na usługi wymaga aktywatora Kultura, a zdolności usługowe bywają wejściami lub wyjściami praktyk zarządzania.","zycie":"Sklep z dobrym sprzętem i kasą nie zadowoli klientów, jeśli sprzedawcy nie lubią obsługiwać ludzi; liczy się też nastawienie na klienta."},"bk_a6_zewn":{"kw":["togaf","itil","model referencyjny"],"pulapka":"Zewnętrzne praktyki zdolności usługowej: TOGAF daje modele referencyjne (techniczny i zintegrowanej infrastruktury), a ITIL wytyczne projektowania i świadczenia usług; nie odwrotnie.","zycie":"Zamiast projektować dom od zera, budowlaniec bierze gotowy katalog projektów i poradnik wykończeń, więc kończy szybciej."},"bk_a7_cele":{"kw":["wykształcenie i kwalifikacje","rotacj","umiejętności behawioralne"],"pulapka":"Cele ludzi to wykształcenie i kwalifikacje, umiejętności techniczne, doświadczenie, wiedza, umiejętności behawioralne oraz dostępność personelu i wskaźnik rotacji; rotacja też jest celem.","zycie":"Szukając opiekunki do dziecka, patrzysz na wykształcenie, doświadczenie i podejście do dzieci, ale też czy ma czas i czy nie zmienia pracy co miesiąc."},"bk_a7_cykl":{"kw":["cykl życia umiejętności","rekrutac","outsourc"],"pulapka":"Cykl życia umiejętności: planowanie, rozwój (szkolenia) lub pozyskanie (rekrutacja), wdrożenie w rolach i pozbycie się, np. po automatyzacji lub outsourcingu; bazę umiejętności ocenia się okresowo.","zycie":"Rodzina planuje, kto nauczy się gotować, wysyła na kurs albo zatrudnia kucharkę, przydziela obowiązki i co roku sprawdza, czego jeszcze brakuje."},"bk_a7_def":{"kw":["umiejętnoś","kompetencj","ludzie"],"pulapka":"Ludzie, umiejętności i kompetencje są potrzebne do realizacji działań, właściwych decyzji i działań naprawczych; nie myl ich ze strukturami organizacyjnymi.","zycie":"Do naprawy kranu potrzebny jest ktoś, kto umie to zrobić i wie, co robić, gdy coś pójdzie nie tak."},"bk_a7_inter":{"kw":["umiejętnoś","interesariusz","rekrutac"],"pulapka":"Każda rola interesariusza (kierownicy, kierownicy projektów, partnerzy, konkurenci, rekruterzy, szkoleniowcy, programiści, specjaliści IT) wymaga osobnego zestawu umiejętności; konkurenci też są na tej liście.","zycie":"W drużynie bramkarz, napastnik, trener i fizjoterapeuta potrzebują zupełnie innych umiejętności, choć grają do jednej bramki."},"bk_a7_rel":{"kw":["umiejętności behawioralne","definicje umiejętności","umiejętnoś"],"pulapka":"Procesy i decyzje struktur wymagają umiejętności, umiejętności behawioralne łączą się z kulturą i etyką, a definicje umiejętności to informacje podlegające dobrym praktykom aktywatora Informacja.","zycie":"Trener może mieć świetny plan treningu, ale bez umiejętnych zawodników nic z tego; liczy się też ich charakter i to, czy grają fair."},"bk_akt_def_ogol":{"kw":["indywidualn","zbiorow","aktywator"],"pulapka":"Aktywatory decydują o działaniu Ładu i Zarządzania indywidualnie i zbiorowo; zaniedbanie jednego może zepsuć całość.","zycie":"Obiad wychodzi dobrze tylko wtedy, gdy przepis, składniki, kucharz i kuchenka działają, każde osobno i wszystkie razem."},"bk_akt_system":{"kw":["wzajemnie powiązan","systemow","aktywator"],"pulapka":"Przedsiębiorstwo zawsze rozważa wzajemnie powiązany zbiór aktywatorów; takie nastawienie wymaga wsparcia kierownictwa najwyższego szczebla.","zycie":"Orkiestra gra dobrze, gdy wszystkie instrumenty grają razem, a dyrygent słyszy całość."},"bk_akt_system_decyzje":{"kw":["całościow","wszystkich","aktywator"],"pulapka":"Dobre decyzje wymagają analizy wszystkich wzajemnie powiązanych aktywatorów; skupienie się na jednym, np. tylko na procesach, przeczy podejściu całościowemu.","zycie":"Przed kupnem psa rodzina myśli o mieszkaniu, czasie, pieniądzach i nawykach wszystkich, a nie tylko o rasie."},"bk_akt_wejscie":{"kw":["dane wejściow","wejści","aktywator"],"pulapka":"Aktywator jest w pełni efektywny tylko z wejściami od innych: procesy wymagają informacji, a struktury organizacyjne umiejętności i zachowania.","zycie":"Kucharz potrzebuje zakupów od domowników, a domownicy listy zakupów od kucharza; jedno bez drugiego nie działa."},"bk_akt_wynik":{"kw":["wynik","aktywator"],"pulapka":"Aktywator dostarcza wyniki innym: procesy dają informacje, a umiejętności i zachowanie zwiększają efektywność procesów; kierunek tej zależności bywa odwracany.","zycie":"Kucharz daje domownikom gotowy obiad, a najedzeni domownicy chętniej i sprawniej sprzątają kuchnię."},"bk_akt_z_kaskady":{"kw":["kaskad","cele związane z it","aktywator"],"pulapka":"Aktywatory opierają się na kaskadzie celów: to cele związane z IT określają, co mają realizować aktywatory, a nie odwrotnie.","zycie":"Cel rodziny „jeść zdrowiej” mówi, czego oczekujesz od lodówki, przepisów i zakupów."},"bk_akt_zasoby":{"kw":["zasob","informacj","ludzie"],"pulapka":"Na Rysunku 12 jako zasoby wyróżniono trzy kategorie: Informacja (5); Usługi, infrastruktura i aplikacje (6); Ludzie, umiejętności i kompetencje (7). To klasyfikacja tego rysunku, a nie ogólne twierdzenie, że organizacja nie może traktować innych rzeczy jako zasobów.","zycie":"Prąd, sprzęt i domownicy pomagają prowadzić dom, a zarazem są zasobami, o które trzeba dbać i których nie wolno marnować."},"bk_aktyw_brak":{"kw":["tworzenia wartości","aktywator","brak"],"pulapka":"Brak zasobów lub aktywatorów może ograniczyć zdolność tworzenia wartości; to element opisu aktywatorów nadzoru, a nie osobna zasada COBIT 5.","zycie":"Bez noża, deski i przepisu nawet dobry kucharz nie zrobi obiadu na czas."},"bk_aktyw_def":{"kw":["aktywator","siedem kategorii","czynnik umożliwiając"],"pulapka":"Aktywator to wszystko, co pomaga osiągnąć cele przedsiębiorstwa, a nie tylko procesy czy narzędzia IT; kategorii jest siedem (Rysunek 12).","zycie":"Do upieczenia ciasta potrzebujesz przepisu, piekarnika, składników, umiejętności i chęci; wszystko, co pomaga osiągnąć cel, to „aktywator”."},"bk_aktyw_nadzoru":{"kw":["aktywatory ładu","zasoby organizacyjne","czynniki umożliwiające"],"pulapka":"Aktywatory nadzoru to zasoby organizacyjne (metodyki, zasady, struktury, procesy, praktyki) oraz zasoby przedsiębiorstwa (usługi, ludzie, informacja).","zycie":"Żeby rodzina dobrze decydowała, potrzebuje domowych zasad i wspólnych narad, ale też ludzi, informacji o budżecie i sprzętu."},"bk_arch_3":{"kw":["architektura referencyjna","architektura docelowa","architektura przejściowa"],"pulapka":"Architektura referencyjna (bazowa) opisuje stan obecny, docelowa – przyszły, a przejściowa – etapy dochodzenia; „referencyjna” nie znaczy tu wzorcowa ani docelowa.","zycie":"Przy przebudowie domu masz plan obecnego układu, plany kolejnych etapów prac i projekt wymarzonego domu na końcu."},"bk_arch_repo":{"kw":["repozytorium","model referencyjny"],"pulapka":"Repozytorium architektury przechowuje wyniki prac architektury (pryncypia, normy, modele referencyjne) i definiuje elementy usług: aplikacje, infrastrukturę techniczną i fizyczną.","zycie":"Segregator działkowca: zasady ogrodu, plan grządek, spis narzędzi i rozprowadzenie wody. Wszystko o działce w jednym miejscu."},"bk_arch_widoki":{"kw":["punkty widzenia","katalog","macierz"],"pulapka":"Punkty widzenia architektury to modele, katalogi i macierze opisujące architekturę bazową, docelową lub przejściową dla różnych interesariuszy; to nie pryncypia architektury.","zycie":"Plan mieszkania można pokazać jako rysunek pokoi dla rodziny, listę gniazdek dla elektryka i tabelę rur dla hydraulika; każdy widzi to, czego potrzebuje."},"bk_architektura_zywa":{"kw":["architektur","baza wiedzy","produkt"],"pulapka":"Architektura produktów COBIT 5 to żywy dokument: nowe produkty powstają z bazy wiedzy COBIT 5; nie jest zamkniętym, stałym zestawem publikacji.","zycie":"Encyklopedia internetowa: ciągle dopisuje się nowe hasła, więc nigdy nie jest „skończona”."},"bk_baza_wiedzy":{"kw":["baza wiedzy","filtr"],"pulapka":"Baza wiedzy zawiera obecne wytyczne i strukturę dla przyszłych treści; aktywatory działają jako filtr zawartości bazy wiedzy (Rysunek 10).","zycie":"Rodzinna szuflada z przepisami: stare karteczki plus miejsce na nowe, z której wybierasz te pasujące do okazji."},"bk_bsc":{"kw":["bsc","zrównoważon","karta wyników"],"pulapka":"Wymiary BSC to Finanse, Klient, Obszar wewnętrzny oraz Szkolenie i rozwój; „Ryzyko” czy „Zgodność” nie są wymiarami BSC.","zycie":"Drużynę piłkarską ocenia się z czterech stron: kasa klubu, kibice, gra na boisku i rozwój zawodników."},"bk_cap":{"kw":["assessment","potencjał","15504"],"pulapka":"Model potencjału procesu COBIT 5 działa w ramach COBIT Assessment Programme i opiera się na ISO/IEC 15504, a nie na modelu dojrzałości COBIT 4.1.","zycie":"Jak program egzaminów na prawo jazdy: ustalony sposób sprawdzania, a każdego kandydata ocenia się według tej samej skali."},"bk_cel_proc_def":{"kw":["cel procesu","artefakt","zmiana stanu"],"pulapka":"Cel procesu to deklaracja pożądanego rezultatu: artefaktu, istotnej zmiany stanu lub istotnej poprawy zdolności innych procesów; nie jest nim miernik ani praktyka.","zycie":"Cel wyprawy na ryby: złowiona ryba, zmiana stanu (pusta lodówka staje się pełna) albo lepsza umiejętność wędkowania na przyszłość."},"bk_cel_proc_kask":{"kw":["kaskad","cele związane z it","cel procesu"],"pulapka":"Cele procesu wspierają cele związane z IT, a te cele organizacji; kaskada idzie od potrzeb interesariuszy przez cele organizacji i cele IT do celów aktywatorów.","zycie":"Dobrze ugotowany obiad wspiera cel „zdrowa rodzina”, a ten wspiera cel „szczęśliwy dom”. Każdy mały cel podpiera większy."},"bk_cel_proc_kat":{"kw":["cele wewnętrzne","cele kontekstowe","jakość wewnętrzna"],"pulapka":"Kategorie celów procesu to cele wewnętrzne (jakość wewnętrzna), kontekstowe oraz dostępności i bezpieczeństwa; „wydajność” nie jest osobną kategorią.","zycie":"Dobra kosiarka kosi równo, pasuje do twojego ogrodu i zawsze stoi w szopie, a sąsiad bez pytania jej nie weźmie."},"bk_cele_odgornie":{"kw":["odgórn","mierni","kaskad"],"pulapka":"Skuteczny Ład: cele ustala się odgórnie i dopasowuje do zatwierdzonych celów biznesowych, a mierniki – oddolnie, by każdy poziom kierownictwa mógł monitorować postęp; nie odwrotnie.","zycie":"Rodzice ustalają cel domowego budżetu z góry, a każdy domownik prowadzi własny licznik wydatków, które składają się w całość."},"bk_cele_procesu":{"kw":["cele procesu","cel procesu","załącznik c"],"pulapka":"Cele procesu to cele jednego z siedmiu aktywatorów (procesów); mapowanie celów IT na procesy znajduje się w Załączniku C, nie B.","zycie":"Poranne wyjście do szkoły ma swój cel: dziecko na czas, z plecakiem i drugim śniadaniem."},"bk_certyf":{"kw":["isaca","certyfikat"],"pulapka":"Podręcznik COBIT 5 z 2012 r. wymienia cztery certyfikaty ISACA: CGEIT (Ład IT), CISA (audyt), CISM (bezpieczeństwo informacji) i CRISC (ryzyko i kontrola). To historyczny wykaz w tym źródle, nie aktualny katalog wszystkich certyfikacji ISACA.","zycie":"Jak dyplomy dla kucharza, kontrolera sanepidu, ochroniarza i doradcy od ubezpieczeń: każdy uczy się z części tej samej wspólnej księgi wiedzy."},"bk_cobit5_rozwoj":{"kw":["wyznaczni","ponad 15","rozwoju cobit"],"pulapka":"Wyznaczniki rozwoju COBIT 5 to potrzeby rynku i zmiany otoczenia, poparte ponad 15 latami doświadczeń użytkowników, a nie np. przepis nakazujący stosowanie COBIT.","zycie":"Producent wypuszcza nowy model auta, bo kierowcy latami zgłaszali uwagi, a drogi i przepisy się zmieniły."},"bk_cobit_istota":{"kw":["optymaln","równowag","korzyści"],"pulapka":"COBIT 5 równoważy realizację korzyści z optymalizacją ryzyka i zasobów. Sama maksymalizacja korzyści lub minimalizacja kosztów nie opisuje całej tej równowagi; redukcja kosztów może jednak być uzasadnionym celem konkretnej inicjatywy.","zycie":"Remont łazienki: chcesz ładnego efektu (korzyść), bez zalania sąsiadów (ryzyko) i w rozsądnym budżecie oraz czasie (zasoby); trzeba to wyważyć."},"bk_cobit_metodyka":{"kw":["struktura ramowa","zasady, polityki"],"pulapka":"COBIT 5 jest przykładem struktury ramowej, czyli należy do aktywatora Zasady, polityki i struktury ramowe; nie do Informacji ani Procesów.","zycie":"Poradnik o prowadzeniu poradników sam też jest poradnikiem. Tak samo COBIT 5 jest przykładem struktury ramowej, którą opisuje."},"bk_cobit_nienorm":{"kw":["normatywn","nie jest normatywny"],"pulapka":"COBIT 5 nie narzuca identycznego układu procesów każdej firmie. Organizacja definiuje własny zbiór procesów obejmujący wszystkie potrzebne jej cele Ładu i Zarządzania; nie musi mechanicznie tworzyć 37 osobnych jednostek organizacyjnych.","zycie":"Poradnik remontowy mówi, co trzeba zrobić, ale nie każe dzielić pracy na dokładnie takie same etapy."},"bk_cobit_ogolny":{"kw":["not-for-profit","wielkości","sektor"],"pulapka":"COBIT 5 jest ogólny: dla firm każdej wielkości, komercyjnych, not-for-profit i publicznych; odpowiedzi „tylko dla dużych korporacji” lub „tylko dla firm IT” są błędne.","zycie":"Jak ogólny przepis na zupę: ugotuje go babcia w domu, szkolna stołówka i restauracja, a każda dopasuje ilości do siebie."},"bk_cykl_info":{"kw":["przechowywanie","udostępnianie","pozbywania się"],"pulapka":"Faza użytkowania/obsługi informacji dzieli się na przechowywanie, udostępnianie i wykorzystanie; archiwizacja i niszczenie należą do fazy aktualizacji/pozbywania się.","zycie":"Projektujesz album zdjęć: ustalasz potrzeby i układ, zbierasz zdjęcia, przechowujesz i udostępniasz album, sprawdzasz jego przydatność, a potem aktualizujesz lub wycofujesz."},"bk_cz_3komp":{"kw":["cykl życia","ciągłe doskonaleni","zarządzanie programem"],"pulapka":"Trzy komponenty cyklu życia to ciągłe doskonalenie (nie projekt jednorazowy), umożliwienie zmian (zachowanie, kultura) i zarządzanie programem.","zycie":"Dbanie o formę to ciągłe treningi, przekonanie siebie do zmiany nawyków i plan, który trzyma całość w ryzach."},"bk_daz1":{"kw":["jakość informacji","decyzj"],"pulapka":"Chodzi o jakość informacji wspierającej decyzje biznesowe, a nie o jakość samego sprzętu czy oprogramowania.","zycie":"Mama decyduje, co kupić na obiad, patrząc na kartkę z zawartością lodówki; jeśli kartka jest nieaktualna, decyzja będzie zła."},"bk_daz2":{"kw":["wartość","inwestycj","korzyści biznesow"],"pulapka":"Wartość z inwestycji IT to osiąganie celów strategicznych i korzyści biznesowych, a nie samo wdrożenie technologii czy zakończenie projektu.","zycie":"Nowy piec w osiedlowej piekarni ma się opłacić: więcej bułek i nowi klienci, a nie tylko błyszczące urządzenie w kącie."},"bk_daz3":{"kw":["sprawnoś","operacyjn"],"pulapka":"Sprawność operacyjna wynika z niezawodnego i efektywnego użycia technologii; nie myl jej z optymalizacją kosztów, która jest osobnym dążeniem.","zycie":"Kasa w sklepie osiedlowym ma działać codziennie, bez zacięć i szybko, żeby kolejka nie rosła."},"bk_daz4":{"kw":["ryzyk","akceptowaln","apetyt na ryzyko"],"pulapka":"Celem jest utrzymanie ryzyka na akceptowalnym poziomie, a nie jego całkowite wyeliminowanie; COBIT mówi o optymalizacji ryzyka, nie o ryzyku zerowym.","zycie":"Kierowca nie rezygnuje z jazdy, choć zawsze grozi stłuczka; zapina pasy i ma ubezpieczenie, żeby ryzyko było do przyjęcia."},"bk_daz5":{"kw":["koszt","optymalizacj"],"pulapka":"Optymalizacja kosztu to nie minimalizacja; chodzi o koszt właściwy do uzyskiwanej wartości, nie o najtańsze usługi IT.","zycie":"Rodzina porównuje abonamenty na telefon i internet, żeby płacić rozsądnie za to, czego naprawdę używa, a nie najmniej za byle co."},"bk_daz6":{"kw":["zgodnoś","przepis","regulacj"],"pulapka":"Zgodność obejmuje wymogi zewnętrzne (przepisy, regulacje, umowy) i wewnętrzne polityki; nie zawężaj jej tylko do prawa.","zycie":"Właściciel sklepu musi naraz przestrzegać przepisów sanepidu, umowy najmu i własnego regulaminu dla pracowników, a tych wymogów ciągle przybywa."},"bk_dazenia":{"kw":["dąż","jakość informacji","streszczeni"],"pulapka":"Dążeń jest sześć i dotyczą przedsiębiorstw oraz zarządów; nie myl ich z pięcioma zasadami COBIT 5 ani z trzema celami Ładu (korzyści, ryzyko, zasoby).","zycie":"Rodzina kupująca samochód chce kilku rzeczy naraz: pewnych informacji o aucie, wartości za pieniądze, niezawodności, bezpieczeństwa, rozsądnych kosztów i legalnych papierów."},"bk_dom_2":{"kw":["edm","apo","dss","domen"],"pulapka":"Ład ma jedną domenę EDM z 5 procesami, a Zarządzanie cztery domeny (APO, BAI, DSS, MEA); razem jest 37 procesów.","zycie":"Klub piłkarski ma dwie części: zarząd z pięcioma sprawami i sztab szkoleniowy podzielony na cztery działy."},"bk_dom_wlasciwa":{"kw":["domen","przypis","proces"],"pulapka":"Choć proces może mieć działania planowania, budowy, uruchamiania i monitorowania, przypisuje się go do jednej domeny, najwłaściwszej dla jego głównego obszaru.","zycie":"Mycie auta wymaga planu, wody i sprawdzenia efektu, ale wpisujesz je na jedną listę: „sprawy samochodu”."},"bk_dost_bezp_def":{"kw":["dostęp","bezpieczeństw","uprawnion"],"pulapka":"Dostęp i bezpieczeństwo ma dwie strony: aktywator dostępny w razie potrzeby i wyniki dostępne tylko dla uprawnionych; to kategoria celów, nie osobny wymiar.","zycie":"Apteczka ma być pod ręką, gdy ktoś się skaleczy, ale zamknięta przed małymi dziećmi."},"bk_dzialania_def":{"kw":["działani","konieczn","normatywn"],"pulapka":"Działania to kroki konieczne i wystarczające do realizacji praktyki (GP/MP); nie są normatywne i trzeba je dostosować, tworząc konkretne procedury organizacji.","zycie":"Przepis na naleśniki to kroki konieczne i wystarczające, ale każda kuchnia dopisuje swoje: patelnia, ilość mleka, czas smażenia."},"bk_dzialania_odb":{"kw":["audytor","działani"],"pulapka":"Opis działań przydaje się kierownictwu, dostawcom usług, użytkownikom końcowym, specjalistom IT i audytorom; nie jest przeznaczony wyłącznie dla działu IT.","zycie":"Z instrukcji montażu szafy korzysta i kupujący, i monter, i sklep, a nawet ktoś, kto sprawdza, czy zrobiono to dobrze."},"bk_edm_rola":{"kw":["edm","interakcj","kierowani"],"pulapka":"Rola Ładu to ocena, kierowanie i monitorowanie (EDM); wymaga zbioru interakcji z Zarządzaniem, a nie całkowitej izolacji obu dziedzin.","zycie":"Rodzice oceniają pomysły dzieci, wskazują kierunek i sprawdzają postępy, ale muszą przy tym ciągle z dziećmi rozmawiać."},"bk_etyka_ind":{"kw":["etyka indywidualna","etyki indywidualnej"],"pulapka":"Etyka indywidualna zależy w dużym stopniu od czynników zewnętrznych: religii, pochodzenia, statusu społeczno-ekonomicznego, geografii i doświadczeń; nie wyznacza jej polityka organizacji.","zycie":"Jeden sąsiad oddaje znaleziony portfel, bo tak go wychowano, a drugi się waha. Każdy kieruje się własnymi wartościami."},"bk_etyka_org":{"kw":["etyka organizacyjna","etyki organizac"],"pulapka":"Etyka organizacyjna wynika z wartości, na których ma opierać się organizacja, a etyka indywidualna z osobistych wartości pracownika; pytania o definicje lubią je zamieniać.","zycie":"Rodzinna piekarnia od pokoleń trzyma się zasady: nie sprzedajemy wczorajszego chleba jako świeżego."},"bk_f2_6mies":{"kw":["sześć miesięcy","6 miesięcy","iteracj"],"pulapka":"Inicjatywa trwająca ponad sześć miesięcy grozi utratą dynamiki, koncentracji i akceptacji; duże inicjatywy dzieli się na wiele iteracji cyklu życia.","zycie":"Dieta rozpisana na rok traci zapał po kilku miesiącach; lepiej planować krótsze etapy z widocznym efektem."},"bk_f2_ryzyko":{"kw":["faza 2","scenariusz","zakres"],"pulapka":"Zakres w fazie 2 ustala się mapowaniem celów przedsiębiorstwa na cele IT i procesy, wspartym scenariuszami ryzyka i ogólną diagnostyką; potem ocenia się stan obecny.","zycie":"Przed remontem sprawdzasz, co najbardziej grozi awarią, np. stare rury i kable, i od tego zaczynasz."},"bk_f3_prior":{"kw":["faza 3","luk","szybkie korzyści"],"pulapka":"W fazie 3 określa się cel doskonalenia oraz luki i możliwe rozwiązania; priorytet mają inicjatywy prostsze i najbardziej korzystne, a nie najambitniejsze.","zycie":"Porządki w ogrodzie zaczynasz od grabienia liści, bo idzie szybko i widać efekt, a przycinanie drzew zostawiasz na później."},"bk_f4_uzas":{"kw":["faza 4","uzasadnieni","plan"],"pulapka":"W fazie 4 planuje się praktyczne rozwiązania: projekty wsparte uzasadnieniami biznesowymi i plan zmian; wdrażanie w praktyce to dopiero faza 5.","zycie":"Przed zakupem nowego auta spisujesz, po co, ile kosztuje i co zyskasz, oraz jak przygotujesz rodzinę do zmiany."},"bk_f5_miary":{"kw":["faza 5","mierni","monitorowani"],"pulapka":"W fazie 5 rozwiązania wdraża się w praktyce, a miary i monitorowanie oparte są na celach i miernikach COBIT; potrzebne są zaangażowanie kierownictwa i własność biznesu oraz IT.","zycie":"Nowy plan treningów wprowadzasz w życie i od razu mierzysz postępy zawodników."},"bk_f6_zrown":{"kw":["faza 6","korzyści","zrównoważon"],"pulapka":"Faza 6 skupia się na trwałym użyciu nowych lub udoskonalonych aktywatorów i monitorowaniu korzyści. Faza 7 obejmuje przegląd ogólnego sukcesu i dalszych wymagań; ocena i monitorowanie nie są zakazane we wcześniejszych fazach.","zycie":"Nowy zwyczaj segregowania śmieci ma się utrwalić, a ty sprawdzasz, czy faktycznie płacisz mniej za odpady."},"bk_f7_iter":{"kw":["faza 7","iteracyj","ciągłego doskonalenia"],"pulapka":"W fazie 7 ocenia się ogólny sukces, wskazuje dalsze wymagania i wzmacnia ciągłe doskonalenie. Inicjatywa lub program mogą zostać zamknięte; podejście do Ładu i Zarządzania jest rozwijane iteracyjnie.","zycie":"Po sezonie drużyna podsumowuje wyniki, wypisuje, co poprawić, i zaczyna przygotowania do nowego sezonu."},"bk_f_wniosek":{"kw":["kryteri","cobit 4.1","integralność"],"pulapka":"Wszystkie 7 kryteriów informacji COBIT 4.1 ma odpowiedniki w celach jakości informacji COBIT 5, a model informacji pozwala zdefiniować dodatkowe; żadnego kryterium nie usunięto.","zycie":"Stary termometr pokazywał tylko temperaturę, a nowa stacja pogodowa pokazuje ją oraz wilgotność i ciśnienie. Nic nie zginęło, doszło więcej."},"bk_f_zgodnosc":{"kw":["zgodnoś","specyfikac","kryteri"],"pulapka":"Zgodność z regulacjami to raczej cel związany ze sposobem wykorzystania informacji niż jej cecha wewnętrzna; zgodność ze specyfikacją ujęto w każdym celu jakości informacji.","zycie":"To, czy wolno zaparkować auto pod domem, zależy od sposobu jego użycia i przepisów, a nie od koloru lakieru czy marki."},"bk_g_uklad":{"kw":["cztery wymiary","wymiar","zarządzanie wydajnością aktywatora"],"pulapka":"Każdy aktywator w Załączniku G ma rysunek, 4 wymiary (interesariusze, cele, cykl życia, dobre praktyki), relacje z innymi i przykłady; zarządzanie wydajnością aktywatora to nie piąty wymiar.","zycie":"Każdy rozdział poradnika ogrodniczego ma ten sam układ: zdjęcie rośliny, cztery rubryki opisu, z czym dobrze rośnie i przykłady z prawdziwych ogrodów."},"bk_h_akt_nadzoru":{"kw":["aktywatory ładu","aktywator"],"pulapka":"Aktywator Ładu to coś materialnego lub niematerialnego, co wspiera skuteczny Ład; aktywatorem jest więc też kultura, nie tylko narzędzia i dokumenty.","zycie":"Wszystko, co pomaga rodzicom dobrze kierować domem: kalendarz, zasady, rozmowa przy kolacji, a nawet zaufanie dzieci."},"bk_h_arch_ref":{"kw":["architektura referencyjna","architektura docelowa"],"pulapka":"Architektura referencyjna (bazowa) to istniejący opis przed cyklem przeprojektowania, czyli stan obecny; przyszły stan opisuje architektura docelowa.","zycie":"Plan mieszkania „jak jest teraz”, narysowany przed remontem, zanim architekt zaprojektuje nowy układ."},"bk_h_atr_proc":{"kw":["atrybut","pa 1.1"],"pulapka":"Atrybut procesu to mierzalna cecha zdolności odnosząca się do każdego procesu; jest ich 9 (PA 1.1–5.2) i każdy ocenia się skalą N, C, W, P.","zycie":"Karta oceny w konkursie kucharskim ma rubryki: smak, planowanie, porządek, powtarzalność. Każda rubryka mierzy jedną cechę."},"bk_h_cel":{"kw":["cele i mierniki","deklaracja","miernik"],"pulapka":"Cel to deklaracja pożądanego wyniku, a miernik – jednostka pomiaru jego osiągnięcia; nie myl celu z miernikiem ani z praktyką.","zycie":"„Chcę mieć ogród warzywny” to cel – opis tego, co chcesz osiągnąć, zanim zaczniesz liczyć grządki."},"bk_h_cel_bizn":{"kw":["cele organizacji","bsc"],"pulapka":"Cel biznesowy (cel organizacji) przekłada misję z deklaracji zamiaru na cele działania i wyniki; 17 typowych celów organizacji ułożono według wymiarów BSC, a nie IT BSC.","zycie":"Rodzinna misja „zdrowe dzieci” zamienia się w konkretne cele: dwa razy w tygodniu basen i warzywa do każdego obiadu."},"bk_h_cel_it":{"kw":["cele związane z it","it bsc","cel it"],"pulapka":"Cel związany z IT to deklaracja pożądanego wyniku IT wspierającego cele organizacji; 17 celów IT ułożono według IT BSC i to one wspierają cele organizacji, nie odwrotnie.","zycie":"Rodzinny cel to zdrowe jedzenie, a cel dla kuchni to sprawna lodówka i piekarnik, które ten cel umożliwią."},"bk_h_cel_procesu":{"kw":["cel procesu","cele procesu"],"pulapka":"Cel procesu to deklaracja pożądanego wyniku procesu: artefaktu, istotnej zmiany stanu lub poprawy zdolności innych procesów; nie myl go z miernikiem ani z opisem procesu.","zycie":"Cel wizyty u fryzjera: krótsze włosy, zmiana wyglądu albo fryzura, którą łatwiej ułożyć rano."},"bk_h_ciaglosc":{"kw":["ciągłoś","dss04"],"pulapka":"Ciągłość działalności to zapobieganie zakłóceniom, łagodzenie skutków i odtwarzanie; plany odtworzenia po katastrofie skupiają się na odtwarzaniu, więc trzeba uwzględnić też odporność.","zycie":"Rodzina trzyma latarkę i zapas wody, żeby awaria prądu nie sparaliżowała domu, a gdy już się zdarzy, żeby szybko wszystko przywrócić."},"bk_h_cobit41":{"kw":["cobit 4.1","cele kontrolne","model dojrzałości"],"pulapka":"COBIT 4.1 opisywał procesy IT, cele kontrolne, wytyczne zarządzania i modele dojrzałości; aktywatory i oddzielenie Ładu od Zarządzania wprowadził COBIT 5.","zycie":"Stara instrukcja do pralki opisywała tylko programy i usterki, a nowa obejmuje całe gospodarstwo domowe."},"bk_h_cobit5":{"kw":["control objectives","akronim","siedem kategorii"],"pulapka":"COBIT 5 używa już tylko akronimu; pełna nazwa Control Objectives for Information and related Technology dotyczy wcześniejszych wersji. COBIT 5 opisuje 5 zasad i 7 aktywatorów.","zycie":"Jak rodzinny sklep nazwany kiedyś od inicjałów założycieli: dziś wszyscy mówią po prostu jego nazwą i nikt nie pamięta, co znaczyły litery."},"bk_h_cykl_ekon":{"kw":["cyklu życia ekonomiczn","uzasadnienie biznesowe"],"pulapka":"Pełny cykl życia ekonomicznego to okres istotnych korzyści i wydatków programu inwestycyjnego, łącznie z eksploatacją i wycofaniem, a nie tylko faza budowy.","zycie":"Koszt samochodu to nie tylko zakup: przez lata płacisz za paliwo i przeglądy, korzystasz z jazdy, a na końcu auto sprzedajesz lub złomujesz."},"bk_h_dobra_prakt":{"kw":["dobra praktyka","dobre praktyki"],"pulapka":"Dobra praktyka to sprawdzone działanie lub proces, z powodzeniem stosowane w wielu organizacjach i dające wiarygodne wyniki; to także jeden z czterech wymiarów aktywatora.","zycie":"Sprawdzona w wielu kuchniach metoda przygotowania sernika jest dobrym punktem wyjścia. Nadal dopasowujesz ją do swojego piekarnika i składników."},"bk_h_dopasowanie":{"kw":["dopasowan","strategi"],"pulapka":"Dopasowanie to stan, w którym aktywatory Ładu i Zarządzania IT wspierają cele i strategię organizacji; to nie to samo co zgodność z przepisami.","zycie":"Wszystkie koła samochodu są ustawione równo, więc auto jedzie prosto tam, gdzie kieruje kierowca."},"bk_h_dzialanie":{"kw":["działanie","konieczn"],"pulapka":"Działanie to podstawowa czynność procesu. Dopiero zbiór działań opisuje konieczne i wystarczające kroki realizacji praktyki; pojedynczy krok nie musi sam wystarczać. Ogólne działania dostosowuje się do procedur organizacji.","zycie":"W przepisie na pierogi pojedynczy krok, np. „zagnieć ciasto”, to działanie – czynność potrzebna, żeby danie powstało."},"bk_h_geit":{"kw":["ład it","ład nad informatyką"],"pulapka":"Ład IT w przedsiębiorstwie (GEIT) daje pewność, że informacja i technologia wspierają strategię i cele organizacji; nie dotyczy tylko działu IT ani samej technologii.","zycie":"Rodzice upewniają się, że telefony, telewizor i internet w domu faktycznie pomagają rodzinie żyć, uczyć się i pracować."},"bk_h_informacje":{"kw":["informacj","zasób"],"pulapka":"Informacje to zasób niezbędny jak inne ważne aktywa i mogą mieć wiele postaci: papierową, elektroniczną, film, rozmowę; nie są to tylko dane w systemach IT.","zycie":"Numer do lekarza zapisany w zeszycie, powiedziany przez telefon albo wysłany SMS-em jest w każdej postaci tak samo cenny jak klucze do domu."},"bk_h_interesariusz":{"kw":["interesariusz","potrzeby interesariuszy"],"pulapka":"Interesariuszem jest każdy, kto ma odpowiedzialność, oczekiwania lub udział w organizacji: udziałowcy, użytkownicy, rząd, dostawcy, klienci, opinia publiczna; nie tylko właściciele.","zycie":"Przy budowie placu zabaw zdanie mają rodzice, dzieci, gmina, wykonawca i sąsiedzi spod okna. Każdy ma w tym swój interes."},"bk_h_jakosc":{"kw":["jakoś","jakość wewnętrzna"],"pulapka":"Jakość to przydatność do celu (uzyskanie zamierzonej wartości), a nie najwyższe parametry; cele aktywatorów dzielą się m.in. na jakość wewnętrzną i kontekstową.","zycie":"Dobre buty do biegania to te, które pasują do biegania, a nie najdroższe czy najładniejsze."},"bk_h_kodeks":{"kw":["kodeks etyki","etyk"],"pulapka":"Kodeks etyki definiuje wartości organizacyjne i reguły, pomagając odróżnić właściwe postępowanie od niewłaściwego; karta etyki to w słowniczku przykład aktywatora Zasada.","zycie":"Spisane prawo harcerskie pomaga młodemu harcerzowi zdecydować, co jest w porządku, a co nie, nawet gdy nikt nie patrzy."},"bk_h_kompetencja":{"kw":["kompetencj","umiejętnoś"],"pulapka":"Kompetencja to zdolność skutecznego wykonania zadania, czynności lub funkcji, a umiejętność – wyuczona zdolność osiągania określonych rezultatów; egzamin lubi je zamieniać.","zycie":"Kierowca, który z prawem jazdy w kieszeni naprawdę bezpiecznie dowozi dzieci do szkoły każdego dnia, wykazuje kompetencję."},"bk_h_kontekst":{"kw":["kontekst","jakość kontekstowa"],"pulapka":"Kontekst obejmuje 5 rodzajów: technologiczny, danych, umiejętności i wiedzy, organizacyjny i kulturowy oraz strategiczny; na tej liście nie ma np. kontekstu prawnego ani finansowego.","zycie":"Czy rodzina będzie używać wspólnego kalendarza, zależy od telefonów, aktualności wpisów, umiejętności obsługi, zwyczaju planowania i tego, czego chce."},"bk_h_kontrola":{"kw":["mechanizmy kontrolne","kontrol"],"pulapka":"Kontrola (mechanizm kontrolny) to metody zarządzania ryzykiem: polityki, procedury, wytyczne, praktyki lub struktury, także administracyjne i prawne; nie tylko zabezpieczenia techniczne.","zycie":"Zamek w drzwiach, regulamin domowy i zasada „ostatni gasi światło” to różne sposoby ograniczania ryzyka w domu."},"bk_h_kultura":{"kw":["kultur","kultura, etyka"],"pulapka":"Kultura to wzorzec zachowań, poglądów, założeń, postaw i sposobów działania; w COBIT 5 należy do aktywatora Kultura, etyka i zachowanie, a nie do Zasad i polityk.","zycie":"W jednej rodzinie przy stole się rozmawia, w innej każdy patrzy w telefon. To nie regulamin, tylko utrwalony wzorzec zachowań."},"bk_h_lad_korp":{"kw":["ładu korporacyjnego","ład korporacyjny"],"pulapka":"Ład korporacyjny to obowiązki i praktyki zarządu i kadry: kierunek strategiczny, osiąganie celów, ryzyko i odpowiedzialne użycie zasobów; Ład IT jest jego częścią, nie odwrotnie.","zycie":"Zarząd spółdzielni wyznacza kierunek, pilnuje celów, trzyma ryzyko w ryzach i sprawdza, czy pieniądze mieszkańców wydano odpowiedzialnie."},"bk_h_mech_proc_bizn":{"kw":["mechanizmy kontrolne","kontroli wewnętrznej"],"pulapka":"Mechanizmy kontrolne procesów biznesowych racjonalnie zapewniają realizację celów danego procesu biznesowego; system kontroli wewnętrznej dotyczy celów całej organizacji.","zycie":"W sklepie osiedlowym liczenie kasy po zmianie, dwa podpisy przy zwrotach i grafik pracy zapewniają, że sprzedaż przebiega poprawnie."},"bk_h_metodyka_nadz":{"kw":["struktura ramowa","coso"],"pulapka":"Struktura ramowa Ładu (podręcznik: metodyka nadzoru) to struktura koncepcyjna: pojęcia, założenia, praktyki, role, relacje i granice; przykłady to COBIT i COSO, nie ISO/IEC 15504.","zycie":"Regulamin rozgrywek ligi mówi, jakie są pojęcia, kto jest sędzią, a kto zawodnikiem, i czego liga w ogóle nie obejmuje."},"bk_h_miernik":{"kw":["miernik","smart"],"pulapka":"Pełne wytyczne miernika określają jednostkę, częstotliwość pomiaru, wartość docelową, procedurę pomiaru i interpretacji wyniku; miernik mierzy cel, sam nim nie jest.","zycie":"Licznik kroków w telefonie mierzy, czy realizujesz cel 10 tysięcy kroków dziennie. Wiadomo co, jak często i ile."},"bk_h_opt_ryz":{"kw":["optymalizacja ryzyka","optymalizacji ryzyka","apetyt"],"pulapka":"Optymalizacja ryzyka to nie jego eliminacja: obejmuje rozpoznanie, ocenę wpływu i prawdopodobieństwa oraz unikanie, ograniczanie lub transfer ryzyka w granicach apetytu na ryzyko.","zycie":"Przed wyjazdem na narty rodzina ocenia ryzyko kontuzji, kupuje ubezpieczenie, omija czarne trasy i godzi się na resztę ryzyka."},"bk_h_opt_zas":{"kw":["optymalizacja zasobów","optymalizacji zasobów"],"pulapka":"Optymalizacja zasobów dotyczy wszystkich zasobów: ludzi, finansów, sprzętu i infrastruktury, a nie tylko kosztów IT; to jeden z trzech celów Ładu.","zycie":"Rodzina rozsądnie wykorzystuje czas, pieniądze, auto i umiejętności każdego domownika, żeby nic się nie marnowało."},"bk_h_pmo":{"kw":["pmo","vmo"],"pulapka":"PMO wspiera kierowników programów i projektów oraz zbiera, ocenia i raportuje informacje o ich realizacji; sekretariatem portfela inwestycji i usług jest VMO.","zycie":"Sekretariat szkolnej ligi pomaga opiekunom drużyn, zbiera ich sprawozdania i informuje dyrekcję o postępach turnieju."},"bk_h_polityka":{"kw":["polityka","polityk"],"pulapka":"Polityka to ogólne zamierzenia i wytyczne formalnie wyrażone przez kierownictwo; zasada wyraża wartości i podstawowe założenia, np. karta etyki.","zycie":"Mama ogłasza: „Przy kolacji odkładamy telefony”. To formalnie wyrażona przez głowę rodziny reguła."},"bk_h_portfel":{"kw":["portfel","apo05"],"pulapka":"Portfel inwestycyjny to zbiór inwestycji rozważanych i/lub realizowanych; obejmuje więc też te dopiero planowane, nie tylko trwające.","zycie":"Lista domowych planów: remont, nowe auto, wakacje. Część już trwa, a resztę rodzina dopiero rozważa."},"bk_h_potencjal":{"kw":["zdolność procesu","zdolności procesu","15504"],"pulapka":"Zdolność procesu (podręcznik: potencjał) to według ISO/IEC 15504 zdolność do osiągania bieżących lub planowanych celów biznesowych; nie myl jej z dojrzałością z COBIT 4.1.","zycie":"Zdolność drużyny do wygrywania kolejnych meczów przez cały sezon, a nie wynik jednego spotkania."},"bk_h_praktyka_gm":{"kw":["praktyki ładu","praktyki zarządzania","praktyka ładu"],"pulapka":"Praktyka Ładu/Zarządzania to ogólne wymogi wobec procesu, deklaracje działań organów Ładu i Zarządzania; kroki „jak to zrobić” opisują dopiero działania.","zycie":"Wymóg „drużyna trenuje regularnie” mówi, co ma się dziać; jak dokładnie, ustala potem trener w konkretnych ćwiczeniach."},"bk_h_proces":{"kw":["właściciel procesu","proces"],"pulapka":"W słowniczku proces ma też jasne przesłanki biznesowe, rozliczanych właścicieli, jasne role i środki pomiaru wydajności; to coś więcej niż lista czynności.","zycie":"Pranie w domu: ktoś za nie odpowiada, wiadomo, kto sortuje, a kto wiesza, i widać, czy ubrania są czyste."},"bk_h_raci_a":{"kw":["odpowiedzialny decyzyjnie","rozliczan","raci"],"pulapka":"A (Accountable) to na egzaminie PL „odpowiedzialny decyzyjnie” (podręcznik: strona rozliczana), a R to „odpowiedzialny wykonawczo”; obie nazwy mają słowo „odpowiedzialny”.","zycie":"Kapitan statku nie musi sam sterować, ale to on ostatecznie odpowiada przed armatorem, czy statek bezpiecznie dopłynie do portu."},"bk_h_raci_c":{"kw":["konsultant","dwukierunkow","raci"],"pulapka":"C (Konsultant) dostarcza dane wejściowe w komunikacji dwukierunkowej; I (Informowany) tylko otrzymuje informacje, jednokierunkowo.","zycie":"Przed wyborem koloru ścian w salonie pytasz żonę o zdanie i słuchasz jej uwag. Rozmowa idzie w obie strony."},"bk_h_raci_i":{"kw":["informowan","jednokierunkow","raci"],"pulapka":"I (Informowany) otrzymuje informacje o postępach i wynikach w komunikacji jednokierunkowej; rola A zawsze powinna dostawać odpowiednie informacje, by nadzorować zadanie.","zycie":"Sąsiad dostaje kartkę: „W sobotę remont, będzie głośno”. Nikt go nie pyta o zdanie, tylko zawiadamia."},"bk_h_raci_r":{"kw":["odpowiedzialny wykonawczo","raci"],"pulapka":"R (Responsible, odpowiedzialny wykonawczo) to rola najbardziej zaangażowana operacyjnie; odpowiada na pytanie „kto realizuje zadanie?”, a nie „kto odpowiada za powodzenie?” (to A).","zycie":"Mechanik, który fizycznie wymienia klocki hamulcowe w twoim aucie, to ten, kto wykonuje robotę."},"bk_h_rada_arch":{"kw":["rada ds. architektury","architektur"],"pulapka":"Rada ds. Architektury daje wytyczne i decyzje w sprawie architektury korporacyjnej oraz opracowuje jej polityki i standardy; to grupa, a nie pojedyncza rola dyrektora ds. architektury.","zycie":"Komisja osiedlowa ustala, jakie ogrodzenia i kolory elewacji są dozwolone, i rozstrzyga spory o nowe budowy."},"bk_h_realiz_korz":{"kw":["realizacja korzyści","realizacji korzyści"],"pulapka":"Realizacja korzyści obejmuje nowe korzyści, utrzymanie i rozszerzenie istniejących oraz eliminację inicjatyw i zasobów bez wystarczającej wartości; nie dotyczy wyłącznie nowych korzyści.","zycie":"Rodzina sprawdza, co daje jej działka, korzysta z niej dalej i rezygnuje z karnetu na siłownię, który tylko kosztuje."},"bk_h_rozl_nadzor":{"kw":["zarząd","rozliczaln","ład"],"pulapka":"W większości organizacji rozliczalność za Ład spoczywa na organie nadzorującym (board), pod kierownictwem jego przewodniczącego. Podręcznik PL używa słów „zarząd” i „prezes”; dobór rzeczywistego organu zależy od struktury organizacji. Delegowanie zadań nie usuwa tej rozliczalności.","zycie":"Rada nadzorcza spółdzielni ocenia potrzeby mieszkańców, ustala, co remontować najpierw, i sprawdza postęp; odpowiada za to cała rada z przewodniczącym."},"bk_h_ryzyko":{"kw":["ryzyk","prawdopodobieństw"],"pulapka":"Ryzyko to połączenie prawdopodobieństwa zdarzenia i jego konsekwencji, a nie samo prawdopodobieństwo ani samo zagrożenie.","zycie":"Ryzyko gołoledzi to połączenie szansy, że rano będzie ślisko, i tego, jak bolesny byłby upadek."},"bk_h_skw":{"kw":["kontroli wewnętrznej","mea02"],"pulapka":"System kontroli wewnętrznej służy realizacji celów oraz zapobieganiu niepożądanym zdarzeniom albo ich wykrywaniu i korygowaniu; jego monitorowanie to proces MEA02.","zycie":"Domowe zasady, plan wydatków, sprawdzanie rachunków i podział obowiązków pomagają osiągać cele rodziny i szybko wyłapywać pomyłki."},"bk_h_struktura_org":{"kw":["struktury organizacyjne","komitet sterujący"],"pulapka":"Struktura organizacyjna jako aktywator obejmuje organizację, jej struktury, hierarchie i zależności, np. komitet sterujący; to nie to samo co diagram RACI.","zycie":"Hierarchia w harcerstwie: drużyna, zastępy, drużynowy i rada. Widać, kto komu podlega i kto podejmuje decyzje."},"bk_h_tabela_raci":{"kw":["diagram raci","raci"],"pulapka":"Diagram RACI (podręcznik: tabela RACI) przypisuje role R, A, C, I do praktyk procesów i łączy aktywator Procesy ze Strukturami organizacyjnymi.","zycie":"Tabelka na drzwiach kuchni: kto gotuje, kto decyduje o menu, kogo pytać o alergie, a kogo zawiadomić o godzinie obiadu."},"bk_h_tworz_wart":{"kw":["tworzenie wartości","tworzenia wartości"],"pulapka":"Tworzenie wartości to główny cel Ładu, osiągany przez równowagę realizacji korzyści, optymalizacji ryzyka i optymalizacji zasobów; to nie maksymalizacja samych korzyści.","zycie":"Udane wakacje to dużo radości, rozsądne ryzyko i budżet, który nie zrujnuje rodziny. Liczy się równowaga wszystkich trzech."},"bk_h_umiejetnosc":{"kw":["umiejętność","kompetencj"],"pulapka":"Umiejętność to wyuczona zdolność osiągania wcześniej określonych rezultatów; kompetencja oznacza zdolność skutecznego wykonania zadania, czynności lub funkcji. Pojęcia są powiązane, ale nie są identycznymi definicjami.","zycie":"Jazdę na rowerze ćwiczysz, aby sprawnie dojeżdżać do wybranego miejsca. Sama znajomość przepisów nie zastąpi praktycznej umiejętności."},"bk_h_uslugi_it":{"kw":["usługi it","service desk"],"pulapka":"Usługi IT to codzienne dostarczanie infrastruktury i aplikacji oraz wsparcie przy korzystaniu z nich, np. Service Desk; zasoby, którymi się je świadczy, to zdolności usługowe.","zycie":"Codzienne dostarczanie prądu, usuwanie awarii i infolinia elektrowni, do której dzwonisz, gdy zgaśnie światło."},"bk_h_we_wy":{"kw":["wejścia i wyjścia","produkty pracy"],"pulapka":"Wejścia i wyjścia to produkty pracy procesu, definiowane na poziomie praktyk; lista przykładów COBIT 5 nie jest wyczerpująca, a wyjście jednego procesu bywa wejściem innego.","zycie":"Dziennik budowy: zapisy z jednego etapu są potrzebne ekipie z następnego, a inspektor może z nich odtworzyć, co i kiedy zrobiono."},"bk_h_wlasciciel":{"kw":["właściciel procesu","właściciel"],"pulapka":"Właściciel to osoba lub grupa z prawami i obowiązkami wobec zasobu, np. właściciel procesu lub systemu; właściciel procesu biznesowego odpowiada za sprawność procesu i zatwierdza zmiany.","zycie":"Właściciel mieszkania ma prawo decydować o remoncie, ale też obowiązek płacić czynsz i dbać o stan lokalu."},"bk_h_wyznacznik":{"kw":["wyznaczni","kaskad"],"pulapka":"Wyznacznik (driver) to czynnik zewnętrzny lub wewnętrzny, który inicjuje działanie lub zmianę i na nie wpływa; wyznaczniki interesariuszy to pierwszy krok kaskady celów.","zycie":"Narodziny dziecka albo podwyżka czynszu sprawiają, że rodzina zmienia sposób życia: przeprowadza się albo tnie wydatki."},"bk_h_zasada":{"kw":["zasad","zasady, polityki"],"pulapka":"Zasada obejmuje wartości, założenia i poglądy kształtujące decyzje oraz dozór, czyli troskę o cudze zasoby; przykłady to karta etyki i karta odpowiedzialności społecznej, nie regulamin haseł.","zycie":"Rodzinne „zawsze mówimy prawdę i pomagamy sąsiadom” wpływa na każdą decyzję, choć nie mówi, co dokładnie robić."},"bk_h_zasob":{"kw":["zasob","optymalizacja zasobów"],"pulapka":"Zasób to każdy zasób organizacji pomagający jej osiągnąć cele; optymalizacja zasobów dotyczy ludzi, finansów, sprzętu i infrastruktury, nie tylko IT.","zycie":"W domu zasobem jest wszystko, co pomaga rodzinie: pieniądze, samochód, czas, umiejętności i życzliwa sąsiadka."},"bk_i38_1":{"kw":["raci","edm05","komitet ds. strategii"],"pulapka":"W porównaniu z ISO/IEC 38500:2008 zasadę Odpowiedzialność wspierają m.in. Procesy, Struktury organizacyjne, RACI oraz EDM05. Opisany komitet strategiczny IT działa w imieniu organu nadzorującego i pod przewodnictwem jego członka; nie jest obowiązkowym organem w każdej organizacji.","zycie":"W rodzinie jasno ustalono: tata płaci rachunki, mama decyduje o wakacjach, a dzieci wynoszą śmieci. Każdy wie, kto za co odpowiada."},"bk_i38_2":{"kw":["edm02","apo","kaskad"],"pulapka":"Porównanie w Załączniku E podaje dla zasady Strategia EDM02, domenę APO i kaskadę celów. BAI omówiono szczególnie przy zasadzie Nabycie; nie wynika z tego, że działania BAI nie mogą wspierać realizacji strategii.","zycie":"Plan zakupu sprzętu dla drużyny musi pasować do planów klubu, np. awansu do wyższej ligi, i do tego, ile ryzyka finansowego klub akceptuje."},"bk_i38_3":{"kw":["apo05","bai","nabywani"],"pulapka":"Według zasady Nabycie projekty IT są częścią szerszej zmiany biznesowej, a nie czysto technicznym przedsięwzięciem; wspierają ją EDM, APO05, APO, BAI oraz MEA i EDM05.","zycie":"Kupno nowej kuchenki to nie tylko zakup: trzeba przerobić instalację, nauczyć domowników obsługi i zmienić nawyki gotowania."},"bk_i38_4":{"kw":["apo09","mea01","apo02"],"pulapka":"Przy zasadzie Sprawność Załącznik E wymienia m.in. APO02, APO09, MEA01 i ocenę zdolności procesu. MEA02 i MEA03 omówiono przy Zgodności. To przykładowe powiązania, a nie rozłączne zbiory wszystkich oddziaływań procesów.","zycie":"Rodzina ustala cel, np. oszczędzić na wakacje, i licznik postępu na lodówce, który każdy rozumie i może śledzić co miesiąc."},"bk_i38_5":{"kw":["mea03","mea02","zgodnoś"],"pulapka":"Zgodność trzeba wbudować w planowanie strategiczne, bo zapewnianie jej po szkodzie jest kosztowne; wspierają ją APO02, MEA02, MEA03 oraz przewodnik COBIT 5 – Audyt.","zycie":"Budując dom, od początku projektujesz go zgodnie z przepisami, bo przeróbki po kontroli nadzoru budowlanego kosztują znacznie więcej."},"bk_i38_6":{"kw":["apo07","bai05","bai08"],"pulapka":"Przy zasadzie Zachowanie pracowników Załącznik E wymienia aktywatory Ludzie, umiejętności i kompetencje oraz Kultura, etyka i zachowanie, a także APO07, BAI02, BAI05 i BAI08. Lista nie oznacza, że zachowania ludzi nie mają znaczenia w procesach DSS.","zycie":"Gdy w domu pojawia się nowy termostat, babcię trzeba spokojnie przekonać i nauczyć obsługi, inaczej będzie go wyłączać."},"bk_i38_edm":{"kw":["oszacuj, kieruj i monitoruj","edm","38500"],"pulapka":"Ocena, kierowanie i monitorowanie z ISO/IEC 38500 odpowiada domenie EDM (Oszacuj, Kieruj i Monitoruj) z 5 procesami Ładu; nie APO, która należy do Zarządzania.","zycie":"Zarząd wspólnoty ocenia propozycje, decyduje o kierunku remontów i sprawdza ich postęp; sam nie maluje klatek."},"bk_il15_feedback":{"kw":["informacje zwrotne","zwrotn","informacj"],"pulapka":"Na Rysunku 15 informacje zwrotne dotyczące zarządzania płyną od obszaru Zarządzania do Oceny (Evaluate) w obszarze Ładu. Nie pomyl tej konkretnej strzałki z funkcją Monitorowania (Monitor) Ładu.","zycie":"Kierownik ekipy co tydzień dzwoni do właścicieli i mówi, ile zrobiono i co się opóźnia."},"bk_il15_kier":{"kw":["kierowani","direct","rysunek 15"],"pulapka":"Kierowanie to strzałka od Ładu do Zarządzania; Zarządzanie nie kieruje Ładem, tylko przekazuje mu informacje zwrotne.","zycie":"Rodzice mówią ekipie: najpierw łazienka, potem kuchnia, a ekipa sama organizuje dalszą pracę."},"bk_il15_mon":{"kw":["monitorowani","mea","edm"],"pulapka":"Monitorowanie występuje w Ładzie (EDM) i w Zarządzaniu (MEA); w Ładzie oznacza sprawdzanie, czy wyznaczony kierunek wcielono w życie.","zycie":"Rodzice zaglądają na budowę, żeby sprawdzić, czy ekipa robi to, co ustalono, ale sami nie kładą płytek."},"bk_il15_ocena":{"kw":["ocena","evaluate","edm"],"pulapka":"Evaluate jest funkcją Ładu w EDM. Assessment i evaluation występują też w obszarze Zarządzania, m.in. MEA; samo polskie słowo „ocena” bez kontekstu nie rozstrzyga, czy chodzi o Ład czy Zarządzanie.","zycie":"Przed remontem rodzice najpierw oglądają mieszkanie i oferty fachowców, a dopiero potem coś postanawiają."},"bk_il15_potrzeby":{"kw":["potrzeby biznesow","rysunek 15","ocena"],"pulapka":"Na Rysunku 15 potrzeby biznesowe są wejściem do Ładu i zasilają Ocenę; nie są elementem żadnej domeny Zarządzania.","zycie":"Najpierw lista potrzeb rodziny; dopiero na jej podstawie rodzice cokolwiek oceniają i postanawiają."},"bk_il33_uwagi":{"kw":["rysunek 33","ilustracyjn","role"],"pulapka":"Role i struktury z Rysunku 33 są ilustracyjne: nie muszą odpowiadać faktycznym funkcjom w organizacji i nie tworzą uniwersalnej struktury dla każdego przedsiębiorstwa.","zycie":"Wzorcowy schemat firmy z poradnika to tylko przykład; mały sklep może mieć jedną osobę w roli szefa, kasjera i magazyniera."},"bk_info_atr_warstwy":{"kw":["warstwa semantyczna","warstwa pragmatyczna","warstwa empiryczna"],"pulapka":"Łatwo pomylić warstwy: aktualność i poziom szczegółowości to atrybuty semantyczne, okres przechowywania i status – pragmatyczne, kanał dostępu – empiryczny, a nośnik – fizyczny.","zycie":"List od babci: papier to nośnik, skrzynka to kanał, polszczyzna to kod, życzenia urodzinowe to znaczenie, „zachowaj do świąt” to użycie, a rodzinna tradycja to kontekst."},"bk_info_tgf":{"kw":["rysunek 9","delegowanie","rozliczalność"],"pulapka":"Interakcje ról z Rysunku 9 wymagają przepływu informacji: rozliczalność, delegowanie, wyznaczanie kierunku, monitorowanie, instruowanie i dopasowanie, raportowanie; to wykorzystanie informacji jako aktywatora Ładu.","zycie":"W klubie sportowym zarząd wyznacza trenerowi kierunek, trener daje zawodnikom zadania, a oni raportują wyniki; wszystko to wymaga przepływu wiadomości."},"bk_info_wartosc":{"kw":["wartoś","uzasadnienie biznesowe","informacj"],"pulapka":"Informacja nie ma wartości sama w sobie, tylko przez wykorzystanie (wewnętrzne lub sprzedaż); uzasadnienie biznesowe uwzględnia też korzyści niewymierne, np. zadowolenie klienta.","zycie":"Książka kucharska na półce nikogo nie nakarmi. Wartość ma dopiero wtedy, gdy ktoś z niej ugotuje obiad."},"bk_info_zasob":{"kw":["informacj","zasób","kluczowy zasób"],"pulapka":"Kluczowym zasobem w streszczeniu jest informacja, a nie technologia; technologia tylko towarzyszy informacji przez cały jej cykl, od utworzenia do zniszczenia.","zycie":"Przepisy babci to rodzinny skarb: zapisane w zeszycie, skopiowane, a na końcu wyrzucone; na każdym etapie potrzebny jest długopis, ksero albo niszczarka."},"bk_info_zasob_przyk":{"kw":["raport","analiz","informacj"],"pulapka":"Raporty dla zarządu i informacje z analizy biznesowej to przykłady informacji, które same są ważnymi aktywatorami nadzoru i zarządzania.","zycie":"Rachunki i miesięczne podsumowanie wydatków pomagają rodzicom decydować o domowym budżecie."},"bk_inne_obszary":{"kw":["marketing","finans","cele przedsiębiorstwa"],"pulapka":"Na cele przedsiębiorstwa wpływają też np. finanse i marketing, ale COBIT 5 uwzględnia tylko działania i cele związane z IT.","zycie":"Na wygraną drużyny wpływają obrońcy i napastnicy, ale poradnik dla bramkarzy omawia tylko bramkarza."},"bk_integr_41":{"kw":["integralność","kompletność","dokładność"],"pulapka":"Integralność z COBIT 4.1 odpowiada w COBIT 5 kompletności i dokładności; wiarygodność z 4.1 to wiarygodność, reputacja i obiektywność.","zycie":"Lista zakupów jest „cała i zdrowa”, gdy niczego nie brakuje i wszystko wpisano poprawnie: dwa litry mleka, a nie dwadzieścia."},"bk_inter_cykl":{"kw":["interesariusz","cykl życia informacji","faz"],"pulapka":"Wymiar interesariuszy informacji nie jest niezależny: w różnych fazach cyklu życia występują różni interesariusze, więc role definiuje się, odwołując się do faz cyklu życia.","zycie":"Przy zbiorze jabłek zrywają je dzieci, przechowuje dziadek w piwnicy, a jedzą wszyscy; w każdej fazie ważny jest ktoś inny."},"bk_iso15504":{"kw":["15504","iso"],"pulapka":"PCM oparto na normie ISO/IEC 15504 (ocena procesów), a nie na ISO/IEC 38500 czy ISO/IEC 27001.","zycie":"Jak przepisy, według których egzaminator na prawo jazdy ocenia każdego kandydata tak samo."},"bk_iso38500":{"kw":["38500","oszacuj, kieruj i monitoruj","edm"],"pulapka":"ISO/IEC 38500 ma 6 zasad (Odpowiedzialność, Strategia, Nabycie, Sprawność, Zgodność, Zachowanie ludzi), a COBIT 5 ma 5 zasad; nie myl tych list.","zycie":"Sześć zasad dobrego zarządu wspólnoty: kto za co odpowiada, plan, zakupy, ocena wyników, przestrzeganie przepisów i dbanie o mieszkańców."},"bk_it_bsc":{"kw":["it bsc","bsc","wymiar"],"pulapka":"IT BSC ma te same cztery wymiary co BSC (Finanse, Klient, Obszar wewnętrzny, Szkolenie i rozwój), ale porządkuje cele związane z IT.","zycie":"Domowy komputer oceniasz z czterech stron: ile kosztuje, czy zadowala domowników, czy sprawnie działa i czy rodzina umie z niego korzystać."},"bk_jak_kont_def":{"kw":["jakość kontekstow","kontekstow","istotn"],"pulapka":"Jakość kontekstowa to dopasowanie wyników do celu w kontekście (istotne, kompletne, aktualne, spójne, zrozumiałe); dokładność i obiektywność to jakość rzeczywista.","zycie":"Prognoza pogody może być dokładna, ale przed wyjściem w góry przyda się tylko aktualna, dla właściwego miejsca i zrozumiała."},"bk_jak_rzecz_def":{"kw":["jakość rzeczywist","dokładn","obiektywn"],"pulapka":"Jakość rzeczywista to dokładność, obiektywność i uznane wyniki; istotność, kompletność czy aktualność należą do jakości kontekstowej.","zycie":"Waga kuchenna pokazuje dokładnie 500 g, gdy kładziesz na niej 500 g; działa rzetelnie i obiektywnie."},"bk_jb_info":{"kw":["ograniczony dostęp","dostęp i bezpieczeństwo","dostępność"],"pulapka":"Jakość dostępu i bezpieczeństwa to dostępność/terminowość i ograniczony dostęp; poufność z COBIT 4.1 odpowiada ograniczonemu dostępowi, a nie dokładności.","zycie":"Książeczka zdrowia dziecka jest pod ręką, gdy trzeba iść do lekarza, ale nie leży na ławce w parku dla obcych."},"bk_jk_info":{"kw":["jakość kontekstowa","istotność","kompletność"],"pulapka":"Jakość kontekstowa i reprezentacji obejmuje m.in. istotność, kompletność, aktualność, odpowiednią ilość, zwięzłe i spójne przedstawienie; wiarygodność należy do jakości wewnętrznej.","zycie":"Rozkład jazdy pomaga, gdy dotyczy twojej linii, jest kompletny, aktualny, nieprzegadany, czytelny i w zrozumiałym języku."},"bk_jr_info":{"kw":["jakość wewnętrzna","obiektywność","reputacja"],"pulapka":"Jakość wewnętrzna informacji (podręcznik: rzeczywista) to dokładność, obiektywność, wiarygodność i reputacja; aktualność i kompletność należą do jakości kontekstowej.","zycie":"Prognoza pogody od znanego meteorologa: dokładna, bezstronna, godna zaufania i z renomowanego źródła, zanim sprawdzisz, czy pasuje do twoich planów."},"bk_kask_k1":{"kw":["wymiern","kaskad","poziom"],"pulapka":"Kaskada definiuje istotne i wymierne cele i zadania na różnych poziomach odpowiedzialności, a nie jeden cel dla całej firmy.","zycie":"W drużynie cel „awans do wyższej ligi” rozkłada się na mierzalne cele trenera, kapitana i każdego zawodnika."},"bk_kask_k2":{"kw":["baza wiedzy","filtr","kaskad"],"pulapka":"Kaskada filtruje bazę wiedzy COBIT 5 według celów przedsiębiorstwa, by wybrać wytyczne do wdrożenia, doskonalenia i audytu; nie tworzy nowych wytycznych.","zycie":"Z grubej książki kucharskiej wybierasz tylko przepisy pasujące do diety rodziny, a reszta zostaje na półce."},"bk_kask_k3":{"kw":["kaskad","aktywator","komunik"],"pulapka":"Kaskada identyfikuje i komunikuje, jak aktywatory pomagają osiągnąć cele przedsiębiorstwa; to trzecia z trzech wymienionych korzyści.","zycie":"Tablica na lodówce pokazuje, jak zmywanie, zakupy i odkurzanie każdego domownika składają się na czysty, spokojny dom."},"bk_kask_korz":{"kw":["kaskad","priorytet"],"pulapka":"Kaskada pozwala ustalić priorytety wdrożenia, doskonalenia i audytu na podstawie celów przedsiębiorstwa i związanego z nimi ryzyka; nie wyznacza poziomów potencjału procesów.","zycie":"Lista celów rodziny pokazuje, który remont zrobić najpierw: przeciekający dach przed nową kuchnią."},"bk_kask_o1":{"kw":["priorytet","kaskad","zmienia"],"pulapka":"Każde przedsiębiorstwo inaczej ustala priorytety celów i mogą się one zmieniać w czasie; to pierwszy powód, by nie stosować kaskady mechanicznie.","zycie":"W jednym domu najważniejszy jest ogród, w drugim garaż, a po narodzinach dziecka priorytety obu domów się zmieniają."},"bk_kask_o2":{"kw":["branż","wielkoś","mapowani"],"pulapka":"Tabele mapowania nie uwzględniają wielkości przedsiębiorstwa ani branży; są „wspólnym mianownikiem”, a nie wynikiem dopasowanym do firmy.","zycie":"Tabela rozmiarów w katalogu to średnia; nie powie, jaki but pasuje przedszkolakowi, a jaki koszykarzowi."},"bk_kask_o3":{"kw":["continuum","kontinuum","dwa poziomy"],"pulapka":"Mapowanie ma tylko dwa poziomy istotności (P i S), choć w rzeczywistości powiązania tworzą kontinuum; to ograniczenie, a nie zaleta tabel.","zycie":"Ocena potraw „lubię / bardzo lubię” upraszcza sprawę, bo naprawdę smak ma wiele odcieni."},"bk_kask_ostr":{"kw":["mechaniczn","uniwersaln","wytyczn"],"pulapka":"Kaskada nie zawiera uniwersalnej prawdy i nie należy stosować jej mechanicznie; pułapką są odpowiedzi „obowiązkowa”, „normatywna”, „stosować dokładnie”.","zycie":"Przepis mówi „piecz 40 minut”, ale twój piekarnik piecze szybciej, więc traktujesz przepis jako wskazówkę."},"bk_kask_p1":{"kw":["wagi","istotnoś","priorytet"],"pulapka":"Nadanie wag to przełożenie priorytetów strategicznych na istotność każdego celu przedsiębiorstwa, a nie celów IT czy procesów.","zycie":"Rodzina daje punkty życzeniom: wakacje 5, rower 3, telewizor 1, i już wie, na co wydać najpierw."},"bk_kask_p2":{"kw":["weryfik","mapowani","branż"],"pulapka":"Weryfikacja mapowania uwzględnia specyfikę środowiska i branży; to drugi podany przykład dostosowania kaskady, obok nadania wag.","zycie":"Plan treningów z podręcznika trener sprawdza pod kątem swojego boiska, wieku zawodników i ligi."},"bk_kask_prakt":{"kw":["dostosow","kaskad","mapowani"],"pulapka":"Pierwszą czynnością przy korzystaniu z kaskady jest zawsze dostosowanie mapowania do własnej sytuacji, a nie przyjęcie tabel COBIT bez zmian.","zycie":"Gotowy projekt remontu z gazety najpierw przerabiasz na własne mieszkanie, porównujesz z oryginałem i poprawiasz szczegóły."},"bk_kask_zrodlo":{"kw":["kaskad","badani"],"pulapka":"Kaskada celów opiera się na badaniach Antwerp Management School, IT Alignment and Governance Institute w Belgii, a nie na normie ISO.","zycie":"Przepis najpierw sprawdzili w pracowni naukowcy, a dopiero potem trafił do książki kucharskiej."},"bk_kaskada":{"kw":["kaskad","cele przedsiębiorstwa","cele aktywator"],"pulapka":"Kaskada biegnie od potrzeb interesariuszy przez cele przedsiębiorstwa i cele związane z IT do celów aktywatorów; odwrócona kolejność lub pominięty poziom to typowa pułapka.","zycie":"Rodzina chce żyć zdrowo; z tego wynika cel „więcej warzyw”, potem „zakupy co tydzień na targu”, a na końcu konkretna lista zakupów."},"bk_kcs":{"kw":["czynniki sukcesu","czynnik sukcesu","kluczowe czynniki"],"pulapka":"Kluczowych czynników sukcesu jest pięć: wsparcie kierownictwa, zrozumienie celów, komunikacja, dostosowanie, szybkie korzyści; nie myl ich z punktami zapalnymi.","zycie":"Udany remont: głowa rodziny go popiera, wszyscy znają cel, ludzie rozmawiają, plan pasuje do mieszkania, a najpierw robi się łatwe rzeczy."},"bk_kcs1":{"kw":["najwyższego kierownictwa","wsparci","kierownictw"],"pulapka":"Czynnik sukcesu to wytyczne, uprawnienia i stałe, widoczne wsparcie najwyższego kierownictwa, a nie jednorazowa zgoda na start projektu.","zycie":"Gdy trener publicznie popiera nowy plan treningów i sam przychodzi na zajęcia, zawodnicy też go przyjmują."},"bk_kcs2":{"kw":["cele biznesowe","rozumie","zrozumie"],"pulapka":"Cele biznesowe i cele IT muszą rozumieć wszystkie strony wspierające procesy nadzoru i zarządzania, a nie tylko dział IT lub tylko zarząd.","zycie":"Każdy domownik wie, że oszczędzamy na wakacje, więc rozumie, czemu gasi się światło."},"bk_kcs3":{"kw":["komunikacj","zmian"],"pulapka":"Efektywna komunikacja i umożliwienie koniecznych zmian to jeden czynnik sukcesu; samo ogłoszenie zmiany, bez wsparcia, nie wystarczy.","zycie":"Przed przemeblowaniem mama mówi wszystkim, co się zmieni i dlaczego, i pomaga każdemu przenieść rzeczy."},"bk_kcs4":{"kw":["dostosow","kontekst"],"pulapka":"Dostosować trzeba zarówno COBIT, jak i inne dobre praktyki i normy do unikalnego kontekstu przedsiębiorstwa; COBIT nie jest wdrażany „z pudełka”.","zycie":"Gotowy projekt kuchni z katalogu dopasowujesz do wymiarów pomieszczenia i rur w twoim mieszkaniu."},"bk_kcs5":{"kw":["szybkie korzyści","szybkich korzyści","quick win"],"pulapka":"Priorytet mają szybkie korzyści oraz usprawnienia najkorzystniejsze i najłatwiejsze; nie te najtrudniejsze ani najbardziej kosztowne.","zycie":"Sprzątanie strychu zaczynasz od wyniesienia oczywistych śmieci; szybki efekt zachęca do dalszej pracy."},"bk_kcs_nadzor":{"kw":["kluczowe czynniki sukcesu","rozliczalnoś"],"pulapka":"Dwa kluczowe czynniki sukcesu Ładu z zasady Sprawność: zatwierdzenie celów przez interesariuszy i akceptacja rozliczalności przez dyrektorów i kierowników; nie myl ich z czynnikami sukcesu wdrożenia.","zycie":"Wspólny wyjazd klasy się uda, gdy rodzice zatwierdzą cel, a wychowawca i trójka klasowa przyjmą odpowiedzialność za jego realizację."},"bk_kont1":{"kw":["kontekst","kultur","etyk"],"pulapka":"Etyka i kultura to czynnik kontekstu do planu wdrożenia, a zarazem treść aktywatora „Kultura, etyka i zachowanie”; nie mieszaj tych dwóch list.","zycie":"Remont w rodzinie, w której wszyscy są szczerzy i zgodni, planujesz inaczej niż w domu pełnym kłótni."},"bk_kont10":{"kw":["branż","praktyk","kontekst"],"pulapka":"Praktyki stosowane w branży to dziesiąty czynnik kontekstu wdrożenia; COBIT często opiera się na innych standardach, które też trzeba dostosować.","zycie":"Sklep osiedlowy podpatruje, jak inne sklepy wprowadziły płatność telefonem, zanim sam to zrobi."},"bk_kont2":{"kw":["przepis","regulacj","kontekst"],"pulapka":"Obowiązujące przepisy, regulacje i polityki to czynnik kontekstu do planu wdrożenia; nie myl go z punktem zapalnym „niespełnianie wymogów regulacyjnych”.","zycie":"Przebudowa domu musi uwzględnić prawo budowlane, warunki wspólnoty mieszkaniowej i regulamin osiedla."},"bk_kont3":{"kw":["misj","wizj","kontekst"],"pulapka":"Misja, wizja i wartości to czynnik kontekstu do planu wdrożenia, a nie element listy 17 celów przedsiębiorstwa (Rysunek 5).","zycie":"Drużyna z misją „szkolimy młodzież” zmienia klub inaczej niż drużyna, która ma tylko wygrywać."},"bk_kont4":{"kw":["polityk","nadzor","kontekst"],"pulapka":"Istniejące polityki i praktyki nadzoru to czynnik kontekstu; COBIT zaleca wykorzystać i rozwinąć istniejące aktywatory ładu, a nie zaczynać od zera.","zycie":"Jeśli w domu działa już zwyczaj rodzinnej narady o budżecie, nowy plan oszczędzania warto oprzeć właśnie na niej."},"bk_kont5":{"kw":["strategi","kontekst"],"pulapka":"Plan biznesowy i strategiczne kierunki to jeden z dziesięciu czynników kontekstu do planu wdrożenia; nie myl go z uzasadnieniem biznesowym (business case).","zycie":"Rodzina, która za rok planuje przeprowadzkę, nie zrobi teraz drogiego remontu kuchni."},"bk_kont6":{"kw":["dojrzałoś","model operacyjn","kontekst"],"pulapka":"Model operacyjny i poziom dojrzałości to czynnik kontekstu; „dojrzałość” nie oznacza tu poziomu potencjału procesu z rozdziału 8.","zycie":"Klub amatorski z jednym trenerem wprowadza zmiany prościej niż zawodowy klub z wieloma działami i długą tradycją."},"bk_kont7":{"kw":["styl zarządzania","kontekst","zarządzani"],"pulapka":"Styl zarządzania to czynnik kontekstu do planu wdrożenia; nie jest kategorią aktywatora ani wymiarem aktywatora.","zycie":"Jeden ojciec decyduje sam, inny pyta całą rodzinę; nowe domowe zasady wprowadzi się u nich inaczej."},"bk_kont8":{"kw":["apetyt na ryzyko","ryzyk","kontekst"],"pulapka":"Apetyt na ryzyko wymieniono jako wewnętrzny czynnik kontekstu kaskady i kontekstu wdrożenia. Zmiana apetytu może też w praktyce pobudzić doskonalenie; listy w podręczniku nie są rozłączną klasyfikacją wszystkich sytuacji.","zycie":"Jedna rodzina jeździ zimą w góry bez łańcuchów, druga zostaje w domu przy pierwszym śniegu."},"bk_kont9":{"kw":["zasob","potencjał","kontekst"],"pulapka":"Potencjał i dostępne zasoby to czynnik kontekstu wdrożenia; „potencjał” nie oznacza tu poziomu potencjału procesu (PCM).","zycie":"Remont planujesz na miarę oszczędności i rąk do pracy w rodzinie, a nie na miarę marzeń z katalogu."},"bk_kont_aktyw":{"kw":["istniejąc","aktywator","ładu korporacyjnego"],"pulapka":"Należy wykorzystać i rozwinąć istniejące aktywatory ładu korporacyjnego; podejście „zacznij od zera i zastąp wszystko COBIT-em” jest błędne.","zycie":"Do nowego grafiku domowego wykorzystujesz stary kalendarz na lodówce, zamiast kupować nowy i uczyć wszystkich od początku."},"bk_kontekst_wew":{"kw":["apetyt na ryzyko","wewnętrzn","kultur"],"pulapka":"Apetyt na ryzyko jest w COBIT 5 czynnikiem wewnętrznym kontekstu (obok kultury i organizacji), a nie zewnętrznym.","zycie":"Jedna rodzina lubi spontaniczne wyjazdy, druga planuje wszystko co do minuty; ich zwyczaje decydują o sposobie planowania."},"bk_kontekst_zew":{"kw":["zewnętrzn","geopolityczn","rynek"],"pulapka":"Rynek, branża i sytuacja geopolityczna to czynniki zewnętrzne; kultura, organizacja i apetyt na ryzyko to wewnętrzne; egzamin lubi je mieszać.","zycie":"Ceny paliwa, nowe przepisy drogowe i pogoda wpływają na to, jak rodzina planuje wakacyjny wyjazd autem."},"bk_korzysci_formy":{"kw":["usługi publiczn","finansow","korzyś"],"pulapka":"Korzyści nie muszą być finansowe: w podmiotach rządowych są nimi usługi publiczne; tworzenie wartości dotyczy także firm niekomercyjnych.","zycie":"Dla piekarni korzyścią jest zarobek, a dla gminnej biblioteki zadowoleni czytelnicy i wypożyczone książki."},"bk_kr_sr":{"kw":["krąg środkowy","umożliwienie zmian","rysunek 17"],"pulapka":"Krąg środkowy to umożliwienie zmian (zachowanie i kultura); nie myl go z kręgiem zewnętrznym, czyli zarządzaniem programem.","zycie":"Przy nowych domowych zasadach trzeba zadbać o nastroje: tłumaczyć, chwalić i rozumieć opory."},"bk_kr_wew":{"kw":["krąg wewnętrzny","ciągłego doskonalenia","rysunek 17"],"pulapka":"Krąg wewnętrzny Rysunku 17 to cykl życia ciągłego doskonalenia; zarządzanie programem to krąg zewnętrzny.","zycie":"Sprzątanie domu to nie jednorazowa akcja: robisz je co tydzień i za każdym razem trochę lepiej."},"bk_kr_zew":{"kw":["krąg zewnętrzny","zarządzanie programem","rysunek 17"],"pulapka":"Krąg zewnętrzny to zarządzanie programem; umożliwienie zmian to krąg środkowy, a ciągłe doskonalenie to krąg wewnętrzny.","zycie":"Kierownik budowy pilnuje harmonogramu, budżetu i ekip, żeby cały remont szedł jako jedna całość."},"bk_krok2":{"kw":["cele przedsiębiorstwa","bsc","17 cel"],"pulapka":"Celów przedsiębiorstwa jest 17, opartych na wymiarach BSC; lista jest typowa i niewyczerpująca, a tabela potrzeb i celów jest w Załączniku D.","zycie":"Życzenia domowników („chcę spokoju”, „chcę oszczędzać”) dopasowujesz do kilku typowych haseł z gotowej listy celów rodziny."},"bk_krok3":{"kw":["cele związane z it","załącznik b","it bsc"],"pulapka":"Celów związanych z IT jest 17, uporządkowanych wg IT BSC; mapowanie celów przedsiębiorstwa na cele IT to Załącznik B, nie C.","zycie":"Rodzina chce oszczędzać, więc stawia cele domowym sprzętom: energooszczędna pralka i termostat, który sam przykręca grzejniki."},"bk_krok4":{"kw":["załącznik c","cele aktywator","krok 4"],"pulapka":"Cele aktywatorów to ostatni krok kaskady; mapowanie celów IT na procesy jest w Załączniku C, ale cele dotyczą wszystkich aktywatorów, nie tylko procesów.","zycie":"Cel „zdrowe obiady” wymaga przepisów, garnków, umiejętności gotowania i zwyczaju wspólnego jedzenia; każde z nich dostaje własny cel."},"bk_lv1_wazny":{"kw":["poziom 1","pa 1.1","ważnym osiągnięciem"],"pulapka":"Poziom 1 istotnie różni się od wyższych: sprawdza, czy proces osiąga cel (PA 1.1 co najmniej W); już sam poziom 1 podręcznik nazywa ważnym osiągnięciem.","zycie":"Pierwszy samodzielny przejazd bez instruktora to już duży sukces, choć do rajdowca daleko. Liczy się, że dojechałeś na miejsce."},"bk_lv_def0":{"kw":["proces niekompletny","poziom 0"],"pulapka":"Poziom 0 to „proces niekompletny”, a nie „nieistniejący” (nazwa z COBIT 4.1): proces może działać, ale nie osiągać celu, np. PA 1.1 ocenione na C daje poziom 0.","zycie":"Drużyna zapisana do ligi, ale na mecze nie przychodzi albo przegrywa walkowerem. Niby istnieje, lecz celu nie osiąga."},"bk_lv_def1":{"kw":["proces wykonywany","pa 1.1","poziom 1"],"pulapka":"Poziom 1 ma jeden atrybut, PA 1.1 Wykonanie procesu, ocenione co najmniej na W; planowanie i monitorowanie realizacji to dopiero poziom 2 (PA 2.1).","zycie":"Obiad jest ugotowany i rodzina najedzona, choć bez przepisu i planu zakupów. Cel osiągnięty, nawet jeśli chaotycznie."},"bk_lv_def2":{"kw":["proces zarządzany","pa 2.1","pa 2.2"],"pulapka":"Poziom 2 ma dwa atrybuty: PA 2.1 Zarządzanie wydajnością i PA 2.2 Zarządzanie produktami pracy; zdefiniowany standardowy proces pojawia się dopiero na poziomie 3.","zycie":"Remont łazienki z harmonogramem, kontrolą postępów i poprawkami planu, a faktury i projekty trzymane porządnie w jednym segregatorze."},"bk_lv_def3":{"kw":["proces ustanowiony","pa 3.1","pa 3.2"],"pulapka":"Poziom 3 to „proces ustanowiony”: PA 3.1 Definicja i PA 3.2 Wdrożenie procesu; „zdefiniowany proces” to nazwa poziomu 3 w COBIT 4.1, nie w COBIT 5.","zycie":"Sieć pizzerii definiuje standardowy proces wypieku. Lokale wdrażają go z uzgodnionym dostosowaniem do wyposażenia, a personel ma potrzebne umiejętności i zasoby. Samo spisanie receptury nie wystarcza."},"bk_lv_def4":{"kw":["proces przewidywalny","pa 4.1","pa 4.2"],"pulapka":"Poziom 4 to „proces przewidywalny” (PA 4.1 Miara, PA 4.2 Kontrola procesu), a nie „zarządzany i mierzalny” – tak nazywał się poziom 4 w COBIT 4.1.","zycie":"Piekarnia mierzy temperaturę pieca i czas wypieku, więc każdy bochenek wychodzi w ustalonych granicach, dzień po dniu."},"bk_lv_def5":{"kw":["proces zoptymalizowany","pa 5.1","pa 5.2","optymalizujący"],"pulapka":"Poziom 5 (egzamin: proces zoptymalizowany, podręcznik: optymalizujący) ma PA 5.1 Innowacja i PA 5.2 Optymalizacja; poziom docelowy bardzo rzadko jest najwyższy.","zycie":"Trener po każdym sezonie szuka przyczyn porażek i wprowadza nowe metody treningu, by drużyna nadążała za obecnymi i przyszłymi ambicjami klubu."},"bk_lv_docel":{"kw":["poziom docelowy","docelowy poziom","korzyści"],"pulapka":"Poziom docelowy wybiera organizacja na podstawie kosztów, korzyści i wykonalności; bardzo rzadko jest to najwyższy poziom, więc odpowiedź „zawsze poziom 5” jest błędna.","zycie":"Rodzina nie buduje w ogródku basenu olimpijskiego dla dzieci; wystarczy brodzik, na który ją stać i który ma sens."},"bk_lv_regula":{"kw":["co najmniej w","w pełni","poziom 3"],"pulapka":"Wyższy poziom wymaga oceny P (pełny) atrybutów niższych poziomów i co najmniej W atrybutów danego poziomu; ocena W na poziomie 2 nie pozwala uzyskać poziomu 3.","zycie":"Do drugiej klasy przechodzisz dopiero po zaliczeniu w całości pierwszej; w nowej klasie wystarczy na razie radzić sobie dobrze, nie od razu perfekcyjnie."},"bk_map_b":{"kw":["rysunek 22","cele związane z it","cele organizacji"],"pulapka":"Rysunek 22 mapuje 17 celów organizacji (wymiary BSC) na 17 celów związanych z IT (IT BSC); mapowanie celów IT na 37 procesów to Rysunek 23 z Załącznika C.","zycie":"Tabela w kuchni pokazuje, które produkty z lodówki są potrzebne do których obiadów w tygodniu: kolumny to dania, wiersze to składniki."},"bk_map_c":{"kw":["rysunek 23","37 procesów","cele związane z it"],"pulapka":"Rysunek 23 mapuje 17 celów związanych z IT na 37 procesów COBIT 5 według domen, skalą P/S; powiązanie celów organizacji z celami IT jest w Rysunku 22.","zycie":"Grafik w domu: wiersze to domownicy, kolumny to obowiązki, a w kratce widać, kto głównie, a kto tylko pomocniczo odpowiada za dane zadanie."},"bk_map_c_ps":{"kw":["podstawow","drugorzędn","mapowani"],"pulapka":"W Załączniku C P/S mówi, czy proces ma podstawowe czy drugorzędne znaczenie dla celu IT; to ta sama skala co w Załączniku B, a w Załączniku D jej nie ma.","zycie":"W tabeli planowania podróży przypisujesz środkom transportu podstawowe lub wspierające znaczenie dla poszczególnych celów. To ocena siły relacji, a nie oznaczenie rzeczy bezwzględnie koniecznych i zbędnych."},"bk_map_d":{"kw":["potrzeby interesariuszy","rysunek 7","cele organizacji"],"pulapka":"Rysunek 24 łączy pytania wewnętrznych interesariuszy (z Rysunku 7) z 17 celami organizacji; to nie mapowanie celów IT na procesy ani celów organizacji na cele IT.","zycie":"Lista życzeń domowników („chcę ciszy”, „chcę oszczędzać”) przypięta do celów domowego budżetu pokazuje, który cel odpowiada na które życzenie."},"bk_map_d_uzycie":{"kw":["priorytet","potrzeby interesariuszy","kaskad"],"pulapka":"Tabelę z Załącznika D używa się do wyznaczania i priorytetyzacji celów organizacji lub celów IT na podstawie potrzeb interesariuszy, ale nie mechanicznie – to sugerowany typowy zbiór.","zycie":"Gdy kibice najgłośniej narzekają na brak parkingu, klub wie, którą inwestycję zrobić najpierw."},"bk_map_d_zasada":{"kw":["potrzeby interesariuszy","zaznacz","cele organizacji"],"pulapka":"W Rysunku 24 komórka jest po prostu wypełniona, gdy potrzeba dotyczy danego celu; nie ma tu skali P/S znanej z Załączników B i C.","zycie":"Na liście zakupów tylko odhaczasz „tak” albo „nie”, bez oceniania, czy produkt jest bardzo czy trochę potrzebny."},"bk_map_ostroznie":{"kw":["mechaniczn","kaskad","dostosow"],"pulapka":"Tabele mapowań to typowy zbiór relacji, a nie mechaniczna reguła: sytuacja każdej organizacji jest inna, więc kaskadę celów trzeba do niej dostosować.","zycie":"Jadłospis dietetyka dla przeciętnej osoby to dobry punkt wyjścia, ale nie stosuje się go ślepo u kogoś z alergią; trzeba go dopasować."},"bk_map_ps":{"kw":["podstawow","drugorzędn","wspierając"],"pulapka":"W mapowaniach P oznacza relację podstawową (Primary), a S wspierającą (Secondary), wciąż silną; to nie skala ocen N, C, W, P, gdzie P znaczy „pełny”.","zycie":"Dla celu „ciepłe mieszkanie” sprawny piec ma znaczenie podstawowe, a lepsze uszczelki wspierające. Obie relacje są istotne; ich ocenę dopasowujesz do konkretnego domu."},"bk_map_zrodla":{"kw":["badań","mapowani"],"pulapka":"Mapowania oparto na badaniach Antwerp Management School (IT Alignment and Governance Research Institute) i opiniach ekspertów; nie wynikają z normy ISO/IEC 15504 ani z COBIT 4.1.","zycie":"Przepis na najlepszy chleb we wsi zebrano z badań w piekarniach i podpowiedzi doświadczonych piekarzy, a nie wymyślono przy biurku."},"bk_metodyki_cechy":{"kw":["struktury ramowe","kompleksow","elastyczn"],"pulapka":"Struktury ramowe (podręcznik: metodyki) mają być kompleksowe, otwarte i elastyczne, aktualne i dostępne dla interesariuszy; to nie cechy polityk ani kryteria zasad.","zycie":"Dobry poradnik remontowy obejmuje wszystkie pomieszczenia, pozwala dopasować się do własnego mieszkania, jest aktualny i leży tam, gdzie każdy zajrzy."},"bk_miernik_def":{"kw":["smart","miernik"],"pulapka":"Miernik to wymierna jednostka pomiaru celu procesu spełniająca SMART: specyficzny, wymierny, oparty na działaniach, istotny, terminowy; „S” nie znaczy „strategiczny”.","zycie":"Zamiast „dużo biegać” zapisujesz: 5 km trzy razy w tygodniu do końca miesiąca. Konkretnie, policzalnie i z terminem."},"bk_mm41_kroki":{"kw":["model dojrzałości","cobit 4.1","cele kontrolne"],"pulapka":"Cele kontrolne, modele dojrzałości i mechanizmy kontrolne procesów (PC) to elementy COBIT 4.1; w COBIT 5 zastąpił je model zdolności procesu oparty na ISO/IEC 15504.","zycie":"Jak ocena w szkole jazdy z czterech osobnych arkuszy: lista zadań, skala zaawansowania, sześć cech kierowcy i dodatkowa lista kontrolna. Dużo papierów, które częściowo się dublują."},"bk_mm41_pc":{"kw":["mechanizmy kontrolne procesów","cobit 4.1","atrybut"],"pulapka":"Mechanizmy kontrolne procesów (PC) to typowe cele kontrolne COBIT 4.1, częściowo pokrywające się z atrybutami modelu dojrzałości; w COBIT 5 ich treść przeniesiono na poziomy 2–5.","zycie":"Przy przeglądzie auta mechanik ma listę kontrolną i osobną tabelę ocen, a połowa punktów występuje w obu. Sprawdza to samo dwa razy."},"bk_mm_cel":{"kw":["dojrzałoś","tak jest","luk"],"pulapka":"Modele dojrzałości COBIT 4.1, Risk IT i Val IT mierzą stan „tak jest”, „tak ma być” i lukę; PCM COBIT 5 ma te same cele, ale inny projekt i sposób użycia.","zycie":"Na wadze widzisz, ile ważysz teraz, ile chcesz ważyć i ile kilogramów dzieli cię od celu."},"bk_mon_2poz":{"kw":["edm05","mea","monitorowani"],"pulapka":"COBIT 5 ma dwa poziomy monitorowania: Ładu (EDM05, rola dyrektora) i Zarządzania (MEA); MEA to domena Zarządzania, a nie Ładu.","zycie":"W klubie piłkarskim zarząd sprawdza, czy sezon idzie zgodnie z planem, a trener codziennie śledzi formę zawodników. Dwa piętra kontroli."},"bk_mon_nadzor_def":{"kw":["monitorowani","organ nadzorując","wcielon"],"pulapka":"W Ładzie monitorowanie to sprawdzanie przez organ nadzorujący, w jakim stopniu kierunek wcielono w życie; nie myl go z operacyjnym monitorowaniem w MEA.","zycie":"Właściciel domu sprawdza, czy budowa idzie zgodnie z jego ustaleniami, a nie sam mierzy ściany."},"bk_nadzor_def":{"kw":["edm","kierowani","ocena, kierowanie"],"pulapka":"Ład to Ocena, Kierowanie, Monitorowanie (EDM); planowanie, budowanie i uruchamianie należą do Zarządzania, więc „planowanie” w definicji Ładu to pułapka.","zycie":"Rodzice oceniają, na co wydać pieniądze w tym roku, mówią „najpierw dach” i sprawdzają, czy fachowcy robią to, co ustalono."},"bk_nadzor_kto":{"kw":["prezes","zarząd","organ nadzorując"],"pulapka":"Za Ład zwykle odpowiada organ nadzorujący (board), kierowany przez przewodniczącego; zadania można delegować. Za Zarządzanie odpowiada kierownictwo wykonawcze pod przywództwem CEO. Polski podręcznik tłumaczy board/chairman jako „zarząd/prezes”; nie utożsamiaj przez to przewodniczącego z CEO w każdym ustroju organizacji.","zycie":"W klubie piłkarskim kierunek wyznacza zarząd z prezesem na czele, a w dużym klubie część spraw oddaje np. komisji finansowej."},"bk_nadzor_negocjacja":{"kw":["negocj","interesariusz","wartoś"],"pulapka":"Ład negocjuje i decyduje o wartości dla różnych interesariuszy, uwzględniając wszystkich; nie chodzi o spełnienie oczekiwań jednej grupy, np. akcjonariuszy.","zycie":"Na rodzinnej naradzie o wakacjach dzieci chcą basenu, babcia spokoju, a rodzice niskiej ceny; trzeba wynegocjować wspólną decyzję."},"bk_oc1":{"kw":["porówna","ocena zdolności"],"pulapka":"Porównywanie zdolności procesów to cel oceny dla organu Ładu i kierownictwa; nie myl go z porównywaniem wyników COBIT 4.1 i COBIT 5, które podręcznik uznaje za trudne.","zycie":"Rodzice porównują oceny dzieci z różnych przedmiotów na jednej skali, żeby wiedzieć, gdzie potrzebny jest korepetytor."},"bk_oc2":{"kw":["jak jest","jak ma być","inwestyc"],"pulapka":"Określenie „jak jest” i „jak ma być” jest wysokopoziomowe i przybliżone; ma ułatwić organowi Ładu i kierownictwu decyzje inwestycyjne o usprawnieniu procesów, nie zastępuje szczegółowego audytu.","zycie":"Przed przeprowadzką mierzysz obecne mieszkanie i rysujesz wymarzone, żeby zdecydować, na co wydać pieniądze."},"bk_oc3":{"kw":["analiza luk","analizy luk","doskonal"],"pulapka":"Analiza luk daje informacje do planowania udoskonaleń i możliwych do uzasadnienia projektów doskonalenia; w cyklu wdrożenia to faza 3 („Do czego dążymy?”), a nie faza 2.","zycie":"Między obecną kondycją a półmaratonem jest różnica; lista brakujących treningów staje się planem, który łatwo uzasadnić przed rodziną."},"bk_oc4":{"kw":["klasyfikac","monitorowan","ocena zdolności"],"pulapka":"Klasyfikacja ocen służy organowi Ładu i kierownictwu do pomiaru i monitorowania aktualnej zdolności procesów; nie jest rankingiem pracowników ani oceną ich kompetencji.","zycie":"Kreski na framudze drzwi, rysowane przez lata, pozwalają rodzicom śledzić, czy dziecko rośnie prawidłowo."},"bk_oc_ambicja":{"kw":["poziom 1","wszystkich procesów"],"pulapka":"Ambicją wielu organizacji jest poziom 1 dla wszystkich procesów, bo inaczej po co je realizować; nie znaczy to, że COBIT wymaga dla każdego procesu poziomu 3 lub wyżej.","zycie":"Po co trzymać w domu pralkę, która nie pierze? Każde domowe urządzenie powinno przynajmniej robić to, do czego jest."},"bk_oc_cele":{"kw":["jak jest","analiza luk","ocena zdolności"],"pulapka":"Cztery cele oceny: porównanie zdolności, „jak jest” i „jak ma być”, analiza luk z planowaniem doskonalenia, klasyfikacja ocen do monitorowania; nie myl ich z pytaniami zarządzania wydajnością aktywatora.","zycie":"Przed remontem domu sprawdzasz stan każdego pokoju, ustalasz, jak ma wyglądać, liczysz różnicę i planujesz prace, a potem śledzisz postęp."},"bk_oc_cele_typ":{"kw":["certyfikac","samoocen","wewnętrzn"],"pulapka":"Ocena zdolności może mieć cel wewnętrzny (porównania, doskonalenie) albo zewnętrzny (formalna ocena, raportowanie, certyfikacja) z różnym rygorem; nie służy wyłącznie certyfikacji.","zycie":"Domowe ważenie się przed lustrem i oficjalne ważenie zawodnika przed walką to ta sama waga, ale inny rygor i inne konsekwencje."},"bk_oc_lv1_kroki":{"kw":["rezultat","praktyki bazowe","produkty pracy"],"pulapka":"Opis ogólnej oceny na s. 45 zaczyna się od wyników procesu i ratingu, potem uwzględnia praktyki bazowe i produkty pracy. Dokumenty mogą stanowić dowody wyników; nie wynika stąd zakaz korzystania z nich na początku oceny.","zycie":"Sprawdzając, czy tort się udał, najpierw patrzysz na sam tort, potem na to, czy zrobiono wszystkie kroki przepisu, a na końcu na zakupy i notatki."},"bk_oc_plan":{"kw":["praktyki bazowe","poziom 1","doskonal"],"pulapka":"Gdy brak poziomu 1, przyczynę wskazuje ocena praktyk bazowych (których brakuje lub które nie działają); nie zaczyna się od atrybutów poziomu 2, bo dotyczą zarządzania procesem.","zycie":"Gdy samochód nie odpala, najpierw stwierdzasz, że nie jedzie, a potem sprawdzasz, czego brakuje: paliwa, akumulatora czy świec."},"bk_oc_wyzsze":{"kw":["praktyki ogólne","typowe praktyki","15504"],"pulapka":"Wyższe poziomy ocenia się typowymi (ogólnymi) praktykami z ISO/IEC 15504-2, wspólnymi dla wszystkich procesów; praktyki bazowe danego procesu służą poziomowi 1.","zycie":"Zasady higieny w kuchni są te same, czy pieczesz ciasto, czy gotujesz zupę. Dotyczą sposobu pracy, a nie konkretnej potrawy."},"bk_p5_cele":{"kw":["apo08","relacj","zadowoleni"],"pulapka":"Przykładowe cele i mierniki dotyczą APO08 Zarządzanie relacjami; miernikiem dobrych relacji są ankiety zadowolenia użytkowników i personelu IT.","zycie":"Sklep osiedlowy chce dobrych relacji z klientami i sprawdza je krótką ankietą przy kasie."},"bk_p5_cykl":{"kw":["potencjał","15504","cykl życia"],"pulapka":"Solidność procesu zwiększa się przez podniesienie poziomu potencjału procesu (model oparty na ISO/IEC 15504), a nie poziomu dojrzałości COBIT 4.1.","zycie":"Nowy rodzinny zwyczaj niedzielnych obiadów: wymyślasz, wprowadzasz, obserwujesz, poprawiasz, a kiedyś go kończysz."},"bk_p5_inne":{"kw":["polityk","raci","umiejętnoś"],"pulapka":"Zasady i polityki formalizują proces: dlaczego istnieje, kogo dotyczy i jak go używać; umiejętności definiuje się dla ról, a struktury widać w tabeli RACI.","zycie":"Przy grafiku sprzątania ustalasz też, kto co umie, kto decyduje, i spisujesz, po co grafik w ogóle istnieje."},"bk_p5_praktyki":{"kw":["procesy umożliwiające","dobre praktyki","przewodnik"],"pulapka":"Dobre praktyki dla procesów szczegółowo opisuje przewodnik COBIT 5: Procesy umożliwiające (inspiracja i przykładowe procesy), a nie sama metodyka.","zycie":"Książka z gotowymi planami treningów dla każdej pozycji na boisku: bierzesz inspirację i dopasowujesz ją do drużyny."},"bk_p5_raci":{"kw":["raci","interesariusz"],"pulapka":"Interesariuszami procesu są wszystkie strony RACI, nie tylko wykonawcy; tabelę RACI opisuje przewodnik COBIT 5: Procesy umożliwiające.","zycie":"Przy przeprowadzce: kto nosi kartony, kto odpowiada za całość, kogo pytasz o zdanie, a komu tylko mówisz, że już po wszystkim."},"bk_pam":{"kw":["pam","model oceny procesu","oszacowani"],"pulapka":"Szczegóły oszacowania potencjału zawiera publikacja ISACA COBIT Process Assessment Model (PAM), a nie sama metodyka COBIT 5.","zycie":"Szczegółowy regulamin zawodów, który dokładnie opisuje, jak sędzia ma przyznawać punkty."},"bk_pbrm_41":{"kw":["cobit 4.1","dopasowanie, planowanie","apo"],"pulapka":"Domeny PBRM rozwijają domeny COBIT 4.1, a ich nazwy mają dodatkowe określenia, np. „Dopasowanie, planowanie i organizacja” (APO), nie samo „Planowanie”.","zycie":"Nowa mapa osiedla rozwija starą: te same dzielnice, ale z dokładniejszymi nazwami."},"bk_pcm":{"kw":["model potencjału","potencjał","15504"],"pulapka":"PCM opiera się na ISO/IEC 15504 i mierzy procesy EDM i PBRM; nie jest kontynuacją skali dojrzałości COBIT 4.1.","zycie":"Egzamin na kolejny pas w karate: sprawdza się, czy umiesz określone rzeczy, według jednej ustalonej skali."},"bk_pcm_korz":{"kw":["korzyści","model zdolności","zdolności procesu"],"pulapka":"Korzyści modelu zdolności to skupienie na celu procesu, uproszczenie, wiarygodność i powtarzalność ocen, użyteczność i zgodność ze standardem; nigdzie nie obiecuje wyższych wyników niż COBIT 4.1.","zycie":"Nowa instrukcja montażu mebli: jedna broszura zamiast czterech, jasne kroki, mniej sporów w rodzinie, czy dobrze skręcone, i zgodna z ogólną normą."},"bk_pcm_ograniczenie":{"kw":["siedmiu","aktywator","pełnego obrazu"],"pulapka":"Procesy to tylko jeden z siedmiu aktywatorów, więc ocena procesów nie daje pełnego obrazu nadzoru; trzeba ocenić też pozostałe aktywatory.","zycie":"Sprawdzenie samego silnika nie powie, czy auto jest w dobrym stanie; trzeba obejrzeć też hamulce, opony i kierowcę."},"bk_pk1":{"kw":["osiąga swój cel","rezultat","cel procesu"],"pulapka":"Pierwsza korzyść to skupienie na tym, czy proces faktycznie osiąga swój cel i wymagane rezultaty, a nie na dokumentacji czy ogólnej dojrzałości organizacji.","zycie":"Hydraulika ocenia się po tym, czy kran przestał cieknąć, a nie po tym, jak ładnie wypełnił papiery."},"bk_pk2":{"kw":["uproszczenie","powiel","cele kontrolne"],"pulapka":"Uproszczenie to usunięcie powielania treści: ocena w COBIT 4.1 wymagała typowego modelu dojrzałości, modeli dojrzałości procesów, celów kontrolnych i mechanizmów kontrolnych procesów.","zycie":"Zamiast czterech książek kucharskich, w których ten sam przepis powtarza się z drobnymi zmianami, kuchnia ma jedną."},"bk_pk3":{"kw":["powtarzalność","niezawodność","spor"],"pulapka":"Korzyścią jest większa wiarygodność i powtarzalność ocen, która ogranicza spory interesariuszy o wyniki; podręcznik nie mówi o szybszej ani tańszej ocenie.","zycie":"Dwóch sędziów ocenia ten sam skok i wystawia tę samą notę, bo mają jasne kryteria. Kibice nie kłócą się o wynik."},"bk_pk4":{"kw":["formaln","samoocen","zewnętrzn"],"pulapka":"Model daje podstawę do bardziej formalnej, rygorystycznej oceny zarówno do celów wewnętrznych, jak i zewnętrznych; nie służy wyłącznie nieformalnej samoocenie.","zycie":"Metoda oceniania z próbnego egzaminu na prawo jazdy przydaje się do nauki, a ta sama metoda działa też na egzaminie państwowym."},"bk_pk5":{"kw":["15504","standard","norm"],"pulapka":"Model zdolności COBIT 5 opiera się na uznanej normie ISO/IEC 15504, a nie na ISO/IEC 38500 (Ład IT) ani ISO/IEC 27000 (bezpieczeństwo informacji).","zycie":"Ładowarka ze standardowym gniazdem pasuje do telefonów wielu firm, więc łatwo ją kupić i każdy serwis ją zna."},"bk_podejscie_nadzor":{"kw":["role, działania i relacje","cel nadzoru","rysunek 8"],"pulapka":"Podejście do nadzoru (Rysunek 8) ma cztery elementy: cel nadzoru, aktywatory nadzoru, zakres nadzoru oraz role, działania i relacje; nie ma tam „procesów EDM”.","zycie":"Klub piłkarski: cel (wygrywać rozsądnie), środki (sprzęt, trenerzy), zakres (drużyna seniorów czy cały klub) i to, kto z kim współpracuje."},"bk_pol_dobre":{"kw":["nieinwazyjn","skuteczn","wydajn"],"pulapka":"Dobre polityki są skuteczne, wydajne i nieinwazyjne (podręcznik: nieingerencyjne); „kompleksowe, otwarte i elastyczne” to cechy struktur ramowych, nie polityk.","zycie":"Dobry regulamin parkingu pod blokiem działa, nie wymaga wiele wysiłku i wydaje się mieszkańcom rozsądny, więc nikt go nie obchodzi."},"bk_pol_dostep":{"kw":["dostęp do polityk","polityk"],"pulapka":"Dostęp do polityk to pytanie, czy interesariusze wiedzą, gdzie je znaleźć; to cel z kategorii dostępu i bezpieczeństwa, a nie jakości kontekstowej.","zycie":"Instrukcja obsługi pieca wisi w kotłowni tuż obok pieca, więc każdy domownik wie, gdzie jej szukać."},"bk_polityki_def":{"kw":["polityka","wytyczn"],"pulapka":"Polityka daje szczegółowe wytyczne, jak stosować zasady w praktyce i w decyzjach, a zasada wyraża podstawowe wartości; nie odwracaj tej hierarchii.","zycie":"Zasada „dbamy o zdrowie” staje się praktyczna dzięki regule: słodycze tylko w weekend, a telefon odkładamy o 22."},"bk_poziomy_usl":{"kw":["poziomy usług","sla","apo09"],"pulapka":"Poziomy usług muszą zdefiniować i osiągnąć dostawcy usług; to dobra praktyka zdolności usługowej, a definiowanie usług w umowach SLA w procesach to APO09.","zycie":"Umowa z firmą sprzątającą określa, jak często i jak dokładnie sprząta; firma musi te warunki ustalić i dotrzymać."},"bk_prak1":{"kw":["rysunek 20","cobit 4.1","model dojrzałości"],"pulapka":"Wyników COBIT 4.1 i COBIT 5 nie porównuje się wprost mimo podobnej skali i słów, bo różnią się zakresem, ukierunkowaniem i intencją (Rysunek 20).","zycie":"Waga łazienkowa i waga kuchenna pokazują liczby, ale ważą co innego i w innym celu. Porównywanie ich odczytów nic nie mówi."},"bk_prak2":{"kw":["niższe","model dojrzałości","poziom 0"],"pulapka":"W COBIT 5 wyniki są zwykle niższe: proces z poziomem 1 lub 2 w COBIT 4.1, który nie osiąga w pełni celów, może dostać 0 lub 1, nie wyższy wynik.","zycie":"Ten sam uczeń dostał czwórkę u łagodnej nauczycielki, a u surowej, która wymaga pełnego rozwiązania zadania, tylko dwójkę."},"bk_prak3":{"kw":["model dojrzałości","każdego procesu","15504"],"pulapka":"COBIT 5 zrezygnował z osobnego modelu dojrzałości dla każdego procesu, bo ISO/IEC 15504 tego nie wymaga, a wręcz uniemożliwia; ocenia się wspólnymi atrybutami.","zycie":"Zamiast osobnego regulaminu oceny dla każdego dania jury konkursu kulinarnego używa jednej wspólnej skali dla wszystkich potraw."},"bk_prak4":{"kw":["profil","n, c, w, p","dziewięciu atrybut"],"pulapka":"W COBIT 5 każdy proces można ocenić dla każdego z 9 atrybutów zdolności, każdy skalą N, C, W, P; „profil dojrzałości” to pojęcie z COBIT 4.1.","zycie":"Zamiast jednej oceny z zachowania wychowawca wystawia ocenę w każdej z dziewięciu rubryk, więc widać, gdzie dziecko potrzebuje pomocy."},"bk_prak5":{"kw":["rysunek 21","przeklasyfik","atrybut"],"pulapka":"Atrybuty dojrzałości COBIT 4.1 i zdolności COBIT 5 częściowo się pokrywają. Rysunek 21 pomaga ponownie wykorzystać i przeklasyfikować wcześniejsze ustalenia; nie jest automatycznym przelicznikiem poziomów ani zwolnieniem z weryfikacji dowodów.","zycie":"Po zmianie kryteriów oceniania wcześniejsze notatki o pracy ucznia nadal pomagają. Trzeba sprawdzić ich aktualność i odnieść je do nowych wymagań; nie wystarczy przeliczyć starej oceny."},"bk_praktyki_cechy":{"kw":["praktyki ładu","praktyki zarządzania","praktyka ładu"],"pulapka":"Praktyki Ładu/Zarządzania są typowe (trzeba je dostosować), zgodne ze standardami i obejmują role biznesu oraz IT; nie są gotowe do wdrożenia bez zmian.","zycie":"Typowe zasady prowadzenia sklepu osiedlowego pasują do wielu sklepów, więc każdy właściciel je dopasowuje; obejmują i szefa, i sprzedawców."},"bk_praktyki_wybor":{"kw":["praktyk","dostosow","ryzyko"],"pulapka":"Organ Ładu i kierownictwo wybierają praktyki, dodają lub dostosowują je, ustalają sposób wdrożenia i mogą zaakceptować ryzyko niewdrożenia; COBIT nie wymaga wdrożenia wszystkich.","zycie":"Z książki z ćwiczeniami trener wybiera te, które pasują drużynie, dodaje własne, ustala, jak często trenować, i świadomie pomija resztę."},"bk_prm_biznes_it":{"kw":["referencyjny model procesu","całej organizacji"],"pulapka":"PRM obejmuje całość działań biznesu i IT związanych z Ładem i Zarządzaniem informacją i technologią. Jest ogólnofirmowy, ale nie opisuje wszystkich działań przedsiębiorstwa niezależnych od IT.","zycie":"Plan przeprowadzki obejmuje nie tylko pakowanie telewizora i komputera, ale też meble, dokumenty, szkołę dzieci i przepisanie liczników."},"bk_prm_daje":{"kw":["audyt","dostawc","sprawnoś"],"pulapka":"Wspólny model procesów daje: pomiar i monitorowanie sprawności IT, audyt IT, komunikację z dostawcami usług i wdrażanie dobrych praktyk.","zycie":"Wspólna lista obowiązków domowych pozwala sprawdzić, jak idzie, rozliczyć, ustalić zakres z firmą sprzątającą i podpatrzeć dobre zwyczaje."},"bk_prm_info":{"kw":["praktyki bazowe","praktyka bazowa","produkty pracy","wejścia i wyjścia"],"pulapka":"W referencyjnym modelu procesu praktyki bazowe to odpowiednik praktyk Ładu/Zarządzania, a produkty pracy – odpowiednik wejść i wyjść; nie myl ich z działaniami ani miernikami.","zycie":"Żeby ocenić warsztat samochodowy, inspektor potrzebuje opisu usługi z celem, listy wykonywanych czynności i dokumentów, które powstają, np. kart napraw."},"bk_prm_jezyk":{"kw":["wspólny język","wspólny model","język"],"pulapka":"Wprowadzenie modelu operacyjnego i wspólnego języka dla IT i biznesu to jeden z najważniejszych kroków ku właściwemu nadzorowi, a nie szczegół techniczny.","zycie":"W drużynie wszyscy muszą tak samo rozumieć słowo „pressing”, inaczej każdy biega gdzie indziej."},"bk_prm_kryt":{"kw":["referencyjny model procesu","model referencyjny procesu","opis procesu"],"pulapka":"Wymogi ISO/IEC 15504-2 dotyczą opisu procesu w referencyjnym modelu procesu: cel i rezultaty, brak cech powyżej poziomu 1, wspólne atrybuty na poziomach 2–5; to nie kryteria SMART.","zycie":"Przepis w książce kucharskiej ma podać, co ma wyjść i jakie kroki wykonać, a nie oceniać, czy kucharz prowadzi dziennik kontroli jakości."},"bk_prm_kryt1":{"kw":["przeznaczenie procesu","rezultat","opis procesu"],"pulapka":"Opis procesu musi zawierać przeznaczenie i rezultaty procesu; to na ich podstawie ocenia się PA 1.1, a nie na podstawie mierników z poziomu 4.","zycie":"Ogłoszenie o zbiórce harcerskiej mówi, po co się spotykamy i co ma powstać – ognisko i rozbity namiot. Bez tego nie wiadomo, czy się udało."},"bk_prm_kryt2":{"kw":["procesy umożliwiające","poziom 1","opis procesu"],"pulapka":"PRM opisuje cel i wyniki procesu oraz praktyki potrzebne do ich osiągnięcia. Nie włącza ogólnych atrybutów zdolności poziomów 2–5 do definicji procesu. Konkretna praktyka może jednak wymagać planowania lub pomiaru, jeśli służy to celowi tego procesu; sam pomiar nie dowodzi PA 4.1.","zycie":"Przepis określa kroki potrzebne do uzyskania potrawy, w tym wymagany pomiar temperatury. Osobno oceniasz, czy kuchnia zarządza wszystkimi procesami według wspólnego standardu i prowadzi kontrolę statystyczną."},"bk_prm_kryt3":{"kw":["mechanizmy kontrolne procesów","typowe praktyki","praktyki ogólne"],"pulapka":"Dawne mechanizmy kontrolne procesów (PC) z COBIT 4.1 nie zniknęły: wspólne atrybuty trafiły na poziomy 2–5 modelu oceny, co usuwa powielanie celów kontrolnych.","zycie":"Zamiast dopisywać do każdego domowego obowiązku „umyj ręce, posprzątaj po sobie”, rodzina wiesza jedną wspólną listę zasad dla wszystkich zadań."},"bk_prm_nastepca":{"kw":["val it","risk it","cobit 4.1"],"pulapka":"PRM COBIT 5 jest następcą modelu procesów COBIT 4.1 i łączy modele procesów Risk IT oraz Val IT; nie wywodzi się z ITIL.","zycie":"Nowa książka kucharska zastępuje trzy stare zeszyty: przepisy codzienne, świąteczne i na przyjęcia."},"bk_prm_niejedyny":{"kw":["model referencyjny","prm","jedyn"],"pulapka":"PRM jest kompletny i kompleksowy, ale nie jest jedynym możliwym modelem; każde przedsiębiorstwo definiuje własny zbiór procesów.","zycie":"Wzorcowy plan dnia z poradnika jest kompletny, ale każda rodzina układa własny."},"bk_prm_przewodnik":{"kw":["procesy umożliwiające","37","przewodnik"],"pulapka":"Pełne opisy 37 procesów są w przewodniku COBIT 5: Procesy umożliwiające, a nie w samej metodyce COBIT 5.","zycie":"Spis dań jest w menu, ale pełne przepisy kucharz trzyma w swoim zeszycie."},"bk_prm_wielkosc":{"kw":["wielkoś","mniejsz","37 proces"],"pulapka":"Mniejsze firmy mogą mieć mniej procesów, większe więcej, ale wszystkie służą tym samym celom; 37 procesów to nie obowiązkowa liczba.","zycie":"W kawalerce jedna osoba gotuje, sprząta i pierze, a w dużym domu te zadania dzieli się na wiele osób."},"bk_proc_nadz_vs_zarz":{"kw":["procesy ładu","proces ładu","pbrm"],"pulapka":"Procesy Ładu dotyczą tworzenia wartości (korzyści, ryzyko, zasoby) i zawierają praktyki EDM; procesy Zarządzania obejmują obszary PBRM; różnica tkwi w celach procesów, nie w nazwie działu.","zycie":"Właściciel restauracji decyduje, jaki ma być lokal, i sprawdza zyski; kierownik planuje menu, zatrudnia ludzi, gotuje i pilnuje kuchni."},"bk_proc_pbrm_wew":{"kw":["pbrm","planowani","procesy ładu"],"pulapka":"Każdy proces, także Ładu, wewnętrznie wymaga planowania, budowania, realizacji i monitorowania; nie znaczy to, że procesy EDM należą do domen PBRM Zarządzania.","zycie":"Nawet zarząd wspólnoty, który tylko decyduje, musi sam zaplanować zebranie, przygotować je, przeprowadzić i sprawdzić, czy poszło dobrze."},"bk_proces_def":{"kw":["zbiór praktyk","proces"],"pulapka":"Proces to zbiór praktyk ukierunkowanych przez polityki i procedury, przetwarzający wejścia w wyjścia (produkty, usługi); sam „zbiór działań” bez wejść, wyjść i polityk to niepełna definicja.","zycie":"Pralka bierze brudne ubrania, proszek i wodę, wykonuje kroki według ustawionego programu i oddaje czyste pranie."},"bk_pryncypia":{"kw":["pryncypia architektury","ponowne wykorzystanie","otwartość"],"pulapka":"Przykładowe pryncypia architektury: ponowne wykorzystanie, nabywanie zamiast tworzenia, prostota, zwinność, otwartość; domyślnie się kupuje, a własny rozwój wymaga zatwierdzonego powodu.","zycie":"Zasady budowania z klocków: używaj tych, które masz, dokupuj gotowe zestawy, nie komplikuj, buduj tak, by łatwo przerobić, i wybieraj klocki pasujące do innych."},"bk_przyklad1":{"kw":["zadowolenie klient","przykład 1","kaskad"],"pulapka":"W Przykładzie 1 z siedmiu celów IT z relacją P firma wybiera jako priorytet tylko pierwsze cztery (01, 04, 07, 09), a nie wszystkie siedem.","zycie":"Sklep chce zadowolonych klientów, więc dba o uprzejmość, stałe godziny otwarcia i szybkie zmiany oferty, a potem o niezawodną kasę i terminal."},"bk_przyklad10":{"kw":["przykład 10","pa 2.1","pa 2.2"],"pulapka":"W Przykładzie 10 kierownicy procesów podnoszą zdolność na poziom 2: PA 2.1 Zarządzanie wydajnością (planowanie, monitorowanie) i PA 2.2 Zarządzanie produktami pracy; to nie poziom 3.","zycie":"Nowy kierownik świetlicy spisuje, kto co robi, jakie zajęcia mają się odbyć i jak je ocenić, a potem planuje i pilnuje ich przebiegu."},"bk_przyklad11":{"kw":["przykład 11","jakości","zachęt"],"pulapka":"W Przykładzie 11 przyczyną słabej jakości aplikacji były zachęty za termin i budżet, a nie zła metodyka rozwoju; rozwiązaniem są lepsze zachęty sprzyjające jakości.","zycie":"Ekipa remontowa dostaje premię za skończenie przed terminem, więc nie czeka, aż tynk wyschnie. Ściany pękają, choć plan pracy był dobry."},"bk_przyklad12":{"kw":["obwiniania","apetyt na ryzyko"],"pulapka":"Przykład 12 podaje symptomy złej kultury ryzyka IT: rozbieżność rzeczywistego apetytu na ryzyko i polityk oraz kulturę obwiniania, najważniejszą przeszkodę w skutecznej komunikacji.","zycie":"Szef sklepu lubi ryzykowne interesy, a regulamin jest bardzo ostrożny; do tego wszyscy zwalają winę na magazyn, więc nikt ze sobą nie rozmawia."},"bk_przyklad13":{"kw":["przykład 13","specyfikac","warstw"],"pulapka":"W Przykładzie 13 model informacji wyznacza specyfikację nowej aplikacji pytaniami warstw, a testerzy używają kryteriów jakości informacji do przypadków testowych; ochrona to Przykład 14.","zycie":"Projektując spiżarnię, pytasz: gdzie stanie, jak się do niej dostać, jak ułożyć półki, co w niej trzymać i jak długo."},"bk_przyklad14":{"kw":["przykład 14","ochron","warstw"],"pulapka":"W Przykładzie 14 zespoły bezpieczeństwa analizują warstwy i fazy cyklu życia, bo informacja wymaga ochrony już od fazy planowania, a nie dopiero przy przechowywaniu.","zycie":"Chroniąc rodzinne dokumenty, myślisz o sejfie już przy kupnie mebli, a potem o tym, gdzie je trzymać, komu pokazać i jak zniszczyć stare."},"bk_przyklad15":{"kw":["przykład 15","łatwości korzystania","jakości"],"pulapka":"Przykład 15 używa kryteriów jakości informacji do przeglądu procesu biznesowego i oceny łatwości korzystania z danych; to nie ocena zdolności procesu skalą N, C, W, P.","zycie":"Przegląd domowej apteczki: czy niczego nie brakuje, czy leki są ważne, czy są pod ręką i czy łatwo je znaleźć."},"bk_przyklad1_wn":{"kw":["same procesy","aktywator","kultur"],"pulapka":"Same procesy nie wystarczą: kultura, struktury organizacyjne i umiejętności też wymagają celów; wynik to spójne cele wszystkich aktywatorów i mierniki.","zycie":"Sam grafik sprzątania nic nie da, jeśli domownicy nie mają nawyku porządku i nikt nie wie, kto o czym decyduje."},"bk_przyklad2":{"kw":["zrównoważon","kultura innowacji","wykwalifikowany"],"pulapka":"Zrównoważony rozwój w Przykładzie 2 to nie tylko ekologia, lecz wszystko, co składa się na długoterminowy sukces; wybrane cele to 1, 4, 8, 16, 17.","zycie":"Rodzina planuje na lata: nie tylko segreguje śmieci, ale też uczy dzieci, odkłada pieniądze i dba o zdrowie."},"bk_przyklad3":{"kw":["usług it","umiejętnoś","przykład"],"pulapka":"Przykład 3 pokazuje, że usługi IT wymagają naraz infrastruktury i aplikacji, ludzi z umiejętnościami (także behawioralnymi), procesów i struktur organizacyjnych.","zycie":"Pizzeria z dowozem potrzebuje pieca i aplikacji do zamówień, kucharzy i kierowców, ustalonych kroków dostawy i szefa zmiany."},"bk_przyklad4":{"kw":["bezpieczeństw","kultur","etyk"],"pulapka":"W Przykładzie 4 polityki i praktyki bezpieczeństwa informacji nie zadziałają bez odpowiedniej kultury i etyki; to argument za Zasadą 4.","zycie":"Zasada zamykania drzwi na klucz nic nie da, jeśli domownicy i tak zostawiają je otwarte, bo „u nas nikt nie kradnie”."},"bk_przyklad5":{"kw":["kierowni","przykład 5","właściciel procesu"],"pulapka":"W Przykładzie 5 kierownicy ds. procesów najpierw analizują aktywator Proces wg czterech wymiarów, a potem sięgają do innych aktywatorów (umiejętności, struktury, polityki).","zycie":"W bloku wyznacza się opiekuna klatki schodowej, który ustala, kto sprząta, po co, jak długo i według jakich sprawdzonych zasad."},"bk_przyklad6":{"kw":["20%","statysty","badani"],"pulapka":"Historyczny Przykład 6 na s. 39 przytacza badanie 250 firm (rentowność wyższa o co najmniej 20%) i ITGI/PwC (38% respondentów wskazało niższe koszty IT). To wyniki przytoczonych badań, nie prognoza ani gwarancja efektów dowolnego wdrożenia.","zycie":"Sąsiedzi, którzy pilnują domowego budżetu, wydają mniej i żyją spokojniej; to przekonuje cię do własnego planu."},"bk_przyklad7":{"kw":["ciągłość i dostępność","zwinność it","przykład 7"],"pulapka":"W Przykładzie 7 cel organizacji 7 (ciągłość i dostępność usług) zależy głównie od celów IT 04, 10 i 14, a cel IT 09 Zwinność IT wspiera głównie cele 2, 8, 11 i 17.","zycie":"Od czego zależy ciepły dom? Głównie od pieca i okien. I odwrotnie: nowy piec pomaga i w cieple, i w niższych rachunkach."},"bk_przyklad8":{"kw":["apo13","przykład 8"],"pulapka":"W Przykładzie 8 APO13 Zarządzanie bezpieczeństwem ma P dla celów IT 02, 04, 06, 10 i 14, a S tylko dla 07 i 08; nie tylko dla celu 10 Bezpieczeństwo.","zycie":"Zamek w drzwiach przede wszystkim chroni przed kradzieżą i uspokaja ubezpieczyciela, a przy okazji trochę ułatwia wygodne korzystanie z domu."},"bk_przyklad9":{"kw":["mediów społecznościowych","przykład 9"],"pulapka":"W Przykładzie 9 nowa polityka mediów społecznościowych jest mniej restrykcyjna i wpływa na inne aktywatory: zachowania, umiejętności i procesy bezpieczeństwa, nie tylko na same polityki.","zycie":"Rodzice pozwalają nastolatkom używać smartfonów przy stole. Muszą wytłumaczyć powód, nauczyć zasad i zmienić ustawienia kontroli rodzicielskiej."},"bk_ps_corg":{"kw":["podstawow","wspierając","p/s"],"pulapka":"P oznacza relację podstawową, a S wspierającą, czyli słabszą, z celami Ładu (korzyści, ryzyko, zasoby); S nie znaczy „strategiczna” ani „szczegółowa”.","zycie":"W domowym budżecie nowa lodówka mocno wspiera oszczędzanie, a tylko trochę zdrowe jedzenie."},"bk_pub_wdrozenie":{"kw":["wdrożeni","ciągłego doskonalenia","normatywn"],"pulapka":"COBIT 5 – Wdrożenie opiera się na cyklu ciągłego doskonalenia, nie jest normatywny ani kompletnym rozwiązaniem; to zbiór wskazówek.","zycie":"Poradnik przeprowadzki: zbiór wskazówek, jak uniknąć typowych wpadek, a nie firma, która przeprowadzi cię sama."},"bk_pyt12_wynik":{"kw":["wskaźniki opóźnione","opóźnion","następując"],"pulapka":"Pytania o potrzeby interesariuszy i osiągnięcie celów mierzą wynik, czyli wskaźniki opóźnione (podręcznik: „następujące”); nie myl ich z wiodącymi.","zycie":"Waga po miesiącu diety pokazuje wynik dopiero po fakcie: mówi, czy cel osiągnięto."},"bk_pyt34_dzial":{"kw":["wiodąc","wyprzedzając","wskaźnik"],"pulapka":"Pytania o cykl życia i dobre praktyki mierzą działanie samego aktywatora, czyli wskaźniki wiodące (podręcznik: „wyprzedzające”), a nie wynik.","zycie":"Liczba zjedzonych warzyw i treningów w tygodniu zapowiada, czy dieta się uda, zanim zobaczysz wynik na wadze."},"bk_pytania_kask":{"kw":["załącznik d","pytania interesariuszy","rysunek 7"],"pulapka":"Pytania interesariuszy z Rysunku 7 są wejściem do kaskady i wiążą się z celami przedsiębiorstwa; ich mapowanie jest w Załączniku D, nie B.","zycie":"Pytania domowników („czy nas stać?”, „czy dom jest bezpieczny?”) zapisujesz i przypisujesz do celów rodziny."},"bk_pz1":{"kw":["frustracj","punkty zapalne","punkt zapal"],"pulapka":"Frustracja biznesu z powodu nieudanych inicjatyw, rosnących kosztów IT i niskiej wartości to punkt zapalny (bieżący problem), a nie zdarzenie wyzwalające.","zycie":"Właściciel sklepu narzeka: kupiliśmy nową kasę, płacimy coraz więcej, a kolejki są takie same."},"bk_pz10":{"kw":["budżet","opóźnieni","punkt zapal"],"pulapka":"Zmiany IT, które nie spełniają potrzeb biznesu, są spóźnione lub przekraczają budżet, to punkt zapalny, a nie czynnik sukcesu ani zdarzenie wyzwalające.","zycie":"Nowe szafki kuchenne przyszły po terminie, kosztowały więcej niż w umowie i nie pasują do potrzeb rodziny."},"bk_pz11":{"kw":["sponsor","niechęć","punkt zapal"],"pulapka":"Niechęć zarządu i kierownictwa do współpracy z IT oraz brak zaangażowanych, zadowolonych sponsorów biznesowych to punkt zapalny; nowy CEO to zdarzenie wyzwalające.","zycie":"Babcia nie chce rozmawiać z wnukiem o nowym telefonie, a nikt w rodzinie nie chce się dołożyć do zakupu."},"bk_pz12":{"kw":["złożon","model operacyjn","punkt zapal"],"pulapka":"Złożone modele operacyjne IT to punkt zapalny; nie myl go z czynnikiem kontekstu „model operacyjny i poziom dojrzałości”.","zycie":"Rodzina ma trzy różne kalendarze, dwa auta rozliczane na różnych zasadach i nikt nie wie, kto co załatwia."},"bk_pz2":{"kw":["utrata danych","incydent","punkt zapal"],"pulapka":"Istotne incydenty ryzyka IT, np. utrata danych lub niepowodzenie projektu, to punkt zapalny; audyt zewnętrzny to już zdarzenie wyzwalające.","zycie":"Rodzina traci wszystkie zdjęcia z wakacji, bo zepsuł się telefon bez kopii zapasowej."},"bk_pz3":{"kw":["outsourc","poziom usług","punkt zapal"],"pulapka":"Problemy z outsourcingiem, np. ciągłe niedotrzymywanie uzgodnionego poziomu usług, to punkt zapalny; zmiana uzgodnień zaopatrzenia to zdarzenie wyzwalające.","zycie":"Firma sprzątająca znowu nie przyszła w umówiony dzień, choć płacisz jej co miesiąc."},"bk_pz4":{"kw":["regulacyjn","wymog","punkt zapal"],"pulapka":"Niespełnianie obecnych wymogów regulacyjnych lub umownych to punkt zapalny; nowe wymagania regulacyjne to zdarzenie wyzwalające; egzamin rozróżnia oba.","zycie":"Kontrola sanepidu w piekarni wytyka braki, a hurtownia skarży się na niedotrzymaną umowę."},"bk_pz5":{"kw":["innowac","zwinnoś","punkt zapal"],"pulapka":"IT ograniczające innowacyjność i zwinność biznesu to punkt zapalny; nie myl go z istotną zmianą technologii, która jest zdarzeniem wyzwalającym.","zycie":"Właściciel kawiarni chce przyjmować zamówienia przez aplikację, ale stary komputer i program na to nie pozwalają."},"bk_pz6":{"kw":["audyt","jakoś","punkt zapal"],"pulapka":"Audyty regularnie wskazujące słabą sprawność IT lub jakość usług to punkt zapalny; jednorazowy audyt zewnętrzny lub ocena konsultantów to zdarzenie wyzwalające.","zycie":"Co roku przegląd techniczny auta wykazuje te same usterki, a nikt ich nie naprawia."},"bk_pz7":{"kw":["ukryte","wydatk","punkt zapal"],"pulapka":"Ukryte i nieuczciwe wydatki na IT to punkt zapalny; nie jest to czynnik kontekstu ani zdarzenie wyzwalające.","zycie":"Ktoś w rodzinie po cichu kupuje elektronikę z domowego budżetu i nikt nie wie, ile naprawdę na to idzie."},"bk_pz8":{"kw":["powiel","marnotraw","punkt zapal"],"pulapka":"Powielanie lub nakładanie się inicjatyw i marnotrawstwo zasobów (np. przedwczesne zakończenie projektu) to punkt zapalny; nie myl go z ogólnofirmową inicjatywą, która jest zdarzeniem wyzwalającym.","zycie":"Dwoje domowników kupuje w tym samym tygodniu dwie identyczne drabiny, a malowanie pokoju porzucono w połowie."},"bk_pz9":{"kw":["wypaleni","umiejętnoś","punkt zapal"],"pulapka":"Brak zasobów i umiejętności IT oraz wypalenie lub niezadowolenie zespołu to punkt zapalny; nie myl go z czynnikiem kontekstu „potencjał i dostępne zasoby”.","zycie":"W drużynie zostało trzech zawodników, nikt nie umie bronić, a ci, którzy grają, są wyczerpani."},"bk_pz_po_co":{"kw":["punkty zapalne","zdarzenia wyzwalając","pilnoś"],"pulapka":"Punkty zapalne i zdarzenia wyzwalające wiążą uzasadnienie biznesowe z codziennymi problemami, dają poczucie pilności, szybkie korzyści i platformę dalszych zmian.","zycie":"Cieknący kran pomaga uzasadnić naprawę i uruchomić przegląd instalacji. Zakres szerszego remontu trzeba dopiero uzasadnić rzeczywistymi potrzebami i korzyściami."},"bk_raci":{"kw":["raci","rozliczan","konsultowan"],"pulapka":"R to ten, kto wykonuje (odpowiedzialny), a A to ten, kto jest rozliczany za wynik; polskie „odpowiedzialny” i „rozliczany” łatwo zamienić.","zycie":"W drużynie: kto strzela karnego (R), kto odpowiada za wynik meczu, czyli trener (A), kogo się radzi (C) i kogo tylko informuje (I)."},"bk_rodzina":{"kw":["rodzina produktów","przewodnik","procesy umożliwiające"],"pulapka":"Procesy umożliwiające i Informacje umożliwiające to przewodniki aktywatorów, a Wdrożenie, Bezpieczeństwo informacji, Audyt i Ryzyko to przewodniki specjalistyczne; łatwo je zamienić miejscami.","zycie":"Jak domowa biblioteczka kucharska: główna książka, osobne zeszyty o przyprawach i pieczeniu, poradniki na specjalne okazje oraz forum, gdzie kucharze wymieniają się radami."},"bk_role_dzial":{"kw":["delegowani","rysunek 9","rozliczan"],"pulapka":"Na Rysunku 9 właściciele delegują do organu nadzorującego, ten wyznacza kierunek Zarządzaniu, a ono instruuje Eksploatację; w górę idą raportowanie, monitorowanie i rozliczanie.","zycie":"Właściciele mieszkania zlecają zarządcy budynku, zarządca wydaje polecenia ekipie, a ekipa raportuje, co zrobiła."},"bk_role_info":{"kw":["wytwórca","opiekun","konsument"],"pulapka":"Wytwórca tworzy informację, opiekun (custodian) odpowiada za jej przechowywanie i utrzymanie, a konsument z niej korzysta. Opiekun i właściciel to odmienne role; jedna osoba może pełnić więcej niż jedną rolę.","zycie":"W rodzinnym albumie babcia robi zdjęcia, mama przechowuje i porządkuje album, a wnuki go oglądają."},"bk_role_info_szcz":{"kw":["właściciel","role","faz"],"pulapka":"Szczegółowe role informacyjne (architekt, właściciel, zarządca, powiernik, dostawca, beneficjent itd.) zależą od fazy cyklu życia informacji, więc wymiar interesariuszy nie jest od niego niezależny.","zycie":"Przy gazetce osiedlowej ktoś projektuje układ, ktoś jest właścicielem tytułu, ktoś dostarcza teksty, a ktoś tylko czyta."},"bk_roz1":{"kw":["model dojrzałości","ad hoc","15504"],"pulapka":"Mimo podobnej skali 0–5 poziomy ISO/IEC 15504 mają inne nazwy i znaczenie niż poziomy dojrzałości COBIT 4.1; proces z poziomem 1 (Ad hoc) może w COBIT 5 dostać 0.","zycie":"Szóstka w polskiej szkole i szóstka w niemieckiej to ta sama cyfra, ale zupełnie inne oceny. Nie przepisuje się ich jeden do jednego."},"bk_roz2":{"kw":["dziewięciu atrybut","dziewięć atrybut","9 atrybut"],"pulapka":"COBIT 5 ma 9 atrybutów procesu (PA 1.1–5.2), a COBIT 4.1 miał 6 atrybutów dojrzałości (np. świadomość i komunikowanie); pokrywają się tylko częściowo i inaczej.","zycie":"Stara karta oceny łyżwiarza miała 6 rubryk, nowa ma 9. Część pytań się pokrywa, ale ułożono je inaczej, więc wyników nie przepiszesz wprost."},"bk_rozw1":{"kw":["przejrzystoś","interesariusz","sprzeczn"],"pulapka":"Chodzi o większy wpływ większej liczby interesariuszy i żądanie przejrzystości; ich oczekiwania bywają rozbieżne, a nawet sprzeczne.","zycie":"Przy remoncie mieszkania każdy domownik chce mieć głos: jedni chcą taniej, inni trwale, a wszyscy chcą widzieć rachunki."},"bk_rozw10":{"kw":["val it","risk it","bmis","itaf"],"pulapka":"Połączone metodyki ISACA to COBIT, Val IT, Risk IT, BMIS, ITAF, Board Briefing on IT Governance i TGF; ITIL czy TOGAF nie są produktami ISACA.","zycie":"Rodzina łączy kilka zeszytów z przepisami różnych babć w jedną wspólną książkę."},"bk_rozw2":{"kw":["outsourc","dostawc","zewnętrzn"],"pulapka":"Uzależnienie od stron zewnętrznych dotyczy biznesu i IT: outsourcingu, dostawców, konsultantów, klientów, chmury; nie tylko dostawców IT.","zycie":"Rodzina, która zamawia catering, opiekunkę i firmę sprzątającą, coraz bardziej zależy od tego, czy oni się wywiążą."},"bk_rozw3":{"kw":["model informacji","informacj"],"pulapka":"Problemem nie jest brak informacji, lecz jej nadmiar i wybór istotnych, wiarygodnych danych; pomaga w tym efektywny model informacji.","zycie":"Skrzynka na listy pęka od ulotek, a trzeba z niej wyłowić ten jeden ważny rachunek."},"bk_rozw4":{"kw":["cio","integraln","biznes"],"pulapka":"Oddzielenie IT od biznesu, nawet przy dobrym dopasowaniu, nie jest już optymalne; IT ma być integralną częścią biznesu, a rola CIO ewoluuje.","zycie":"W rodzinnym warsztacie komputer diagnostyczny jest częścią każdej naprawy, a nie osobnym pokojem, do którego nikt nie zagląda."},"bk_rozw5":{"kw":["innowac","nowe technologie"],"pulapka":"Innowacyjność obejmuje też usprawnienie rozwoju produktów, produkcji i łańcucha dostaw, a nie tylko wymyślanie nowych produktów.","zycie":"Osiedlowa cukiernia wymyśla nowe ciasto i sprzedaż przez internet, żeby zdobyć nowych klientów i szybciej piec."},"bk_rozw6":{"kw":["odpowiedzialnoś","kultur","struktur"],"pulapka":"Pełny zakres odpowiedzialności obejmuje biznes i IT oraz struktury, polityki, kulturę i procesy, a nie samą technikę.","zycie":"Udany dom to nie tylko meble: liczą się domowe zasady, podział obowiązków i atmosfera między ludźmi."},"bk_rozw7":{"kw":["użytkownik","inicjowan","kontrol"],"pulapka":"Chodzi o kontrolę nad rozwiązaniami IT inicjowanymi i kontrolowanymi przez użytkowników spoza działu IT, a nie o kontrolę samych użytkowników.","zycie":"Dzieci same instalują gry na rodzinnym komputerze, a rodzice chcą mieć nad tym większą kontrolę."},"bk_rozw8":{"kw":["zadowoleni","wartoś","zgodnoś"],"pulapka":"To jeden wyznacznik z czterema elementami: wartość z IT, zadowolenie użytkowników biznesowych, zgodność oraz lepsze relacje potrzeb biznesu i celów IT.","zycie":"Elektryk ma nie tylko podłączyć prąd, ale też zadowolić domowników, spełnić normy i dobrze się z nimi dogadywać."},"bk_rozw9":{"kw":["itil","togaf","prince2","coso"],"pulapka":"ITIL, TOGAF, PMBOK, PRINCE2, COSO i ISO to standardy zewnętrzne, z którymi COBIT 5 się wiąże; Val IT i Risk IT to metodyki ISACA wchłonięte przez COBIT 5.","zycie":"Nowa książka kucharska odsyła do znanych poradników o pieczeniu i grillowaniu, zamiast je przepisywać."},"bk_sfia":{"kw":["sfia","definicje umiejętności"],"pulapka":"SFIA (Skills Framework for the Information Age) to zewnętrzne źródło definicji umiejętności dla aktywatora Ludzie; nie jest modelem oceny procesów ani częścią rodziny produktów COBIT.","zycie":"Jak oficjalny katalog pasów w karate: od białego do czarnego, z opisem, co trzeba umieć na każdym stopniu."},"bk_skala_proc":{"kw":["częściowy","większościowy","nieosiągnięty"],"pulapka":"N/C/W/P: 0–15%, >15–50%, >50–85%, >85–100%. Dokładnie 85% to W, nie P. Pełne osiągnięcie wymaga systematyczności i braku istotnych słabości, nie koniecznie 100%.","zycie":"Jak ocena koszyka truskawek: prawie pusty, część, większość, prawie pełny. Granice to 15, 50 i 85 procent."},"bk_spr_regularnie":{"kw":["sprawnoś","mierni","cztery pytania"],"pulapka":"Zarządzanie sprawnością aktywatora to regularne monitorowanie odpowiedzi na cztery pytania przy użyciu mierników, a nie jednorazowa ocena.","zycie":"Kierowca regularnie zerka na wskaźniki paliwa, prędkości i temperatury, żeby wiedzieć, czy auto jedzie dobrze."},"bk_srod_diagn":{"kw":["diagnoz","kondycj","świadomoś"],"pulapka":"Kontrole kondycji, diagnostyka i oceny służą tu podniesieniu świadomości, uzgodnieniu stanowiska i uzyskaniu zobowiązania do działania, a nie tylko pomiarowi.","zycie":"Przegląd auta u mechanika pokazuje całej rodzinie, że hamulce wymagają wymiany, i wszyscy zgadzają się na wydatek."},"bk_srod_kroki":{"kw":["zaangażowani","rol","struktur"],"pulapka":"Zaangażowanie interesariuszy zdobywa się od samego początku, a cele i korzyści przedstawia w kategoriach biznesowych; dopiero potem zasoby, role i struktury.","zycie":"Festyn osiedlowy: najpierw zbierasz poparcie sąsiadów, potem uzasadniasz koszty, zdobywasz pieniądze, dzielisz zadania i powołujesz komitet."},"bk_srod_nie_cel":{"kw":["samym w sobie","realn","aktywator"],"pulapka":"Aktywatory oparte na COBIT mają rozwiązywać realne potrzeby i problemy biznesu, a nie być celem samym w sobie; wymagania akceptuje kierownictwo.","zycie":"Nowy robot kuchenny ma rozwiązać problem braku czasu na gotowanie, a nie stać w kuchni dla ozdoby."},"bk_srod_niepowodz":{"kw":["niepowodzeni","wsparci","środowisk"],"pulapka":"Istotne inicjatywy IT, także wdrożenia COBIT, zawodzą z braku ukierunkowania, wsparcia i nadzoru interesariuszy; w niekorzystnym środowisku wsparcie jest jeszcze ważniejsze.","zycie":"Wycieczka klasowa się nie uda, jeśli rodzice i dyrekcja jej nie popierają, nawet przy świetnym planie."},"bk_std_27000":{"kw":["27000","27001","bezpieczeństw"],"pulapka":"ISO/IEC 27000 pokrywa procesy bezpieczeństwa i ryzyka w EDM, APO i DSS, działania bezpieczeństwa w innych domenach oraz monitorowanie MEA; nie ogranicza się do DSS.","zycie":"Poradnik zabezpieczania domu mówi o zamkach, alarmach i ubezpieczeniu, a także o tym, jak regularnie sprawdzać, czy wszystko działa."},"bk_std_31000":{"kw":["ryzyk","27000"],"pulapka":"Porównanie w Załączniku E wskazuje dla ISO/IEC serii 31000 procesy zarządzania ryzykiem w EDM i APO. To zakres tego zestawienia, nie zakaz stosowania podejścia do ryzyka w pozostałych obszarach.","zycie":"Lekarz rodzinny ocenia ryzyko chorób w rodzinie i zaleca, czego unikać; nie wydaje leków ani nie operuje."},"bk_std_cmmi":{"kw":["bai","apo"],"pulapka":"W Załączniku E CMMI dla rozwoju zestawiono z budowaniem aplikacji i nabywaniem w BAI oraz wybranymi procesami APO dotyczącymi organizacji i jakości. Nie jest to pełna lista wszystkich możliwych powiązań ani opis nowszych wydań CMMI.","zycie":"Poradnik stolarza mówi, jak budować i kupować dobre meble oraz trochę o organizacji warsztatu, ale nie o codziennej obsłudze klientów."},"bk_std_itil":{"kw":["itil","dss"],"pulapka":"Historyczne zestawienie dotyczy ITIL V3 2011 oraz ISO/IEC 20000: podzbioru DSS i BAI oraz niektórych procesów APO. Nie przenoś tej tabeli automatycznie na inne wydania ITIL ani nie traktuj jej jako zakazu innych powiązań.","zycie":"Poradnik dla restauratora opisuje głównie codzienną obsługę gości i kuchnię, trochę wprowadzanie nowych dań, a mało planowanie strategii firmy."},"bk_std_map_proc":{"kw":["powiązane wytyczne","procesy umożliwiające","inne standardy"],"pulapka":"Szczegółowe mapowanie każdego procesu na powiązane standardy jest w przewodniku COBIT 5: Procesy umożliwiające (sekcja „Powiązane wytyczne”), a nie w samej strukturze ramowej.","zycie":"Spis tras w przewodniku turystycznym podaje przy każdej z nich, w której innej książce znajdziesz dokładniejszą mapę."},"bk_std_prince2":{"kw":["prince2","bai01","apo05"],"pulapka":"Załącznik E wiąże PRINCE2 z obszarem portfela w APO oraz programami i projektami w BAI. To uproszczone zestawienie COBIT 5; nie oznacza, że samo PRINCE2 jest pełną metodą zarządzania portfelem lub programami. W COBIT wybór portfela to APO05, a programy i projekty to BAI01.","zycie":"Rodzina wybiera, które remonty zrobić w tym roku, a potem każdy remont prowadzi ekipa według własnego planu."},"bk_std_togaf":{"kw":["togaf","apo03","architektur"],"pulapka":"TOGAF 9 odpowiada zasobom w EDM (Rada ds. Architektury) i architekturze korporacyjnej w APO; fazy ADM A–G odwzorowano w praktykach APO03, a nie w BAI.","zycie":"Architekt osiedla zasiada w radzie budowy, która pilnuje planu, a sam plan rozrysowuje w fazach: wizja, projekty, wybór wykonawców, harmonogram."},"bk_std_togaf_komp":{"kw":["togaf","pryncypia architektury","apo03"],"pulapka":"Osiem komponentów TOGAF 9 (m.in. pryncypia architektury, zarządzanie interesariuszami, zgodność i umowy architektury) odwzorowano w praktyce świadczenia usług architektury korporacyjnej (APO03).","zycie":"Organizator wesela ma stały zestaw narzędzi: listę życzeń pary, styl przyjęcia, rozmowy z rodzinami, ocenę gotowości, ryzyka, budżet, kontrolę zgodności z planem i umowy."},"bk_struktura_ksiazki":{"kw":["rozdział","załącznik"],"pulapka":"Rozdziały 2–6 odpowiadają zasadom 1–5 (przesunięcie o jeden), rozdział 7 to wdrożenie, a rozdział 8 to model potencjału procesu.","zycie":"Spis treści poradnika o domu: najpierw pięć rozdziałów o zasadach, potem rozdział o przeprowadzce, na końcu tabele i słowniczek."},"bk_szcz_dzial":{"kw":["szczegółowe działani","itil","prince2"],"pulapka":"Szczegółowych działań nie ma w COBIT 5: Procesy umożliwiające; bierze się je z ITIL, ISO/IEC 27000, PRINCE2 lub dodatkowych produktów rodziny COBIT 5.","zycie":"Gdy przepis mówi tylko „upiecz chleb”, sięgasz po poradnik piekarski z dokładną temperaturą i czasem wyrastania."},"bk_tgf":{"kw":["taking governance forward","tgf"],"pulapka":"Taking Governance Forward (TGF) włączono do COBIT 5 i wycofano jako osobny zasób; nie jest już odrębnie utrzymywaną metodyką.","zycie":"Stary zeszyt z zasadami domu przepisano do nowej książki domowej, więc zeszyt można odłożyć."},"bk_toolkit":{"kw":["narzędzia","samoocen","narzędzi"],"pulapka":"Zestaw narzędzi wdrożeniowych ma trzy elementy: narzędzia samooceny, pomiaru i diagnostyki; prezentacje dla różnych odbiorców; artykuły i wyjaśnienia.","zycie":"Do remontu dostajesz poziomicę i miarkę, ulotki dla domowników i artykuły z poradami fachowców."},"bk_uz1":{"kw":["beneficjen","korzyści biznesow","uzasadnieni"],"pulapka":"Pierwszy element uzasadnienia obejmuje docelowe korzyści i zgodność ze strategią. FW-PL s. 39 używa słowa „beneficjenci”, lecz oryginał EN s. 38 mówi benefit owners: osoby po stronie biznesu odpowiedzialne za uzyskanie korzyści, nie tylko ich odbiorcy.","zycie":"Nowe okna: w domu będzie cieplej, to pasuje do planu oszczędzania, skorzysta cała rodzina i wiadomo, kto tego dopilnuje."},"bk_uz2":{"kw":["luk","kondycj","zakres"],"pulapka":"Wymagane zmiany biznesowe i zakres (co się w nim mieści, a co nie) ustala się na podstawie kontroli kondycji i analizy luk potencjału.","zycie":"Przed remontem łazienki fachowiec ocenia stan rur i mówi, co trzeba zmienić, a czego nie ruszać."},"bk_uz3":{"kw":["inwestycj","szacun","uzasadnieni"],"pulapka":"Wymagane inwestycje szacuje się na podstawie wymaganych projektów; to osobny element niż bieżące koszty IT i biznesowe.","zycie":"Kosztorys remontu: ile wydasz na płytki, robociznę i materiały, wyliczone z ofert fachowców."},"bk_uz4":{"kw":["bieżące koszt","koszt","uzasadnieni"],"pulapka":"Bieżące koszty IT i koszty biznesowe to obowiązkowy element uzasadnienia; nie myl ich z inwestycjami wymaganymi do wprowadzenia zmian.","zycie":"Ile co miesiąc płacisz dziś za prąd i gaz w starym domu: to punkt odniesienia do porównań."},"bk_uz5":{"kw":["oczekiwane korzyści","korzyści","uzasadnieni"],"pulapka":"Oczekiwane korzyści z funkcjonowania po zmianach to osobny element obok docelowych korzyści biznesowych; liczy się tylko korzyści realistyczne.","zycie":"Po wymianie pieca rachunki mają być niższe, a w domu cieplej; to spodziewany efekt po zmianie."},"bk_uz6":{"kw":["ograniczeni","zależnoś","ryzyk"],"pulapka":"Uzasadnienie musi uwzględniać ryzyko związane z pozostałymi elementami, w tym ograniczenia i zależności, ustalane na podstawie wyzwań i czynników sukcesu.","zycie":"Ekipa może się spóźnić, płytek może zabraknąć, a hydraulik musi skończyć przed glazurnikiem."},"bk_uz7":{"kw":["rozliczalnoś","odpowiedzialnoś","rol"],"pulapka":"Role, zakresy odpowiedzialności i rozliczalności to jeden z ośmiu minimalnych elementów uzasadnienia biznesowego, a nie opcjonalny dodatek.","zycie":"Przy przeprowadzce ustalasz, kto pakuje, kto zamawia transport i kto odpowiada za to, żeby wszystko dojechało."},"bk_uz8":{"kw":["ekonomiczn","monitorowani","mierni"],"pulapka":"Monitorowanie inwestycji i tworzenia wartości obejmuje pełny cykl życia ekonomicznego i mierniki oparte na celach; nie kończy się wraz z projektem.","zycie":"Przez wszystkie lata używania auta notujesz koszty, naprawy i kilometry, żeby wiedzieć, czy się opłaciło."},"bk_uzas":{"kw":["uzasadnienie biznesowe","business case","dynamiczn"],"pulapka":"Uzasadnienie biznesowe nie jest jednorazowym, statycznym dokumentem, lecz dynamicznym narzędziem operacyjnym, które stale się aktualizuje.","zycie":"Przed kupnem lodówki rodzina spisuje, co zyska, ile wyda i czym ryzykuje, i poprawia to, gdy zmieniają się ceny."},"bk_uzas_potrzeba":{"kw":["dzwon","pilnoś","potrzeb"],"pulapka":"Potrzeba działania może przyjąć formę „dzwonka alarmowego” (punkty zapalne) albo szansy udoskonalenia; trzeba też uświadomić ryzyko zaniechania.","zycie":"Kapiący sufit to sygnał alarmowy „działaj teraz”, a promocja na okna to okazja, z której warto skorzystać."},"bk_uzas_real":{"kw":["realistyczn","kwantyfik","korzyści"],"pulapka":"Kwantyfikacja korzyści bywa trudna, więc skupia się tylko na korzyściach realistycznych i osiągalnych; pomocne są badania przeprowadzone w innych firmach.","zycie":"Nie obiecuj rodzinie, że nowa pralka zmniejszy rachunki o połowę; licz na tyle, ile realnie da."},"bk_uzas_sponsor":{"kw":["sponsor","odgórn","kamieni"],"pulapka":"Inicjatywa wymaga sponsora i wszystkich kluczowych interesariuszy; podejście odgórne zaczyna od pożądanych wyników biznesowych, potem zadania, kamienie milowe i role.","zycie":"Wycieczkę klasową prowadzi jeden opiekun, który najpierw mówi, co chcą osiągnąć, a dopiero potem dzieli zadania."},"bk_wart_def":{"kw":["tworzenie wartości","realizacja korzyści","optymalizacja ryzyka"],"pulapka":"Tworzenie wartości to realizacja korzyści przy optymalnym koszcie zasobów i optymalizacji ryzyka, a nie samo zwiększanie zysku ani cięcie kosztów.","zycie":"Dobre zakupy na targu: świeże warzywa (korzyść), bez przepłacania (zasoby) i bez zepsutych sztuk w torbie (ryzyko)."},"bk_wdr_tematy":{"kw":["uzasadnienie biznesowe","punkty zapalne","środowisk"],"pulapka":"Cztery tematy: uzasadnienie biznesowe; punkty zapalne i zdarzenia wyzwalające; właściwe środowisko; COBIT do wskazania luk i rozwoju aktywatorów.","zycie":"Przed remontem: uzasadnij wydatek, zauważ, co najbardziej przeszkadza, przygotuj domowników i sprawdź, czego brakuje."},"bk_wdr_wart":{"kw":["dostosow","wdrożeni","kultur"],"pulapka":"Wartość z COBIT wymaga przyjęcia i dostosowania wytycznych do środowiska organizacji. Podręcznik podkreśla szczególnie wyzwania kultury i zachowań; nie oznacza to, że technika nie może być wyzwaniem.","zycie":"Garnitur z sieciówki leży dobrze dopiero po poprawkach u krawca, a najtrudniej przekonać właściciela, żeby go nosił."},"bk_we_wy":{"kw":["wejścia i wyjścia","produkty pracy","ścieżk"],"pulapka":"Wejścia i wyjścia (produkty pracy) definiuje się na poziomie praktyk, nie działań; dają ścieżkę audytu, a lista przykładowych wejść i wyjść COBIT 5 nie jest kompletna.","zycie":"Paragony, listy zakupów i notatki z rodzinnej narady pozwalają podjąć decyzję i później sprawdzić, kto co postanowił."},"bk_wym1_def":{"kw":["interesariusz","wewnętrzn","zewnętrzn"],"pulapka":"Interesariusze aktywatora to strony, które grają aktywną rolę lub są nim zainteresowane; mogą być wewnętrzni i zewnętrzni, nie tylko wykonawcy.","zycie":"Przy rodzinnym grillu interesariusze to ci, którzy go rozpalają, i ci, którzy czekają na kiełbaski."},"bk_wym1_kask":{"kw":["potrzeby interesariuszy","rysunek 7","sprzeczn"],"pulapka":"Potrzeby interesariuszy przekładają się na cele przedsiębiorstwa, a te na cele związane z IT; listę interesariuszy pokazuje Rysunek 7.","zycie":"Dzieci chcą grać, rodzice chcą ciszy; te sprzeczne życzenia stają się celami domu, a potem wymaganiami wobec sprzętu."},"bk_wym2_kryt":{"kw":["cele aktywator","jakość","oczekiwan"],"pulapka":"Cele aktywatora definiuje się wg oczekiwanych wyników i wg zastosowania samego aktywatora; kategorie celów to jakość rzeczywista, kontekstowa oraz dostęp i bezpieczeństwo.","zycie":"Odkurzacz oceniasz po czystym dywanie (wynik) i po tym, czy wygodnie się nim sprząta (samo używanie)."},"bk_wym2_ostatni":{"kw":["ostatni","kaskad","cele aktywator"],"pulapka":"Cele aktywatorów to ostatni etap kaskady celów; nie są jej punktem wyjścia ani celami przedsiębiorstwa.","zycie":"Ostatni szczebel drabiny: od marzenia rodziny do konkretnego zadania dla pralki czy kalendarza."},"bk_wym3_def":{"kw":["cykl życia","planowanie","pozbywa"],"pulapka":"Fazy cyklu życia aktywatora to planowanie, projektowanie, budowanie/nabywanie, użytkowanie, ocena/monitorowanie, aktualizacja/pozbywanie się; to nie siedem faz wdrożenia z Rysunku 17.","zycie":"Rodzinny samochód: wybór modelu, zakup, jazda, przeglądy, a w końcu sprzedaż albo złomowanie."},"bk_wym4_def":{"kw":["dobre praktyki","produkty działań","dobrych praktyk"],"pulapka":"Dobre praktyki obejmują praktyki oraz produkty działań (dane wejściowe i wyniki); to czwarty wymiar aktywatora, obok interesariuszy, celów i cyklu życia.","zycie":"Sprawdzony sposób babci na kiszenie ogórków: co robić i co mieć na wejściu (słoje, sól, koper), żeby wyszły dobrze."},"bk_wym4_zrodla":{"kw":["dobre praktyki","standard","metodyk"],"pulapka":"COBIT 5 daje przykłady dobrych praktyk tylko dla niektórych aktywatorów (np. procesów); dla innych korzysta się z wytycznych innych standardów i metodyk.","zycie":"Przepisy na ciasta masz w rodzinnej książce, a jak naprawić pralkę, sprawdzasz w instrukcji producenta."},"bk_wym_korz":{"kw":["wymiar","wspólnych wymiar"],"pulapka":"Wspólne wymiary dają typowe, proste i ustrukturyzowane użycie aktywatorów, zarządzanie ich złożonymi interakcjami i skuteczne wykorzystanie.","zycie":"Jeden formularz dla każdego sprzętu w domu (kto używa, po co, jak długo, jak o niego dbać) porządkuje cały dom."},"bk_wyzn_inter":{"kw":["wyznacznik","potrzeby interesariuszy","krok 1"],"pulapka":"Krok 1 to wyznaczniki (zmiany strategii, otoczenia biznesowego i regulacyjnego, nowe technologie), które wpływają na potrzeby; potrzeby nie są jeszcze celami przedsiębiorstwa.","zycie":"Nowe przepisy o piecach, przeprowadzka czy narodziny dziecka zmieniają to, czego rodzina potrzebuje od domu."},"bk_z2_a":{"kw":["wszystkich aspektów","funkcji it","wszystkie funkcje"],"pulapka":"Zasada 2 nie ogranicza się do funkcji IT; informacja i technologia to aktywa, o które dbają wszyscy pracownicy, jak o każdy inny zasób.","zycie":"O oszczędzanie prądu w domu dbają wszyscy domownicy, a nie tylko tata, który zna się na elektryce."},"bk_z2_b":{"kw":["kompleksow","ogólnofirmow","wewnątrz"],"pulapka":"Aktywatory są ogólnofirmowe i kompleksowe: obejmują wszystkich i wszystko, także strony spoza przedsiębiorstwa; ograniczenie ich do wnętrza firmy to błąd.","zycie":"Przy organizacji wesela liczy się nie tylko rodzina, ale też catering, zespół muzyczny i sala: wszyscy, w domu i poza nim."},"bk_z2_info":{"kw":["cykl życia","informacj","wymog"],"pulapka":"Model aktywatora pozwala zdefiniować wymogi informacyjne i cykl życia informacji; Informacja to aktywator, który łączy potrzeby biznesu z IT.","zycie":"Dla rodzinnych przepisów ustalasz: kto ich potrzebuje, jak mają wyglądać, gdzie leżą i kiedy wyrzucić stare."},"bk_z2_lad_korp":{"kw":["ładu korporacyjnego","ład korporacyjn"],"pulapka":"Ład IT jest częścią ładu korporacyjnego i da się go płynnie zintegrować z każdym systemem nadzoru; nie zastępuje ładu korporacyjnego.","zycie":"Zasady korzystania z rodzinnego auta są częścią ogólnych zasad domu, a nie osobnym regulaminem."},"bk_z2_wszedzie":{"kw":["wszystkie funkcje","zewnętrzn","usług it"],"pulapka":"Rozszerzone przedsiębiorstwo obejmuje wewnętrzne i zewnętrzne usługi IT oraz procesy biznesowe, wszędzie tam, gdzie przetwarzana jest informacja.","zycie":"Dokumenty rodziny są w szufladzie, w telefonie, u księgowej i w banku, więc dbasz o nie wszędzie, nie tylko w domu."},"bk_z3_jak":{"kw":["cobit 4.1","załącznik","materiał"],"pulapka":"Źródła COBIT 5 to wytyczne ISACA (COBIT 4.1, Val IT 2.0, Risk IT, BMIS) oraz dopasowanie do ITIL, TOGAF i norm ISO; pełna lista jest w Załączniku A.","zycie":"Nowa książka kucharska: zebrane stare przepisy rodziny, dopisane brakujące, porównane z poradnikami szefów kuchni i ułożone według działów."},"bk_z3_nadrz":{"kw":["nadrzędn","itil","zintegrowan"],"pulapka":"COBIT 5 nie zastępuje ITIL, TOGAF ani norm ISO; jest z nimi spójny na wysokim poziomie, więc może być strukturą nadrzędną, która je integruje.","zycie":"Jeden duży parasol, pod którym mieszczą się mniejsze: osobne przepisy na ciasta, zupy i sałatki zebrane w jednej książce kucharskiej."},"bk_z3_p1":{"kw":["nadrzędn","spójn","standard"],"pulapka":"Spójność z innymi standardami pozwala integrować je pod COBIT 5 jako strukturą nadrzędną; COBIT ich nie zastępuje ani nie unieważnia.","zycie":"Jeden kalendarz rodzinny, do którego przepisujesz plan treningów, szkoły i pracy z osobnych kalendarzy."},"bk_z3_p2":{"kw":["techniczn","język","całe przedsiębiorstwo"],"pulapka":"COBIT 5 obejmuje całe przedsiębiorstwo i jest pisany językiem przystępnym dla osób bez wiedzy technicznej; nie jest przeznaczony tylko dla specjalistów IT.","zycie":"Instrukcja do pralki napisana tak, że zrozumie ją babcia, a nie tylko serwisant."},"bk_z3_p3":{"kw":["architektur","produkt"],"pulapka":"Prosta architektura strukturyzuje materiały pomocnicze i tworzy spójny zbiór produktów; to cecha Zasady 3, a nie Zasady 4.","zycie":"Szafka kuchenna z jasnymi przegródkami, w której łatwo dołożyć nową przyprawę we właściwe miejsce."},"bk_z3_p4":{"kw":["val it","risk it","bmis"],"pulapka":"COBIT 5 łączy wiedzę ISACA: COBIT, Val IT, Risk IT, BMIS, Board Briefing on IT Governance i ITAF; ITIL i TOGAF to standardy zewnętrzne.","zycie":"Zamiast kilku zeszytów babci z przepisami na ciasta, zupy i przetwory masz jedną książkę, w której jest wszystko."},"bk_z3_powody":{"kw":["zintegrowan","jednej zintegrowanej","zasada 3"],"pulapka":"Cztery powody to: spójność z innymi standardami, objęcie całego przedsiębiorstwa, prosta architektura i połączenie wiedzy ISACA; „zastępuje ITIL” nie jest powodem.","zycie":"Jedna rodzinna książka domowa: spójna z poradnikami, zrozumiała dla każdego, prosto ułożona i zbierająca stare notatki."},"bk_z5_3roznice":{"kw":["oddzielenie","struktur","zasada 5"],"pulapka":"Ład i Zarządzanie różnią się rodzajem działań, strukturami organizacyjnymi i celami, a nie tym, że jedno dotyczy biznesu, a drugie IT.","zycie":"Zarząd klubu i trener różnią się tym, co robią, w jakim gronie zasiadają i jaki cel mają."},"bk_zach1":{"kw":["wobec ryzyka","zachowanie","ryzyk"],"pulapka":"Zachowanie wobec podejmowania ryzyka pyta, ile ryzyka organizacja może przyjąć i jakie chce podjąć; nie myl go z zachowaniem wobec negatywnych wyników.","zycie":"Jeden kierowca jeździ ostrożnie, drugi wyprzedza na trzeciego. Rodzina musi wiedzieć, ile ryzyka na drodze może i chce zaakceptować."},"bk_zach2":{"kw":["przestrzegania polityk","zachowanie"],"pulapka":"Zachowanie wobec przestrzegania polityki dotyczy tego, w jakim stopniu pracownicy przyjmują politykę i jej przestrzegają; samo istnienie polityki nie oznacza właściwego zachowania.","zycie":"W domu obowiązuje zasada „buty zostawiamy w przedpokoju”. Pytanie brzmi, ilu domowników naprawdę ją stosuje."},"bk_zach3":{"kw":["negatywnych wynik","obwinia"],"pulapka":"Zachowanie wobec negatywnych wyników: czy organizacja traktuje szkodę jako okazję do nauki i usuwa przyczynę, czy tylko przypisuje winę; kultura obwiniania to symptom złej kultury.","zycie":"Po spalonym obiedzie jedna rodzina szuka winnego, a druga sprawdza, czemu kuchenka grzeje za mocno, i kupuje minutnik."},"bk_zach_ind":{"kw":["zachowania indywidualne","kultur"],"pulapka":"Zachowania indywidualne łącznie określają kulturę organizacji; wpływają na nie czynniki zewnętrzne, relacje interpersonalne oraz osobiste cele i ambicje.","zycie":"Gdy każdy zawodnik osobno spóźnia się na trening, cała drużyna ma kulturę spóźnialstwa."},"bk_zakres_cobit":{"kw":["zakres","przedsiębiorstw"],"pulapka":"Zakresem COBIT 5 jest przedsiębiorstwo, ale metodyka może działać przy każdym sposobie postrzegania zakresu; nie ogranicza się do działu IT.","zycie":"Mapa całego miasta, której możesz użyć też do zaplanowania spaceru po jednej dzielnicy."},"bk_zakres_nadzoru":{"kw":["zakres","jednostk"],"pulapka":"Nadzór może dotyczyć całego przedsiębiorstwa, jednostki, środków trwałych czy wartości niematerialnych; zakres systemu nadzoru trzeba zdefiniować.","zycie":"Możesz pilnować porządku w całym domu, tylko w kuchni albo tylko w garażu; trzeba najpierw ustalić, czego to dotyczy."},"bk_zal_a":{"kw":["inne standardy","itil","togaf","prince2"],"pulapka":"Załącznik A to lista 17 materiałów referencyjnych użytych przy tworzeniu COBIT 5; nie myl go z mapowaniem procesów na standardy z Załącznika E i Procesów umożliwiających.","zycie":"Babcina książka kucharska powstała z przepisów od sąsiadek, z gazet i od mamy. Korzysta z wielu źródeł, ale jest jedną spójną całością."},"bk_zal_a_arch":{"kw":["togaf","architektur"],"pulapka":"TOGAF 9, FEA i CEAF to źródła o architekturze korporacyjnej; nie o zarządzaniu usługami IT jak ITIL ani o projektach jak PRINCE2.","zycie":"Plan zagospodarowania osiedla mówi, gdzie staną bloki, drogi i rury, zanim ktokolwiek zacznie budować. Takie plany robią architekci."},"bk_zal_a_lad":{"kw":["38500","ład korporacyjny","king"],"pulapka":"Ze źródeł o ładzie ISO/IEC 38500 dotyczy Ładu IT i jest powiązana z domeną EDM; nie myl jej z ISO/IEC 15504 (ocena procesów) ani ISO/IEC 20000 (usługi IT).","zycie":"Regulamin wspólnoty mieszkaniowej korzysta z ustawy, statutu i dobrych zwyczajów innych bloków. To źródła o tym, kto decyduje i kto odpowiada."},"bk_zal_a_proj":{"kw":["prince2","pmbok","zarządzania zmianą"],"pulapka":"PRINCE2 i PMBOK to źródła zarządzania projektami, MSP i APM – programami, a Kotter „Leading Change” – zmianą; Kotter nie jest metodyką prowadzenia projektów.","zycie":"Przy organizacji wesela ktoś pilnuje harmonogramu, ktoś koordynuje kilka imprez naraz, a ktoś przekonuje rodzinę do zmian. To projekt, program i zmiana."},"bk_zal_a_usl":{"kw":["itil","iso 9001","27001"],"pulapka":"ITIL i ISO/IEC 20000 to usługi IT, ISO 9001 – jakość, BS25999 – ciągłość działania, ISO/IEC 27005 – ryzyko bezpieczeństwa informacji; łatwo je pomylić w pytaniach dopasowujących.","zycie":"Sklep osiedlowy dba, by towar był dobrej jakości, kasy działały mimo awarii prądu, klienci byli dobrze obsłużeni, a zamki chroniły przed złodziejem."},"bk_zarz_def":{"kw":["pbrm","uruchamian","planowanie, budowanie"],"pulapka":"Zarządzanie to Planowanie, Budowanie, Uruchamianie, Monitorowanie (PBRM) zgodnie z kierunkiem od Ładu; słowo „monitorowanie” jest w obu definicjach, więc niczego nie rozstrzyga.","zycie":"Trener planuje treningi, buduje skład, prowadzi mecze i sprawdza wyniki, zgodnie z celami postawionymi przez zarząd klubu."},"bk_zarz_kto":{"kw":["ceo","kadra zarządzając","kadra kierownicza"],"pulapka":"Za Zarządzanie odpowiada zwykle kierownictwo wykonawcze pod przywództwem CEO. Odróżnij tę rolę od organu nadzorującego (board) i jego przewodniczącego; polskie nazwy stanowisk zależą od ustroju organizacji.","zycie":"W restauracji właściciele ustalają kierunek, a codzienną pracą kuchni kieruje szef kuchni ze swoim zespołem."},"bk_zasady_kryt":{"kw":["ograniczona liczba","prosty język"],"pulapka":"Kryteria dotyczą zasad: ograniczona liczba oraz prosty i precyzyjny język; nie myl ich z cechami dobrych polityk (skuteczne, wydajne, nieinwazyjne) ani struktur ramowych.","zycie":"Najlepsze zasady drużyny to trzy krótkie hasła w szatni, a nie trzydzieści akapitów, których nikt nie pamięta."},"bk_zasady_razem":{"kw":["pięć zasad","5 zasad","zasad"],"pulapka":"Zasad jest pięć i dopiero razem dają skuteczny system Ładu i Zarządzania; nie myl ich z siedmioma aktywatorami ani z sześcioma dążeniami zarządów.","zycie":"Jak pięć palców jednej dłoni: każdy osobno niewiele utrzyma, a razem pozwalają mocno chwycić."},"bk_zdolnosc_usl":{"kw":["zdolności usługow","zdolność usługow","infrastruktur"],"pulapka":"Zdolność do świadczenia usług odnosi się do zasobów, takich jak aplikacje i infrastruktura, wykorzystywanych do świadczenia usług związanych z IT. Odróżnij zdolność od codziennego dostarczania i wsparcia usługi; cała kategoria Usługi, infrastruktura i aplikacje jest wyróżniona jako zasób.","zycie":"Kuchnia restauracji – piec, lodówki, garnki i notes zamówień – to wyposażenie, dzięki któremu kelnerzy mogą podać danie gościom."},"bk_zewn_dp":{"kw":["dobre praktyki","inne standardy","zewnętrzn"],"pulapka":"Zewnętrzne dobre praktyki (inne normy i struktury ramowe) mogą mieć dowolną formę i szczegółowość; COBIT jest z nimi dopasowany i podaje zestawienia, ale ich nie przepisuje.","zycie":"Do domowego segregatora z instrukcjami dokładasz porady z internetu i ulotki w dowolnej formie, a spis mówi, co do czego pasuje."},"bk_zi1":{"kw":["fuzj","przejęci","zdarzenia wyzwalając"],"pulapka":"Fuzje, przejęcia i zbycia to zdarzenie wyzwalające (zmiana w otoczeniu firmy), a nie punkt zapalny.","zycie":"Dwie rodziny łączą się po ślubie i trzeba ustalić wspólne zasady domu, konta i obowiązki."},"bk_zi2":{"kw":["pozycj","konkurencyj","zdarzenia wyzwalając"],"pulapka":"Zmiana pozycji rynkowej, ekonomicznej lub konkurencyjnej to zdarzenie wyzwalające, a nie czynnik kontekstu „praktyki stosowane w branży”.","zycie":"Obok osiedlowego sklepu otwiera się duży market i właściciel musi przemyśleć, jak dalej działać."},"bk_zi3":{"kw":["sourcing","zdarzenia wyzwalając","zdarzenie wyzwalając"],"pulapka":"Zmiana modelu biznesowego lub uzgodnień zaopatrzenia to zdarzenie wyzwalające; problemy z istniejącym outsourcingiem to punkt zapalny.","zycie":"Rodzina przestaje chodzić do sklepu i przechodzi na dostawy z internetu; zmienia się cały sposób zaopatrzenia."},"bk_zi4":{"kw":["nowe wymagania","regulacyjn","zdarzenia wyzwalając"],"pulapka":"Nowe wymagania regulacyjne lub zgodności to zdarzenie wyzwalające, a niespełnianie obecnych wymogów regulacyjnych to punkt zapalny.","zycie":"Wchodzi nowy przepis o obowiązkowych czujnikach dymu w mieszkaniach i trzeba coś w domu zmienić."},"bk_zi5":{"kw":["paradygmat","technologi","zdarzenia wyzwalając"],"pulapka":"Istotna zmiana technologii lub przesunięcie paradygmatu to zdarzenie wyzwalające; IT blokujące innowacje to punkt zapalny.","zycie":"Sąsiedzi przechodzą z pieca węglowego na pompę ciepła, co zmienia sposób ogrzewania całego osiedla."},"bk_zi6":{"kw":["ogólnofirmow","inicjatyw","zdarzenia wyzwalając"],"pulapka":"Ogólnofirmowa inicjatywa lub projekt nadzoru to zdarzenie wyzwalające; nie myl go z „powielaniem inicjatyw”, które jest punktem zapalnym.","zycie":"Wspólnota ogłasza remont całego bloku i każde mieszkanie musi się do niego przygotować."},"bk_zi7":{"kw":["nowy ceo","nowy dyrektor","zdarzenia wyzwalając"],"pulapka":"Nowy CEO, CFO czy CIO to zdarzenie wyzwalające; brak zadowolonych sponsorów biznesowych IT to punkt zapalny.","zycie":"Do drużyny przychodzi nowy trener i od razu chce przejrzeć, jak wszystko działa."},"bk_zi8":{"kw":["audyt zewnętrzn","konsultant","zdarzenia wyzwalając"],"pulapka":"Audyt zewnętrzny lub ocena konsultantów to zdarzenie wyzwalające; audyty regularnie wskazujące słabą sprawność IT to punkt zapalny.","zycie":"Rzeczoznawca ogląda dom przed sprzedażą i wskazuje, co trzeba poprawić."},"bk_zi9":{"kw":["nowa strategia","strategi","zdarzenia wyzwalając"],"pulapka":"Nowa strategia biznesowa lub nowy priorytet to zdarzenie wyzwalające; w kaskadzie zmiany strategii są też wyznacznikiem interesariuszy (krok 1).","zycie":"Rodzina postanawia od teraz oszczędzać na własne mieszkanie i zmienia priorytety wszystkich wydatków."},"bk_zm_opor":{"kw":["opór","oporu","ustrukturyzowan"],"pulapka":"Nie należy zakładać, że interesariusze chętnie przyjmą zmianę; brak świadomości i opór uwzględnia się w podejściu ustrukturyzowanym i proaktywnym.","zycie":"Nie zakładaj, że dzieci ucieszą się z zakazu telefonów przy stole; przygotuj się na opór i wytłumacz wszystko zawczasu."},"bk_zm_plan_kom":{"kw":["plan komunikacji","komunikacj"],"pulapka":"Plan komunikacji określa treść, sposób i odpowiedzialność za przekaz w kolejnych fazach programu (Framework EN s. 37: by whom). FW-PL s. 37 mówi o adresatach; praktyczny plan powinien określać zarówno nadawcę, jak i odbiorcę.","zycie":"Przed przeprowadzką ustalasz, co, jak i komu powiesz na każdym etapie: dzieciom, sąsiadom i babci."},"bk_zm_trwala":{"kw":["trwał","egzekw","zaangażowani"],"pulapka":"Trwałą poprawę daje zaangażowanie interesariuszy (zaufanie, liderzy, komunikacja) lub, gdy trzeba, egzekwowanie zgodności (administrowanie, monitorowanie, egzekwowanie).","zycie":"Porządek w pokoju utrzymasz, gdy dzieci same chcą go pilnować albo gdy codziennie sprawdzasz i wymagasz."},"bk_zm_wlasciwa":{"kw":["umożliwienie zmian","zachowani","zmian"],"pulapka":"Wdrożenie wymaga właściwej zmiany wprowadzonej we właściwy sposób; najczęściej zaniedbuje się aspekt ludzki, zachowanie i kulturę, a nie technikę.","zycie":"Nowa dieta to nie tylko lista produktów, ale też przekonanie domowników, że warto ją jeść."},"bk_zwiazane_it":{"kw":["związane z it","powiązan","technologi"],"pulapka":"„Związane z IT” oznacza informację i powiązaną technologię, a nie wyłącznie dział IT czy jego cele.","zycie":"„Domowa elektronika” to nie tylko kąt z komputerem, ale też wszystkie rachunki, zdjęcia i dokumenty, które w niej trzymasz."},"cakt":{"kw":["cele aktywator","krok 4"],"pulapka":"Cele aktywatorów (krok 4 kaskady) dotyczą wszystkich siedmiu aktywatorów, nie tylko procesów: podręcznik mówi, że same procesy nie wystarczą.","zycie":"Cel „szybsze śniadania” rozpisuje się na cele dla wszystkiego: lista zakupów, podział dyżurów, sprawny ekspres i dzieci, które umieją zrobić kanapki."},"ce1":{"kw":["wartość inwestycji","cel organizacji","rysunek 5"],"pulapka":"Cel 1 (Finanse) ma P tylko przy realizacji korzyści i S przy zasobach; nie myl go z celem IT 05 „Uzyskanie korzyści z inwestycji i portfela usług związanych z IT”.","zycie":"Rodzina wkłada oszczędności w nowy piec; po roku sprawdza, czy rachunki za ogrzewanie spadły na tyle, żeby zakup się opłacił."},"ce10":{"kw":["optymalizacja kosztów świadczenia usług","cel 10"],"pulapka":"Cel 10 leży w wymiarze Klient, nie Obszar wewnętrzny; ma P przy korzyściach i zasobach, a nie przy ryzyku; koszty procesów biznesowych to osobny cel 12.","zycie":"Pizzeria tak układa trasy dostawców, żeby jeden kierowca obsłużył całe osiedle w jednym kursie."},"ce11":{"kw":["funkcjonalno","procesów biznesowych","cel organizacji"],"pulapka":"Cel 11 (Obszar wewnętrzny) dotyczy funkcjonalności procesów biznesowych (P przy korzyściach i zasobach); nie myl z celem 12 (ich koszty) ani z celem IT 12 (integracja aplikacji z procesami).","zycie":"Rodzina przestawia kuchnię tak, żeby lodówka, zlew i kuchenka stały blisko siebie i gotowanie szło sprawniej."},"ce12":{"kw":["procesów biznesowych","optymalizacja kosztów"],"pulapka":"Cel 12 to koszty procesów biznesowych (Obszar wewnętrzny), a cel 10 to koszty świadczenia usług (Klient); oba mają P przy korzyściach i zasobach.","zycie":"Piekarz kupuje mąkę hurtem i piecze nocą w tańszej taryfie prądu, żeby każdy bochenek kosztował mniej."},"ce13":{"kw":["programami biznesowymi","zmiany biznesowe"],"pulapka":"Cel 13 (Obszar wewnętrzny) to programy zmian biznesowych (P przy korzyściach i ryzyku, S przy zasobach); cel IT 13 dotyczy realizacji programów w terminie i budżecie.","zycie":"Przeprowadzka rodziny do innego miasta: nowa szkoła, praca i lekarz, zaplanowane krok po kroku, żeby nic się nie rozsypało."},"ce14":{"kw":["obszar wewnętrzny","cel organizacji","wymiar bsc"],"pulapka":"Cel 14 leży w Obszarze wewnętrznym, nie w Szkoleniu i rozwoju, choć mówi o pracownikach; ma P przy korzyściach i zasobach, a wykwalifikowany personel to cel 16.","zycie":"W warsztacie każdy mechanik ma swoje stanowisko i narzędzia pod ręką, więc w ciągu dnia naprawia więcej aut."},"ce15":{"kw":["zgodność z politykami wewnętrznymi","cel 15"],"pulapka":"Cel 15 to zgodność z politykami wewnętrznymi (Obszar wewnętrzny, P tylko przy ryzyku); zgodność z prawem to cel 4 (Finanse), a cel IT 15 to zgodność IT z politykami.","zycie":"Szkoła pilnuje własnego statutu: dyżury nauczycieli, regulamin wycieczek i zasady oceniania są naprawdę przestrzegane."},"ce16":{"kw":["wykwalifikowany i zmotywowany personel","zmotywowany personel"],"pulapka":"Cel 16 (Szkolenie i rozwój) ma S przy korzyściach i P przy ryzyku i zasobach; nie myl z celem IT 16 „Kompetentny i zmotywowany personel działu biznesowego i działu IT”.","zycie":"Klub piłkarski wysyła trenerów na kursy i nagradza najlepszych, żeby nie odchodzili do konkurencji."},"ce17":{"kw":["kultura innowacji","innowacji produktów"],"pulapka":"Cel 17 (Szkolenie i rozwój) ma P tylko przy realizacji korzyści; nie myl z celem IT 17 „Wiedza, kompetencje oraz inicjatywy w zakresie innowacji biznesowych”.","zycie":"Właścicielka kawiarni zachęca baristów do własnych przepisów; najlepszy co miesiąc trafia do karty."},"ce2":{"kw":["portfel konkurencyjnych","cel organizacji"],"pulapka":"Cel 2 leży w wymiarze Finanse, nie Klient, choć mówi o produktach; ma P przy korzyściach i ryzyku oraz S przy zasobach.","zycie":"Sklep osiedlowy dobiera towar tak, żeby klienci nie jeździli do marketu: świeże pieczywo, dobra kawa, ceny jak u konkurencji."},"ce3":{"kw":["zarządzane ryzyko","ochrona zasobów"],"pulapka":"Cel 3 (Finanse) ma P przy optymalizacji ryzyka i S przy zasobach; nie myl go z celem IT 04 „Zarządzanie ryzykiem biznesowym związanym z IT”.","zycie":"Właściciel warsztatu ubezpiecza narzędzia, montuje alarm i zamyka magazyn, żeby kradzież nie zatrzymała firmy."},"ce4":{"kw":["zgodność z przepisami prawa","cel organizacji"],"pulapka":"Cel 4 to zgodność z przepisami zewnętrznymi (Finanse, P tylko przy ryzyku); zgodność z politykami wewnętrznymi to cel 15 (Obszar wewnętrzny), a IT 02 to cel związany z IT.","zycie":"Restauracja trzyma się przepisów sanepidu i prawa pracy, żeby nie płacić kar i nie stracić pozwoleń."},"ce5":{"kw":["przejrzystość finansowa","cel organizacji"],"pulapka":"Cel 5 (Finanse) ma P przy korzyściach i S przy ryzyku i zasobach; nie myl go z celem IT 06 (przejrzystość kosztów, korzyści i ryzyka IT) ani z procesem EDM05.","zycie":"Skarbnik klubu pokazuje rodzicom, na co poszły składki: ile na stroje, ile na wyjazdy, ile na wynajem boiska."},"ce6":{"kw":["zorientowanych na klienta","cel organizacji"],"pulapka":"Cel 6 (Klient) ma P przy korzyściach i S przy zasobach; to cel organizacji, a „dostarczanie usług IT zgodnie z wymogami biznesowymi” to cel IT 07.","zycie":"Ekspedientka w piekarni pamięta, kto lubi chleb krojony, i sama proponuje odłożenie bułek na jutro."},"ce7":{"kw":["ciągłość i dostępność usług biznesowych","cel 7"],"pulapka":"Cel 7 (Klient) ma P tylko przy optymalizacji ryzyka, nie przy korzyściach; podstawowo wspierają go cele IT 04, 10 i 14 (Rysunek 22).","zycie":"Apteka dyżurna musi być otwarta w nocy i w święta; zamknięte drzwi to klient u konkurencji albo coś gorszego."},"ce8":{"kw":["zwinność","otoczenia biznesowego","cel organizacji"],"pulapka":"Cel 8 to cel organizacji w wymiarze Klient (P przy korzyściach, S przy zasobach); „Zwinność IT” to osobny cel IT 09.","zycie":"Gdy obok otwiera się dyskont, właściciel sklepiku w tydzień zmienia godziny otwarcia i dodaje dowóz zakupów."},"ce9":{"kw":["świadome podejmowanie decyzji","decyzji strategicznych","p p p"],"pulapka":"Cel 9 to jedyny cel z układem P P P (korzyści, ryzyko, zasoby); leży w wymiarze Klient, nie Finanse, a cel IT 14 to dostępność wiarygodnych informacji.","zycie":"Przed otwarciem drugiego sklepu właścicielka liczy ruch, sprzedaż i koszty najmu, zamiast ufać przeczuciu."},"ci1":{"kw":["zgodność it z biznesowymi","przykładzie 1","it bsc"],"pulapka":"Cel IT 01 leży w wymiarze Finanse IT BSC; w Przykładzie 1 (zadowolenie klientów) to jeden z czterech celów wybranych jako priorytet: 01, 04, 07, 09.","zycie":"Ekipa robi kuchnię pod to, czego rodzina naprawdę chce: dużo gotują, więc dostają duży blat, a nie modny barek."},"ci10":{"kw":["bezpieczeństwo informacji","infrastruktury"],"pulapka":"Cel 10 (bezpieczeństwo informacji, infrastruktury i aplikacji) leży w Obszarze wewnętrznym; nie myl go z kategorią celów aktywatora Dostęp i Bezpieczeństwo.","zycie":"Zamki w drzwiach, alarm i sejf chronią dom, sprzęty i dokumenty rodziny."},"ci11":{"kw":["aktywów","optymalizacja zasobów"],"pulapka":"Cel 11 (optymalizacja aktywów, zasobów i potencjału IT) leży w Obszarze wewnętrznym; nie myl go z Optymalizacją zasobów, składnikiem Celu Ładu z Rysunku 8.","zycie":"Rodzina dzieli jeden samochód tak, żeby jeździł codziennie, zamiast trzymać trzy stojące auta."},"ci12":{"kw":["integracj","procesów biznesowych"],"pulapka":"Cel 12 to integracja aplikacji i technologii z procesami biznesowymi (Obszar wewnętrzny); nie myl go z celem organizacji 11 „Optymalizacja funkcjonalności procesów biznesowych”.","zycie":"Nowy piekarnik pasuje do zabudowy i do tego, jak rodzina piecze, więc gotowanie idzie płynnie."},"ci13":{"kw":["programów","budżet"],"pulapka":"Cel 13 łączy terminowość, budżet i jakość programów (Obszar wewnętrzny); nie myl go z celem organizacji 13 „Zarządzanie programami biznesowymi — zmiany biznesowe”.","zycie":"Remont łazienki kończy się w terminie, w kosztorysie i zgodnie z umówionym standardem płytek."},"ci14":{"kw":["przydatnych informacji","proces decyzyjny","decyzj"],"pulapka":"Cel 14 (wiarygodne i przydatne informacje do decyzji) leży w Obszarze wewnętrznym, nie w wymiarze Klient; nie myl go z celem organizacji 9 o decyzjach strategicznych.","zycie":"Przed zakupem mieszkania rodzina ma sprawdzone informacje o cenach i czynszu, więc decyduje świadomie."},"ci15":{"kw":["politykami wewnętrznymi","zgodność it z politykami"],"pulapka":"Cel IT 15 (polityki wewnętrzne) leży w Obszarze wewnętrznym, a cel 02 (przepisy zewnętrzne) w Finansach; cel organizacji 15 ma prawie tę samą nazwę.","zycie":"Ekipa w bloku przestrzega regulaminu wspólnoty i hałasuje tylko w dozwolonych godzinach."},"ci16":{"kw":["zmotywowany personel","szkolenie i rozwój"],"pulapka":"Cel 16 obejmuje personel działu biznesowego i działu IT, nie tylko IT; leży w wymiarze Szkolenie i rozwój, obok celu organizacji 16.","zycie":"W drużynie zarówno zawodnicy, jak i sztab trenerski są dobrze wyszkoleni i chętni do gry."},"ci17":{"kw":["innowacj","szkolenie i rozwój"],"pulapka":"Cel 17 (wiedza i inicjatywy w zakresie innowacji biznesowych) leży w Szkoleniu i rozwoju; nie myl go z celem organizacji 17 „Kultura innowacji produktów i biznesu”.","zycie":"Kucharka w barze śledzi nowe przepisy i sama proponuje nowe dania na sezonową kartę."},"ci2":{"kw":["przepisami prawa","zgodność z przepisami"],"pulapka":"Cel 02 (przepisy zewnętrzne) jest w wymiarze Finanse, a cel 15 (polityki wewnętrzne) w Obszarze wewnętrznym; nie myl go też z celem organizacji 4.","zycie":"Elektryk robi instalację zgodnie z przepisami i pomaga właścicielowi przejść odbiór budynku."},"ci3":{"kw":["kadry zarządzającej","it bsc"],"pulapka":"Cel 03 (zaangażowanie kadry zarządzającej w decyzje o IT) leży w wymiarze Finanse IT BSC; kompetentny i zmotywowany personel to osobny cel 16 w Szkoleniu i rozwoju.","zycie":"Przy zakupie rodzinnego auta decydują rodzice, a nie tylko syn mechanik."},"ci4":{"kw":["zarządzanie ryzykiem biznesowym"],"pulapka":"Numer celu IT nie wskazuje procesu o tym samym numerze: cel 04 to nie APO04; ryzykiem zajmują się m.in. EDM03 i APO12.","zycie":"Przed zimą kierowca sprawdza opony i hamulce, żeby awaria nie zrujnowała rodzinnego wyjazdu."},"ci5":{"kw":["korzyści z inwestycji","portfel"],"pulapka":"Cel IT 05 (korzyści z inwestycji i portfela usług IT) leży w Finansach; nie myl go z celem organizacji 1 „Wartość inwestycji biznesowych dla interesariuszy”.","zycie":"Rodzina sprawdza, czy kupiona zmywarka naprawdę oszczędza czas i wodę, za które zapłaciła."},"ci6":{"kw":["przejrzystość kosztów","przejrzystość"],"pulapka":"Cel 06 łączy przejrzystość kosztów, korzyści i ryzyka IT (Finanse); nie myl go z celem organizacji 5 „Przejrzystość finansowa”.","zycie":"Na zebraniu wspólnoty zarządca pokazuje: ile kosztuje nowa winda, co da mieszkańcom i co może pójść źle."},"ci7":{"kw":["dostarczanie usług it","wymogami biznesowymi","przykładzie 1"],"pulapka":"Cel 07 to jeden z dwóch celów IT w wymiarze Klient (obok 08); w Przykładzie 1 (zadowolenie klientów) jest wśród czterech celów priorytetowych.","zycie":"Kasa w sklepie osiedlowym działa w godzinach, gdy przychodzą klienci, i obsługuje ich tak szybko, jak potrzebują."},"ci8":{"kw":["adekwatne wykorzystanie","it bsc"],"pulapka":"Cel 08 (adekwatne wykorzystanie aplikacji, informacji i technologii) leży w wymiarze Klient, nie w Obszarze wewnętrznym; nie myl go z celem 14 o informacjach do decyzji.","zycie":"Kupiona kosiarka naprawdę kosi trawnik, zamiast stać w garażu, bo nikt nie umie jej uruchomić."},"ci9":{"kw":["zwinność it","zwinność"],"pulapka":"Cel IT 09 „Zwinność IT” leży w Obszarze wewnętrznym; nie myl go z celem organizacji 8 (zwinność wobec otoczenia) ani z pryncypium architektury „zwinność”.","zycie":"Drużyna piłkarska szybko zmienia ustawienie, gdy rywal zaczyna grać inaczej."},"cit":{"kw":["cele związane z it","cele związane z informatyką","celu związanego z informatyką"],"pulapka":"Numer celu związanego z IT nie wskazuje procesu o tym samym numerze (cel IT 04 to nie APO04); cele IT wynikają z celów organizacji w kroku 3 kaskady.","zycie":"Rodzina chce płacić mniej za rachunki, więc cel dla domowej techniki brzmi: liczniki odczytywane w aplikacji i ogrzewanie sterowane z telefonu."},"corg":{"kw":["cele organizacji","zrównoważon","17 celów"],"pulapka":"17 typowych celów organizacji ułożono według wymiarów zrównoważonej karty wyników (BSC); „cele organizacji” (egzamin) i „cele przedsiębiorstwa” (podręcznik) to ten sam poziom kaskady.","zycie":"Właściciel sklepu osiedlowego spisuje cele na rok: zysk, więcej stałych klientów, porządek na zapleczu i przeszkolona obsługa."},"dapo":{"kw":["apo","dostosuj, planuj i organizuj","apo12"],"pulapka":"Egzamin: „Dostosuj, Planuj i Organizuj” (podręcznik: Dopasowanie, planowanie i organizacja); APO ma 13 procesów, m.in. APO12 Ryzyko i APO13 Bezpieczeństwo, i należy do Zarządzania.","zycie":"Przed sezonem trener ustala skład, plan treningów, budżet na sprzęt i to, kto odpowiada za szatnię."},"dbai":{"kw":["bai","twórz, nabywaj i wdrażaj"],"pulapka":"BAI ma 10 procesów, w tym zmiany BAI06, wiedzę BAI08, aktywa BAI09 oraz zarządzanie dostępnością i pojemnością BAI04. Codzienne działanie i wsparcie usług należą także do DSS; samo słowo dostępność nie przesądza o domenie.","zycie":"Ekipa kupuje i montuje nową kuchnię, uczy domowników obsługi płyty i oddaje gotowe pomieszczenie."},"ddss":{"kw":["dss","dostarczaj, obsługuj i wspieraj","dss02"],"pulapka":"DSS ma 6 procesów dostarczania i wsparcia, np. DSS02 zgłoszenia i incydenty, DSS03 problemy, DSS05 usługi bezpieczeństwa. To Wykonuj w PBRM. MEA odpowiada za monitorowanie i ocenę wydajności, kontroli i zgodności; bieżące monitorowanie może być także działaniem innych procesów.","zycie":"Dyżurny hydraulik spółdzielni codziennie odbiera telefony o cieknących kranach i naprawia je na bieżąco."},"decyz":{"kw":["uzasadnienie biznesowe","celem samym w sobie","kluczowy czynnik sukcesu"],"pulapka":"Właściwe środowisko to widoczne wsparcie kierownictwa, uzasadnienie biznesowe, zasoby i przydzielone role; aktywatory mają rozwiązywać realne problemy biznesu, nie być celem samym w sobie.","zycie":"Zanim ruszy remont, cała rodzina go popiera, wie, po co go robi, odkłada pieniądze i ustala, kto czego pilnuje."},"dmea":{"kw":["mea","monitoruj, oszacuj i oceń","mea01"],"pulapka":"MEA ma 3 procesy i należy do Zarządzania („Monitoruj” w PBRM), nie do Ładu; EDM monitoruje kierunek, a MEA mierzy sprawność, kontrolę wewnętrzną i zgodność.","zycie":"Raz w miesiącu kierowniczka sklepu porównuje sprzedaż z planem i zgłasza właścicielowi, co nie działa."},"docel":{"kw":["docelow","faza 3","dokąd chcemy"],"pulapka":"Poziom docelowy organizacja wybiera z rachunku kosztów i korzyści i bardzo rzadko jest on najwyższy; zdefiniowanie stanu docelowego to faza 3 („Do czego dążymy?”), nie faza 2.","zycie":"Rodzinie wystarczy pewne auto na co dzień, a nie sportowe; lepsze kosztowałoby więcej, niż dałoby korzyści."},"drv":{"kw":["wyznacznik","kaskad","potrzeby interesariuszy"],"pulapka":"Wyznaczniki (drivers) w kaskadzie celów to krok 1: wpływają na potrzeby interesariuszy; nie myl ich z wyznacznikami fazy 1 cyklu wdrożenia ani z celami organizacji.","zycie":"Zima się zbliża, ceny rosną, sąsiedzi kupili pompę ciepła: takie zmiany sprawiają, że rodzina zaczyna chcieć czegoś nowego od swojego domu."},"edm1":{"kw":["edm01"],"pulapka":"EDM01 ustala zasady decydowania o IT (ramy Ładu) i nie jest składnikiem celu Ładu; organizowanie ról, polityk i procesów działu IT to APO01 (Zarządzanie).","zycie":"Rodzina ustala, że o wydatkach powyżej tysiąca złotych decydują razem oboje rodzice, a o drobnych każde z nich samo."},"edm2":{"kw":["edm02","realizacja korzyści"],"pulapka":"EDM02 to realizacja korzyści na poziomie Ładu: rozlicza wartość inwestycji; zarządzanie portfelem to APO05, a prowadzenie projektu to BAI01.","zycie":"Po roku od zakupu zmywarki rodzina sprawdza, czy naprawdę zyskała czas i spokój, czy tylko wydała pieniądze."},"edm3":{"kw":["edm03","apetyt na ryzyko"],"pulapka":"EDM03 ustala apetyt na ryzyko i pilnuje granic (Ład); rejestr, analiza i codzienne zarządzanie ryzykiem to APO12 (Zarządzanie).","zycie":"Rodzice decydują, że nastolatek może wracać sam do 22, ale nie później; to ich granica akceptowalnego ryzyka."},"edm4":{"kw":["edm04","zasob"],"pulapka":"EDM04 to decyzja Ładu o wszystkich zasobach (ludzie, pieniądze, aktywa); ewidencja laptopów to BAI09, a braki w zespole kierownika to codzienne zarządzanie.","zycie":"Rodzina decyduje, ile pieniędzy i weekendów przeznaczy w tym roku na remont, a ile na wyjazdy."},"edm5":{"kw":["edm05","przejrzystości","transparentności"],"pulapka":"EDM05 to przejrzystość wobec interesariuszy na poziomie Ładu, a nie składnik celu Ładu; bieżące monitorowanie i raporty sprawności to MEA01.","zycie":"Zarząd wspólnoty raz w roku na zebraniu mówi mieszkańcom otwarcie, co zrobiono z ich pieniędzmi i co się nie udało."},"il10_baza_wiedzy":{"kw":["baza wiedzy","bazy wiedzy"],"pulapka":"Rysunek 10 przedstawia w bazie wiedzy aktualne wytyczne i strukturę dla przyszłych treści. Nie ogranicza jej do opisów 37 procesów; rodzina produktów powstaje na podstawie tej bazy.","zycie":"Domowy segregator na instrukcje sprzętów ma zapełnione koszulki i puste na sprzęty, które dopiero kupimy."},"il10_bw_aktualne":{"kw":["aktualne wytyczne","baza wiedzy"],"pulapka":"Aktualne wytyczne i treści to jeden z dwóch punktów bazy wiedzy (drugi: struktura dla przyszłych treści); nie myl bazy wiedzy z rodziną produktów, która z niej powstaje.","zycie":"Na półce stoją wszystkie poradniki, które rodzina zdążyła już zebrać."},"il10_bw_struktura":{"kw":["przyszłych treści","baza wiedzy"],"pulapka":"Struktura dla przyszłych treści oznacza, że baza wiedzy jest otwarta na rozbudowę; to drugi punkt bazy wiedzy, a nie osobny produkt ani filtr.","zycie":"W nowej szafie zostawiasz wolne półki na rzeczy, które dopiero kupisz, żeby potem nie przestawiać wszystkiego."},"il10_czynniki_c5":{"kw":["filtr","aktywatory cobit 5"],"pulapka":"Na Rysunku 10 aktywatory (czynniki umożliwiające) pełnią rolę filtra zawartości bazy wiedzy; filtrem nie są pięć zasad, BSC ani wejścia (ISACA, inne standardy).","zycie":"Kartony w przeprowadzce opisane „kuchnia”, „łazienka”, „sypialnia”: każda rzecz trafia do właściwego, więc łatwo ją potem znaleźć."},"il10_filtr":{"kw":["filtr","filtra zawartości"],"pulapka":"Filtrem zawartości na Rysunku 10 są aktywatory COBIT 5, nie pięć zasad; z przefiltrowanej bazy wiedzy powstaje rodzina produktów.","zycie":"Z wielkiej książki kucharskiej wybierasz tylko przepisy świąteczne i drukujesz z nich osobną broszurkę."},"il10_inne_standardy":{"kw":["itil","togaf","nadrzędn"],"pulapka":"COBIT 5 jest spójny z ITIL, TOGAF i normami ISO i może być nadrzędną strukturą ramową, ale ich nie zastępuje i nie musi być z nimi stosowany.","zycie":"Majster korzysta z norm budowlanych i instrukcji producentów, ale całym remontem kieruje według jednego planu."},"il10_nowe_isaca":{"kw":["nowe materiały","wejści"],"pulapka":"Nowe materiały ISACA uzupełniają obszary wymagające opracowania i aktualizacji; to drugie z trzech wejść do bazy wiedzy, a nie produkt rodziny COBIT 5.","zycie":"Do starego zeszytu z przepisami dopisuje się rozdział o daniach bezglutenowych, bo tego wcześniej brakowało."},"il10_obecne_isaca":{"kw":["val it","risk it","bmis"],"pulapka":"COBIT 5 łączy wcześniejsze wytyczne ISACA: COBIT 4.1, Val IT, Risk IT, BMIS (oraz m.in. ITAF); ITIL, TOGAF i normy ISO nie są wytycznymi ISACA.","zycie":"Rodzina łączy trzy stare zeszyty z przepisami, od babci, mamy i cioci, w jeden porządny zeszyt."},"il10_r_cobit5":{"kw":["framework","rodzina produktów"],"pulapka":"Sam COBIT 5 (framework) należy do rodziny produktów, ale nie jest ani przewodnikiem o aktywatorach, ani specjalistycznym; to metodyka główna.","zycie":"Główny podręcznik jazdy samochodem, do którego dochodzą osobne broszury o jeździe zimą czy z przyczepą."},"il10_r_przew_czynniki":{"kw":["procesy umożliwiające","informacje umożliwiające","aktywatorach"],"pulapka":"Przewodniki o aktywatorach to np. „Procesy umożliwiające” i „Informacje umożliwiające”; „Bezpieczeństwo informacji” mimo słowa „informacja” jest przewodnikiem specjalistycznym.","zycie":"Osobne instrukcje do każdego sprzętu w kuchni: jedna o piekarniku, druga o zmywarce."},"il10_r_przew_spec":{"kw":["specjalistyczn","cobit 5 – ryzyko"],"pulapka":"Przewodniki specjalistyczne to Wdrożenie, Bezpieczeństwo informacji, Audyt i Ryzyko; „Procesy umożliwiające” do nich nie należą (to przewodnik o aktywatorach).","zycie":"Poradnik „Jak przygotować dom do zimy” korzysta z wiedzy o wszystkich sprzętach naraz."},"il10_r_srodowisko":{"kw":["środowisko sieciowe","współpracy"],"pulapka":"Środowisko sieciowe oparte na współpracy jest elementem rodziny produktów (wyjście), a nie filtrem ani wejściem do bazy wiedzy.","zycie":"Osiedlowa grupa w komunikatorze, w której sąsiedzi wymieniają się poradami o remontach i polecają fachowców."},"il10_rodzina":{"kw":["rodzina produktów","rodziny produktów"],"pulapka":"Rodzina produktów to wyjście z bazy wiedzy: COBIT 5, przewodniki o aktywatorach, przewodniki specjalistyczne i środowisko współpracy; ITIL do niej nie należy.","zycie":"Z jednego zeszytu przepisów powstają broszurki o ciastach, zupach i grillu, a obok grupa w komunikatorze do wymiany porad."},"il10_zrodla":{"kw":["wejści","baza wiedzy","rysunek 10"],"pulapka":"Na Rysunku 10 trzy źródła (obecne wytyczne ISACA, nowe materiały ISACA, inne standardy) to wejścia do bazy wiedzy, a nie filtr ani rodzina produktów.","zycie":"Do domowej książki kucharskiej trafiają przepisy babci, nowe od znajomych i te z gazet; wszystkie zbiera się w jednym miejscu."},"il14_informacje":{"kw":["wejścia i wyjścia","dane wejściowe","rysunek 14"],"pulapka":"Informacje łączą Ład i Zarządzanie jako wejścia i wyniki praktyk procesów; dostarczanie organowi Ładu informacji przez systemy to interakcja przez Usługi, infrastrukturę i aplikacje.","zycie":"Właściciel kamienicy dostaje od zarządcy miesięczny raport i odsyła mu decyzje; bez tej wymiany kartek nie ma porządnego zarządzania domem."},"il14_kultura":{"kw":["odgórnie","przykład","kultura, etyka"],"pulapka":"Zachowanie ustala się odgórnie, przez przykład przywództwa; odpowiedzi o kształtowaniu kultury oddolnie albo głosowaniem pracowników są błędne.","zycie":"Dyrektorka szkoły sama nie parkuje na kopercie dla niepełnosprawnych i po miesiącu nauczyciele też przestają."},"il14_ludzie":{"kw":["ludzie, umiejętności","umiejętności","rysunek 14"],"pulapka":"Kluczowa umiejętność członków organu Ładu i osób zarządzających to znajomość charakteru obu ról i dzielących je różnic, a nie identyczne kompetencje.","zycie":"Inwestor musi umieć ocenić projekt domu, a kierownik budowy poprowadzić ekipy; obaj muszą rozumieć, czym różnią się ich zadania."},"il14_procesy":{"kw":["raci","rysunek 14","edm"],"pulapka":"Interakcja przez Procesy to rozdział procesów Ładu i Zarządzania plus tabele RACI; decyzje o portfelu i apetycie na ryzyko to interakcja przez Struktury.","zycie":"W restauracji tablica zadań mówi, kto gotuje, kto zatwierdza menu, kogo pytać o alergeny i kogo informować o brakach."},"il14_struktury":{"kw":["apetyt na ryzyko","portfel","struktury organizacyjne"],"pulapka":"Struktury Ładu decydują np. o portfelu inwestycji i apetycie na ryzyko, co wpływa na decyzje wdrożeniowe; instytucjonalizacja decyzji Ładu to rola Zasad i polityk.","zycie":"Rodzice ustalają, ile wydać na wakacje i czy ryzykować wyjazd last minute, a ciocia organizująca wyjazd dobiera do tego hotel."},"il14_uslugi":{"kw":["usługi, infrastruktura","infrastruktur","rysunek 14"],"pulapka":"Usługi, infrastruktura i aplikacje dostarczają organowi Ładu informacji do oceny, kierowania i monitorowania; wymiana wejść i wyników między procesami to aktywator Informacje.","zycie":"Licznik prądu z wyświetlaczem w kuchni pokazuje właścicielowi domu bieżące zużycie, więc może ocenić sytuację i zdecydować o oszczędnościach."},"il14_zasady":{"kw":["instytucjonaliz","polityk"],"pulapka":"Zasady, polityki i struktury ramowe instytucjonalizują decyzje Ładu; kusi odpowiedź „Struktury organizacyjne”, bo słowo „struktury” występuje w obu nazwach.","zycie":"Rodzinne postanowienie „oszczędzamy wodę” zostaje spisane w zasadach domu, więc obowiązuje także wtedy, gdy rodziców nie ma."},"il1_audyt":{"kw":["audyt","przewodnik specjalistyczny"],"pulapka":"COBIT 5 — Audyt (EN: Assurance) to przewodnik specjalistyczny; audytor szuka go wśród przewodników specjalistycznych, nie wśród przewodników o aktywatorach.","zycie":"Osobna instrukcja dla rzeczoznawcy, który sprawdza, czy dom zbudowano zgodnie z projektem."},"il1_bezp_inf":{"kw":["bezpieczeństwo informacji","przewodnik specjalistyczny"],"pulapka":"COBIT 5 — Bezpieczeństwo informacji to przewodnik specjalistyczny; nie myl go z przewodnikiem o aktywatorze Informacje umożliwiające.","zycie":"Poradnik dla rodziców o tym, jak chronić dokumenty, klucze i zapasowe kody do domowego alarmu."},"il1_cobit5":{"kw":["rodzina produktów","rodziny produktów","struktura ramowa"],"pulapka":"COBIT 5 (struktura ramowa) to centrum rodziny produktów: pięć zasad i aktywatory; szczegóły 37 procesów są w przewodniku Procesy umożliwiające, nie w samej strukturze ramowej.","zycie":"Główna książka kucharska rodziny opisuje zasady gotowania, a osobne zeszyty rozwijają ciasta czy przetwory."},"il1_informacje_umozl":{"kw":["informacje umożliwiające","rodziny produktów"],"pulapka":"„Informacje umożliwiające” to przewodnik o aktywatorze Informacja, a nie specjalistyczny przewodnik Bezpieczeństwo informacji.","zycie":"Osobny poradnik o domowych papierach mówi, jakie dokumenty trzymać, jak je opisywać i kiedy niszczyć."},"il1_inne_przew_czynniki":{"kw":["przewodników o aktywatorach","rodziny produktów"],"pulapka":"Pozostałe przewodniki o aktywatorach należą do grupy przewodników o aktywatorach, nie do specjalistycznych; podręcznik odsyła po nie na www.isaca.org/cobit.","zycie":"Seria poradników remontowych ma na półce miejsce na kolejne tomy, które wydawca dopiero dopisze."},"il1_inne_spec":{"kw":["przewodników specjalistycznych","rodziny produktów"],"pulapka":"Lista przewodników specjalistycznych jest otwarta: obok czterech wymienionych są inne, wskazane na www.isaca.org/cobit.","zycie":"Wydawca poradników kulinarnych zapowiada kolejne tomy: wegański, dla diabetyków, dla stołówek."},"il1_procesy_umozl":{"kw":["procesy umożliwiające","37 procesów"],"pulapka":"„Procesy umożliwiające” to przewodnik o aktywatorze, nie specjalistyczny; zawiera szczegóły wszystkich 37 procesów, m.in. RACI, wejścia i wyjścia praktyk.","zycie":"Książka serwisowa samochodu opisuje po kolei każdą czynność przeglądu, z kolejnością i odpowiedzialnymi."},"il1_przew_czynniki":{"kw":["przewodników o aktywatorach","procesy umożliwiające","rodziny produktów"],"pulapka":"Przewodniki o aktywatorach to np. Procesy umożliwiające i Informacje umożliwiające; Wdrożenie, Audyt, Ryzyko i Bezpieczeństwo informacji to przewodniki specjalistyczne.","zycie":"Do serii poradników ogrodniczych dochodzą tomy o pojedynczych sprawach: osobno gleba, osobno nawadnianie."},"il1_przew_spec":{"kw":["przewodnik specjalistyczny","przewodników specjalistycznych","przewodniki specjalistyczne"],"pulapka":"Przewodniki specjalistyczne (EN: professional guides) to Wdrożenie, Bezpieczeństwo informacji, Audyt, Ryzyko i inne; Procesy umożliwiające do nich nie należą.","zycie":"Oprócz ogólnego poradnika jazdy są osobne książki dla kierowcy ciężarówki, rajdowca i instruktora."},"il1_ryzyko":{"kw":["COBIT 5 Ryzyko","Risk IT"],"pulapka":"COBIT 5 — Ryzyko jest przewodnikiem specjalistycznym. Risk IT to wcześniejsza struktura ramowa ISACA uwzględniona w bazie wiedzy COBIT 5. Taking Governance Forward dotyczy podejścia do Ładu, nie nazwy tego przewodnika.","zycie":"Poradnik ubezpieczyciela pokazuje, co w domu może się zepsuć, zalać albo spłonąć i jak się na to przygotować."},"il1_srodowisko":{"kw":["środowisko sieciowe","rodziny produktów"],"pulapka":"Środowisko sieciowe oparte na współpracy to osobny element rodziny produktów, ani przewodnik o aktywatorach, ani specjalistyczny; jest wyjściem z bazy wiedzy, nie jej wejściem.","zycie":"Mieszkańcy osiedla mają wspólną grupę, gdzie wymieniają porady o remontach i pomagają sobie nawzajem."},"il1_wdrozenie":{"kw":["cobit 5 – wdrożenie","cobit 5 — wdrożenie","cyklu wdrożenia"],"pulapka":"COBIT 5 — Wdrożenie to przewodnik specjalistyczny, nie normatywny i nie kompletne rozwiązanie, lecz zbiór wskazówek; opisuje cykl wdrożenia w siedmiu fazach.","zycie":"Poradnik przeprowadzki mówi krok po kroku, jak przejść ze starego mieszkania do nowego bez chaosu."},"il20_k_jedn":{"kw":["dojrzałości","powtarzalne","ad hoc"],"pulapka":"Poziomy 0–2 to wiedza indywidualna: poziom 2 COBIT 4.1 zależy od wiedzy poszczególnych osób, stąd ryzyko błędów; dopiero od poziomu 3 wiedza jest korporacyjna.","zycie":"Tylko babcia wie, ile czego dać do bigosu; gdy wyjedzie, nikt w domu nie odtworzy smaku."},"il20_k_przeds":{"kw":["dojrzałości","zdefiniowany proces","ustanowiony"],"pulapka":"W kolumnie „Kontekst” Rysunku 20 poziomy 3–5 to punkt widzenia przedsiębiorstwa (wiedza korporacyjna), a 0–2 – jednostki; granica przebiega między poziomem 2 a 3.","zycie":"Przepis na rodzinny bigos jest spisany w zeszycie, więc ugotuje go każdy domownik, nie tylko babcia."},"il20_m0":{"kw":["nieistniejące","niekompletny"],"pulapka":"„Nieistniejące”, czyli całkowity brak rozpoznawalnych procesów, to poziom 0 COBIT 4.1; poziom 0 COBIT 5 („niekompletny”) obejmuje też proces, który istnieje, ale nie osiąga celu.","zycie":"W garażu od lat kapie olej z auta i nikt nawet nie zauważył, że to jakiś problem."},"il20_m1":{"kw":["ad hoc","dojrzałości"],"pulapka":"Poziom 1 COBIT 4.1 (Wstępne/Ad hoc) może w COBIT 5 dać poziom 0, jeśli proces nie osiąga swoich wyników.","zycie":"Gdy zalewa piwnicę, ktoś łapie wiadro i ściera wodę; problem jest znany, ale każdy radzi sobie po swojemu."},"il20_m2":{"kw":["powtarzalne","dojrzałości","cobit 4.1"],"pulapka":"Poziom 2 COBIT 4.1 („powtarzalne lecz intuicyjne”) opiera się na wiedzy osób; ten sam proces w COBIT 5 dostanie zwykle niższy wynik.","zycie":"Każdy w rodzinie robi pranie podobnie, bo podpatrzył mamę, ale nikt tego nie spisał; gdy mama wyjedzie, zaczynają się wpadki."},"il20_m3":{"kw":["zdefiniowany proces","dojrzałości"],"pulapka":"W COBIT 4.1 poziom 3 to procedury udokumentowane i przekazane szkoleniem, ale odstępstw raczej się nie wykrywa; 3 w COBIT 4.1 nie równa się poziomowi 3 w COBIT 5.","zycie":"W szatni wisi spisany regulamin, nowi zawodnicy przechodzą szkolenie, ale nikt nie sprawdza, czy ktoś łamie zasady."},"il20_m4":{"kw":["model dojrzałości","dojrzałości","pozorne podobieństw"],"pulapka":"„Zarządzane i mierzalne” to poziom 4 COBIT 4.1, a nie poziom 2 COBIT 5 („zarządzany”); wspólne słowo to tylko pozorne podobieństwo skal.","zycie":"Kierowniczka sklepu sprawdza, czy pracownicy trzymają się procedur, i reaguje, gdy coś nie działa; częściowo pomaga jej program kasowy."},"il20_m5":{"kw":["zoptymalizowane","dojrzałości","cobit 4.1"],"pulapka":"„Zoptymalizowane” to poziom 5 dojrzałości COBIT 4.1; poziom 5 zdolności COBIT 5 to „proces zoptymalizowany” (egzamin) lub „optymalizujący” (podręcznik). Definicje są inne, ocen nie przenosi się wprost.","zycie":"Restauracja z gwiazdką podpatruje najlepsze kuchnie świata, ma zautomatyzowane zamówienia i błyskawicznie zmienia menu, gdy zmieniają się gusta gości."},"il20_p0":{"kw":["niekompletny","poziom 0"],"pulapka":"Poziom 0 COBIT 5 to proces niewdrożony lub nieosiągający celu; „problemu nawet nie dostrzeżono” to opis poziomu 0 COBIT 4.1 (Nieistniejące).","zycie":"Rodzina „ma” plan oszczędzania, ale do skarbonki nikt nic nie wrzuca, więc celu nie ma szans osiągnąć."},"il20_p1":{"kw":["wykonywany","pa 1.1"],"pulapka":"Poziom 1 COBIT 5 wymaga, by proces osiągał swój cel; działanie doraźne bez efektu daje poziom 0.","zycie":"Dziecko co rano dociera do szkoły na czas; nieważne jak, ważne, że cel jest osiągany."},"il20_p1_uwaga":{"kw":["dojrzałości","niższe","poziom 0"],"pulapka":"Wyniki w COBIT 5 są zasadniczo niższe niż w COBIT 4.1: proces z 1 w modelu dojrzałości może dostać 0, a nie odwrotnie.","zycie":"Uczeń, który tylko „próbował” odrabiać lekcje, u łagodnej nauczycielki dostawał 1 punkt; u surowej dostaje 0, bo zadań nie rozwiązał."},"il20_p2":{"kw":["zarządzany","pa 2.1"],"pulapka":"Poziom 2 COBIT 5 („zarządzany”) to planowanie, monitorowanie, dostosowanie i kontrola produktów działań; nie myl go z poziomem 2 COBIT 4.1 („powtarzalne lecz intuicyjne”).","zycie":"Rodzice planują ferie, sprawdzają postępy przygotowań, zmieniają plan, gdy trzeba, a bilety i rezerwacje trzymają w jednej teczce."},"il20_p3":{"kw":["ustanowiony","pa 3.1"],"pulapka":"Poziom 3 COBIT 5 („ustanowiony”) to proces zarządzany, wdrożony jako zdefiniowany; „zdefiniowany proces” to nazwa poziomu 3 COBIT 4.1.","zycie":"Wszystkie oddziały przedszkola mają jedną spisaną procedurę odbioru dziecka i naprawdę według niej działają."},"il20_p4":{"kw":["przewidywalny","pa 4.1"],"pulapka":"Poziom 4 COBIT 5 („przewidywalny”) to proces ustanowiony, działający w zdefiniowanych granicach; „Zarządzane i mierzalne” z COBIT 4.1 to inna skala.","zycie":"Pociąg podmiejski jeździ według rozkładu z odchyleniem najwyżej dwóch minut, bo maszyniści pilnują ustalonych granic."},"il20_p5":{"kw":["optymalizujący","pa 5.1","zoptymalizowany"],"pulapka":"Poziom 5 COBIT 5 to proces przewidywalny, stale doskonalony pod obecne i przyszłe cele biznesowe; jego atrybuty to PA 5.1 Innowacja i PA 5.2 Optymalizacja.","zycie":"Ogrodnik, którego warzywnik już daje równe plony, co roku testuje nowe odmiany i nawozy pod plany na kolejne sezony."},"il21_a_cele":{"kw":["ustalanie celu","atrybutów dojrzałości","pa 4.1"],"pulapka":"Ustalanie celów i pomiar to atrybut dojrzałości COBIT 4.1; nie myl go z PA 4.1 Miara procesu ani z wymiarem Cele aktywatora.","zycie":"Odchudzający się ustala cel minus pięć kilo i co tydzień staje na wadze."},"il21_a_narzedzia":{"kw":["narzędzia i automatyzacja","atrybutów dojrzałości"],"pulapka":"Narzędzia i automatyzacja to atrybut dojrzałości COBIT 4.1 (jeden z sześciu); w COBIT 5 nie ma atrybutu procesu o tej nazwie.","zycie":"Zamiast płacić rachunki ręcznie, rodzina ustawia stałe zlecenia w banku."},"il21_a_odpowiedzialnosc":{"kw":["atrybutów dojrzałości","model dojrzałości"],"pulapka":"To atrybut dojrzałości COBIT 4.1, a nie macierz RACI z opisu procesu COBIT 5; ocena w COBIT 5 nie korzysta z atrybutów dojrzałości.","zycie":"W drużynie wiadomo, kto strzela karne i kto odpowie przed trenerem za pudło."},"il21_a_polityki":{"kw":["pewnym stopniu","atrybutów dojrzałości"],"pulapka":"Atrybuty COBIT 4.1 tylko „w pewnym stopniu pokrywają się” z atrybutami COBIT 5: starą ocenę można wykorzystać, ale nie przepisuje się jej jeden do jednego.","zycie":"Wspólnota ma spisany regulamin, roczny plan remontów i instrukcję zgłaszania awarii."},"il21_a_swiadomosc":{"kw":["świadomość i komunikowanie","atrybutów dojrzałości"],"pulapka":"To jeden z sześciu atrybutów dojrzałości COBIT 4.1, nie atrybut procesu COBIT 5; COBIT 5 ma dziewięć atrybutów procesu.","zycie":"W rodzinie wszyscy wiedzą, że w sobotę jest sprzątanie, bo mama ogłosiła to przy obiedzie."},"il21_a_umiejetnosci":{"kw":["atrybutów dojrzałości","cobit 4.1"],"pulapka":"Umiejętności i szczegółowa wiedza to atrybut dojrzałości COBIT 4.1; nie myl go z aktywatorem COBIT 5 Ludzie, Umiejętności i Kompetencje.","zycie":"Do wymiany instalacji gazowej wołasz fachowca z uprawnieniami, a nie szwagra."},"il21_pa11":{"kw":["pa 1.1","wykonanie procesu","poziom 1"],"pulapka":"Egzamin: PA 1.1 „Wykonanie procesu” (podręcznik: sprawność procesu); jedyny atrybut poziomu 1, oceniany przez praktyki bazowe i produkty pracy z modelu referencyjnego.","zycie":"Ciasto po prostu wychodzi i da się je zjeść, choć każdy piecze je po swojemu."},"il21_pa21":{"kw":["pa 2.1","zarządzanie wydajnością"],"pulapka":"Egzamin: PA 2.1 „Zarządzanie wydajnością” (podręcznik: zarządzanie sprawnością); dotyczy planowania i monitorowania wykonania, a nie produktów pracy (PA 2.2).","zycie":"Malowanie mieszkania ma plan na weekend; ktoś pilnuje postępu i przesuwa prace, gdy farba nie dojedzie."},"il21_pa22":{"kw":["pa 2.2","produktami pracy"],"pulapka":"Egzamin: PA 2.2 „Zarządzanie produktami pracy” (podręcznik: produktami działań); dotyczy wyników procesu, a nie standardowej definicji procesu (PA 3.1).","zycie":"Kosztorys remontu jest sprawdzony, podpisany i schowany w teczce, a każda poprawka ma nową datę."},"il21_pa31":{"kw":["pa 3.1","definicja procesu"],"pulapka":"Egzamin: PA 3.1 „Definicja procesu”: udokumentowany standardowy wzorzec; faktyczne stosowanie tego wzorca ocenia dopiero PA 3.2.","zycie":"Rodzina spisuje jeden przepis na wigilijny barszcz, z którego ma korzystać każdy, kto gotuje."},"il21_pa32":{"kw":["pa 3.2","wdrożenie procesu"],"pulapka":"Egzamin: PA 3.2 „Wdrożenie procesu”: chodzi o stosowanie standardowego procesu z rolami, kompetencjami i zasobami, a nie o 7 faz wdrażania COBIT 5.","zycie":"W sieci piekarni każdy oddział naprawdę piecze chleb według firmowej receptury, a piekarze są w niej przeszkoleni."},"il21_pa41":{"kw":["pa 4.1","miara procesu"],"pulapka":"Egzamin: PA 4.1 „Miara procesu” (podręcznik: pomiar procesu); pomiar to cecha poziomu 4, więc opis procesu w modelu referencyjnym go nie zawiera.","zycie":"Kierowca prowadzi zeszyt spalania i sprawdza, czy auto pali tyle, ile założył."},"il21_pa42":{"kw":["pa 4.2","kontrola procesu"],"pulapka":"Egzamin: PA 4.2 „Kontrola procesu”: utrzymanie wykonania w limitach daje przewidywalne wyniki (poziom 4); to nie system kontroli wewnętrznej z domeny MEA.","zycie":"Termostat utrzymuje temperaturę w ustalonym przedziale, więc w pokojach jest przewidywalnie ciepło."},"il21_pa51":{"kw":["pa 5.1","innowacja procesu"],"pulapka":"Egzamin: PA 5.1 „Innowacja procesu” (il. 19: innowacje procesowe); zmiany wynikają z analizy przyczyn zmienności, a ich wdrożenie ocenia PA 5.2.","zycie":"Właścicielka sklepu sprawdza, czemu w poniedziałki rośnie kolejka, i próbuje nowego układu kas."},"il21_pa52":{"kw":["pa 5.2","optymalizacja procesu","poziom 5"],"pulapka":"PA 5.2 „Optymalizacja procesu” to atrybut poziomu 5. Poziom 5 na egzaminie: „proces zoptymalizowany” (podręcznik: „optymalizujący”). Nie myl go z poziomem 5 dojrzałości COBIT 4.1 („Zoptymalizowany”), który ma inną treść.","zycie":"Drużyna po analizie meczów zmienia trening na stałe i sprawdza, czy wyniki rosną zgodnie z celem."},"il26_c5_dokladnosc":{"kw":["dokładność","jakość wewnętrzna"],"pulapka":"Dane sprzed tygodnia mogą być dokładne, a mimo to nieaktualne; wtedy zawodzi jakość kontekstowa (aktualność), a nie dokładność z jakości wewnętrznej.","zycie":"Waga w sklepie pokazuje dokładnie tyle, ile ważą jabłka, co do grama."},"il26_c5_dostepnosc":{"kw":["dostępność","terminowość"],"pulapka":"Dostępność (s. 82: dostępność/terminowość) należy do kategorii Dostęp i Bezpieczeństwo; aktualność, czyli czy dane są dość świeże do zadania, to jakość kontekstowa.","zycie":"Grafik dyżurów w przedszkolu wisi rano przy wejściu, akurat wtedy, gdy rodzice go potrzebują."},"il26_c5_interpretacja":{"kw":["możliwość interpretacji","interpretacj","jednostek"],"pulapka":"Kwoty raz w złotych, raz w tysiącach bez opisu jednostek to brak możliwości interpretacji, a nie błąd dokładności, bo same liczby mogą być poprawne.","zycie":"Przepis podaje „200 g mąki” i „piekarnik 180°C”, a nie „trochę mąki” i „gorący piekarnik”."},"il26_c5_istotnosc":{"kw":["istotność","jakość kontekstowa"],"pulapka":"Istotność, czyli przydatność do zadania, to jakość kontekstowa, nie wewnętrzna; w Rysunku 26 odpowiada skuteczności z COBIT 4.1.","zycie":"Mechanik pyta tylko o objawy usterki auta, a nie o kolor tapicerki, bo tylko to pomaga w naprawie."},"il26_c5_jasnosc":{"kw":["jasność","jakość kontekstowa","zrozumiał"],"pulapka":"Jasność przekazu (informacja łatwa do zrozumienia) to jakość kontekstowa; nie myl jej z możliwością interpretacji, która dotyczy języka, symboli, jednostek i definicji.","zycie":"Kartka dla opiekunki: „kolacja o 19, w lodówce zupa, spanie o 20”; od razu wiadomo, o co chodzi."},"il26_c5_kompletnosc":{"kw":["kompletność","jakość kontekstowa"],"pulapka":"Kompletność to jakość kontekstowa, nie wewnętrzna, bo zależy od zadania; razem z dokładnością odpowiada integralności z COBIT 4.1.","zycie":"Paczka z meblami ma wszystkie śrubki i części; niczego nie trzeba dokupywać w markecie."},"il26_c5_latwosc":{"kw":["łatwość","jakość kontekstowa"],"pulapka":"Łatwość eksploatacji (s. 82: łatwość posługiwania się) to jakość kontekstowa, choć w Rysunku 26 jest odpowiednikiem wydajności z COBIT 4.1.","zycie":"Pilot do telewizora ma duże przyciski i babcia bez instrukcji włącza ulubiony kanał."},"il26_c5_obiektywnosc":{"kw":["obiektywność","jakość wewnętrzna"],"pulapka":"Obiektywność należy do jakości wewnętrznej (podręcznik: rzeczywistej), choć w Rysunku 26 jest odpowiednikiem dwóch kryteriów COBIT 4.1: skuteczności i wiarygodności.","zycie":"Sędzia ocenia faul tak samo, niezależnie od tego, czy gra jego ulubiona drużyna."},"il26_c5_ograniczony":{"kw":["ograniczony dostęp","poufność"],"pulapka":"Ograniczony dostęp (tylko dla upoważnionych) to kategoria Dostęp i Bezpieczeństwo i odpowiednik poufności z COBIT 4.1; „dostępne, gdy potrzebne” to inny cel: dostępność.","zycie":"Klucz do szafki z lekami ma tylko mama; dzieci jej nie otworzą."},"il26_c5_reputacja":{"kw":["reputacj","jakość wewnętrzna"],"pulapka":"Reputacja brzmi jak opinia otoczenia, ale należy do jakości wewnętrznej (rzeczywistej), razem z dokładnością, obiektywnością i wiarygodnością.","zycie":"Prognozie z państwowego instytutu meteorologii ufasz bardziej niż plotce z kolejki w sklepie."},"il26_c5_wiarygodnosc":{"kw":["wiarygodność","jakość wewnętrzna"],"pulapka":"Wiarygodność to cel jakości wewnętrznej; „wewnętrzna” znaczy „sama w sobie”, a nie „powstała w organizacji”. W Rysunku 26 łączy się z wydajnością i wiarygodnością COBIT 4.1.","zycie":"Kartce od sąsiada „jutro wyłączą wodę w godz. 8–12” wierzysz, bo jego ostrzeżenia zawsze się sprawdzały."},"il26_c5_wlasciwa_ilosc":{"kw":["odpowiednia ilość","jakość kontekstowa"],"pulapka":"Właściwa ilość informacji to jakość kontekstowa i odpowiednik skuteczności z COBIT 4.1; na s. 82 ten sam cel nazywa się „odpowiednia ilość informacji”.","zycie":"Instrukcja składania szafy ma tyle rysunków, ile trzeba: ani trzech stron ogólników, ani stu stron szczegółów."},"il26_kr_dostepnosc":{"kw":["dostępność","dostęp i bezpieczeństwo"],"pulapka":"Dostępność z COBIT 4.1 to jeden cel kategorii Dostęp i Bezpieczeństwo (podręcznik: dostępność/terminowość); aktualność to inny cel, z jakości kontekstowej.","zycie":"Numer do hydraulika wisi na lodówce, więc gdy pęknie rura, masz go od ręki."},"il26_kr_integralnosc":{"kw":["integralność","kompletność","dokładność"],"pulapka":"Integralność z COBIT 4.1 odpowiada dwóm celom: kompletności (jakość kontekstowa) i dokładności (jakość wewnętrzna); odpowiedź z samą dokładnością to tylko połowa prawdy.","zycie":"Lista zakupów na imprezę jest pełna i bez pomyłek: niczego nie brakuje, a ilości się zgadzają."},"il26_kr_poufnosc":{"kw":["poufność","ograniczony dostęp"],"pulapka":"Poufność z COBIT 4.1 odpowiada celowi „ograniczony dostęp” (Dostęp i Bezpieczeństwo); nie myl jej z integralnością, czyli kompletnością i dokładnością.","zycie":"Kod do domowego sejfu znają tylko rodzice; dzieci i goście go nie dostają."},"il26_kr_skutecznosc":{"kw":["skuteczność","kryteri","cobit 4.1"],"pulapka":"Skuteczność dotyczy informacji jako produktu (spełnia potrzeby odbiorcy), a wydajność – sposobu jej uzyskania małym nakładem; obiektywność mapuje się i na skuteczność, i na wiarygodność.","zycie":"Mapka dojazdu na wesele ma dokładnie to, czego gość potrzebuje: adres, parking i godzinę, i od razu wiadomo, jak dojechać."},"il26_kr_wiarygodnosc":{"kw":["wiarygodność","reputacj"],"pulapka":"Wiarygodność bywa brana za synonim dokładności, ale jest bardziej subiektywna; w COBIT 5 odpowiadają jej wiarygodność, reputacja i obiektywność, a nie integralność.","zycie":"Przepisowi babci na sernik ufasz, bo zawsze wychodził, a babcia słynie z wypieków, choć nikt go nigdy nie sprawdzał w laboratorium."},"il26_kr_wydajnosc":{"kw":["wydajność","kryteri","wydajna"],"pulapka":"Wydajność to informacja spełniająca potrzeby, uzyskana i użyta małym nakładem; samo spełnienie potrzeb to skuteczność. Odpowiedniki: wiarygodność, dostępność, łatwość eksploatacji, reputacja.","zycie":"Rozkład jazdy wisi na przystanku i jest w telefonie; sprawdzasz go w sekundę, bez dzwonienia i szukania."},"il26_kr_zgodnosc":{"kw":["zgodność","specyfikacjami"],"pulapka":"Zgodność ze specyfikacjami jest wbudowana w każdy cel jakościowy, a zgodność z regulacjami dotyczy raczej sposobu użycia informacji; osobnej kategorii „jakość zgodności” nie ma.","zycie":"Tort ma być zgodny z zamówieniem klienta, a cukiernia musi go sprzedać zgodnie z przepisami sanepidu; to dwie różne zgodności."},"il28_c_dostep":{"kw":["dostęp do polityk","gdzie znaleźć"],"pulapka":"Dostęp do polityk (czy interesariusze wiedzą, gdzie je znaleźć) nie jest czwartą cechą dobrej polityki; cechy są trzy: skuteczna, wydajna, nieinwazyjna.","zycie":"Grafik sprzątania wisi na lodówce, więc każdy domownik wie, gdzie go znaleźć."},"il28_c_metodyki":{"kw":["struktury ramowe","kompleksowe, otwarte","otwarte i elastyczne"],"pulapka":"Na egzaminie „struktury ramowe” (podręcznik: metodyki): mają być kompleksowe, otwarte i elastyczne, aktualne oraz dostępne; to nie cechy polityk ani kryteria zasad.","zycie":"Segregator domowych instrukcji ma przegródki na wszystko, pozwala dopisać nowe sprzęty, jest aktualny i każdy domownik może go otworzyć."},"il28_c_nieingerencyjne":{"kw":["nieinwazyjn","nieingerencyjn","oporu"],"pulapka":"Na egzaminie „nieinwazyjne” (podręcznik: „nieingerencyjne”): polityka wydaje się logiczna i nie budzi zbędnego oporu; nie oznacza, że nie wymaga żadnej zmiany nawyków.","zycie":"Obowiązek zdejmowania butów nikogo nie złości, bo przy wejściu stoi półka i kapcie dla gości."},"il28_c_skuteczne":{"kw":["skuteczn","nieinwazyjn"],"pulapka":"Skuteczna polityka osiąga wskazany cel; pytanie o najmniejszy nakład dotyczy wydajności, a o brak zbędnego oporu nieinwazyjności.","zycie":"Zakaz telefonów przy stole jest dobry, jeśli rodzina naprawdę zaczyna rozmawiać podczas obiadu."},"il28_c_wydajne":{"kw":["wydajn","najbardziej wydajny"],"pulapka":"Wydajna polityka wdraża zasady w najbardziej wydajny sposób (najmniejszym nakładem); osiąganie celu to skuteczność, a logiczność dla przestrzegających to nieinwazyjność.","zycie":"Zamiast pilnować każdego dziecka osobno, mama ustawia w routerze jedno wyłączenie internetu o 22 dla całego domu."},"il28_c_zasady":{"kw":["ograniczona liczba","prostym językiem","liczba zasad"],"pulapka":"Zasady: ograniczona liczba, prosty język, precyzyjne wyrażenie podstawowych wartości; szczegółowe wytyczne, wyjątki i konsekwencje to już polityki, nie zasady.","zycie":"W rodzinie obowiązują trzy hasła: „mówimy prawdę”, „pomagamy sobie”, „szanujemy cudzy czas”. Krótko i bez szczegółów."},"il28_cele":{"kw":["komunikowan","zasady, polityki","instrukcj"],"pulapka":"Cele tego aktywatora to komunikowanie reguł organizacji; nie myl ich z kryteriami zasad (mała liczba, prosty język) ani z cechami polityk (skuteczne, wydajne, nieinwazyjne).","zycie":"Regulamin szkoły ma jeden sens: przekazać uczniom, czego oczekuje dyrekcja, żeby szkoła osiągała swoje cele i trzymała się swoich wartości."},"il28_cykl":{"kw":["aktualność","cykl życia","najnowszej wersji"],"pulapka":"Kluczowy aspekt cyklu życia polityk to aktualność: przeglądy, aktualizacje, świadomość zmian i dostęp do obowiązującej wersji. Starsze wersje mogą pozostać w oznaczonym archiwum; problemem są niejednoznaczne lub nieoznaczone wersje obowiązujące.","zycie":"Po zmianie regulaminu wspólnoty nową wersję wywiesza się na tablicy, a starą zdejmuje, żeby nikt się nie pomylił."},"il28_dobre":{"kw":["apetyt","hierarch","restrykcyjn"],"pulapka":"Dobra praktyka: polityki są częścią hierarchicznej struktury ramowej, odnoszą się do zasad i są dopasowane do apetytu na ryzyko; organizacja niechętna ryzyku ma polityki bardziej restrykcyjne.","zycie":"Regulamin osiedlowego boiska wynika ze statutu wspólnoty, a ostrożna wspólnota pisze surowsze przepisy niż ta, która lubi ryzyko."},"il28_dp_konsekwencje":{"kw":["konsekwencje nieprzestrzegania","konsekwencj"],"pulapka":"Konsekwencje nieprzestrzegania to element struktury polityk, nie kryterium zasad; mówią, co grozi za złamanie reguły, a nie kiedy wolno od niej odstąpić (to wyjątki).","zycie":"Regulamin biblioteki: za każdy dzień spóźnienia ze zwrotem książki płacisz 50 groszy."},"il28_dp_kontrola":{"kw":["kontrola zgodności","kontrolę zgodności","pomiar zgodności"],"pulapka":"Kontrola i pomiar zgodności (np. kwartalny przegląd logowań) to osobny element struktury polityk; nie zastępuje go ani cykl życia, ani obsługa wyjątków.","zycie":"Kierowniczka sklepu co tydzień sprawdza, czy pracownicy prowadzą zeszyt temperatur lodówek, i liczy braki wpisów."},"il28_dp_metodyka":{"kw":["struktura ramowa","ładu i zarządzania"],"pulapka":"Na egzaminie to „struktura ramowa ładu i zarządzania” (podręcznik: metodyka nadzoru i zarządzania); COBIT 5 sam jest przykładem takiej struktury opisanej w tym aktywatorze.","zycie":"Domowa instrukcja prowadzenia gospodarstwa: kto decyduje o wydatkach, kto robi zakupy, gdzie leżą rachunki i jak to sprawdzamy."},"il28_dp_metodyka_polityk":{"kw":["struktura polityk","struktury polityk"],"pulapka":"Struktura (podręcznik: metodyka) polityk to rama do tworzenia i utrzymania spójnego zbioru polityk; musi opisać zakres i ważność, konsekwencje, wyjątki oraz kontrolę zgodności.","zycie":"Teczka z regulaminami bloku ma spis treści i przegródki: parking, śmieci, remonty, więc nowy regulamin od razu ma swoje miejsce."},"il28_dp_waznosc":{"kw":["zakres i ważność","ważność","prawidłowość"],"pulapka":"Ważność wraz z zakresem należy do struktury polityk. Określa się warunki obowiązywania i przeglądu polityki; nie każda musi automatycznie wygasać po roku. To inne zagadnienie niż trzy cechy dobrej polityki.","zycie":"Karnet na siłownię ma datę ważności; po roku trzeba go odnowić, bo przestaje obowiązywać."},"il28_dp_wyjatki":{"kw":["wyjątk","obsługa wyjątków"],"pulapka":"Obsługa wyjątków mówi, kiedy i kto może odstąpić od polityki; w scenariuszu „zepsuł się laptop służbowy, a trzeba obsłużyć klienta” to ona, nie konsekwencje.","zycie":"W szkole obowiązują mundurki, ale w dzień wycieczki dyrektor pozwala przyjść w dresie."},"il28_dp_zakres":{"kw":["zakres i ważność","zakres"],"pulapka":"Zakres i ważność (podręcznik: zakres i prawidłowość) to element struktury polityk, a nie cecha dobrej polityki; mówi, kogo polityka dotyczy i jak długo obowiązuje.","zycie":"Regulamin parkingu dotyczy tylko mieszkańców bloku nr 5, a goście zostawiają auta na ulicy."},"il28_dp_zasady":{"kw":["ograniczona liczba","wartości"],"pulapka":"Zasady wyrażają podstawowe wartości i są ogólne; zdanie typu „wyjątki zatwierdza kierownik” to już polityka, a nie zasada.","zycie":"Na drzwiach szatni drużyny wisi jedno zdanie: „Gramy fair i za siebie nawzajem”."},"il28_interesariusze":{"kw":["interesariusz","dwojaki","regulacyjne"],"pulapka":"Jedni interesariusze definiują polityki, inni mają zapewnić ich przestrzeganie. Interesariuszami są również audytorzy, klienci, dostawcy i regulatorzy; konkretny mandat zależy od roli i kontekstu, nie tylko od nazwy grupy.","zycie":"Regulamin basenu piszą kierownik i ratownicy, a przestrzegać go muszą pływacy; obie strony są zainteresowane tym samym dokumentem."},"il28_pr_deklaracje":{"kw":["deklaracj","produkty"],"pulapka":"Produktem działań tego aktywatora są deklaracje polityk (dane wejściowe/wyniki); nie myl ich z praktykami procesu, które podręcznik nazywa deklaracjami działań.","zycie":"Wywieszony w windzie regulamin to gotowy produkt pracy zarządu wspólnoty, z którego korzystają lokatorzy."},"il29_c_dostep_bezp":{"kw":["cele dostępności","poufny"],"pulapka":"Cel „proces dostępny dla potrzebujących i poufny, gdy trzeba” to cele dostępności i bezpieczeństwa; trzy kategorie celów procesu to nie cztery wymiary aktywatora.","zycie":"Instrukcję obsługi pieca zna każdy domownik, ale kod do bramy garażu znają tylko dorośli."},"il29_c_kontekst":{"kw":["cele kontekstowe","kontekstow"],"pulapka":"Poprawny proces przejęty z innej organizacji, który nie pasuje do jej realiów albo jest niezrozumiały, narusza cele kontekstowe, a nie wewnętrzne.","zycie":"Przepis z włoskiej książki jest dobry, ale w twojej kuchni nie ma pieca do pizzy; trzeba go dopasować, żeby dało się z niego skorzystać."},"il29_c_wewnetrzne":{"kw":["cele wewnętrzne","intrinsic"],"pulapka":"„Wewnętrzne” (intrinsic) znaczy „jakość sama w sobie”, a nie „wewnątrz organizacji”; zgodność z przepisami zewnętrznymi też jest celem wewnętrznym.","zycie":"Mechanik naprawia hamulce zgodnie ze sztuką i z przepisami technicznymi; naprawa jest porządna sama w sobie."},"il29_cele":{"kw":["smart","cele procesu"],"pulapka":"Praktyki procesu są ukierunkowane przez polityki i procedury, a cele procesu ocenia się miernikami SMART. Actionable oznacza, że miara umożliwia podjęcie działania.","zycie":"Poranne wyjście z domu ma cel: o 7:30 wszyscy są za drzwiami z drugim śniadaniem; łatwo sprawdzić, czy się udało."},"il29_cykl":{"kw":["cykl życia procesu","wycofywany","cykl życia"],"pulapka":"Cykl życia procesu to definiowanie, tworzenie, obsługa, monitorowanie oraz dostosowanie lub wycofanie; „dane–informacje–wiedza” i siedem faz wdrożenia to inne cykle.","zycie":"Grafik sprzątania w akademiku ktoś wymyśla, wprowadza, pilnuje i poprawia po skargach, aż w końcu go znosi, gdy przychodzi firma sprzątająca."},"il29_cz_typowe_praktyki":{"kw":["15504","typowe praktyki"],"pulapka":"Typowe praktyki wspierające cykl życia procesu pochodzą z modelu oceny opartego na ISO/IEC 15504, a nie z ISO/IEC 27000, ITIL czy ISO/IEC 38500.","zycie":"Ogólne zasady dobrego remontu: zaplanuj, zabezpiecz, sprawdź efekt, popraw; działają przy łazience, kuchni i dachu."},"il29_dobre":{"kw":["dobre praktyki","procesy umożliwiające","praktyki, działania"],"pulapka":"Dobre praktyki procesu opisuje model referencyjny z przewodnika Procesy umożliwiające; kolejność szczegółowości to praktyki, działania, szczegółowe działania, a nie odwrotnie.","zycie":"Książka kucharska opisuje danie od ogółu do szczegółu: co ugotować, jakie kroki zrobić, a w dopiskach podaje porady mistrzów."},"il29_dp_dzialania":{"kw":["działania","normatywn"],"pulapka":"Zbiór działań opisuje konieczne i wystarczające kroki realizacji praktyki. Ogólne działania COBIT nie są normatywną procedurą: organizacja je dostosowuje i rozwija.","zycie":"Przepis podaje zestaw kroków potrzebnych do uzyskania potrawy. Kuchnia dopasowuje szczegóły do swoich urządzeń i tworzy własną instrukcję."},"il29_dp_praktyki":{"kw":["praktyki nadzoru","praktyki zarządzania","praktyk bazowych"],"pulapka":"Praktyki to ogólne wymogi do dostosowania przez organizację, a nie do wdrożenia słowo w słowo; w modelu oceny odpowiadają im praktyki bazowe.","zycie":"Praktyka „ustal wymagania dotyczące bezpiecznego przechowywania żywności” określa oczekiwane działanie. Konkretne kroki jego realizacji kuchnia dopasowuje do produktów i wyposażenia."},"il29_dp_praktyki_dzialania":{"kw":["szczegółowe działania","praktyki, działania"],"pulapka":"Trzy poziomy szczegółowości to praktyki, działania i szczegółowe działania; produkty działań (wejścia i wyniki) nie są czwartym poziomem, tylko osobnym elementem dobrych praktyk.","zycie":"Plan przeprowadzki: „spakuj kuchnię” to praktyka, „owiń talerze, opisz kartony” to działania, a porady z poradnika przeprowadzek to szczegóły."},"il29_dp_produkty":{"kw":["produkty pracy","ścieżk","dane wejściowe"],"pulapka":"Wejścia i wyniki (produkty pracy) wspierają decyzje i dają ścieżkę rewizyjną; nie przypisują ról (to robi RACI) i nie zastępują praktyk.","zycie":"Paragony i protokół odbioru po remoncie pokazują, co zrobiono i na jakiej podstawie; po latach widać, kto co zatwierdził."},"il29_dp_szczegolowe":{"kw":["szczegółowe działania","itil","prince2"],"pulapka":"Szczegółowe działania bierze się z innych standardów (ITIL, ISO/IEC 27000, PRINCE2), a nie z tabeli RACI ani z modelu dojrzałości COBIT 4.1.","zycie":"Gdy instrukcja montażu szafy jest za ogólna, sięgasz po filmik producenta albo poradnik stolarza."},"il29_interesariusze":{"kw":["interesariusze wewnętrzni","raci","interesariusze zewnętrzni"],"pulapka":"Interesariusze procesu bywają wewnętrzni i zewnętrzni (klienci, partnerzy, regulatorzy); ich odpowiedzialność opisuje tabela RACI, która nie jest osobnym wymiarem aktywatora.","zycie":"Przy remoncie łazienki są domownicy, którzy z niej korzystają, ekipa, która kładzie płytki, i sąsiad, któremu przeszkadza hałas; każdy ma inną rolę."},"il29_poziom_potencjalu":{"kw":["poziom zdolności","15504"],"pulapka":"Poziom zdolności nie jest kategorią wskaźników wydajności aktywatora (wiodące i opóźnione); to osobna skala oceny procesu według ISO/IEC 15504.","zycie":"Trener ocenia nie tylko, czy drużyna wygrała, ale też jak trenuje: czy ma plan, mierzy postępy i poprawia słabe strony."},"il30_apo":{"kw":["apo","dostosuj, planuj i organizuj"],"pulapka":"APO to na egzaminie „Dostosuj, Planuj i Organizuj” (podręcznik: dopasowanie, planowanie i organizacja); obejmuje m.in. strategię, architekturę, budżet, ryzyko i bezpieczeństwo.","zycie":"Przed remontem ustalasz układ pomieszczeń, budżet i harmonogram ekip."},"il30_bai":{"kw":["bai","twórz, nabywaj i wdrażaj"],"pulapka":"BAI to na egzaminie „Twórz, Nabywaj i Wdrażaj”; zarządzanie zmianami i konfiguracją jest w BAI, a nie w DSS.","zycie":"Ekipa kupuje meble, stawia nową kuchnię według projektu i podłącza sprzęty."},"il30_dss":{"kw":["dss","dostarczaj, obsługuj i wspieraj"],"pulapka":"DSS to na egzaminie „Dostarczaj, Obsługuj i Wspieraj”, obszar Wykonuj (Run): eksploatacja, incydenty, problemy, ciągłość i usługi bezpieczeństwa.","zycie":"Na co dzień w kuchni się gotuje, a gdy cieknie kran, ktoś go od razu naprawia."},"il30_kierowanie":{"kw":["kieruj","kierunek","edm"],"pulapka":"Kierowanie (Direct) to ustalanie priorytetów i podejmowanie decyzji przez Ład; kierunek płynie od Ładu do Zarządzania, nie odwrotnie.","zycie":"Kapitan drużyny ogłasza: w tym sezonie stawiamy na obronę, a pieniądze idą na bramkarza."},"il30_mea":{"kw":["mea","monitoruj, oszacuj i oceń"],"pulapka":"MEA to domena Zarządzania „Monitoruj, Oszacuj i Oceń”, a nie Ładu; to ona daje Ładowi informacje zwrotne.","zycie":"Raz w miesiącu sprawdzasz liczniki i rachunki: czy dom zużywa tyle, ile planowano."},"il30_monitorowanie":{"kw":["monitoruj","mea","edm"],"pulapka":"Na Rysunku 30 są dwa „Monitorowania”: w Ładzie (EDM, czy kierunek wcielono w życie) i domena MEA w Zarządzaniu; zarząd porównujący raport z decyzją monitoruje w Ładzie.","zycie":"Właściciel działki przyjeżdża po miesiącu i sprawdza, czy ogrodnik posadził to, co ustalili."},"il30_nadzor":{"kw":["edm","oszacuj, kieruj i monitoruj","rysunek 15"],"pulapka":"Podręcznik: „Nadzór”, egzamin: „Ład”; jego domena to EDM z pięcioma procesami, a Rysunek 30 to ten sam schemat co Rysunek 15.","zycie":"Rada rodzinna decyduje, czy w tym roku remont, czy wakacje, a potem sprawdza efekt; sama nie maluje ścian."},"il30_ocena":{"kw":["oszacuj","edm"],"pulapka":"Egzamin: „Oszacuj” (Evaluate), pierwsza czynność EDM; to ocena potrzeb i opcji przez Ład, nie domena MEA „Monitoruj, Oszacuj i Oceń”.","zycie":"Przed kupnem auta rodzina zbiera potrzeby wszystkich: dojazdy, budżet, wyjazdy z psem, i waży możliwe opcje."},"il30_s_informacje_zwrotne":{"kw":["informację zwrotną","informacje zwrotne","informacji zwrotnej"],"pulapka":"Informacje zwrotne płyną od Zarządzania do Ładu, a kierunek odwrotnie; oddzielenie Ładu od Zarządzania nie oznacza odcięcia komunikacji.","zycie":"Zarządca budynku co miesiąc wysyła właścicielom raport o naprawach i wydatkach."},"il30_s_potrzeby":{"kw":["potrzeb biznesowych","potrzeby biznesowe"],"pulapka":"Przepływ na Rysunku 30 (i 15) zaczyna się od potrzeb biznesowych trafiających do Ładu, a nie od planowania w APO ani od MEA.","zycie":"Rodzina mówi: potrzebujemy pokoju dla dziecka; od tej prośby zaczyna się cała decyzja o remoncie."},"il30_zarzadzanie":{"kw":["pbrm","planuj, twórz, wykonuj i monitoruj"],"pulapka":"Zarządzanie ma cztery domeny PBRM: APO, BAI, DSS i MEA; MEA należy do Zarządzania, choć nazywa się „Monitoruj”.","zycie":"Kierownik budowy planuje, zamawia materiały, pilnuje ekipy i raportuje inwestorowi postęp."},"il32_cele":{"kw":["struktury organizacyjne","jakość kontekstowa","decyzj"],"pulapka":"Cele struktury to właściwe umocowanie, dobrze zdefiniowane zasady działania i inne dobre praktyki; wynikiem mają być odpowiednie działania i decyzje.","zycie":"Kapitan drużyny ma od zawodników jasne pełnomocnictwo i reguły; jego zadaniem są konkretne decyzje na boisku, a nie samo noszenie opaski."},"il32_cykl":{"kw":["mandat","cykl życia"],"pulapka":"Mandat, czyli powód i cel istnienia, definiuje się przy założeniu struktury; termin rozwiązania nie jest wymagany, choć struktura może zostać rozwiązana.","zycie":"Komitet organizacyjny wesela powstaje z konkretnym zadaniem, zmienia skład, a po imprezie się rozwiązuje."},"il32_cz_mandat":{"kw":["mandat","struktury organizacyjne"],"pulapka":"Mandat i zasady działania struktury określa wdrożona struktura polityk (s. 75); mandat to nie zakres kontroli ani poziom uprawnień.","zycie":"Rada rodziców powstaje „żeby zebrać pieniądze na wycieczkę klasową”; to jedno zdanie mówi, po co istnieje i czym się zajmuje."},"il32_dobre":{"kw":["delegowanie uprawnień","zasady operacyjne","zakres kontroli"],"pulapka":"Na ilustracji jest pięć praktyk, a tekst dodaje szóstą: skład; komunikowanie czy zachęty to praktyki Kultury, a nieinwazyjność to cecha dobrej polityki.","zycie":"Klub kibica ma ustalone: kiedy się spotyka, kto w nim jest, o czym decyduje sam, a co oddaje zarządowi klubu."},"il32_dp_eskalacja":{"kw":["procedury eskalacji","eskalac"],"pulapka":"Eskalacja idzie w górę, gdy struktura ma problem z podjęciem decyzji, a delegowanie w dół; w pytaniach te dwa pojęcia często się zamienia.","zycie":"Sędziowie nie mogą ustalić wyniku meczu, więc zgodnie z regulaminem sprawa trafia do komisji ligi."},"il32_dp_poziom_uprawnien":{"kw":["poziom uprawnień","uprawnienia decyzyjne"],"pulapka":"Poziom uprawnień (podręcznik: poziom decyzyjny/uprawnienia decyzyjne) to decyzje, które struktura może podjąć; granice tych uprawnień to zakres kontroli.","zycie":"Kierownik zmiany w sklepie może sam przyjąć zwrot do 200 zł; większe kwoty zatwierdza tylko właściciel."},"il32_dp_przekazywanie":{"kw":["delegowanie uprawnień","przekazywanie uprawnień"],"pulapka":"Na egzaminie „delegowanie uprawnień”: przekazanie w dół, strukturom podległym; przekazanie sprawy w górę, gdy brak decyzji, to procedura eskalacji.","zycie":"Zarząd klubu pozwala sekcji juniorów samej decydować o turniejach, a budżet zostawia sobie."},"il32_dp_sklad":{"kw":["skład","struktury organizacyjne"],"pulapka":"Skład to członkowie struktury, wewnętrzni lub zewnętrzni; jest w tekście (s. 75), ale nie na Ilustracji 32, i powinien odzwierciedlać właściwe umiejętności.","zycie":"Do komisji przetargu na remont elewacji wchodzą dwaj mieszkańcy i zaproszony z zewnątrz inspektor budowlany."},"il32_dp_zakres_kontroli":{"kw":["zakres kontroli","granice uprawnień"],"pulapka":"Zakres kontroli to granice uprawnień decyzyjnych struktury; „decyzje, do których struktura jest uprawniona” to już poziom uprawnień.","zycie":"Rada osiedla decyduje o placu zabaw i trawnikach, ale o remoncie dachu bloku już nie; tam kończy się jej teren."},"il32_dp_zasady_dzialania":{"kw":["zasady operacyjne","zasady działania"],"pulapka":"Na egzaminie „zasady operacyjne” (podręcznik: zasady działania): częstotliwość zebrań, dokumentacja, porządek; nie myl ich z poziomem uprawnień ani z regułami i normami.","zycie":"Wspólnota zbiera się w pierwszy poniedziałek miesiąca, ktoś pisze protokół, a dyskusja ma ustalony porządek."},"il32_interesariusze":{"kw":["struktury organizacyjne","rysunek 32","interesariusz"],"pulapka":"Interesariusze struktury to członkowie, inne struktury, klienci, dostawcy i regulatorzy; ich role to decydowanie, wywieranie wpływu i doradztwo, nie samo członkostwo.","zycie":"Przy wyborze szkolnego mundurka dyrekcja decyduje, rodzice wywierają wpływ, a krawiec doradza; każdy ma inną rolę."},"il32_pr_decyzje":{"kw":["decyzj","dane wejściowe"],"pulapka":"Produktem struktury są decyzje, a wejściem zwykle informacje; o tym, czy decyzje struktur są wdrażane, decyduje też Kultura, etyka i zachowanie (s. 75, 80).","zycie":"Rodzinna narada dostaje trzy oferty wakacji, porównuje je i wybiera jedną; jej „produktem” jest decyzja, a wejściem oferty."},"il33_audyt":{"kw":["audyt","audyty wewnętrzne"],"pulapka":"W tabeli rola Audyt odpowiada za audyty wewnętrzne, CRO za zarządzanie ryzykiem, a Zgodność za wytyczne dotyczące wymogów. Audyt może oceniać ryzyko i zgodność; nie przejmuje przez to zarządczej odpowiedzialności za te obszary.","zycie":"Komisja rewizyjna klubu raz w roku niezależnie przegląda kasę i dokumenty, a potem mówi zarządowi, co działa, a co nie."},"il33_ceo":{"kw":["ceo","dyrektor generalny"],"pulapka":"CEO jest najwyższym rangą dyrektorem odpowiedzialnym za pełne zarządzanie przedsiębiorstwem. Rozliczalność za Ład przypisano organowi nadzorującemu (board). CEO może jednocześnie być jego członkiem, lecz są to odrębne role.","zycie":"Kierowniczka sklepu osiedlowego odpowiada za cały sklep: towar, kasę, grafik i ludzi; wszyscy kierownicy działów ostatecznie odpowiadają przed nią."},"il33_cfo":{"kw":["cfo","dyrektor ds. finansowych","rachunkowość"],"pulapka":"CFO odpowiada za ryzyko finansowe, a nie za całe ryzyko organizacji (to CRO); słowo „rachunkowość” w opisie roli wskazuje na CFO.","zycie":"W rodzinie jedna osoba pilnuje domowego budżetu, rachunków i oszczędności, sprawdza wyciągi i ostrzega, gdy wydatki rosną za szybko."},"il33_cio":{"kw":["cio","dyrektor ds. informatyki","dopasowanie strategii"],"pulapka":"Najwyższa rangą rola od dopasowania strategii IT do biznesowej to CIO (Sample Paper); ale komitetowi ds. strategii IT przewodniczy zwykle członek zarządu, nie CIO.","zycie":"Domowy „szef od sprzętu” dobiera telefony, internet i komputery tak, żeby pasowały do planów domowników, np. nauki zdalnej i pracy z domu."},"il33_ciso":{"kw":["ciso","bezpieczeństwo informacji","wszystkich formach"],"pulapka":"CISO odpowiada za bezpieczeństwo informacji we wszystkich formach, także papierowych; nie myl z Kierownikiem ds. bezpieczeństwa informacji, który projektuje, nadzoruje i ocenia zabezpieczenia.","zycie":"Sekretarka szkoły pilnuje, żeby oceny i dane uczniów nie wyciekły: ani z segregatora, ani z komputera, ani z rozmowy przy kawie."},"il33_coo":{"kw":["coo","dyrektor ds. operacyjnych","funkcjonowanie"],"pulapka":"COO odpowiada za funkcjonowanie całej organizacji; środowiska operacyjne i infrastruktura IT to Dyrektor ds. operacji IT: podobna nazwa, inna rola.","zycie":"Dyrektor operacyjny sieci restauracji odpowiada za codzienne funkcjonowanie całej sieci: sprawne dostawy, obsadę i obsługę gości."},"il33_cro":{"kw":["cro","dyrektor ds. ryzyka","ryzykiem w całej"],"pulapka":"CRO odpowiada za wszystkie aspekty zarządzania ryzykiem przedsiębiorstwa; CFO za zarządzanie finansami, w tym ryzyko finansowe, a CISO za bezpieczeństwo informacji. Komitet ryzyka jest grupą uzgadniającą wspólne stanowisko; CRO może uczestniczyć w jej pracach.","zycie":"Kapitan przed rejsem sprawdza wszystkie zagrożenia naraz: pogodę, sprzęt, zdrowie załogi i zapasy, a nie tylko jedną sprawę."},"il33_czlonek_kier":{"kw":["naczelnego kierownictwa","jednostki biznesowej","dyrektor działu biznesowego"],"pulapka":"Członek naczelnego kierownictwa odpowiada za jedną jednostkę biznesową lub spółkę zależną (Sample Paper: „Dyrektor Działu Biznesowego”); całą organizacją kieruje CEO.","zycie":"W sieci piekarni kierownik jednej filii odpowiada za swój punkt: wyniki, ludzi i obsługę, choć cała sieć ma wspólnego szefa."},"il33_dyr_admin_it":{"kw":["administracji it","kwestie administracyjne"],"pulapka":"Zapisy związane z IT i sprawy administracyjne IT to Dyrektor ds. administracji IT; nie myl go z PMO, które zbiera i raportuje informacje o realizacji projektów.","zycie":"Sekretarz klubu prowadzi segregatory: umowy, faktury za sprzęt, ewidencję i wszystkie papierowe sprawy, żeby nic nie zginęło."},"il33_dyr_arch":{"kw":["dyrektor ds. architektury","szef architektury"],"pulapka":"Dyrektor ds. architektury (Sample Paper: „Szef Architektury”) odpowiada za proces architektury korporacyjnej; wytyczne, polityki i standardy architektury daje Rada ds. Architektury.","zycie":"Przy remoncie całego domu jedna osoba trzyma plan całości i pilnuje, żeby kuchnia, łazienka i instalacje do siebie pasowały."},"il33_dyr_hr":{"kw":["zasobami ludzkimi","kadrow"],"pulapka":"Planowanie i polityki kadrowe to Dyrektor ds. zarządzania zasobami ludzkimi, nie COO; to rola z Rysunku 33, a nie aktywator Ludzie, umiejętności i kompetencje.","zycie":"W klubie sportowym jedna osoba planuje nabór trenerów, ich szkolenia i zasady wynagradzania na kolejne sezony."},"il33_dyr_operacji_it":{"kw":["operacji it","infrastrukturę it"],"pulapka":"Środowiska operacyjne i infrastruktura IT to Dyrektor ds. operacji IT, nie COO (funkcjonowanie całej organizacji) i nie Kierownik ds. ciągłości (funkcje krytyczne po zakłóceniu).","zycie":"Dozorca budynku dba, żeby codziennie działały winda, ogrzewanie, prąd i woda, a awarie usuwano od razu."},"il33_dyr_prywatnosci":{"kw":["ds. prywatności","prywatności","ochrony danych"],"pulapka":"Ryzyko i wpływ przepisów o prywatności to Dyrektor ds. prywatności (inaczej: ds. ochrony danych); funkcja Zgodność obejmuje wymogi prawne ogólnie, nie tylko prywatność.","zycie":"Trener młodzików pilnuje, żeby zdjęcia i dane dzieci nie trafiały do sieci bez zgody rodziców, i zna przepisy, które tego wymagają."},"il33_dyr_rozwoju":{"kw":["dyrektor ds. rozwoju","rozwoju rozwiązań"],"pulapka":"Dyrektor ds. rozwoju odpowiada za procesy rozwoju rozwiązań IT, czyli budowanie; utrzymanie środowisk i infrastruktury to Dyrektor ds. operacji IT, a usługi dla klientów – Kierownik ds. usług.","zycie":"W piekarni jedna osoba wymyśla i dopracowuje nowe wypieki, zanim trafią na półkę."},"il33_kier_bezp_inf":{"kw":["kierownik ds. bezpieczeństwa informacji","bezpieczeństwa informacji"],"pulapka":"Kierownik ds. bezpieczeństwa informacji projektuje, nadzoruje i ocenia bezpieczeństwo; dyrektor najwyższego szczebla od bezpieczeństwa informacji we wszystkich formach to CISO.","zycie":"Fachowiec od zabezpieczeń projektuje w domu zamki, alarm i sejf, potem sprawdza, czy działają, i poprawia słabe miejsca."},"il33_kier_ciaglosci":{"kw":["ciągłości działalności","ciągłości"],"pulapka":"Opis kierownika ds. ciągłości obejmuje zdolność przedsiębiorstwa do utrzymania funkcji krytycznych po zakłóceniach. Dyrektor operacji IT i CISO również mogą wspierać ciągłość, ale mają inne podstawowe zakresy odpowiedzialności.","zycie":"Mama ma plan na wypadek awarii prądu: latarki, kuchenka turystyczna, zapas wody i numer do sąsiadów, żeby dom działał dalej."},"il33_kier_uslug":{"kw":["kierownik ds. usług","grupy klientów"],"pulapka":"Kierownik ds. usług zarządza produktami i usługami dla określonego klienta lub grupy klientów; środowiska i infrastruktura to Dyrektor ds. operacji IT, a rozwój rozwiązań – Dyrektor ds. rozwoju.","zycie":"W restauracji kierownik cateringu dla firm opracowuje nowe zestawy, wprowadza je i sprawdza, czy stałym klientom smakują."},"il33_komitet_ryzyka":{"kw":["komitet ds. zarządzania ryzykiem","zarządzania ryzykiem przedsiębiorstwa","komitet ds. ryzyka"],"pulapka":"Grupa uzgadniająca wspólne stanowisko w sprawie ERM to komitet ds. zarządzania ryzykiem w przedsiębiorstwie; CRO to jedna osoba, a rada ds. ryzyka IT może komitetowi tylko doradzać.","zycie":"Przed wyjazdem na kolonie wychowawcy, kierowca i pielęgniarka siadają razem i uzgadniają wspólne zasady bezpieczeństwa całego obozu."},"il33_komitet_strategii":{"kw":["komitet ds. strategii","przewodniczy","wykonawczy it"],"pulapka":"Przewodniczy zwykle członek zarządu, nie CIO: klasyczna pułapka. Komitet odpowiada za portfele inwestycji, usług i zasobów IT, a komitety sterujące za pojedyncze programy i projekty.","zycie":"Rada rodziców wybiera kilka osób, które decydują, w co szkoła zainwestuje: tablice, komputery czy boisko; przewodniczy im przedstawiciel rady, nie szkolny informatyk."},"il33_komitety_sterujace":{"kw":["komitet sterujący","komitety sterujące","programów i projektów"],"pulapka":"Wytyczne dla programów i projektów, przydział zasobów, korzyści i ryzyko to komitety sterujące; PMO tylko wspiera kierowników i raportuje, a komitet ds. strategii pilnuje całego portfela.","zycie":"Przy budowie domu rodzina, kierownik budowy i architekt spotykają się co tydzień: pilnują planu, dzielą pieniądze i ekipy, reagują na opóźnienia."},"il33_pmo":{"kw":["pmo","biuro zarządzania projektami"],"pulapka":"PMO wspiera kierowników programów i projektów oraz gromadzi, ocenia i raportuje informacje o realizacji. Kierownik prowadzi projekt, a komitet sterujący zapewnia wytyczne i nadzór. Sekretariat portfela inwestycji i usług to w tej tabeli VMO.","zycie":"Koordynatorka wesela zbiera od wszystkich wykonawców informacje o postępach, pilnuje listy zadań i mówi młodej parze, co jest gotowe."},"il33_rada_arch":{"kw":["rada ds. architektury","architektury korporacyjnej"],"pulapka":"Rada ds. Architektury to grupa, która daje wytyczne oraz tworzy polityki i standardy architektury; za proces architektury korporacyjnej odpowiada jedna osoba: Dyrektor ds. architektury.","zycie":"Mieszkańcy osiedla razem z fachowcami ustalają zasady zabudowy: wysokość ogrodzeń, kolor elewacji, miejsce na śmietniki; każdy nowy dom musi je spełniać."},"il33_vmo":{"kw":["vmo","biuro zarządzania wartością","uzasadnień biznesowych"],"pulapka":"Sekretariat portfela inwestycji i usług, ocena uzasadnień biznesowych i raport o wartości to VMO, nie PMO; litery P i V łatwo zamienić.","zycie":"Doradca rodziny podpowiada, który wydatek opłaci się najbardziej: nowe okna, auto czy kurs dla dziecka, i sprawdza potem, czy obiecany pożytek przyszedł."},"il33_wlasc_proc":{"kw":["właściciel procesu","właściciela procesu","sprawność procesu"],"pulapka":"Sprawność procesu, jego doskonalenie i zatwierdzanie zmian to właściciel procesu biznesowego; CEO odpowiada za całą organizację, a członek naczelnego kierownictwa za całą jednostkę.","zycie":"Babcia odpowiada za przepis na świąteczne pierogi: pilnuje, żeby wychodziły, co roku go poprawia i to ona zgadza się na każdą zmianę farszu."},"il33_zarzad":{"kw":["zarząd","rysunku 33","członek zarządu"],"pulapka":"Board (organ nadzorujący; w podręczniku PL „zarząd”) jest rozliczany za Ład i ogólną kontrolę nad zasobami. CEO odpowiada za pełne zarządzanie. Nie wyciągaj z tego wniosku, że CEO nie może być członkiem organu nadzorującego.","zycie":"Rada wspólnoty decyduje, na co idą pieniądze z funduszu remontowego, i rozlicza administratora; sama nie maluje klatki schodowej."},"il33_zgodnosc":{"kw":["zgodność","wymogami prawnymi","funkcja zgodność"],"pulapka":"Funkcja Zgodność odpowiada w tej tabeli za wytyczne dotyczące wymogów prawnych, regulacyjnych i umownych. Audyt odpowiada za audyty wewnętrzne, a dyrektor ds. prywatności za szczególny obszar ochrony prywatności. Obszary współpracują, nie są od siebie odizolowane.","zycie":"Znajomy prawnik podpowiada wspólnocie, czego wymagają przepisy budowlane i umowa z administratorem, zanim mieszkańcy zaczną remont dachu."},"il34_c_etyka_ind":{"kw":["etyka indywidualna","etykę indywidualną","osobiste wartości"],"pulapka":"Etykę indywidualną kształtują osobiste wartości, w znacznym stopniu zależne od czynników zewnętrznych i doświadczeń. System wynagradzania sklasyfikowano wśród dobrych praktyk jako zachęty; może on wpływać na zachowania, ale nie jest definicją etyki indywidualnej.","zycie":"Sąsiad oddaje znaleziony portfel z pieniędzmi, bo tak nauczyli go rodzice; nikt mu tego nie kazał."},"il34_c_etyka_org":{"kw":["etyka organizac","etykę organizac","wartości"],"pulapka":"Etyka organizacji to wartości, na których ma działać przedsiębiorstwo; osobiste wartości pracownika to etyka indywidualna, a suma zachowań to kultura.","zycie":"Kodeks klubu: „gramy fair, nie symulujemy fauli”. To wartości drużyny, niezależnie od tego, kto akurat wychodzi na boisko."},"il34_c_wzorce":{"kw":["wzorce zachowań","wzorców zachowań","kulturę"],"pulapka":"Kulturę organizacji tworzą łącznie indywidualne wzorce zachowań, a nie regulamin ani wartości jednego lidera.","zycie":"Każdy domownik zostawia buty, gdzie popadnie; razem tworzy to „styl domu”, nawet jeśli kartka na drzwiach mówi co innego."},"il34_cele":{"kw":["etyka indywidualna","etyka organizac","etyk"],"pulapka":"Cele tego aktywatora to etyka organizacji, etyka indywidualna i indywidualne wzorce zachowań; komunikowanie, egzekwowanie i zachęty to dobre praktyki, nie cele.","zycie":"W rodzinie liczą się trzy rzeczy: zasady domu, przekonania każdego domownika i to, jak wszyscy naprawdę zachowują się przy stole."},"il34_cykl":{"kw":["cykl życia","kultura, etyka"],"pulapka":"Kultura ma cykl życia jak każdy aktywator i zaczyna się od kultury już istniejącej, nie od zera; nie myl go z siedmioma fazami cyklu życia wdrożenia.","zycie":"Nowy trener przejmuje drużynę z jej nawykami: patrzy, co jest, decyduje, co zmienić, i krok po kroku wprowadza nowe zwyczaje."},"il34_dobre":{"kw":["dobre praktyki","czempion","komunikowanie"],"pulapka":"Sześć praktyk: komunikowanie, egzekwowanie, zachęty i nagrody, świadomość, reguły i normy, czempioni; zakres kontroli czy delegowanie uprawnień to praktyki Struktur organizacyjnych.","zycie":"Rodzice uczą dzieci porządku na kilka sposobów: mówią o zasadach, sami sprzątają, chwalą, pilnują i wieszają grafik dyżurów."},"il34_dp_egzekwowanie":{"kw":["egzekwowanie","egzekwowania","kultura, etyka"],"pulapka":"Egzekwowanie to pilnowanie przestrzegania wymagań, a nie ich ogłaszanie (komunikowanie) ani nagradzanie (zachęty i nagrody).","zycie":"Ratowniczka na basenie nie wpuszcza do wody nikogo bez czepka, nawet stałego klienta."},"il34_dp_komunikowanie":{"kw":["komunikowanie","komunikowania"],"pulapka":"Komunikowanie to ogłaszanie pożądanych zachowań i wartości w całej organizacji; dawanie przykładu przez kierownictwo to już praktyka „świadomość”.","zycie":"Na zebraniu wspólnoty prezes ogłasza wszystkim: „u nas segregujemy śmieci, bo dbamy o wspólne podwórko”."},"il34_dp_osoby_wsp":{"kw":["czempion","osoby wspierające"],"pulapka":"Na egzaminie to „czempioni” (podręcznik: inne osoby wspierające); nie myl ich z właścicielami procesów biznesowych ani z konsultowanymi z RACI.","zycie":"Najstarszy zawodnik pierwszy zostaje po treningu na rozciąganie i pociąga za sobą innych, choć nie jest trenerem."},"il34_dp_reguly":{"kw":["reguły i normy","zasadami i politykami"],"pulapka":"Reguły i normy to dodatkowe wytyczne o zachowaniach, wyraźnie powiązane z zasadami i politykami; nie myl ich z praktyką struktur „zasady operacyjne”.","zycie":"Regulamin działek dopisuje: grill do 22, ognisko po zgłoszeniu zarządowi. To szczegóły ogólnej zasady „nie przeszkadzamy sąsiadom”."},"il34_dp_swiadomosc":{"kw":["świadomoś","przykład kierownictwa"],"pulapka":"Świadomość buduje przykład kierownictwa wyższego szczebla i czempionów; nie myl jej z atrybutem dojrzałości COBIT 4.1 „świadomość i komunikowanie” (Rysunek 18).","zycie":"Szefowa kuchni sama myje ręce przed każdym daniem; po tygodniu kucharze robią to samo, bez żadnego polecenia."},"il34_dp_zachety":{"kw":["zachęty","wynagradza"],"pulapka":"Zachęty obejmują także środki zniechęcające i wiążą się z wynagradzaniem HR. Przykład 11 pokazuje, że premiowanie wyłącznie terminu i budżetu może osłabić jakość; nie jest to nieuchronny skutek każdej takiej premii.","zycie":"Dziecko dostaje kieszonkowe za posprzątany pokój, a za bałagan traci wyjście do kina."},"il34_interesariusze":{"kw":["kultura, etyka","rysunek 34","interesariusz"],"pulapka":"Interesy są dwojakie: jedni (dział prawny, ryzyko, HR, rada ds. wynagrodzeń) definiują i egzekwują zachowania, inni muszą ich przestrzegać; zewnętrzni to regulatorzy, audytorzy zewnętrzni, organy nadzorcze.","zycie":"W szkole dyrektor i wychowawcy ustalają zasady zachowania, uczniowie mają ich przestrzegać, a kuratorium z zewnątrz sprawdza, czy szkoła o to dba."},"il34_z_negatywne":{"kw":["negatywnych wynik","winn","obwinia"],"pulapka":"Pytanie: czy firma uczy się na szkodach i utraconych szansach, czy tylko przypisuje winę bez usunięcia przyczyny; „kultura obwiniania” to symptom złej kultury ryzyka (Przykład 12).","zycie":"Po zalaniu łazienki jedna rodzina szuka winnego, a druga sprawdza, który wąż pękł, i wymienia wszystkie na nowe."},"il34_z_polityka":{"kw":["przestrzeganiem polityki","przestrzegania polityki","polityk"],"pulapka":"Pytanie brzmi: w jakim stopniu pracownicy przyjmują politykę i jej przestrzegają; znajomość polityki bez jej stosowania to właśnie ten rodzaj zachowania.","zycie":"W bloku wisi regulamin: cisza nocna od 22. Jedni lokatorzy się stosują, inni puszczają muzykę do północy."},"il34_z_ryzyko":{"kw":["podejmowaniem ryzyka","apetyt na ryzyko"],"pulapka":"To przykład zachowania (ile ryzyka firma może przyjąć i jakie gotowa jest podjąć), a nie dobra praktyka; formalny apetyt na ryzyko ustala Ład (EDM03).","zycie":"Jeden kierowca jeździ zimą na letnich oponach, drugi zmienia je już w październiku. Różni ich to, ile ryzyka są gotowi podjąć."},"il35_dane":{"kw":["danych","dane"],"pulapka":"Dane to wynik pracy procesów biznesowych; aktywator Informacja obejmuje głównie fazę „informacje”, ale uwzględnia też dane i wiedzę.","zycie":"Stos paragonów w szufladzie: same kwoty i daty, z których jeszcze nic nie wynika."},"il35_informacje":{"kw":["cykl życia informacji","cykl informacji","informacj"],"pulapka":"Rysunek 35 (cykl informacji) to nie cykl życia aktywatora Informacja (planowanie… pozbywanie się) ani warstwy atrybutów z Rysunku 36.","zycie":"Paragony wpisane do tabelki: „w marcu na jedzenie wydaliśmy 2400 zł”. Teraz liczby coś mówią."},"il35_procesy_biz":{"kw":["procesy biznesowe","cykl informacji","rysunek 35"],"pulapka":"Dane generują i przetwarzają procesy biznesowe (z procesami IT w środku), nie tylko dział IT; Informacja obejmuje też informacje niezautomatyzowane.","zycie":"Codzienne domowe czynności, takie jak zakupy, gotowanie i płacenie rachunków, same zostawiają paragony i notatki."},"il35_procesy_it":{"kw":["procesy it","cykl informacji"],"pulapka":"Procesy IT leżą wewnątrz procesów biznesowych na Rysunku 35; nie są początkiem cyklu ani jego wyznacznikiem.","zycie":"Kalkulator i zeszyt pomagają rodzinie liczyć wydatki, ale właściwą czynnością są zakupy i rachunki."},"il35_s_generowanie":{"kw":["generuj","cykl informacji"],"pulapka":"Na Rysunku 35 strzałka Generowanie i przetwarzanie prowadzi od procesów biznesowych do danych. Procesy IT są pokazane wewnątrz procesów biznesowych; także one mogą uczestniczyć w generowaniu i przetwarzaniu danych.","zycie":"Każde zakupy zostawiają paragon; samo robienie zakupów „produkuje” dane."},"il35_s_przeksztalcanie_1":{"kw":["przekształc","informacj"],"pulapka":"Na Rysunku 35 są dwie strzałki „przekształcanie”: dane → informacje i informacje → wiedza; „tworzenie” to dopiero wiedza → wartość.","zycie":"Wieczorem ktoś sortuje paragony według kategorii i sumuje; z luźnych liczb robi się zestawienie."},"il35_s_przeksztalcanie_2":{"kw":["przekształc","wiedz"],"pulapka":"Drugie „przekształcanie” zamienia informacje w wiedzę; nie myl go z „tworzeniem”, które z wiedzy daje wartość.","zycie":"Patrząc na kilka zestawień, mama zauważa prawidłowość: zimą rachunki za prąd rosną dwukrotnie."},"il35_s_tworzenie":{"kw":["tworzeni","wartoś"],"pulapka":"„Tworzenie” to jedyna strzałka prowadząca do wartości, a jej źródłem jest wiedza.","zycie":"Znając zimowe rachunki, rodzina wymienia żarówki i uszczelnia okna; oszczędność to stworzona wartość."},"il35_s_wyznacznik":{"kw":["wyznacznik","cykl informacji"],"pulapka":"„Wyznacznik” na Rysunku 35 to etykieta strzałki zamykającej cykl między wartością a procesami biznesowymi; nie myl go z wyznacznikami (drivers) na górze Kaskady Celów.","zycie":"Oszczędności zachęcają rodzinę do kolejnych zmian w domowych nawykach; korzyść napędza następne działania."},"il35_wartosc":{"kw":["wartość","wartości"],"pulapka":"Na Rysunku 35 wartość jest efektem wykorzystania wiedzy w cyklu: dane → informacje → wiedza → wartość. To model pojęciowy; nie oznacza zakazu uzyskiwania korzyści z danych ani tego, że same zebrane dane automatycznie tworzą wartość.","zycie":"Dzięki tej wiedzy rodzina co roku jedzie na wakacje bez debetu; to realna korzyść, a nie sama tabelka."},"il35_wiedza":{"kw":["wiedz","cykl informacji"],"pulapka":"Kolejność to dane → informacje → wiedza → wartość; odpowiedzi z odwróconą kolejnością (np. wiedza tworzy dane) są błędne.","zycie":"Po kilku miesiącach tabelek rodzina wie, że w miesiącach z urodzinami zawsze wydaje więcej, więc odkłada wcześniej."},"il36_a_aktualnosc":{"kw":["aktualność","przyszłości","semantyczn"],"pulapka":"Atrybut „aktualność informacji” (przeszłość, teraźniejszość, przyszłość) leży w warstwie semantycznej; „wystarczająco świeża do zadania” to cel jakości kontekstowej.","zycie":"Kalendarz rodzinny ma wpisy o zeszłych urodzinach, dzisiejszym obiedzie i przyszłych wakacjach."},"il36_a_innowacyjnosc":{"kw":["innowacyjność","pragmatyczn"],"pulapka":"Innowacyjność jest tu atrybutem pragmatycznym: informacja tworzy nową wiedzę lub potwierdza istniejącą. To inne pojęcie niż PA 5.1 Innowacje procesu i cel IT 17; samo wspólne słowo nie oznacza tej samej klasyfikacji.","zycie":"SMS „dziecko odebrane” przynosi nowinę, a drugi taki sam tylko potwierdza to, co już wiesz."},"il36_a_kanal":{"kw":["kanał dostępu","empirycznej"],"pulapka":"Kanał dostępu (np. interfejs użytkownika) to atrybut warstwy empirycznej, nie fizycznej; nie myl go też z celem „ograniczony dostęp”.","zycie":"Oceny dziecka sprawdzasz w dzienniku w telefonie albo na wywiadówce; to dwa kanały do tej samej informacji."},"il36_a_kod":{"kw":["kod/język","syntaktyczn"],"pulapka":"Kod/język (format kodowania, reguły łączenia symboli) to atrybut warstwy syntaktycznej; pytania o strony kodowe i strukturę zapisu też prowadzą do tej warstwy.","zycie":"Przepis zapisano po polsku i według stałego wzoru: składniki na górze, kroki niżej."},"il36_a_kontekst":{"kw":["kontekst","społeczn"],"pulapka":"Kontekst (kulturowy, dziedziny tematycznej) to atrybut warstwy społecznej; „jakość kontekstowa” to zupełnie inna rzecz, kategoria w wymiarze Cele.","zycie":"Zdanie „mamy remont” w rozmowie z szefem znaczy spóźnienie, a z sąsiadem hałas za ścianą."},"il36_a_nosnik":{"kw":["nośnik","warstwa fizyczna"],"pulapka":"Nośnik/media (papier, sygnały elektryczne, fale dźwiękowe) to atrybut warstwy fizycznej; nie myl go z kanałem dostępu z warstwy empirycznej.","zycie":"Ogłoszenie o zebraniu wspólnoty wisi na kartce w klatce albo ktoś odczytuje je przez megafon."},"il36_a_okres":{"kw":["okres przechowywania","pragmatyczn"],"pulapka":"Okres przechowywania to atrybut warstwy pragmatycznej, nie fizycznej; samo niszczenie po terminie to faza cyklu życia Aktualizacja/pozbywanie się.","zycie":"Gwarancję na lodówkę trzymasz do końca jej ważności, potem możesz ją wyrzucić."},"il36_a_poziom":{"kw":["poziom informacji","szczegółowości","semantyczn"],"pulapka":"Poziom informacji (sprzedaż roczna, kwartalna, miesięczna) to szczegółowość w warstwie semantycznej; nie myl go z celem „odpowiednia ilość informacji”.","zycie":"Rachunki za prąd możesz oglądać miesiąc po miesiącu albo jedną sumą za cały rok."},"il36_a_status":{"kw":["status informacji","historyczn","pragmatyczn"],"pulapka":"Status informacji (operacyjne czy historyczne) to warstwa pragmatyczna; nie myl go z atrybutem aktualność (przeszłość/teraźniejszość/przyszłość) z warstwy semantycznej.","zycie":"Bieżąca lista zakupów wisi na lodówce, a zeszłoroczne paragony leżą w pudełku na pamiątkę."},"il36_a_typ":{"kw":["typ informacji","semantyczn"],"pulapka":"Typ informacji (finansowe/niefinansowe, zewnętrzne/wewnętrzne, prognozowane/zaobserwowane, planowane/uzyskane) leży w warstwie semantycznej, nie pragmatycznej.","zycie":"W domowym budżecie oddzielasz plan wydatków na wakacje od tego, ile naprawdę wydano."},"il36_a_zaleznosc":{"kw":["zależność","pragmatyczn"],"pulapka":"Zależność wskazuje informacje, które muszą poprzedzać daną informację; to atrybut warstwy pragmatycznej, nie relacja między aktywatorami.","zycie":"Polecenie „przekręć pokrętło na dwójkę” ma sens dopiero, gdy wiesz, które pokrętło to piekarnik."},"il36_cele":{"kw":["jakość kontekstowa","jakość wewnętrzna","dostęp i bezpieczeństwo"],"pulapka":"Trzy podwymiary jakości to kategorie wymiaru Cele, nie osobne wymiary aktywatora; egzamin: jakość wewnętrzna, jakość kontekstowa (i reprezentacji) oraz Dostęp i Bezpieczeństwo.","zycie":"Dobra lista zakupów musi być prawdziwa, pasować do dzisiejszego obiadu i leżeć w kieszeni, a nie zostać w domu."},"il36_cykl":{"kw":["cykl życia","cyklowi informacji"],"pulapka":"Cykl życia aktywatora Informacja (planowanie…pozbywanie się) to nie cykl informacji z Rysunku 35 (dane → informacje → wiedza → wartość).","zycie":"Mleko kupujesz, trzymasz w lodówce, pijesz, sprawdzasz datę, a przeterminowane wylewasz; każdy etap wymaga innego traktowania."},"il36_dobre":{"kw":["atrybutów informacji","warstw","dobre praktyki"],"pulapka":"Dobra praktyka aktywatora Informacja to definiowanie atrybutów na sześciu warstwach; nie ma ogólnie przyjętej definicji informacji, a warstwy to nie podwymiary jakości.","zycie":"Nie da się jednym zdaniem powiedzieć, czym jest „dobre jedzenie”, ale da się je opisać: smak, skład, termin, porcja."},"il36_dp_definiowanie":{"kw":["definiowanie atrybutów","atrybutów informacji"],"pulapka":"„Definiowanie atrybutów informacji” to praktyka aktywatora Informacja; w pytaniach o dobre praktyki innych aktywatorów często jest błędną odpowiedzią.","zycie":"Opisując słoik w spiżarni, notujesz szkło, etykietę, pismo, zawartość, termin użycia i dla kogo jest; od rzeczy po zwyczaje domu."},"il36_interesariusze":{"kw":["interesariusza informacji","opiekun informacji","wytwórca informacji"],"pulapka":"Wymiar Interesariusze informacji nie jest niezależny: role zależą od fazy cyklu życia; szczegółowe role (architekt, właściciel, powiernik) to inna lista niż trzy role ogólne.","zycie":"Przy rodzinnych przepisach jedna osoba je zapisuje, druga pilnuje zeszytu, a reszta gotuje; każdy ma inną rolę wobec tych samych kartek."},"il36_l_aktualizacja":{"kw":["pozbywanie","cykl życia"],"pulapka":"Archiwizacja i niszczenie to faza Aktualizacja/pozbywanie się; maksymalny czas trzymania to osobny atrybut „okres przechowywania” w warstwie pragmatycznej.","zycie":"Stare rachunki za prąd po latach niszczysz, a umowę najmu odkładasz do archiwum."},"il36_l_budowanie":{"kw":["budowanie/nabywanie","nabywanie","cykl życia"],"pulapka":"Tworzenie zapisów, nabywanie danych i ładowanie plików zewnętrznych to Budowanie/nabywanie; przechowywanie to już faza Użytkowanie/obsługa.","zycie":"Wpisujesz do zeszytu pierwsze rachunki i przepisujesz do niego wyciągi z banku."},"il36_l_ocena":{"kw":["ocena/monitorowanie","monitorowanie","cykl życia"],"pulapka":"Czyszczenie, scalanie i usuwanie duplikatów to Ocena/monitorowanie, nie Aktualizacja/pozbywanie się; celem jest zachowanie wartości zasobu.","zycie":"Raz w roku przeglądasz kontakty w telefonie, poprawiasz numery i usuwasz zdublowane wpisy."},"il36_l_planowanie":{"kw":["planowanie","cykl życia"],"pulapka":"Identyfikacja celów, architektura informacji, standardy i definicje danych to faza Planowanie, nie Projektowanie; Projektowanie nie ma w podręczniku opisu.","zycie":"Zanim założysz zeszyt domowego budżetu, ustalasz, po co go prowadzisz i jakie będą w nim rubryki."},"il36_l_projektowanie":{"kw":["projektowanie","cykl życia"],"pulapka":"Projektowanie jest wymienione w ogólnym cyklu aktywatora. Szczegółowy tekst o informacji nie opisuje go osobnym punktem; nie należy na tej podstawie twierdzić, że faza nie istnieje lub nie może dotyczyć jej pytanie.","zycie":"Rysujesz na kartce, jak będzie wyglądać tabela wydatków, zanim cokolwiek do niej wpiszesz."},"il36_l_przechowywanie":{"kw":["przechowywanie","warstwa fizyczna"],"pulapka":"Przechowywanie obejmuje papier, a nawet ludzką pamięć, nie tylko systemy; to część Użytkowania/obsługi, a fizyczne „gdzie” opisuje warstwa fizyczna.","zycie":"Przepisy babci leżą w zeszycie, część w telefonie, a część babcia pamięta tylko w głowie."},"il36_l_udostepnianie":{"kw":["udostępnianie","przechowywanie"],"pulapka":"Udostępnianie (np. e-mail, dostęp do bazy) może się mocno nakładać na przechowywanie, gdy informacja jest w postaci elektronicznej.","zycie":"Mama wysyła plan wakacji na rodzinną grupę, żeby każdy mógł go przeczytać."},"il36_l_uzytkowanie":{"kw":["użytkowanie","udostępnianie","cykl życia"],"pulapka":"Użytkowanie/obsługa to faza zbiorcza: przechowywanie, udostępnianie i wykorzystanie są jej częściami, nie osobnymi fazami głównego cyklu.","zycie":"Rodzinne zdjęcia trzymasz w albumie, pokazujesz gościom i wybierasz z nich te do kalendarza."},"il36_l_wykorzystanie":{"kw":["wykorzystanie","cykl życia"],"pulapka":"Wykorzystanie obejmuje też pozyskiwanie i konwersję informacji; informacje nie mają wartości same w sobie, daje ją dopiero ich użycie.","zycie":"Na podstawie prognozy pogody decydujesz, czy jechać na działkę."},"il36_q_aktualnosc":{"kw":["aktualność","jakość kontekstowa"],"pulapka":"Aktualność jako cel jakości (jakość kontekstowa) to co innego niż atrybut „aktualność informacji” w warstwie semantycznej, który mówi tylko, czy informacja dotyczy przeszłości, teraźniejszości czy przyszłości.","zycie":"Cennik w sklepie osiedlowym jest z tego tygodnia, a nie sprzed podwyżki."},"il36_q_bezp":{"kw":["dostęp i bezpieczeństwo","bezpieczeństwa i dostępności"],"pulapka":"Podręcznik: „jakość bezpieczeństwa/dostępności”, egzamin: „Dostęp i Bezpieczeństwo”; to kategoria celów w wymiarze Cele, nie osobny aktywator ani piąty wymiar.","zycie":"Klucz do domu masz zawsze przy sobie, ale nie dostanie go nikt obcy."},"il36_q_dokladnosc":{"kw":["dokładność","integralność","jakość wewnętrzna"],"pulapka":"Dokładność należy do jakości wewnętrznej; integralność z COBIT 4.1 rozpisano w COBIT 5 na dwa cele: kompletność i dokładność.","zycie":"Paragon ze sklepu osiedlowego ma dokładnie te ceny i ilości, które kupiłeś."},"il36_q_dostepnosc":{"kw":["dostępność","dostęp i bezpieczeństwo"],"pulapka":"Dostępność/terminowość należy do Dostępu i Bezpieczeństwa, nie do jakości kontekstowej: „dostępna, gdy potrzebna” to dostęp, a „wystarczająco świeża” to aktualność.","zycie":"Numer do hydraulika wisi na lodówce, więc przy zalaniu łazienki masz go od razu."},"il36_q_ilosc":{"kw":["odpowiedniej ilości","ilości informacji","jakość kontekstowa"],"pulapka":"Odpowiednia ilość informacji (właściwy wolumen) to jakość kontekstowa; nie myl jej z kompletnością (niczego nie brakuje) ani z poziomem informacji (szczegółowość, warstwa semantyczna).","zycie":"Przepis na ciasto podaje to, co potrzebne, a nie dziesięć stron historii mąki."},"il36_q_interpretacja":{"kw":["interpretacji","jakość kontekstowa"],"pulapka":"Możliwość interpretacji (właściwe języki, symbole, jednostki, jasne definicje) to jakość kontekstowa; nie myl jej z jasnością przekazu, czyli łatwą zrozumiałością.","zycie":"Przepis podaje gramy i stopnie Celsjusza, a nie nieznane miarki z obcego kraju."},"il36_q_istotnosc":{"kw":["istotność","jakość kontekstowa"],"pulapka":"Istotność (informacja daje się zastosować w zadaniu) należy do jakości kontekstowej; na Rysunku 36 przy jakości kontekstowej stoi w nawiasie „istotność, skuteczność”.","zycie":"Na wizytę u mechanika bierzesz książkę serwisową auta, a nie instrukcję pralki."},"il36_q_jasnosc":{"kw":["zrozumiał","jakość kontekstowa"],"pulapka":"Jasność przekazu (informacje łatwo zrozumiałe) to jakość kontekstowa i reprezentacji; słowo „zrozumiały” w pytaniu wskazuje jakość kontekstową, nie wewnętrzną.","zycie":"Babcia rozumie kartkę od wnuka bez dopytywania, bo napisano ją prostymi słowami."},"il36_q_kompletnosc":{"kw":["kompletność","integralność","jakość kontekstowa"],"pulapka":"Kompletność to jakość kontekstowa, nie wewnętrzna; razem z dokładnością przejęła kryterium integralności z COBIT 4.1.","zycie":"Lista gości na wesele ma wszystkich krewnych; nikogo nie pominięto."},"il36_q_kontekstowa":{"kw":["jakość kontekstowa","reprezentacji"],"pulapka":"Jakość kontekstowa zależy od zadania: istotność, kompletność, aktualność, zrozumiałość. Dokładne, ale nieaktualne dane to brak jakości kontekstowej, nie wewnętrznej.","zycie":"Instrukcja montażu szafki przydaje się tylko wtedy, gdy dotyczy twojej szafki i da się ją zrozumieć."},"il36_q_latwosc":{"kw":["łatwość posługiwania","jakość kontekstowa"],"pulapka":"Łatwość posługiwania się (łatwo przekształcić i użyć w różnych zadaniach) to jakość kontekstowa; nie myl jej z dostępnością, która dotyczy uzyskania informacji na czas.","zycie":"Listę zakupów w telefonie łatwo przerobić na listę prezentów albo podzielić między domowników."},"il36_q_obiektywnosc":{"kw":["obiektywność","jakość wewnętrzna"],"pulapka":"Obiektywność (bezstronność, brak uprzedzeń) to jakość wewnętrzna, nie kontekstowa; nie myl jej z wiarygodnością, czyli tym, czy informację uważa się za prawdziwą.","zycie":"Sędzia piłkarski opisuje faul tak samo, niezależnie od tego, której drużynie kibicuje."},"il36_q_ograniczony":{"kw":["ograniczony dostęp","dostęp i bezpieczeństwo"],"pulapka":"Ograniczony dostęp (tylko upoważnione strony) to Dostęp i Bezpieczeństwo; nie myl go z atrybutem „kanał dostępu” z warstwy empirycznej.","zycie":"Kod do sejfu z rodzinnymi dokumentami znają tylko rodzice."},"il36_q_reputacja":{"kw":["reputacja","reputację"],"pulapka":"Reputacja zależy od źródła lub treści, nie od zadania, więc to jakość wewnętrzna, nie kontekstowa; nie myl jej też z warstwą świata społecznego (kontekst).","zycie":"Przepis z książki znanej kucharki uznajesz za dobry, bo cenisz autorkę."},"il36_q_rzeczywista":{"kw":["jakość wewnętrzna","jakość rzeczywista"],"pulapka":"Podręcznik: „jakość rzeczywista”, egzamin: „jakość wewnętrzna”. „Wewnętrzna” znaczy „sama w sobie”, nie „wewnątrz organizacji”; obejmuje dokładność, obiektywność, wiarygodność, reputację.","zycie":"Licznik w samochodzie pokazuje tyle kilometrów, ile auto naprawdę przejechało; nikt go nie cofnął."},"il36_q_spojne":{"kw":["spójne przedstawienie","jakość kontekstowa"],"pulapka":"Spójne przedstawienie to ten sam format (jakość kontekstowa); różny zapis dat bywa też pytaniem o warstwę syntaktyczną, więc sprawdź, czy pytają o cel jakości, czy o warstwę.","zycie":"Wszystkie słoiki w spiżarni mają etykiety w tym samym miejscu i tym samym układzie."},"il36_q_wiarygodnosc":{"kw":["wiarygodność","jakość wewnętrzna"],"pulapka":"Wiarygodność (informacja uważana za prawdziwą i godną zaufania) to jakość wewnętrzna; nie myl jej z reputacją, która wynika z cenionego źródła lub treści.","zycie":"Sąsiadowi, który zawsze mówi prawdę o pogodzie na działce, wierzysz bez sprawdzania."},"il36_q_zwiezle":{"kw":["zwięzł","jakość kontekstowa"],"pulapka":"Zwięzłe przedstawienie to jakość kontekstowa i reprezentacji; nie myl go ze spójnym przedstawieniem, które oznacza ten sam format prezentacji.","zycie":"Kartka dla opiekunki do dziecka mieści najważniejsze godziny i numery na jednej stronie."},"il36_r_konsument":{"kw":["konsument informacji","korzystanie z informacji"],"pulapka":"Konsument informacji z niej korzysta; gdy pytanie mówi „kto używa raportu do decyzji”, odpowiedzią jest konsument, nie opiekun ani wytwórca.","zycie":"Kierowca czyta mapę, żeby dojechać na miejsce; nie rysował jej i nie musi jej przechowywać."},"il36_r_opiekun":{"kw":["opiekun informacji","przechowywanie i utrzymywanie"],"pulapka":"Opiekun przechowuje i utrzymuje informacje. Dział IT może pełnić tę rolę dla danych biznesu, a dla innych informacji być jednocześnie wytwórcą lub konsumentem; role opisują relację do konkretnych informacji.","zycie":"Bibliotekarka dba o przechowywanie i utrzymanie katalogu. Gdy sama dopisuje wpis, działa również jako wytwórca, a gdy szuka książki, jako konsument informacji."},"il36_r_wytworca":{"kw":["wytwórca informacji","tworzenie informacji"],"pulapka":"Wytwórca tworzy informacje; nie myl go z opiekunem (przechowuje i utrzymuje) ani z konsumentem (korzysta). To role ogólne z modelu informacji, nie role z Rysunku 33.","zycie":"Trener spisuje wyniki meczu w zeszycie drużyny: to on tworzy informację, choć potem czytają ją inni."},"il36_w_empiryczny":{"kw":["warstwa empiryczna","empirycznej"],"pulapka":"Warstwa empiryczna to obserwacja znaków i kanał dostępu (interfejs użytkownika), nie „wiedza z doświadczenia”; pytanie „jak uzyskać dostęp?” wskazuje właśnie ją.","zycie":"W hałaśliwej kuchni musisz odróżnić dzwonek minutnika od szumu wody, żeby zauważyć sygnał."},"il36_w_fizyczny":{"kw":["warstwa fizyczna","fizycznej","nośnik"],"pulapka":"Warstwa fizyczna odpowiada na pytanie „gdzie informacje są przechowywane”; „jak uzyskać dostęp” to już warstwa empiryczna.","zycie":"Przepis może być na kartce w szufladzie albo nagrany głosem babci; papier i dźwięk to nośniki."},"il36_w_pragmatyczny":{"kw":["warstwa pragmatyczna","pragmatyczn"],"pulapka":"Warstwa pragmatyczna to sposób wykorzystania: okres przechowywania, status, innowacyjność, zależność; pytanie o wymogi przechowywania wskazuje ją, a nie warstwę fizyczną.","zycie":"Kartka „mleko” na lodówce to dla domowników polecenie: kup po drodze."},"il36_w_semantyczny":{"kw":["warstwa semantyczna","semantyczn"],"pulapka":"Warstwa semantyczna to znaczenie oraz atrybuty: typ, aktualność i poziom; „aktualność” oznacza tu horyzont czasowy, nie cel jakości kontekstowej.","zycie":"Słowo „zamek” na kartce od majstra znaczy zamek w drzwiach, nie zamek królewski; liczy się sens."},"il36_w_spoleczny":{"kw":["społeczn","warstwa świata społecznego"],"pulapka":"Warstwa świata społecznego (umowy, prawo, kultura) to warstwa atrybutów, nie kategoria jakości; „kontekst” tej warstwy to nie jakość kontekstowa.","zycie":"Uścisk dłoni przy kupnie auta od sąsiada znaczy umowę tylko tam, gdzie taki zwyczaj obowiązuje."},"il36_w_syntaktyczny":{"kw":["syntaktyczn","format"],"pulapka":"Warstwa syntaktyczna dotyczy formy (język, format); gdy znaczenie jest to samo, a różni się zapis, to nie jest warstwa semantyczna.","zycie":"Datę urodzin jeden domownik pisze 01.03, a drugi 1 marca; znaczą to samo, różni się tylko zapis."},"il37_c_aplikacje":{"kw":["infrastruktura","aplikacje"],"pulapka":"Na Rysunku 37 aplikacje, infrastruktura, technologia i poziomy usług to przedmiot celów tego aktywatora, wpisany przy jakości kontekstowej, a nie osobne aktywatory.","zycie":"W kuchni restauracji liczy się, jakie są piece, lodówki i wentylacja oraz jak szybko trafiają na salę dania."},"il37_cele":{"kw":["zdolność usługowa","poziomy usług"],"pulapka":"Cele to usługi i poziomy usług najbardziej ekonomiczne dla przedsiębiorstwa oraz wkład we wspieranie procesów biznesowych, a nie technika dla niej samej.","zycie":"Rodzina wybiera taki abonament na prąd i telefon, który wystarcza na codzienne potrzeby i nie przepłaca za zbędne pakiety."},"il37_cykl":{"kw":["architektura referencyjna","architektura przejściowa","architektura docelowa"],"pulapka":"Stan bieżący opisuje architektura referencyjna (bazowa), przyszły docelowa, etapy pośrednie przejściowa; „referencyjna” kusi jako „wzorcowa”, ale oznacza stan obecny.","zycie":"Przy remoncie domu masz zdjęcia obecnego stanu, projekt wymarzonego wnętrza i plan etapów, gdy kuchnia już gotowa, a łazienka jeszcze nie."},"il37_dobre":{"kw":["togaf","itil","sfia"],"pulapka":"Zewnętrzne dobre praktyki tego aktywatora to TOGAF (techniczny model referencyjny) i ITIL (projektowanie i wykonywanie usług); SFIA należy do aktywatora Ludzie, umiejętności i kompetencje.","zycie":"Budując dom, korzystasz z gotowych projektów i norm budowlanych zamiast wymyślać wszystko od zera."},"il37_dp_poziomy_uslug":{"kw":["poziomy usług","apo09"],"pulapka":"Tu poziomy usług są dobrą praktyką aktywatora Usługi, infrastruktura i aplikacje; jako proces uzgadnia je APO09, a dostawców pilnuje APO10.","zycie":"Firma sprzątająca obiecuje sprzątać klatkę dwa razy w tygodniu i usunąć zgłoszony bałagan w ciągu doby."},"il37_dp_pryncypia":{"kw":["pryncypium","zasady architektury"],"pulapka":"Pryncypia architektury to ogólne wytyczne wdrażania i wykorzystania zasobów IT; nie myl ich z pięcioma zasadami COBIT 5 ani z aktywatorem Zasady, polityki i struktury ramowe.","zycie":"Rodzina ustala zasady urządzania mieszkania: najpierw używamy tego, co mamy, kupujemy gotowe meble i nie komplikujemy."},"il37_dp_punkty_widzenia":{"kw":["punkty widzenia","punktów widzenia"],"pulapka":"Definiowanie punktów widzenia architektury to dobra praktyka. Modele, katalogi i macierze dobrane do interesariuszy opisują architekturę bazową, docelową lub przejściową; ich konkretne opracowania są wynikami pracy, więc nie wykluczaj ogólnie słowa „produkt”.","zycie":"Ten sam dom ma różne plany: elektryk dostaje plan gniazdek, hydraulik plan rur, a rodzina rzut pokoi."},"il37_interesariusze":{"kw":["usługi, infrastruktura i aplikacje","zdolność usługowa"],"pulapka":"Interesariuszami są i dostawcy usług (dział IT, operacje, outsourcing), i użytkownicy: wewnętrzni (biznes) oraz zewnętrzni (partnerzy, klienci, dostawcy).","zycie":"Ciepło w bloku dostarcza spółdzielnia albo wynajęta firma, a korzystają z niego lokatorzy, sklep na parterze i goście."},"il37_pa_nabywanie":{"kw":["nabywanie lub samodzielne tworzenie","kupić czy zbudować"],"pulapka":"Domyślnie się kupuje, a własne tworzenie wymaga zatwierdzonego powodu; podchwytliwa wersja odwraca regułę i każe budować, chyba że zakup jest uzasadniony.","zycie":"Szafę kupujesz w sklepie, a stolarza wołasz tylko z dobrego powodu, np. przy nietypowej wnęce."},"il37_pa_otwartosc":{"kw":["otwartość","otwartych standardach"],"pulapka":"Otwartość to oparcie architektury na otwartych standardach branżowych; nie chodzi o jawność informacji ani przejrzystość wobec interesariuszy (EDM05).","zycie":"Kupujesz żarówki ze zwykłym gwintem, więc pasują do każdej lampy i dostaniesz je w każdym sklepie."},"il37_pa_ponowne":{"kw":["ponowne wykorzystanie","pryncypium"],"pulapka":"Ponowne wykorzystanie dotyczy wspólnych komponentów, które organizacja już ma; wybór „kupić czy zbudować” to osobne pryncypium Nabywanie lub samodzielne tworzenie.","zycie":"Do pokoju dziecka bierzesz regał i lampę z piwnicy zamiast kupować nowe."},"il37_pa_prostota":{"kw":["prostota","pryncypium"],"pulapka":"Prostota to architektura możliwie najprostsza, ale nadal spełniająca wymagania przedsiębiorstwa; nie oznacza obcinania funkcji poniżej potrzeb.","zycie":"W kuchni jest tyle szafek i sprzętów, ile naprawdę trzeba do gotowania, bez zbędnych gadżetów."},"il37_pa_zwinnosc":{"kw":["zwinność","pryncypium"],"pulapka":"Zwinność to skuteczna i wydajna odpowiedź architektury na zmieniające się potrzeby biznesu; nie myl z otwartością, która dotyczy standardów branżowych.","zycie":"Meble na kółkach pozwalają w jeden wieczór zamienić salon w pokój dla gości."},"il37_pr_architektura":{"kw":["architektura docelowa","architektura referencyjna","architektura przejściowa"],"pulapka":"Architektura docelowa, przejściowa i referencyjna to produkty działań (wyniki) tego aktywatora; referencyjna oznacza stan bieżący, nie wzorzec.","zycie":"Album z trzema planami ogrodu: jak wygląda dziś, jak ma wyglądać za pięć lat i co zrobimy w tym sezonie."},"il37_pr_repozytorium":{"kw":["repozytorium","produkty działań"],"pulapka":"Repozytorium referencyjne (architektury) to produkt działań, czyli miejsce na pryncypia, normy i modele; nie jest planem etapu przejściowego ani repozytorium konfiguracji z BAI10.","zycie":"Teczka domu z planami, instrukcjami urządzeń i zasadami remontów leży w jednym miejscu dla wszystkich domowników."},"il37_rep_aplikacje":{"kw":["aplikacje","repozytorium"],"pulapka":"Aplikacje zapewniające funkcjonalność biznesową to jeden z trzech elementów usług w repozytorium, obok infrastruktury technicznej i fizycznej, a nie osobny aktywator.","zycie":"W restauracji to karta dań i kasa przyjmująca zamówienia: to, z czego bezpośrednio korzystają kelner i gość."},"il37_rep_infra_fiz":{"kw":["infrastruktura fizyczna","fizyczn","infrastruktura"],"pulapka":"Infrastruktura fizyczna (budynki, pomieszczenia) to trzeci, osobny element usług w repozytorium architektury, obok aplikacji i infrastruktury technicznej.","zycie":"To same ściany, dach i piwnica, w której stoją piec i liczniki."},"il37_rep_infra_techn":{"kw":["infrastruktura techniczna","infrastruktura"],"pulapka":"Infrastruktura techniczna obejmuje sprzęt, oprogramowanie systemowe i sieć; repozytorium wymienia osobno infrastrukturę fizyczną, więc tych dwóch nie łącz.","zycie":"W domu to instalacja elektryczna, kable i skrzynka z bezpiecznikami, bez których nic nie działa."},"il38_c_behawioralne":{"kw":["umiejętności behawioralne","kultura, etyka"],"pulapka":"Umiejętności behawioralne (jakość kontekstowa) łączą ten aktywator z aktywatorem Kultura, etyka i zachowanie; to nie są umiejętności techniczne.","zycie":"Kelnerka spokojnie i uprzejmie uspokaja zdenerwowanego gościa, zamiast się z nim kłócić."},"il38_c_dostepnosc":{"kw":["dostępność","jakość kontekstowa"],"pulapka":"Dostępność personelu to cel w jakości kontekstowej; nie myl jej z kategorią celów „dostęp i bezpieczeństwo”, choć brzmi podobnie.","zycie":"Szkoła ma nauczyciela matematyki, ale gdy on choruje, ktoś musi poprowadzić lekcje."},"il38_c_doswiadczenie":{"kw":["doświadczenie","jakość kontekstowa"],"pulapka":"Doświadczenie jest w jakości kontekstowej; do wewnętrznej należą tylko wykształcenie, kwalifikacje i umiejętności techniczne.","zycie":"Kierowca z dwudziestoletnim stażem lepiej radzi sobie w zamieci niż ktoś świeżo po egzaminie."},"il38_c_rotacja":{"kw":["rotacja","jakość kontekstowa"],"pulapka":"Wskaźnik rotacji to cel aktywatora w jakości kontekstowej; utrata wiedzy po odejściu eksperta to temat BAI08, a braki kadrowe APO07.","zycie":"Gdy z pizzerii co miesiąc odchodzi połowa kucharzy, nikt nie zdąży nauczyć się przepisów."},"il38_c_techniczne":{"kw":["umiejętności techniczne","jakość wewnętrzna"],"pulapka":"Umiejętności techniczne są w jakości wewnętrznej razem z wykształceniem; umiejętności behawioralne należą już do jakości kontekstowej.","zycie":"Kucharz umie ostrzyć noże, filetować rybę i ustawić piec konwekcyjny."},"il38_c_wiedza":{"kw":["wiedza","jakość kontekstowa"],"pulapka":"Wiedza to cel w jakości kontekstowej Rysunku 38; nie myl jej z procesem BAI08 Zarządzanie wiedzą ani z aktywatorem Informacja.","zycie":"Farmaceutka wie, których leków nie wolno łączyć, i ostrzega o tym klienta."},"il38_c_wyksztalcenie":{"kw":["wykształcenie i kwalifikacje","jakość wewnętrzna"],"pulapka":"Na Rysunku 38 wykształcenie i kwalifikacje należą do jakości wewnętrznej (podręcznik: rzeczywistej), a nie do kontekstowej.","zycie":"Elektryk musi mieć szkołę i uprawnienia, zanim podłączy instalację w nowym domu."},"il38_cele":{"kw":["rotacja","dostępność personelu"],"pulapka":"Cele to nie tylko kwalifikacje i umiejętności, ale też dostępność personelu i wskaźnik rotacji; to cele aktywatora, a nie proces APO07.","zycie":"Szpital chce lekarzy z dyplomem, doświadczeniem i podejściem do pacjenta, a do tego pełnej obsady dyżurów i małej liczby odejść."},"il38_cykl":{"kw":["cykl życia","umiejętności"],"pulapka":"Cykl życia umiejętności obejmuje też pozbycie się ich, np. po automatyzacji lub outsourcingu; bazę umiejętności ocenia się okresowo, np. raz w roku.","zycie":"Klub co sezon ocenia skład, szkoli juniorów, kupuje zawodników i oddaje tych, których już nie potrzebuje."},"il38_dobre":{"kw":["sfia","definicje umiejętności"],"pulapka":"Zewnętrzną dobrą praktyką tego aktywatora jest SFIA (definicje umiejętności); TOGAF i ITIL należą do aktywatora Usługi, infrastruktura i aplikacje.","zycie":"Szkoła tańca opisuje, co uczeń musi umieć na poziomie podstawowym, średnim i zaawansowanym w każdym stylu."},"il38_dp_kategorie":{"kw":["kategorie umiejętności","analiza biznesowa"],"pulapka":"Kategorie umiejętności odnoszą się do działań IT, a Rysunek 39 przypisuje je do domen, np. analiza biznesowa do BAI, audyt mechanizmów kontrolnych do MEA.","zycie":"W orkiestrze osobno ocenia się grę na skrzypcach, na trąbce i dyrygowanie."},"il38_dp_poziomy":{"kw":["poziomy umiejętności","umiejętności"],"pulapka":"Poziomy umiejętności opisuje się w poszczególnych kategoriach umiejętności; nie myl ich z poziomami zdolności procesu 0–5 z Rysunku 19.","zycie":"Pasy w karate pokazują, jak daleko zaszedł zawodnik: biały to początek, czarny to mistrzostwo."},"il38_dp_sfia":{"kw":["sfia","definicji umiejętności"],"pulapka":"SFIA (Skills Framework for the Information Age) to zewnętrzne źródło definicji umiejętności; nie jest modelem referencyjnym procesów ani modelem architektury (TOGAF).","zycie":"Jak katalog zawodów, który dokładnie opisuje, co powinien umieć np. elektryk na każdym stopniu wtajemniczenia."},"il38_dp_wymagane":{"kw":["zestawy umiejętności","umiejętności"],"pulapka":"Dobra praktyka to obiektywne zestawy umiejętności dla każdej roli różnych interesariuszy, a nie jeden wspólny zestaw dla całej organizacji.","zycie":"Przed naborem do szpitala ustala się, co musi umieć pielęgniarka, a co rejestratorka."},"il38_interesariusze":{"kw":["ludzie, umiejętności i kompetencje","umiejętności"],"pulapka":"Wśród interesariuszy są też konkurenci, rekruterzy i szkoleniowcy; każda rola wymaga osobnego zestawu umiejętności, nie ma jednego zestawu dla wszystkich.","zycie":"Umiejętności zawodników w klubie obchodzą trenera, łowcę talentów, sponsora, a nawet drużyny rywali."},"il38_pr_definicje":{"kw":["definicje umiejętności","produkt"],"pulapka":"Definicje umiejętności to produkt działań tego aktywatora; same są też informacjami, więc stosuje się do nich dobre praktyki aktywatora Informacja.","zycie":"Kartka na ścianie kuchni opisuje, co znaczy być pomocnikiem, kucharzem i szefem zmiany."},"il39_apo":{"kw":["apo","dostosuj, planuj i organizuj","portfel"],"pulapka":"Egzaminowa nazwa APO to „Dostosuj, Planuj i Organizuj”; jej kategorie to polityka, strategia, architektura, innowacje, finanse i portfele, ale nie pojedyncze projekty (to BAI).","zycie":"Przed remontem rodzina siada przy stole: ustala plan, budżet, styl mieszkania i kolejność prac, zanim ktokolwiek kupi pierwszy worek kleju."},"il39_apo_architektura_korporacyjna":{"kw":["architektura korporacyjna","apo03"],"pulapka":"Architektura korporacyjna to kategoria APO (proces APO03), nie BAI; BAI w Rysunku 39 ma m.in. analizę biznesową i programowanie.","zycie":"Architekt rysuje plan całego domu: gdzie ściany nośne, rury i prąd, żeby kolejne pokoje dało się dobudować bez burzenia."},"il39_apo_innowacje":{"kw":["innowacj","apo04"],"pulapka":"Innowacje należą w Rysunku 39 do APO (proces APO04), nie do BAI; dystraktor wstawia je do zestawu „analiza biznesowa, innowacje, programowanie” jako rzekomo całego BAI.","zycie":"Właścicielka piekarni co miesiąc testuje nowe przepisy i sprawdza, czy nowy piec mógłby skrócić poranny wypiek."},"il39_apo_opracowanie_polityki_it":{"kw":["opracowanie polityki it","rysunek 39"],"pulapka":"To kategoria umiejętności domeny APO (Rysunek 39), nie EDM; same polityki należą do aktywatora Zasady, Polityki i Struktury ramowe, ale umiejętność ich pisania to APO.","zycie":"Rodzice spisują domowe reguły korzystania z telefonów: kiedy wolno, gdzie leży ładowarka i co grozi za granie w nocy."},"il39_apo_strategia_it":{"kw":["strategia it","apo02"],"pulapka":"Strategia IT należy w Rysunku 39 do APO, nie do EDM; Ład zatwierdza kierunek, a układanie strategii (stan obecny, docelowy, luka, mapa drogowa) to APO02.","zycie":"Kierownik drużyny osiedlowej planuje sezon: w której lidze chce grać za dwa lata i jakich zawodników oraz boisk do tego potrzebuje."},"il39_apo_zarzadzanie_finansowe":{"kw":["zarządzanie finansowe","apo06"],"pulapka":"Zarządzanie finansowe to kategoria APO (budżet i koszty to APO06), nie EDM; EDM04 decyduje o zasobach na poziomie Ładu, ale nie prowadzi budżetu.","zycie":"Domowy skarbnik prowadzi budżet: ile idzie na rachunki, ile na naprawę auta i czy wydatki zgadzają się z planem."},"il39_apo_zarzadzanie_portfelami_projektow":{"kw":["portfel","zarządzanie portfelami projektów","apo05"],"pulapka":"Portfele projektów (które projekty w ogóle robimy) to APO, a zarządzanie pojedynczymi projektami (jak dowieźć jeden) to BAI; Rysunek 39 rozdziela te podobne nazwy.","zycie":"Ojciec wybiera, które z pięciu domowych remontów zrobić w tym roku: łazienkę, dach czy ogrodzenie, bo na wszystko nie starczy."},"il39_bai":{"kw":["bai","twórz, nabywaj i wdrażaj","pojemności"],"pulapka":"Egzaminowa nazwa BAI to „Twórz, Nabywaj i Wdrażaj” (podręcznik: Budowanie, nabywanie i wdrażanie); w Rysunku 39 tu jest zarządzanie pojemnością, a dostępnością już w DSS.","zycie":"Ekipa remontowa wchodzi do mieszkania: kupuje materiały, buduje łazienkę i oddaje ją gotową do używania."},"il39_bai_analiza_biznesowa":{"kw":["analiza biznesowa","analizy biznesowej"],"pulapka":"W przykładowym przypisaniu kategorii umiejętności na Rysunku 39 analiza biznesowa jest w BAI. Nie znaczy to, że analizy biznesowej nie można stosować w procesach APO lub innych domen.","zycie":"Przed zakupem lodówki ktoś sprawdza, czego rodzina naprawdę potrzebuje: ilu domowników, ile mrożonek, ile miejsca w kuchni."},"il39_bai_definiowanie_wymagan_i":{"kw":["definiowanie wymagań","bai02"],"pulapka":"Definiowanie wymagań i zarządzanie nimi to kategoria BAI (proces BAI02), nie DSS ani APO; przyporządkowanie „definiowanie wymagań – DSS” to błędny dystraktor.","zycie":"Przed zamówieniem szafy na wymiar rodzina spisuje: ile półek, jaka wysokość, gdzie drążek na ubrania."},"il39_bai_ergonomia_systemu":{"kw":["ergonomia systemu","ergonomi"],"pulapka":"Ergonomia systemu należy do BAI; zestaw „analiza biznesowa, programowanie, ergonomia systemu” to w całości BAI, a dystraktory dorzucają innowacje (APO) albo eksploatację IT (DSS).","zycie":"Projektant kuchni ustawia blat na wysokość gospodyni, a lodówkę blisko zlewu, żeby gotowanie nie męczyło."},"il39_bai_ocena_uzytecznosci":{"kw":["ocena użyteczności","użyteczności"],"pulapka":"Ocena użyteczności należy do BAI; słowa „oceń” w nazwie MEA i „oszacuj” w EDM kuszą, ale Rysunek 39 przypisuje ją do budowania rozwiązań.","zycie":"Zanim sklep wstawi kasy samoobsługowe, prosi kilku klientów o zrobienie zakupów i patrzy, w którym miejscu się gubią."},"il39_bai_programowanie":{"kw":["programowanie","rysunek 39"],"pulapka":"Programowanie to kategoria domeny BAI (budowa rozwiązań), nie DSS; DSS ma eksploatację IT i administrowanie bazami danych, czyli obsługę działających systemów.","zycie":"Stolarz według rysunku przycina deski i składa zamówioną szafę w swoim warsztacie."},"il39_bai_wycofanie_oprogramowania_z":{"kw":["wycofanie oprogramowania","rysunek 39"],"pulapka":"Wycofanie oprogramowania z użycia należy do BAI, nie do DSS, choć brzmi jak koniec eksploatacji; w pytaniu „która nie należy do DSS” to ono jest odpowiedzią.","zycie":"Rodzina oddaje stary samochód na złom: najpierw wyjmuje rzeczy, wypowiada ubezpieczenie i wyrejestrowuje auto."},"il39_bai_zarzadzanie_pojemnoscia":{"kw":["pojemności","zarządzanie pojemnością","bai04"],"pulapka":"Rysunek 39 przypisuje kategorię umiejętności Zarządzanie pojemnością do BAI, a Zarządzanie dostępnością do DSS. To tabela kategorii umiejętności; proces BAI04 w PRM obejmuje zarządzanie zarówno dostępnością, jak i pojemnością.","zycie":"Przed weselem kucharz liczy, czy kuchnia, garnki i lodówki wystarczą na 150 gości, a nie na zwykłe 20."},"il39_bai_zarzadzanie_projektami":{"kw":["zarządzanie projektami","bai01"],"pulapka":"Zarządzanie projektami to BAI (proces BAI01), a portfelami projektów APO; przyporządkowanie „zarządzanie projektami – APO” to typowy błędny dystraktor.","zycie":"Kierownik budowy pilnuje jednego remontu kuchni: terminu, budżetu i kolejności prac fachowców."},"il39_dss":{"kw":["dss","dostarczaj, obsługuj i wspieraj"],"pulapka":"Egzaminowa nazwa DSS to „Dostarczaj, Obsługuj i Wspieraj”; w Rysunku 39 są tu dostępność, problemy, Service Desk, bezpieczeństwo, eksploatacja i bazy danych, ale nie wycofanie oprogramowania (BAI).","zycie":"Pogotowie hydrauliczne spółdzielni codziennie przyjmuje zgłoszenia, usuwa awarie i pilnuje, żeby woda w blokach płynęła bez przerwy."},"il39_dss_administracja_bezpieczenstwa":{"kw":["administracja bezpieczeństwa","dss05"],"pulapka":"Administracja bezpieczeństwa (konta, uprawnienia) to DSS, nie APO ani MEA; MEA ma audyt mechanizmów kontrolnych, czyli sprawdzanie, a nie codzienne nadawanie dostępów.","zycie":"Dozorca bloku wydaje klucze nowym lokatorom i odbiera je od tych, którzy się wyprowadzają."},"il39_dss_administrowanie_bazami_danych":{"kw":["bazami danych","rysunek 39"],"pulapka":"Administrowanie bazami danych to DSS, nie BAI: BAI buduje rozwiązania, a bazami działających systemów administruje się w codziennej obsłudze.","zycie":"Bibliotekarka prowadzi katalog książek: dopisuje nowe pozycje, poprawia błędy i robi kopię kartoteki."},"il39_dss_eksploatacja_it":{"kw":["eksploatacja it","dss01"],"pulapka":"Eksploatacja IT to DSS (codzienna obsługa, proces DSS01), nie BAI; zestaw „programowanie, eksploatacja IT, ocena użyteczności” nie jest więc w całości BAI.","zycie":"Mechanik floty taksówek dba, żeby auta codziennie rano odpalały, były zatankowane i miały aktualny przegląd."},"il39_dss_zarzadzanie_dostepnoscia":{"kw":["dostępności","zarządzanie dostępnością"],"pulapka":"W tabeli kategorii umiejętności (Rysunek 39) dostępność jest przypisana do DSS. W modelu procesów BAI04 obejmuje jednak dostępność i pojemność. Rozróżnij pytanie o kategorię z rysunku od pytania o proces PRM.","zycie":"Właściciel sklepu osiedlowego pilnuje, żeby był otwarty codziennie od szóstej do 22, nawet gdy kasjerka zachoruje."},"il39_dss_zarzadzanie_jednostka_service":{"kw":["service desk","incydent","dss02"],"pulapka":"To kategoria DSS (proces DSS02): incydent to szybkie przywrócenie usługi; szukanie przyczyny to zarządzanie problemami, też w DSS.","zycie":"Recepcja hotelu przyjmuje skargę, że w pokoju nie ma ciepłej wody, i od razu daje gościowi inny pokój."},"il39_dss_zarzadzanie_problemami":{"kw":["zarządzanie problemami","dss03"],"pulapka":"Zarządzanie problemami to DSS (proces DSS03): szukanie przyczyny powtarzających się incydentów; szybkie przywrócenie działania to Service Desk i incydenty (DSS02).","zycie":"Gdy pralka trzeci raz zalewa łazienkę, ktoś szuka przyczyny, np. pękniętego węża, zamiast znowu tylko wycierać podłogę."},"il39_edm":{"kw":["edm","ład nad it","oszacuj, kieruj i monitoruj"],"pulapka":"Na egzaminie EDM to „Oszacuj, Kieruj i Monitoruj” (podręcznik: Ocena, kierowanie i monitorowanie); to jedyna domena Ładu i w Rysunku 39 ma tylko jedną kategorię umiejętności.","zycie":"Rada wspólnoty mieszkaniowej nie sprząta klatki; decyduje, na co idą pieniądze z funduszu remontowego, i sprawdza, czy zarządca dobrze je wydał."},"il39_edm_nadzor_nad_technologiami":{"kw":["ład nad it","nadzór nad technologiami","rysunek 39"],"pulapka":"Na egzaminie to „Ład nad IT w organizacji” (podręcznik: nadzór); to jedyna kategoria EDM, a „monitorowanie sprawności” mimo słowa „monitoruj” należy do MEA.","zycie":"Prezes klubu piłkarskiego nie gra w meczu, ale umie ustalić, czego klub chce, ocenić trenera i rozliczyć wyniki sezonu."},"il39_mea":{"kw":["mea","monitoruj, oszacuj i oceń"],"pulapka":"Egzaminowa nazwa MEA to „Monitoruj, Oszacuj i Oceń” (podręcznik: Monitorowanie, ocena i oszacowanie); to domena Zarządzania, nie Ładu, choć EDM też „monitoruje”.","zycie":"Domowy księgowy co miesiąc przegląda rachunki: czy plan się zgadza, czy nie przekroczono budżetu i czy nikt nie łamie umów."},"il39_mea_audyt_mechanizmow_kontrolnych":{"kw":["audyt mechanizmów","mea02"],"pulapka":"Audyt mechanizmów kontrolnych to MEA (kontrola wewnętrzna, proces MEA02), nie DSS; DSS na co dzień obsługuje zabezpieczenia, a MEA sprawdza, czy działają.","zycie":"Rodzic sprawdza, czy zamek szafki z lekami naprawdę działa i czy dzieci nie znają kodu."},"il39_mea_monitorowanie_sprawnosci":{"kw":["monitorowanie sprawności","mea01"],"pulapka":"Monitorowanie sprawności (wydajności) to MEA, nie EDM; EDM też monitoruje, ale jego jedyna kategoria w Rysunku 39 to Ład nad IT.","zycie":"Trener biega ze stoperem i co tydzień notuje czasy zawodników, żeby widzieć, czy forma rośnie."},"il39_mea_weryfikacja_zgodnosci":{"kw":["weryfikacja zgodności","mea03"],"pulapka":"Weryfikacja zgodności należy w Rysunku 39 do MEA, nie do APO ani EDM; ocena zgodności z wymogami zewnętrznymi to proces MEA03.","zycie":"Inspektor sanepidu sprawdza w restauracji, czy kuchnia spełnia przepisy i własny regulamin lokalu."},"il7_audyt_wew":{"kw":["audyt wewnętrzny","audytorzy zewnętrzni"],"pulapka":"Pułapka nazwy: audyt wewnętrzny jest interesariuszem wewnętrznym, choć kontroluje innych; po stronie zewnętrznej są audytorzy zewnętrzni.","zycie":"Ciocia, która mieszka z rodziną, co miesiąc przegląda domowe rachunki i mówi, gdzie coś się nie zgadza."},"il7_audytorzy_zew":{"kw":["audytorzy zewnętrzni","audyt zewnętrzny","zdarzenie wyzwalające"],"pulapka":"Audytorzy zewnętrzni są zewnętrzni, audyt wewnętrzny wewnętrzny; audyt zewnętrzny lub ocena konsultantów to też przykład zdarzenia wyzwalającego wdrożenie (s. 37).","zycie":"Biegły rewident raz w roku sprawdza księgi spółdzielni mieszkaniowej; nie jest jej pracownikiem, a mieszkańcy ufają jego podpisowi."},"il7_ceo":{"kw":["ceo","dyrektor generalny"],"pulapka":"CEO kieruje Zarządzaniem (kadrą kierowniczą), a nie Ładem; Ład to zarząd z prezesem na czele (s. 31).","zycie":"Kierownik budowy dostaje od inwestora projekt i budżet, a potem prowadzi codzienną pracę ekip, żeby dom powstał zgodnie z planem."},"il7_cfo":{"kw":["cfo","dyrektor finansowy","koszty it"],"pulapka":"CFO to interesariusz wewnętrzny; jego typowe pytanie „Jak kontrolować koszty IT?” jest wejściem Kaskady Celów, a nie wskaźnikiem KPI ani celem aktywatora.","zycie":"Skarbnik klubu piłkarskiego pilnuje składek i rachunków oraz sprawdza, czy nowe stroje zmieszczą się w kasie."},"il7_cio":{"kw":["cio","komitet ds. strategii","strategii it"],"pulapka":"CIO dopasowuje strategię IT do strategii biznesowej (Ilustracja 33), ale komitetowi ds. strategii IT przewodniczy zwykle członek zarządu, nie CIO.","zycie":"Szef floty w firmie przewozowej dba, by auta pasowały do planów firmy: ile tras, jakie pojazdy, kiedy serwis."},"il7_cro":{"kw":["cro","dyrektor ds. ryzyka","ryzyk"],"pulapka":"CRO odpowiada za zarządzanie ryzykiem w całym przedsiębiorstwie (Ilustracja 33); za bezpieczeństwo informacji odpowiada CISO, nie zamieniaj tych ról.","zycie":"W rodzinie jedna osoba pilnuje ubezpieczeń domu, auta i zdrowia oraz ocenia, na jakie ryzyko rodzinę stać."},"il7_dostawcy":{"kw":["dostawca chmury","dostawc"],"pulapka":"Dostawca, np. chmury, to osobna firma, więc interesariusz zewnętrzny; częsty błąd w pytaniach typu „który wpis zakwalifikowano błędnie”.","zycie":"Hurtownia napojów spóźnia się z dostawą i półki w sklepie stoją puste, choć to nie ona prowadzi sklep."},"il7_dyr_prywatnosc":{"kw":["prywatno","ochron","danych osobowych"],"pulapka":"Dyrektorzy ds. prywatności to interesariusze wewnętrzni; nie myl ich z organami nadzorczymi ds. ochrony danych, które na Rysunku 7 są zewnętrzne.","zycie":"Mama z trójki klasowej pilnuje, żeby lista telefonów rodziców nie trafiła do obcych i służyła tylko sprawom szkolnym."},"il7_int_wew":{"kw":["interesariusz wewnętrzn","interesariuszem wewnętrznym","rysunek 7"],"pulapka":"Wewnętrzni to też audyt wewnętrzny i użytkownicy IT; udziałowcy, dostawcy i konsultanci są na Rysunku 7 po stronie zewnętrznej.","zycie":"Rodzina planuje wakacje: mama pilnuje budżetu, tata trasy, dzieci pytają o basen. Każdy domownik ma własne pytania, choć jadą razem."},"il7_int_zew":{"kw":["interesariusz zewnętrzn","interesariuszem zewnętrznym","interesariuszy zewnętrznych"],"pulapka":"Udziałowcy, dostawcy i konsultanci są zewnętrzni, mimo bliskich związków z firmą; własność nie przesądza o grupie na Rysunku 7.","zycie":"Wokół domu są nie tylko domownicy: listonosz, sąsiedzi, bank od kredytu, urząd gminy. Wszyscy czegoś od tego domu oczekują."},"il7_itd_wew":{"kw":["interesariusz","rysunek 7"],"pulapka":"„Itd.” znaczy, że lista interesariuszy wewnętrznych jest przykładowa, a nie zamknięta; nie ucz się jej jako kompletnego katalogu ról COBIT 5.","zycie":"Lista gości weselnych kończy się słowami „i inni”: przyjdą też fotograf i kucharz, choć nikt ich nie wpisał z nazwiska."},"il7_itd_zew":{"kw":["organy regulacyjne","interesariusz"],"pulapka":"Lista zewnętrznych jest przykładowa („itd.”); przy interesariuszach procesu podręcznik wymienia np. klientów, partnerów, udziałowców i organy regulacyjne (s. 69).","zycie":"Na festyn osiedlowy oprócz mieszkańców przychodzą goście, sponsorzy, policja i dziennikarze; tej listy nie da się zamknąć."},"il7_kier_bezp":{"kw":["ciso","bezpieczeństw"],"pulapka":"Kierownik ds. bezpieczeństwa (np. CISO) to rola wewnętrzna; CRO odpowiada szerzej, za ryzyko całego przedsiębiorstwa, a nie tylko za bezpieczeństwo informacji.","zycie":"Dozorca bloku pilnuje zamków, domofonu i kluczy do piwnic, żeby obcy nie wchodzili na klatkę."},"il7_kier_hr":{"kw":["zasobami ludzkimi","wynagradza","zachęty"],"pulapka":"HR jest na Rysunku 7 interesariuszem wewnętrznym. Przy Kulturze, etyce i zachowaniu system wynagradzania wiąże HR z zachętami i nagrodami; nie oznacza to wykluczenia HR z ustalania reguł lub innych praktyk.","zycie":"Trener młodzików szuka nowych zawodników, ustala treningi i nagrody za postępy, żeby za rok drużyna miała kim grać."},"il7_kier_it":{"kw":["kierownik it","zasada 2","całe przedsiębiorstwo"],"pulapka":"Kierownicy ds. IT to tylko jedna z wielu grup; COBIT 5 obejmuje całe przedsiębiorstwo (Zasada 2), więc pytania o IT zadają też CFO, HR czy audyt.","zycie":"Majster ekipy elektryków odpowiada za kable, gniazdka i rozdzielnię, ale o tym, co budować, decyduje inwestor."},"il7_kier_obszaru_biz":{"kw":["kierownicy obszaru biznesowego","interesariusz wewnętrzn","partner"],"pulapka":"Kierownicy obszaru biznesowego to interesariusze wewnętrzni; nie myl ich z partnerami biznesowymi, którzy na Rysunku 7 stoją po stronie zewnętrznej.","zycie":"Kierownik stoiska z warzywami w supermarkecie pyta, czy nowa waga z drukarką etykiet przyspieszy obsługę jego klientów."},"il7_kier_ryzyko":{"kw":["kierownicy ds. ryzyka","ryzyk"],"pulapka":"Na Rysunku 7 są po prostu wewnętrzni; na Rysunku 34 kierownicy ds. ryzyka to przykład tych, którzy definiują i egzekwują pożądane zachowania.","zycie":"Ratownik na basenie wyznacza, gdzie wolno skakać, i pilnuje, by pływający trzymali się tych stref."},"il7_kier_uslugi":{"kw":["apo09","poziom usług","poziomy usług"],"pulapka":"Kierownicy ds. usług są wewnętrzni; umowy o poziomie usług obsługuje APO09, ale samo pytanie o jakość usług to potrzeba interesariusza.","zycie":"Kierownik osiedlowej pralni pilnuje, żeby ubrania wracały czyste i na czas, tak jak obiecano klientowi przy oddaniu."},"il7_klienci":{"kw":["klienci","klient"],"pulapka":"Klienci są interesariuszami zewnętrznymi; „Kultura usług zorientowanych na klienta” to już cel organizacji, a nie grupa interesariuszy.","zycie":"Klientów warzywniaka nie obchodzi zaplecze, ale wybiorą inny sklep, jeśli kasa ciągle się zawiesza."},"il7_konsultanci":{"kw":["konsultan","raci"],"pulapka":"Konsultanci z Rysunku 7 to interesariusze zewnętrzni; nie myl ich z rolą C (konsultowany) w tabeli RACI, która opisuje udział w praktyce procesu.","zycie":"Projektant wnętrz wynajęty na miesiąc doradza przy remoncie, a po skończeniu zlecenia odchodzi."},"il7_naczelne_kier":{"kw":["naczelne kierownictwo","kierownictwa wyższego szczebla","kadra kierownicza"],"pulapka":"Członek naczelnego kierownictwa odpowiada za jednostkę biznesową lub spółkę zależną (Ilustracja 33); to interesariusz wewnętrzny, a nie organ Ładu.","zycie":"W sieci piekarni każdy kierownik regionu odpowiada za swoje sklepy, a razem z prezesem tworzą ścisłe kierownictwo firmy."},"il7_org_normalizacyjne":{"kw":["iso","itil","norm"],"pulapka":"Organizacje normalizacyjne (np. ISO) są zewnętrzne; COBIT 5 dopasowuje się do norm i dobrych praktyk (ISO, ITIL, TOGAF), ale ich nie zastępuje.","zycie":"Instytucja ustalająca kształt gniazdek nie mieszka w twoim domu, ale elektryk musi stosować jej normy."},"il7_organy_nadzorcze":{"kw":["organy nadzor","organ nadzoru","regulator"],"pulapka":"Organy nadzorcze i rządowe są zewnętrzne; na Rysunku 34 wraz z audytorami zewnętrznymi są przykładem zewnętrznych interesariuszy Kultury, etyki i zachowania.","zycie":"Sanepid odwiedza restaurację i sprawdza kuchnię; nie należy do restauracji, a może ją zamknąć."},"il7_partnerzy":{"kw":["partnerzy biznesowi","partner"],"pulapka":"Partnerzy biznesowi są zewnętrzni, a kierownicy obszaru biznesowego wewnętrzni; firma kurierska na umowie to partner, nie udziałowiec.","zycie":"Sklep osiedlowy współpracuje z piekarnią, która co rano dowozi chleb; obie strony zależą od siebie, ale to dwie różne firmy."},"il7_pyt_wew":{"kw":["załącznik d","dane wejściowe","kaskad"],"pulapka":"Załącznik D (Ilustracja 24) mapuje potrzeby interesariuszy wewnętrznych na cele organizacji; Załącznik B to cele organizacji → cele IT, a C – cele IT → procesy.","zycie":"Domownicy zapisują na lodówce pytania: ile wydajemy na prąd, czy auto wytrzyma kolejną zimę. Z tej listy rodzina buduje potem domowe cele."},"il7_pyt_zew":{"kw":["pytania interesariuszy","kaskad","załącznik d"],"pulapka":"Pytań zewnętrznych na Rysunku 7 są tylko cztery i też zasilają Kaskadę Celów; Załącznik D (Ilustracja 24) mapuje jednak potrzeby interesariuszy wewnętrznych.","zycie":"Sąsiedzi pytają wspólnotę, czy dach jest bezpieczny i czy rachunki się zgadzają. Ich pytania też trafiają do planu remontów."},"il7_q_audyt":{"kw":["przewodnik specjalistyczny","audyt","mea02"],"pulapka":"Dla audytora COBIT 5 ma przewodnik specjalistyczny (COBIT 5: Audyt), a nie przewodnik aktywatora; samo pytanie zadaje interesariusz wewnętrzny.","zycie":"Przed sprzedażą mieszkania zamawiasz niezależnego rzeczoznawcę, żeby kupujący uwierzył, że instalacje są w porządku."},"il7_q_budzet":{"kw":["budżet","punkt zapalny"],"pulapka":"Zmiany „z opóźnieniem lub ponad budżet” podręcznik wymienia też jako punkt zapalny (s. 37); nie myl punktu zapalnego ze zdarzeniem wyzwalającym, np. nowym CFO.","zycie":"Budowa altany miała kosztować 10 tysięcy, a kosztowała 15. Działkowicz liczy, o ile średnio przekracza budżet przy każdej budowie."},"il7_q_ciaglosc":{"kw":["dss04","ciągłoś"],"pulapka":"„Ciągłość i dostępność usług biznesowych” to cel organizacji (Ilustracja 5), a nie wyznacznik; ciągłością działania zarządza proces DSS04.","zycie":"Gdy w domu wysiądzie prąd, rodzina wie, gdzie są latarki, co zrobić z lodówką i u kogo przenocować, jeśli awaria potrwa."},"il7_q_decyzje":{"kw":["procedury eskalacji","poziom uprawnień","decyzj"],"pulapka":"Szybkość decyzji wspierają praktyki Struktur organizacyjnych: poziom uprawnień, delegowanie i procedury eskalacji; samo pytanie to wejście kaskady z Rysunku 7.","zycie":"Wspólnota mieszkaniowa od pół roku nie może zdecydować o nowej windzie, bo każda uchwała krąży między zarządem a mieszkańcami."},"il7_q_dostawcy":{"kw":["apo10","dostawc","outsourcing"],"pulapka":"To pytanie zadaje interesariusz wewnętrzny; sami dostawcy (także dostawca chmury) są na Rysunku 7 interesariuszami zewnętrznymi.","zycie":"Rodzina zamawia obiady zawsze z jednej garmażerki i pyta: co, jeśli ją zamkną? I kto sprawdzi, czy dba o higienę?"},"il7_q_kadry":{"kw":["apo07","umiejętności"],"pulapka":"Kadry i umiejętności to APO07 i aktywator Ludzie, umiejętności i kompetencje; „zasoby” w BAI09 to aktywa (sprzęt, licencje), a nie ludzie.","zycie":"Właściciel warsztatu liczy, czy mechaników wystarczy na sezon wymiany opon, kogo wysłać na szkolenie i jak ocenić ich pracę."},"il7_q_koszty":{"kw":["koszty it","apo06","kaskad"],"pulapka":"„Jak kontrolować koszty IT?” to potrzeba interesariusza, czyli wejście kaskady; nie jest celem aktywatora, wskaźnikiem wiodącym ani praktyką zarządzania.","zycie":"Para przegląda wyciąg z konta: abonamenty, prąd, raty. Szuka, gdzie przepłaca i czy taniej byłoby coś wynająć, niż kupić."},"il7_q_nowe_techn":{"kw":["wyznacznik","nowa technologia","nowe technologie"],"pulapka":"Pojawienie się nowej technologii to wyznacznik (krok 1 Kaskady Celów), a pytanie, jak ją wykorzystać, to już potrzeba interesariusza (krok 2).","zycie":"W osiedlowym sklepie można już płacić telefonem; właściciel zastanawia się, czy dzięki temu przyciągnie nowych klientów."},"il7_q_operacje":{"kw":["dss01","operacj","kaskad"],"pulapka":"Pytania z Rysunku 7 to przykłady wejścia do Kaskady Celów, a nie lista obowiązkowych KPI; nie traktuj ich jak mierników procesów DSS.","zycie":"Pizzeria sprawdza, czy dostawcy nie jeżdżą pustymi kursami i czy w piątkowy szczyt da się szybko dorzucić kierowcę."},"il7_q_procesy_biz":{"kw":["zasada 2","procesy biznesowe","od początku do końca"],"pulapka":"COBIT 5 obejmuje całe przedsiębiorstwo od początku do końca (Zasada 2), więc pytanie dotyczy procesów biznesowych, a nie tylko procesów działu IT.","zycie":"Kawiarnia sprawdza, co staje, gdy padnie terminal: płatności kartą tak, parzenie kawy nie. Wie, czego wymagać od serwisu."},"il7_q_projekty":{"kw":["bai01","punkt zapalny","punkty zapalne"],"pulapka":"Podobny problem (nieudane inicjatywy, niepowodzenie projektu) podręcznik wymienia też jako punkt zapalny wdrożenia (s. 36); tu to pytanie interesariusza z Rysunku 7.","zycie":"Remont łazienki miał trwać miesiąc, trwa trzy, a efekt rozczarowuje. Rodzina pyta, co poszło źle i czy przez to przesunąć przeprowadzkę."},"il7_q_reaktywnosc":{"kw":["załącznik d","proaktywn","reaktywn"],"pulapka":"Załącznik D wiąże to pytanie z celami przedsiębiorstwa. Dalej kaskada prowadzi do celów IT i aktywatorów; zestawienie nie zabrania rozważania bezpośrednich związków pytania z konkretnymi procesami.","zycie":"Hydraulik w bloku ciągle łata cieknące rury, zamiast wymienić pion, i nie ma czasu pomóc przy planowanym remoncie."},"il7_q_ryzyko":{"kw":["apo12","edm03","apetyt na ryzyko"],"pulapka":"Optymalizacja ryzyka jest częścią tworzenia wartości (s. 17); apetyt na ryzyko ustalają struktury Ładu (Rysunek 14), a ryzykiem zarządza proces APO12.","zycie":"Przed urlopem sprawdzasz: woda zakręcona, okna zamknięte, sąsiad ma klucze. Chcesz mieć pewność, że o niczym nie zapomniałeś."},"il7_q_sprawnosc":{"kw":["sprawnoś","wydajnoś","mea01"],"pulapka":"To pytanie interesariusza z Rysunku 7, a nie jedno z czterech pytań zarządzania wydajnością aktywatora (s. 29), np. „Czy osiągnięto cele aktywatora?”.","zycie":"Właściciel auta sprawdza spalanie, przeglądy i usterki, żeby wiedzieć, czy samochód jeździ tak dobrze, jak powinien."},"il7_q_struktura_it":{"kw":["struktury organizacyjne","ilustracja 33","struktur"],"pulapka":"Role i struktury z Ilustracji 33 są tylko przykładowe; COBIT 5 nie narzuca uniwersalnej struktury działu IT dla każdego przedsiębiorstwa (s. 76).","zycie":"Klub piłkarski zastanawia się, czy mieć jednego trenera od wszystkiego, czy osobnych od bramkarzy, kondycji i taktyki."},"il7_q_transparent":{"kw":["edm05","przejrzystoś"],"pulapka":"EDM05 zapewnia przejrzystość wobec interesariuszy na poziomie Ładu. Procesy MEA dostarczają pomiaru, oceny i raportowania, które mogą ją wspierać. Odróżnij EDM05 od celu przedsiębiorstwa Przejrzystość finansowa.","zycie":"Skarbnik komitetu rodzicielskiego wywiesza rozliczenie z paragonami: ile zebrano i na co wydano. Każdy rodzic może sprawdzić."},"il7_q_wartosc":{"kw":["tworzenie wartości","edm02","korzyści"],"pulapka":"Wartość w COBIT 5 wymaga równowagi korzyści, ryzyka i zasobów. Sama minimalizacja wydatków nie jest pełną definicją wartości; ograniczenie kosztów może być jednak uzasadnioną korzyścią danej inicjatywy.","zycie":"Rodzina kupiła robot kuchenny i pyta: czy naprawdę gotujemy szybciej i smaczniej, czy sprzęt tylko stoi na blacie?"},"il7_q_wymogi_inf":{"kw":["jakość kontekstowa","załącznik f","kryteri"],"pulapka":"Wymogi wobec informacji opisuje aktywator Informacja (cele jakości: rzeczywista, kontekstowa, dostępność i bezpieczeństwo); Załącznik F tylko porównuje go z kryteriami COBIT 4.1.","zycie":"Lekarz wymaga, by karta pacjenta była aktualna, czytelna i dostępna tylko personelowi; inaczej nie podejmie bezpiecznej decyzji."},"il7_q_zabezp":{"kw":["apo13","dss05","bezpieczeństwo informacji"],"pulapka":"APO13 dotyczy zarządzania bezpieczeństwem, a DSS05 usług bezpieczeństwa. Dostęp i Bezpieczeństwo w modelu informacji to kategoria celów w wymiarze Cele, nie odrębny aktywator ani dodatkowy wymiar.","zycie":"Dokumenty i biżuterię trzymasz w sejfie, a szyfr znają tylko dwie osoby. Chcesz mieć pewność, że nic nie zginie ani nie wycieknie."},"il7_q_zasoby_strat":{"kw":["edm04","infrastruktur","zasob"],"pulapka":"Infrastruktura należy do aktywatora Usługi, infrastruktura i aplikacje, a nie Ludzie; optymalne wykorzystanie zasobów zapewnia Ład w procesie EDM04.","zycie":"Przed przeprowadzką na wieś rodzina sprawdza, czy auto, studnia i internet wystarczą do nowego życia i pracy z domu."},"il7_q_zgodnosc":{"kw":["mea03","zgodnoś","regulac"],"pulapka":"To wersja wewnętrzna; zewnętrzna brzmi „Skąd wiadomo, że przedsiębiorstwo przestrzega przepisów?”. Zgodność zewnętrzną monitoruje MEA03, kontrolę wewnętrzną MEA02.","zycie":"Właściciel food trucka sprawdza, czy ma wszystkie pozwolenia sanepidu i czy kasa drukuje paragony zgodnie z przepisami."},"il7_q_zwinnosc":{"kw":["zwinnoś","cele organizacji","cel organizacji"],"pulapka":"Nie myl pytania z celem organizacji „Zwinność w reagowaniu na zmieniające się otoczenie biznesowe” (Ilustracja 24); pytanie to potrzeba, cel jest poziom niżej.","zycie":"Restauracja z ruchomymi stolikami w godzinę przestawia salę z obiadów na wesele, bo meble i kuchnia na to pozwalają."},"il7_qz_kontrola":{"kw":["mea02","kontroli wewnętrznej","system kontroli"],"pulapka":"Mimo słów „kontrola wewnętrzna” to pytanie interesariusza zewnętrznego; system kontroli wewnętrznej monitoruje MEA02, a zgodność zewnętrzną MEA03.","zycie":"Bank przed udzieleniem kredytu pyta firmę, czy ktoś sprawdza faktury drugi raz i czy kasy nie pilnuje jedna osoba."},"il7_qz_lancuch":{"kw":["łańcuch","partner","informac"],"pulapka":"Dotyczy przepływu informacji między partnerami, a nie wewnątrz firmy; to jedno z zaledwie czterech pytań zewnętrznych na Rysunku 7.","zycie":"Dwie firmy przeprowadzkowe dzielą się listą klientów; każda chce wiedzieć, że druga jej nie zgubi ani nie przekaże dalej."},"il7_qz_partner":{"kw":["wiarygodn","partner","chroni"],"pulapka":"To pytanie zadaje zewnętrzny partner o operacje przedsiębiorstwa; wersja wewnętrzna dotyczy własnych danych: „Czy informacje, które przetwarzam, są dobrze zabezpieczone?”.","zycie":"Sklep zamawia ciasta w cukierni i chce wiedzieć, czy ma ona lodówki z alarmem i zapas mąki, żeby dostawy nie stanęły."},"il7_qz_przepisy":{"kw":["zgodność z przepisami","mea03","przepis"],"pulapka":"To pytanie zewnętrzne (np. regulatora); wewnętrzne brzmi podobnie, ale pyta, czy IT ułatwia zgodność i jak samemu sprawdzić przestrzeganie regulacji.","zycie":"Inspektor budowlany pyta dewelopera, skąd ma pewność, że blok spełnia normy przeciwpożarowe; chce dowodów, nie zapewnień."},"il7_udzialowcy":{"kw":["udziałowc","shareholder"],"pulapka":"Udziałowcy są na Rysunku 7 zewnętrzni, choć są właścicielami; nie myl też udziałowca (shareholder) z interesariuszem (stakeholder).","zycie":"Wspólnicy, którzy włożyli pieniądze w rodzinną pizzerię, ale w niej nie pracują, chcą wiedzieć, czy interes się opłaca."},"il7_uzytk_it":{"kw":["użytkownicy it","użytkownik"],"pulapka":"Rysunek 7 umieszcza grupę Użytkownicy IT wśród interesariuszy wewnętrznych, a Użytkowników zewnętrznych osobno. To przypisanie na tym rysunku; ogólne pojęcie użytkownika IT nie ogranicza się do pracowników.","zycie":"Domownicy korzystający z pralki i telewizora: sami ich nie naprawiają, ale pierwsi zauważą, że coś nie działa."},"il7_uzytk_zew":{"kw":["użytkownicy zewnętrzni","użytkownik"],"pulapka":"Użytkownicy zewnętrzni są na Rysunku 7 odrębną grupą po stronie zewnętrznej. Oni również mogą korzystać z IT; nie ucz się fałszywej zasady, że każdy użytkownik IT musi być pracownikiem.","zycie":"Goście hotelu korzystają z windy i karty do pokoju: nie pracują w hotelu, ale pierwsi się skarżą, gdy coś nie działa."},"il7_wlasc_proc_biz":{"kw":["właściciel procesu biznesowego","właściciele procesów biznesowych","właściciel procesu"],"pulapka":"Właściciel procesu biznesowego odpowiada za sprawność procesu i zatwierdza jego zmiany (Ilustracja 33); jest wewnętrzny i nie musi pracować w dziale IT.","zycie":"Szefowa kuchni w restauracji odpowiada za drogę dania od zamówienia do talerza i zatwierdza każdą zmianę przepisu."},"il7_zarzad":{"kw":["zarząd","organ ładu","edm"],"pulapka":"Za Ład odpowiada zwykle zarząd pod przywództwem prezesa, a za Zarządzanie kadra kierownicza pod CEO (s. 31); nie przypisuj zarządowi planowania i budowania.","zycie":"Rada rodzinna ustala, czy w tym roku remont, czy nowy samochód, i potem rozlicza efekt; sama nie jeździ po materiały do marketu."},"il8_cel_nadzoru":{"kw":["tworzenie wartości","cel ładu"],"pulapka":"Egzamin: Cel Ładu „Tworzenie Wartości”; to równowaga trzech celów, a nie maksymalizacja korzyści ani eliminacja ryzyka.","zycie":"Rodzina chce, by nowe auto dawało wygodę, nie narażało na wypadki i nie zjadało całej pensji naraz."},"il8_czynniki_nadzor":{"kw":["aktywatory ładu","podejścia do ładu"],"pulapka":"Egzamin: „Aktywatory Ładu” (podręcznik: czynniki umożliwiające nadzór); to komponent Podejścia do Ładu z Rysunku 8, nie wymiar aktywatora.","zycie":"Sprawny dom potrzebuje regulaminu, ludzi do pracy i narzędzi; bez nich nawet najlepszy plan remontu staje."},"il8_optym_ryzyka":{"kw":["optymalizacja ryzyka","apetyt na ryzyko"],"pulapka":"Optymalizacja ryzyka nie oznacza jego całkowitej eliminacji. Reakcje mogą obejmować unikanie, ograniczanie, dzielenie lub transfer oraz akceptację odpowiednio ocenionego ryzyka, w ramach ustalonego apetytu.","zycie":"Rowerzysta zakłada kask i jeździ ścieżką, ale nie rezygnuje z jazdy; ryzyko trzyma na rozsądnym poziomie."},"il8_optym_zasobow":{"kw":["optymalizacja zasobów","optymalizacji zasobów"],"pulapka":"Optymalizacja zasobów dotyczy wszystkich zasobów (ludzie, finanse, sprzęt, infrastruktura), nie tylko budżetu; nie myl jej z celem IT 11.","zycie":"Na budowie wszystkie prace korzystają z jednej betoniarki, a ludzi kieruje się tam, gdzie są potrzebni."},"il8_realizacja_korzysci":{"kw":["realizacja korzyści","realizacji korzyści"],"pulapka":"Realizacja korzyści obejmuje też eliminowanie inicjatyw i zasobów bez wystarczającej wartości, a nie tylko tworzenie nowych korzyści.","zycie":"Grządki, które dają warzywa, dalej uprawiasz, a tę, na której nic nie rośnie, likwidujesz."},"il8_role_dzial_rel":{"kw":["role, działania i relacje","delegowanie","rysunek 9"],"pulapka":"Rysunek 9: właściciele i interesariusze delegują; organ Ładu wyznacza kierunek; Zarządzanie instruuje i dopasowuje eksploatację, a eksploatacja raportuje do Zarządzania. Strzałka monitorowania biegnie od Zarządzania do organu Ładu. Sam Ład również obejmuje monitorowanie (FW-PL s. 31–32).","zycie":"Właściciele wybierają organ kierujący wspólnotą. Ten nadaje kierunek administratorowi, a wykonawca raportuje administratorowi o pracach. Administrator monitoruje wykonanie i przekazuje informacje organowi kierującemu."},"il8_zakres_nadzoru":{"kw":["zakres ładu","podejścia do ładu"],"pulapka":"Egzamin: „Zakres Ładu”: przedsiębiorstwo, jednostka lub aktywa, a zakres COBIT 5 obejmuje przedsiębiorstwo; to komponent podejścia, nie kategoria celów.","zycie":"Zarządca może dbać o cały blok, jedną klatkę albo tylko windę; najpierw trzeba ustalić, czego pilnuje."},"il9_eksploatacja":{"kw":["eksploatacja","raportowan","ról operacyjnych"],"pulapka":"Rysunek 9 pokazuje instrukcje od Zarządzania do Eksploatacji i raportowanie w przeciwnym kierunku. Nie jest to zakaz innych uzasadnionych kanałów raportowania w rzeczywistej organizacji.","zycie":"Kucharze w stołówce gotują według jadłospisu od kierowniczki i na koniec dnia mówią jej, ile porcji wydano i czego zabrakło."},"il9_organ_nadzorujacy":{"kw":["organ nadzoruj","organ ładu","prezesa"],"pulapka":"Organ nadzorujący (board), kierowany przez przewodniczącego, wyznacza Zarządzaniu kierunek. W podręczniku PL board/chairman to „zarząd/prezes”. Rysunek 9 pokazuje instrukcje dla Eksploatacji od Zarządzania, a nie bezpośrednią strzałkę od organu Ładu.","zycie":"Rada nadzorcza spółdzielni ustala kierunek: „w tym roku ocieplamy bloki”, a potem sprawdza, czy zarząd spółdzielni to robi."},"il9_role_dzial_rel":{"kw":["rysunku 9","role, działania i relacje"],"pulapka":"Rysunek 9 rozwija dolną część Rysunku 8; role, działania i relacje to jeden z elementów systemu Ładu, obok celu, aktywatorów i zakresu.","zycie":"W klubie sportowym są członkowie, zarząd klubu, trener i zawodnicy; każdy wie, komu przekazuje decyzje, od kogo dostaje polecenia i przed kim się rozlicza."},"il9_s_delegowanie":{"kw":["delegowan","rysunku 9"],"pulapka":"Na Rysunku 9 delegowanie płynie od właścicieli i interesariuszy do organu nadzorującego; w dobrych praktykach struktur „delegowanie uprawnień” to przekazanie decyzji w dół.","zycie":"Właściciele kamienicy oddają decyzje o jej utrzymaniu wybranemu zarządcy, bo sami nie mają na to czasu."},"il9_s_instruowanie":{"kw":["instruowanie","dopasowanie"],"pulapka":"Instruowanie i dopasowanie to relacja Zarządzania wobec eksploatacji i wykonania, a nie organu Ładu wobec Zarządzania (tam jest wyznaczanie kierunku).","zycie":"Kierowniczka zmiany rozdziela sprzedawcom zadania na dzień i przestawia ludzi, gdy przy kasie robi się kolejka."},"il9_s_monitorowanie":{"kw":["monitorowani","rysunku 9","monitoruje"],"pulapka":"Ład monitoruje, na ile kierunek wcielono w życie; ale w pytaniach o role z Rysunku 9 egzamin PL przypisuje odpowiedzialność wykonawczą za monitorowanie kierownictwu. Czytaj, o co pyta treść.","zycie":"Rodzice co miesiąc zaglądają do zeszytu, czy plan nauki do matury jest realizowany, ale nie odrabiają zadań za dziecko."},"il9_s_raportowanie":{"kw":["raportowan","rysunku 9"],"pulapka":"Raportowanie na Rysunku 9 płynie od eksploatacji do Zarządzania; organ Ładu z Zarządzaniem łączy para: wyznaczanie kierunku i monitorowanie.","zycie":"Kurier na koniec dnia melduje dyspozytorowi, ile paczek doręczył, a które wróciły do magazynu."},"il9_s_strona_rozliczana":{"kw":["strona rozliczana","odpowiedzialny decyzyjnie","rozliczan"],"pulapka":"Na Rysunku 9 strona rozliczana to organ nadzorujący wobec właścicieli; w RACI „strona rozliczana” to podręcznikowa nazwa roli A, na egzaminie: odpowiedzialny decyzyjnie.","zycie":"Skarbnik klasy po wycieczce pokazuje rodzicom, na co poszły zebrane pieniądze, i odpowiada za każdą złotówkę."},"il9_s_wyznaczanie_kierunku":{"kw":["wyznaczanie kierunku","kierunek"],"pulapka":"Wyznaczanie kierunku łączy organ nadzorujący z Zarządzaniem; z eksploatacją łączy Zarządzanie inna relacja: instruowanie i dopasowanie.","zycie":"Organ kierujący klubem ustala z trenerem cele sezonu i priorytety. Trener organizuje pracę zespołu oraz raportuje i monitoruje wykonanie wobec przyjętego kierunku."},"il9_wlasciciele":{"kw":["właściciele","delegowan","interesariusze"],"pulapka":"Rysunek 9 przedstawia delegowanie od właścicieli i interesariuszy do organu nadzorującego oraz jego rozliczalność wobec nich. Brak bezpośredniej strzałki z Eksploatacji nie oznacza zakazu otrzymywania raportów ani innych praw interesariuszy.","zycie":"Mieszkańcy bloku wybierają radę wspólnoty, przekazują jej decyzje o funduszu remontowym i co roku rozliczają ją na zebraniu."},"il9_zarzadzanie":{"kw":["kadra zarządzająca","planowanie, budowanie","zarządzanie"],"pulapka":"Zarządzanie planuje, buduje, uruchamia i monitoruje zgodnie z kierunkiem Ładu; zwykle odpowiada za nie kierownictwo wykonawcze pod przywództwem CEO. Odróżniaj role board/chairman i management/CEO niezależnie od lokalnych nazw stanowisk.","zycie":"Kierownik budowy dostaje od inwestora kierunek i budżet, a sam planuje prace, organizuje ekipy i pilnuje postępów."},"kask":{"kw":["kaskad","cele organizacji","cele związane z it"],"pulapka":"Kaskada idzie: wyznaczniki → potrzeby interesariuszy → cele organizacji → cele IT → cele aktywatorów; nie odwrotnie i bez pomijania celów IT.","zycie":"Rodzina chce taniej ogrzewać dom, więc ustala cel „niższe rachunki”, z niego wynika „ocieplić ściany”, a z tego konkretne zadania dla ekipy."},"kont":{"kw":["kontekst","apetyt na ryzyko","styl zarządzania"],"pulapka":"Apetyt na ryzyko, styl zarządzania, etyka i kultura opisują kontekst dopasowania wdrożenia. W konkretnym scenariuszu ich zmiana może też stać się bodźcem do działania; rozróżniaj rolę faktu w pytaniu.","zycie":"Plan remontu zależy od budżetu rodziny, przepisów budowlanych, gustu domowników i tego, jak bardzo boją się ryzyka."},"lad":{"kw":["edm","oszacuj, kieruj","ład"],"pulapka":"W Referencyjnym Modelu Procesu pięć procesów Ładu należy do domeny EDM: Oszacuj, Kieruj i Monitoruj. Ład wykorzystuje jednak wszystkie siedem aktywatorów, nie same procesy. MEA należy do Zarządzania.","zycie":"Rada rodzinna wybiera wakacje: ocenia możliwości, decyduje o morzu i budżecie, a po powrocie sprawdza, czy było warto."},"lv0":{"kw":["niekompletny","poziom 0"],"pulapka":"Poziom 0 to proces niewdrożony lub nieosiągający celu, nawet gdy coś się robi; „całkowity brak rozpoznawalnych procesów” to poziom 0 dojrzałości COBIT 4.1.","zycie":"Kran w łazience cieknie od miesięcy i nikt go nie naprawia albo „naprawa” kończy się dalszym kapaniem."},"lv1":{"kw":["pa 1.1","wykonywany","wykonanie procesu"],"pulapka":"Poziom 1 wymaga PA 1.1 co najmniej W; „wykonywany” nie znaczy „ktoś coś robi”, tylko „proces osiąga cel”. Podręcznik nazywa PA 1.1 „sprawnością procesu”.","zycie":"Gdy kran cieknie, tata w końcu go naprawia, ale bez planu: kiedy znajdzie czas i narzędzia, za każdym razem inaczej."},"lv2":{"kw":["pa 2.1","pa 2.2","zarządzany"],"pulapka":"Poziom 2 wymaga zarządzania wykonaniem i produktami pracy (PA 2.1 i PA 2.2), przy PA 1.1 w pełni osiągniętym. Samo spisanie wspólnej procedury nie dowodzi poziomu 3: potrzebne są PA 3.1 i PA 3.2 oraz pełne osiągnięcie niższych atrybutów.","zycie":"W domu wisi grafik: kto kiedy wynosi śmieci i sprząta; ktoś sprawdza, czy zrobione, a lista zakupów leży zawsze w tym samym miejscu."},"lv3":{"kw":["pa 3.1","pa 3.2","ustanowiony"],"pulapka":"Poziom 3 wymaga zdefiniowania i wdrożenia procesu (PA 3.1 i PA 3.2), z pełnym osiągnięciem niższych atrybutów. Standard można dostosowywać według reguł; nie oznacza to identycznego wykonania każdej czynności.","zycie":"Sieć pizzerii definiuje wspólny standard przygotowania i kontroli ciasta, wdraża go w lokalach oraz dopuszcza uzasadnione dostosowanie do ich warunków. Sam dokument to dopiero część rozwiązania."},"lv4":{"kw":["pa 4.1","pa 4.2","przewidywalny"],"pulapka":"Atrybuty poziomu 4 to Miara procesu (PA 4.1) i Kontrola procesu (PA 4.2); Innowacja to poziom 5, a Zarządzanie wydajnością – poziom 2 (pułapka z Sample Paper).","zycie":"Piekarnia mierzy czas wypieku i wagę bochenka; gdy wyniki wychodzą poza ustalone granice, od razu koryguje piec."},"lv5":{"kw":["pa 5.1","pa 5.2","zoptymalizowany"],"pulapka":"Egzamin PL mówi „proces zoptymalizowany”, podręcznik „optymalizujący”; „Zoptymalizowane” to też poziom 5 dojrzałości COBIT 4.1, więc nie myl modeli.","zycie":"Drużyna analizuje nagrania każdego meczu i stale zmienia treningi, żeby grać lepiej pod cele na przyszły sezon."},"mier1":{"kw":["opóźnion","następując"],"pulapka":"Wskaźniki opóźnione (podręcznik: następujące, mierniki realizacji celów) odpowiadają na pytania o interesariuszy i cele; zamiana pary wiodący–opóźniony to typowy dystraktor.","zycie":"Po sezonie patrzysz w tabelę: ile meczów drużyna wygrała. Wynik widać dopiero po fakcie."},"mier2":{"kw":["wiodąc","wyprzedzając"],"pulapka":"W modelu aktywatora wskaźniki wiodące oceniają zarządzanie cyklem życia i stosowanie dobrych praktyk. Rodzaj wskaźnika zależy od jego relacji z celem, nie od okresu raportowania. Ta sama miara może być wynikiem jednego działania i zapowiedzią innego.","zycie":"W trakcie sezonu trener sprawdza, czy zawodnicy chodzą na treningi i robią rozgrzewkę, zanim padnie wynik."},"obecny":{"kw":["gdzie jesteśmy","stan obecn","faza 2"],"pulapka":"Stan obecny i potencjał procesów ocenia się w fazie 2 („Gdzie jesteśmy teraz?”); punkty zapalne rozpoznaje faza 1, a poziom docelowy (rzadko najwyższy) wybiera faza 3.","zycie":"Przed remontem kuchni sprawdzasz, w jakim jest stanie: co działa, co przecieka, co do wymiany; dopiero potem planujesz nową."},"ocena":{"kw":["wymiar procesu","wymiar zdolności","15504"],"pulapka":"Wymiar procesu pomaga ocenić osiąganie przeznaczenia przez rezultaty, praktyki bazowe i produkty pracy. Wymiar zdolności obejmuje PA 1.1–5.2, a więc również poziom 1, nie tylko 2–5. Reguła poziomu uwzględnia wymagania wszystkich niższych atrybutów.","zycie":"Egzamin na prawo jazdy sprawdza dwie rzeczy: czy dojechałeś do celu i jak jeździsz: czy planujesz trasę, trzymasz się przepisów i poprawiasz błędy."},"papo01":{"kw":["apo01","metodyką zarządzania"],"pulapka":"APO01 organizuje system Zarządzania IT (role, procesy, polityki); ustanowienie systemu Ładu to EDM01, a „metodyka” nie oznacza metodyki projektowej (BAI01).","zycie":"Właściciel restauracji spisuje, kto za co odpowiada w kuchni, jakie obowiązują zasady i kto decyduje o zmianach."},"papo02":{"kw":["apo02","zarządzanie strategią"],"pulapka":"APO02 opracowuje strategię IT po stronie Zarządzania (stan docelowy, luka, mapa drogowa); ocena i zmiana kierunku przez zarząd to Ład, czyli EDM.","zycie":"Rodzina planuje na trzy lata: gdzie jesteśmy, gdzie chcemy mieszkać i jakie kroki zrobimy po kolei."},"papo03":{"kw":["apo03","architektur"],"pulapka":"APO03 opisuje i rozwija architekturę (biznes, informacje, aplikacje, technologia); spis konkretnych elementów i ich wersji to BAI10 Zarządzanie konfiguracją.","zycie":"Mapa osiedla pokazuje, jak domy, drogi, rury i kable łączą się w jedną całość."},"papo04":{"kw":["apo04","innowacj"],"pulapka":"APO04 śledzi nowości i prowadzi pilotaże; wybór i finansowanie konkretnych pomysłów z ograniczonej puli pieniędzy to już APO05 Zarządzanie portfelem.","zycie":"Piekarz próbnie piecze chleb z nowej mąki na jednej blasze, zanim zmieni przepis."},"papo05":{"kw":["apo05","portfel"],"pulapka":"APO05 dobiera i równoważy programy, projekty i usługi; prowadzenie pojedynczego projektu to BAI01, a ustalanie zasad optymalizacji wartości przez Ład to EDM02.","zycie":"Rodzina ma pięć pomysłów: auto, remont, wakacje, kurs i rower, ale pieniędzy starczy na dwa, więc wybiera najkorzystniejsze."},"papo06":{"kw":["apo06","budżet"],"pulapka":"APO06 planuje budżet IT i kontroluje koszty; ewidencja sprzętu i licencji to BAI09, a wybór inwestycji APO05.","zycie":"Domowy budżet: ile miesięcznie idzie na jedzenie, rachunki i naprawy, i czy mieścimy się w planie."},"papo07":{"kw":["apo07","zasobami ludzkimi"],"pulapka":"Słowo „zasoby” kusi: APO07 dotyczy tylko ludzi i ich kompetencji; zasady dla wszystkich zasobów ustala Ład w EDM04.","zycie":"Trener szuka nowych zawodników, szkoli ich i planuje zastępstwa na wypadek kontuzji."},"papo08":{"kw":["apo08","relacj"],"pulapka":"APO08 rozwija relacje i wspólne rozumienie potrzeb między IT a biznesem. APO10 zajmuje się zarządzaniem dostawcami, a APO09 usługami i ich uzgodnionymi poziomami. O rozpoznaniu decyduje cel relacji, nie samo słowo zewnętrzny.","zycie":"Szef kuchni co tydzień siada z kelnerami i pyta, czego potrzebują goście i co trzeba poprawić."},"papo09":{"kw":["apo09","umowami o świadczenie usług","poziom usług"],"pulapka":"APO09 identyfikuje i uzgadnia usługi oraz poziomy usług z odbiorcami, a potem je monitoruje i przegląda. APO10 zarządza relacjami i kontraktami z dostawcami, które mogą wspierać te uzgodnienia. Nie klasyfikuj wyłącznie według wewnętrzny lub zewnętrzny.","zycie":"Pizzeria obiecuje dowóz w 30 minut, a gdy się spóźni, pizza jest gratis."},"papo10":{"kw":["apo10","dostawc"],"pulapka":"APO10 obejmuje wybór, kontrakty i ocenę dostawców. APO09 uzgadnia oraz przegląda poziomy usług odpowiadające potrzebom odbiorców; kontrakty dostawców mogą wspierać te uzgodnienia.","zycie":"Wspólnota wybiera firmę od wywozu śmieci, podpisuje umowę i co kwartał ocenia, czy odbiera je na czas."},"papo11":{"kw":["apo11","jakości"],"pulapka":"APO11 ustala standardy jakości i doskonali procesy; raport mierników dla zarządu to MEA01, a obsługa pojedynczego zgłoszenia DSS02.","zycie":"Sieć cukierni ustala jednakowe standardy smaku i czystości, regularnie pyta klientów o zdanie i poprawia, co trzeba."},"papo12":{"kw":["apo12","zarządzanie ryzykiem"],"pulapka":"APO12 identyfikuje, analizuje i obsługuje ryzyko po stronie Zarządzania; ustalenie apetytu na ryzyko i nadzór nad nim przez zarząd to EDM03.","zycie":"Przed wakacjami rodzina myśli, co może pójść źle, np. kradzież albo zalanie, i kupuje ubezpieczenie oraz prosi sąsiada o doglądanie."},"papo13":{"kw":["apo13"],"pulapka":"APO13 organizuje system zarządzania bezpieczeństwem informacji; codzienną ochronę, np. blokowanie kont, wykonuje DSS05.","zycie":"Właściciel kamienicy ustala zasady bezpieczeństwa: kto dostaje klucze, jak chronić piwnice i kto tego pilnuje."},"pbai01":{"kw":["bai01","programami i projektami"],"pulapka":"BAI01 zarządza programami i projektami, w tym monitorowaniem wyników oraz realizacji korzyści (BAI01.05–.06). APO05 równoważy portfel, a EDM02 zapewnia perspektywę Ładu nad wartością. Nie ograniczaj BAI01 do zakresu, terminu i budżetu.","zycie":"Przeprowadzka rodziny: lista zadań, terminy, budżet i jedna osoba, która pilnuje, żeby wszystko zdążyć na czas."},"pbai02":{"kw":["bai02","wymagań"],"pulapka":"BAI02 spisuje, co rozwiązanie ma robić; jak je zbudować lub kupić to BAI03, a odbiór z użytkownikami to BAI07.","zycie":"Przed kupnem auta rodzina spisuje, czego potrzebuje: siedem miejsc, duży bagażnik i hak na przyczepę."},"pbai03":{"kw":["bai03","budowaniem rozwiązań"],"pulapka":"BAI03 projektuje, buduje lub kupuje rozwiązanie i testuje je w trakcie budowy; testy akceptacyjne z użytkownikami i odbiór to BAI07.","zycie":"Stolarz według listy wymagań projektuje szafę, przycina deski, składa ją i sprawdza, czy drzwi się domykają."},"pbai04":{"kw":["bai04","pojemności"],"pulapka":"BAI04 równoważy bieżące i przyszłe potrzeby dostępności, wydajności i pojemności z kosztami, ocenia możliwości, prognozuje potrzeby i usuwa problemy. DSS01 prowadzi eksploatację, a APO09 uzgadnia poziomy usług; DSS01 nie jest tylko dostawcą danych.","zycie":"Przed sylwestrową imprezą sprawdzasz, czy bezpieczniki wytrzymają piekarnik, czajnik i grzejnik włączone naraz."},"pbai05":{"kw":["bai05","zmian organizacyjnych"],"pulapka":"Opór ludzi i stare nawyki to BAI05; podręcznikowa nazwa BAI06 „Zarządzanie zmianami” kusi, ale dotyczy zatwierdzania zmian w systemach.","zycie":"Nowy podział obowiązków w domu: trzeba przekonać nastolatków, że od dziś sami zmywają, i wytrwać, aż wejdzie im to w nawyk."},"pbai06":{"kw":["bai06","zarządzanie zmianami"],"pulapka":"BAI06 ocenia, zatwierdza i wprowadza zmiany w działających systemach; nie wybiera inwestycji i nie zajmuje się przekonywaniem ludzi (BAI05).","zycie":"Zanim ktoś przesunie ścianę w mieszkaniu, właściciel ogląda plan, ocenia skutki i wyznacza termin prac."},"pbai07":{"kw":["bai07","akceptacji"],"pulapka":"BAI07 to testy akceptacyjne z użytkownikami, odbiór i przejście do eksploatacji; zgoda na termin zmiany to BAI06, a testy w trakcie budowy BAI03.","zycie":"Odbiór mieszkania od dewelopera: obchodzisz pokoje z listą usterek, a dopiero potem podpisujesz protokół i wnosisz meble."},"pbai08":{"kw":["bai08","zarządzanie wiedzą"],"pulapka":"BAI08 wspiera pozyskiwanie, utrzymywanie i dzielenie się wiedzą, także wiedzą ekspertów, której nie zapisano w formalnych źródłach. BAI10 dotyczy elementów konfiguracji i ich relacji; nie ograniczaj całej wiedzy do dokumentacji (Enabling Processes, BAI08.03, s. 160).","zycie":"Doświadczony pracownik pokazuje nowej osobie, jak rozpoznać nietypowy problem. Część wskazówek trafia do wspólnej bazy wiedzy, a część przekazuje podczas pracy."},"pbai09":{"kw":["bai09","aktyw"],"pulapka":"Podręcznikowa nazwa „Zarządzanie zasobami” myli: BAI09 dotyczy aktywów (sprzęt, licencje), a nie ludzi; Ład nad wszystkimi zasobami to EDM04.","zycie":"Spis domowego majątku do ubezpieczenia: telewizor, rower i laptop, każdy z datą zakupu i ceną."},"pbai10":{"kw":["bai10","konfiguracj"],"pulapka":"BAI10 opisuje elementy systemu, ich wersje i zależności (repozytorium konfiguracji); BAI06 korzysta z tego przy ocenie wpływu zmiany, a BAI09 ewidencjonuje aktywa.","zycie":"Schemat instalacji elektrycznej: który bezpiecznik zasila który pokój i co wyłączy się razem z pralką."},"pdss01":{"kw":["dss01","eksploatacj"],"pulapka":"DSS01 to zaplanowana rutyna; przerwa w usłudze trafia do DSS02, a prognozowanie i planowanie pojemności to BAI04.","zycie":"Dozorca codziennie rano otwiera bramę, sprawdza piec i wystawia śmieci według stałego grafiku."},"pdss02":{"kw":["dss02","incydent"],"pulapka":"DSS02 przywraca usługę i obsługuje zwykłe prośby (np. założenie konta); szukanie przyczyny powtarzających się awarii to DSS03, a wprowadzenie poprawki BAI06.","zycie":"Gdy w mieszkaniu cieknie kran, hydraulik przyjeżdża i szybko go uszczelnia, żeby woda przestała lecieć."},"pdss03":{"kw":["dss03","problem"],"pulapka":"DSS03 szuka przyczyny źródłowej powtarzających się incydentów; samo przywrócenie działania to DSS02, a zmianę usuwającą przyczynę wprowadza BAI06.","zycie":"Kran cieknie co miesiąc, więc hydraulik szuka przyczyny i odkrywa za wysokie ciśnienie w rurach."},"pdss04":{"kw":["dss04","ciągłości"],"pulapka":"DSS04 przygotowuje utrzymanie i odtworzenie krytycznych działań po zakłóceniach. Obejmuje ciągłość, odporność, plany, ćwiczenia i kopie zapasowe; nie ogranicza się do katastrofy ani odtworzenia serwera.","zycie":"Rodzina planuje, gdzie przenocuje po poważnym zalaniu mieszkania, jak zabezpieczy ważne dokumenty i kogo powiadomi. Sprawdza, czy plan jest wykonalny."},"pdss05":{"kw":["dss05"],"pulapka":"DSS05 obejmuje operacyjną ochronę informacji i IT: tożsamości i uprawnienia, ochronę przed złośliwym oprogramowaniem, monitorowanie zdarzeń, a także fizyczny dostęp do zasobów i ochronę dokumentów. System zarządzania bezpieczeństwem organizuje APO13.","zycie":"Codziennie zamykasz drzwi na klucz, zmieniasz kod do furtki po wyprowadzce lokatora i sprawdzasz, kto dzwonił domofonem."},"pdss06":{"kw":["dss06"],"pulapka":"DSS06 to kontrole wbudowane w proces biznesowy (np. „dwie pary oczu”); ocena, czy kontrole działają, to MEA02, a techniczne konta to DSS05.","zycie":"W sklepie kasjerka przyjmuje zwrot towaru, ale zatwierdzić go musi kierowniczka."},"petla":{"kw":["pierścień","aktywowanie zmiany","zarządzanie programem"],"pulapka":"Pierścienie: zewnętrzny to zarządzanie programem, środkowy aktywowanie zmiany (kultura, zachowania), wewnętrzny ciągłe doskonalenie; ocena stanu obecnego to faza 2 „Gdzie jesteśmy teraz?”.","zycie":"Rodzinne odchudzanie: po co, ile ważymy, ile chcemy, jak dojdziemy, działamy, sprawdzamy efekt i pilnujemy nawyków, a przy tym motywujemy domowników i trzymamy plan."},"pmea01":{"kw":["mea01"],"pulapka":"MEA01 mierzy wyniki i porównuje je z celami; przejrzystość wobec interesariuszy na poziomie Ładu to EDM05, a ocena mechanizmów kontrolnych to MEA02.","zycie":"Na koniec miesiąca właściciel sklepu porównuje sprzedaż i czas obsługi z planem, a wyniki pokazuje wspólnikom."},"pmea02":{"kw":["mea02","kontroli wewnętrznej"],"pulapka":"MEA02 ocenia, czy mechanizmy kontrolne działają; wbudowanie kontroli w proces biznesowy (np. dwie pary oczu) to DSS06, a rejestr ryzyk to APO12.","zycie":"Raz na kwartał księgowa sprawdza, czy zasada „utarg liczą dwie osoby” naprawdę działa, czy tylko wisi na kartce."},"pmea03":{"kw":["mea03","wymogami zewnętrznymi"],"pulapka":"MEA03 to zgodność z wymogami zewnętrznymi (przepisy, umowy); monitorowanie kierunku przez organ Ładu należy do EDM, więc nie każde monitorowanie to MEA.","zycie":"Właścicielka kawiarni sprawdza, czy spełnia przepisy sanepidu i warunki umowy najmu, zanim przyjdzie kontrola."},"pomiar":{"kw":["faza 6","fazie 6","eksploatacja i pomiar"],"pulapka":"Faza 6 obejmuje realizację korzyści oraz obsługę i pomiar. W fazie 5 definiuje się lub doprecyzowuje miary powodzenia, ale cele i miary korzyści mogą być określone już wcześniej w uzasadnieniu biznesowym. Przegląd skuteczności programu należy do fazy 7.","zycie":"Po wymianie okien porównujesz rachunki za ogrzewanie, żeby sprawdzić, czy wydatek się opłacił."},"potrz":{"kw":["potrzeby interesariuszy","wyznacznik","kaskad"],"pulapka":"Zmiany otoczenia (przepisy, technologie, strategia) to wyznaczniki, które wpływają na potrzeby interesariuszy w kroku 1 kaskady; nie myl wyznacznika z samą potrzebą.","zycie":"Zanim rodzina wybierze nowe auto, pyta każdego: mama chce bezpiecznego, tata taniego w utrzymaniu, dzieci dużego bagażnika."},"prm":{"kw":["37 proces","referencyjn","32 procesy"],"pulapka":"PRM ma 37 procesów: 5 Ładu (EDM) i 32 Zarządzania (APO 13, BAI 10, DSS 6, MEA 3); model nie jest normatywny, więc nie trzeba wdrażać wszystkich.","zycie":"Książka kucharska ma 37 sprawdzonych przepisów; nikt nie gotuje wszystkich, wybiera się te, których rodzina naprawdę potrzebuje."},"przeg":{"kw":["faza 7","fazie 7","ciągłego doskonalenia"],"pulapka":"Faza 7 ocenia skuteczność programu, utrzymuje zmianę i rozpoznaje dalsze wymagania. Może prowadzić do kolejnego cyklu usprawnień; nie oznacza automatycznie zakończenia całego doskonalenia. Realizacja korzyści i obsługa oraz pomiar należą do fazy 6.","zycie":"Po roku z nowym planem treningów klub sprawdza, co się udało i czego brakuje, i ustala kolejne cele, zamiast osiąść na laurach."},"pz":{"kw":["punkt zapalny","punkty zapalne","punktu zapalnego"],"pulapka":"Punkt zapalny to dostrzegany problem uzasadniający usprawnienie, np. nieudane inwestycje, ustalenia audytu lub nieprzejrzyste koszty. Nie musi trwać określonego czasu. Zdarzenie wyzwalające jest bodźcem, np. fuzją lub zmianą kierownictwa.","zycie":"W kuchni od miesięcy cieknie kran i wszyscy się na to złoszczą; ten ciągły kłopot w końcu skłania do remontu."},"r12_a1":{"kw":["zasady, polityki","struktury ramowe","struktury ramowej"],"pulapka":"Egzamin PL mówi „Zasady, Polityki i Struktury ramowe” (podręcznik: metodyki); struktura ramowa to np. COBIT 5, a komitet to Struktura organizacyjna.","zycie":"Rodzinna zasada „przy stole nie używamy telefonów” zamienia oczekiwane zachowanie w jasną wskazówkę na co dzień."},"r12_a2":{"kw":["procesy","uporządkowany zbiór"],"pulapka":"Procesy to uporządkowany zbiór praktyk i działań, który daje określone wyniki; kluczowe jednostki decyzyjne to Struktury organizacyjne, a procesy nie są zasobem.","zycie":"Przepis na ciasto to uporządkowane kroki: odmierz, wymieszaj, upiecz; na końcu jest gotowy wypiek."},"r12_a3":{"kw":["struktury organizacyjne","kluczowe jednostki"],"pulapka":"Zespół, który podejmuje decyzje (np. komitet), to Struktury organizacyjne, a nie Ludzie, umiejętności i kompetencje; nie myl go też ze Strukturą ramową.","zycie":"W klubie zarząd decyduje o budżecie, a komisja sportowa o składzie drużyny; to stałe miejsca, gdzie zapadają decyzje."},"r12_a4":{"kw":["kultura, etyka","niedocenian"],"pulapka":"Kultura, etyka i zachowanie to „często niedoceniany” czynnik sukcesu Ładu i Zarządzania, a nie „przeceniany” ani „jedyny obowiązkowy”.","zycie":"W jednym domu po błędzie dziecka się rozmawia, w innym krzyczy; to, jak naprawdę się zachowujecie, działa mocniej niż spisane zasady."},"r12_a5":{"kw":["informacja","zasob"],"pulapka":"Informacja jest aktywatorem i zarazem zasobem; dotyczy całej organizacji, a na poziomie operacyjnym bywa jej kluczowym produktem.","zycie":"Lista alergii dziecka, numer do lekarza i plan lekcji: bez tych informacji dom by się posypał."},"r12_a6":{"kw":["usługi, infrastruktura","zasob"],"pulapka":"Usługi, infrastruktura i aplikacje to aktywator i zasób, który daje możliwości przetwarzania i usługi IT; awaria techniki dotyczy tego aktywatora, błędne dane – Informacji.","zycie":"Prąd, internet, pralka i aplikacja banku to domowa technika, bez której codziennych spraw nie dałoby się załatwić."},"r12_a7":{"kw":["ludzie, umiejętności","umiejętności behawioralne","zasob"],"pulapka":"Ludzie, umiejętności i kompetencje to zasób (umiejętności, decyzje, działania naprawcze); grupa decyzyjna to już Struktura organizacyjna, a zachowania to Kultura.","zycie":"Do remontu potrzebny jest fachowiec, który umie kłaść płytki i podejmuje dobre decyzje, gdy coś pójdzie nie tak."},"r12_zas":{"kw":["zasobami","zasoby","rysunku 12"],"pulapka":"Zasobami są tylko trzy aktywatory: 5 Informacja, 6 Usługi, infrastruktura i aplikacje, 7 Ludzie, umiejętności i kompetencje; nie wszystkie siedem i nie Procesy.","zycie":"W domu trzeba rozsądnie gospodarować trzema rzeczami: wiedzą, co i gdzie leży, sprzętem i domownikami z ich umiejętnościami."},"r13_c":{"kw":["cele aktywatora","kaskada celów"],"pulapka":"Cele aktywatora to ostatni etap kaskady celów i dzielą się na trzy kategorie: jakość wewnętrzna, kontekstowa oraz dostęp i bezpieczeństwo; kategorie nie są osobnymi wymiarami.","zycie":"Pizza ma być smaczna, podana na czas i dowieziona tylko pod właściwy adres: trzy rodzaje oczekiwań wobec jednej rzeczy."},"r13_c1":{"kw":["jakość wewnętrzna","jakość rzeczywista"],"pulapka":"Egzamin: jakość wewnętrzna, podręcznik: jakość rzeczywista (dokładność, obiektywność, wiarygodność); to ta sama kategoria, tylko inna forma nazwy.","zycie":"Waga w sklepie mięsnym ma pokazywać dokładnie tyle, ile waży kiełbasa, bez względu na to, kto ją kładzie."},"r13_c2":{"kw":["jakość kontekstowa","kompletność"],"pulapka":"Jakość kontekstowa to dopasowanie do celu i sytuacji: istotność, kompletność, aktualność, zrozumiałość; dokładność i obiektywność należą do jakości wewnętrznej.","zycie":"Rozkład jazdy może nie mieć błędów, ale jeśli jest nieaktualny albo nieczytelny dla pasażera, nie spełnia swojej roli."},"r13_c3":{"kw":["dostęp i bezpieczeństwo","ograniczony dostęp"],"pulapka":"Dostęp i bezpieczeństwo to trzecia kategoria celów wewnątrz wymiaru Cele, a nie piąty wymiar aktywatora ani osobny aktywator.","zycie":"Domowa apteczka ma być pod ręką, gdy ktoś się skaleczy, ale zamknięta przed małymi dziećmi."},"r13_i":{"kw":["wymiary aktywatora","interesariusze wewnętrzni"],"pulapka":"Interesariusze to jeden z czterech wymiarów aktywatora, obok celów, cyklu życia i dobrych praktyk; aktywatorów jest siedem, wymiarów cztery.","zycie":"Przy budowie placu zabaw zdanie mają dzieci, rodzice, sąsiedzi i gmina, a każdy oczekuje czegoś innego."},"r13_i1":{"kw":["interesariusze wewnętrzni","interesariusz"],"pulapka":"Interesariusze wewnętrzni (np. zarząd, kierownicy biznesu, dział IT) mają własne, niekiedy wykluczające się potrzeby; ich lista jest na Rysunku 7.","zycie":"W rodzinnej piekarni swoje zdanie mają właściciel, piekarze i sprzedawczynie zza lady."},"r13_i2":{"kw":["interesariusze zewnętrzni","regulator"],"pulapka":"Interesariusze zewnętrzni to m.in. klienci, dostawcy, regulatorzy i audytorzy zewnętrzni; jeden aktywator zwykle ma interesariuszy po obu stronach.","zycie":"Na tę samą piekarnię patrzą też klienci, dostawca mąki, sanepid i właściciel lokalu."},"r13_m1":{"kw":["wskaźniki opóźnione","wskaźniki następujące"],"pulapka":"Egzamin: wskaźniki opóźnione (podręcznik: następujące); mierzą osiągnięcie celów i potrzeb interesariuszy, a nie stosowanie praktyk ani zdolność procesu.","zycie":"Wynik na tablicy mówi, czy drużyna wygrała, ale dopiero po końcowym gwizdku."},"r13_m2":{"kw":["wskaźniki wiodące","wyprzedzające"],"pulapka":"Egzamin: wskaźniki wiodące (podręcznik: wyprzedzające); mierzą cykl życia i dobre praktyki, czyli czy dobrze pracujemy, zanim zobaczymy wynik.","zycie":"Liczba treningów i frekwencja zawodników w tygodniu zapowiadają, jak drużyna zagra w sobotę."},"r13_p":{"kw":["dobre praktyki","produkty działań"],"pulapka":"Dobre praktyki obejmują praktyki oraz produkty działań; COBIT 5 podaje je dla niektórych aktywatorów (np. procesów), dla innych korzysta się z zewnętrznych standardów.","zycie":"Sprawdzony przepis podpowiada, jak upiec ciasto i jakie składniki oraz naczynia muszą stać na stole."},"r13_p1":{"kw":["dobre praktyki","praktyki procesu"],"pulapka":"Praktyki to tylko jedna część dobrych praktyk, drugą są produkty działań; dla procesów przykłady dobrych praktyk daje sam COBIT 5.","zycie":"Doświadczony stolarz wie, jakie kroki zrobić, żeby szafka była prosta i solidna."},"r13_p2":{"kw":["produkty działań","produkty pracy","dane wejściowe"],"pulapka":"Produkty działań to dane wejściowe i wyniki praktyk; w modelu oceny procesu egzamin nazywa je produktami pracy (work products).","zycie":"Do pieczenia chleba wchodzi mąka i drożdże, a wychodzi bochenek i paragon dla klienta."},"r13_qc":{"kw":["wskaźniki opóźnione","na podstawie mierników"],"pulapka":"Pytanie o osiągnięcie celów to wskaźnik opóźniony; na wszystkie cztery pytania odpowiada się na podstawie mierników, nie decyzji organu Ładu.","zycie":"Po malowaniu sprawdzasz, czy ściany są równe, w dobrym kolorze i bez zacieków."},"r13_qi":{"kw":["cztery pytania","wskaźniki opóźnione"],"pulapka":"To pierwsze z czterech pytań; razem z pytaniem o cele mierzy wynik aktywatora wskaźnikami opóźnionymi (podręcznik: następującymi), nie wiodącymi.","zycie":"Po urodzinach pytasz gości i solenizanta, czy impreza była taka, jakiej chcieli."},"r13_qp":{"kw":["wskaźniki wiodące","dobre praktyki"],"pulapka":"Pytanie o dobre praktyki to wskaźnik wiodący; pytania 1–2 dotyczą wyniku (opóźnione), a 3–4 funkcjonowania aktywatora (wiodące).","zycie":"W trakcie gotowania zaglądasz, czy kucharz trzyma się sprawdzonego przepisu i właściwej temperatury."},"r13_qz":{"kw":["wskaźniki wiodące","cyklem życia"],"pulapka":"Pytanie o cykl życia to wskaźnik wiodący (podręcznik: wyprzedzający), bo mierzy funkcjonowanie samego aktywatora, a nie jego wynik.","zycie":"Właściciel auta pilnuje terminów przeglądów i wymiany oleju, a w porę decyduje o sprzedaży."},"r13_z":{"kw":["cykl życia","pozbywanie się"],"pulapka":"Cykl życia ma sześć faz, od planowania po aktualizację/pozbywanie się, i dotyczy każdego aktywatora, także informacji, struktur i polityk.","zycie":"Samochód kupujesz po namyśle, jeździsz nim, serwisujesz, a w końcu sprzedajesz albo oddajesz na złom."},"r13_z1":{"kw":["cykl życia","planowanie"],"pulapka":"Planowanie obejmuje opracowanie i wybór koncepcji; nie myl sześciu faz cyklu życia aktywatora z siedmioma fazami cyklu wdrożenia.","zycie":"Zanim weźmiecie psa, rodzina decyduje, czy go chce, jaką rasę wybrać i kto będzie z nim wychodził."},"r13_z2":{"kw":["projektowanie","cykl życia"],"pulapka":"Projektowanie to druga z sześciu faz cyklu życia aktywatora: po planowaniu, przed budowaniem/nabywaniem/tworzeniem/wdrażaniem.","zycie":"Architekt rysuje plan domu: gdzie będzie kuchnia, ile okien i jak pobiegną rury."},"r13_z3":{"kw":["nabywanie","cykl życia"],"pulapka":"Budowanie/nabywanie/tworzenie/wdrażanie to jedna faza z czterema czasownikami, nie cztery fazy; faz cyklu życia jest sześć.","zycie":"Dom można zbudować samemu albo kupić gotowy, a potem trzeba się wprowadzić i go urządzić."},"r13_z4":{"kw":["eksploatacja","użytkowanie"],"pulapka":"Użytkowanie/eksploatacja to czwarta faza cyklu życia; w tekście podręcznik pisze „użytkowanie/obsługa”, na rysunku „eksploatacja”, a to ta sama faza.","zycie":"Pralka stoi w łazience i co tydzień pierze rodzinie ubrania."},"r13_z5":{"kw":["monitorowanie","cykl życia"],"pulapka":"Ocena/monitorowanie to faza cyklu życia samego aktywatora; nie myl jej z domeną MEA ani z oceną zdolności procesu z Rysunku 19.","zycie":"Co roku przegląd techniczny pokazuje, czy hamulce i światła w aucie wciąż działają jak trzeba."},"r13_z6":{"kw":["pozbywanie się","aktualizacja"],"pulapka":"Ostatnia faza łączy aktualizację i pozbywanie się; np. umiejętności pozbywa się, gdy działanie zautomatyzowano lub zlecono na zewnątrz (Rysunek 38).","zycie":"Stara lodówka po latach idzie do naprawy albo na elektrośmieci, gdy łatanie przestaje się opłacać."},"r18_a1":{"kw":["świadomoś","komunikow","cobit 4.1"],"pulapka":"To atrybut dojrzałości COBIT 4.1, a nie dobre praktyki „świadomość” i „komunikowanie” aktywatora Kultura, etyka i zachowanie (Rysunek 34).","zycie":"Wszyscy w klubie wiedzą, dlaczego zbiórka jest o ósmej, bo kierownik drużyny powtarza to na każdym spotkaniu."},"r18_a2":{"kw":["polityk","procedur","cobit 4.1"],"pulapka":"„Polityki, plany, procedury” to atrybut dojrzałości COBIT 4.1; nie myl go z aktywatorem COBIT 5 „Zasady, polityki i struktury ramowe”.","zycie":"Plan remontu, spisane zasady i instrukcja montażu szafek: bez nich każda ekipa zrobiłaby kuchnię inaczej."},"r18_a3":{"kw":["narzędzi","automatyz","atrybut"],"pulapka":"„Narzędzia i automatyzacja” to atrybut COBIT 4.1; w COBIT 5 nie ma atrybutu o tej nazwie, a dziewięć atrybutów procesu oznacza się od PA 1.1 do PA 5.2.","zycie":"Zmywarka i robot kuchenny sprawiają, że gotowanie idzie szybciej i za każdym razem tak samo, bo część pracy robią maszyny."},"r18_a4":{"kw":["umiejętności","cobit 4.1"],"pulapka":"To atrybut dojrzałości COBIT 4.1, a nie aktywator COBIT 5 „Ludzie, umiejętności i kompetencje”; nazwy się zazębiają, ale to inne modele.","zycie":"Mechanik, który zna każdy model auta na pamięć, i praktykant, który dopiero się uczy: od ich wiedzy zależy jakość naprawy."},"r18_a5":{"kw":["raci","rozliczaln","odpowiedzialn"],"pulapka":"Atrybut 4.1 „odpowiedzialność i rozliczalność” to nie tabela RACI; RACI w COBIT 5 wiąże działania procesu z rolami i strukturami organizacyjnymi.","zycie":"W domu ustalono, kto wynosi śmieci, a kto rozlicza się przed resztą rodziny, gdy kosz się przepełni."},"r18_a6":{"kw":["pa 4.1","pomiar","cobit 4.1"],"pulapka":"Atrybut 4.1 „ustalanie celów i ich pomiar” to nie PA 4.1 „Pomiar procesu” z COBIT 5; nazwy i znaczenie poziomów obu modeli są zupełnie inne (s. 43).","zycie":"Biegacz wyznacza sobie czas na 10 kilometrów i co tydzień sprawdza postęp na zegarku."},"r18_att":{"kw":["sześć atrybut","dziewięć","atrybut"],"pulapka":"COBIT 4.1 miał 6 atrybutów dojrzałości, COBIT 5 ma 9 atrybutów procesu (PA 1.1–5.2); nie są identyczne, tylko częściowo się pokrywają (Ilustracja 21).","zycie":"Jury konkursu kulinarnego ocenia każdą potrawę według tych samych sześciu kryteriów, bez względu na to, czy to zupa, czy deser."},"r18_ck":{"kw":["cele kontrolne","model dojrzałości","cobit 4.1"],"pulapka":"W COBIT 4.1 najpierw sprawdzano realizację celów kontrolnych, potem stosowano model dojrzałości; COBIT 5 upraszcza ocenę, usuwając powielanie tych komponentów (s. 44).","zycie":"Egzaminator na prawo jazdy najpierw sprawdza, czy wykonałeś wszystkie obowiązkowe manewry, a dopiero potem ocenia, jak płynnie jeździsz."},"r18_m0":{"kw":["proces niekompletny","dojrzałości","cobit 4.1"],"pulapka":"Poziom 0 COBIT 4.1 „Nie istnieje” to brak rozpoznania problemu; w COBIT 5 poziom 0 to „proces niekompletny”: proces niewdrożony lub cel nieosiągany.","zycie":"W domu nikt nie płaci rachunków i nikt nawet nie zauważył, że przychodzą upomnienia."},"r18_m1":{"kw":["ad hoc","15504","cobit 4.1"],"pulapka":"Proces z poziomem 1 dojrzałości (Ad hoc) może w ISO/IEC 15504 dostać 0, jeśli nie osiąga wyników (Ilustracja 20); oceny w COBIT 5 są zwykle niższe.","zycie":"Rodzina wie, że rachunki trzeba płacić, ale płaci ten, kto akurat pamięta, i każdy robi to po swojemu."},"r18_m2":{"kw":["powtarzaln","proces zarządzany"],"pulapka":"„Powtarzalny” to nazwa poziomu 2 modelu dojrzałości COBIT 4.1; poziom 2 modelu zdolności COBIT 5 to „proces zarządzany”.","zycie":"Mama i tata płacą rachunki podobnie, bo podpatrzyli się nawzajem, ale nic nie jest spisane; gdy jedno wyjedzie, drugie się gubi."},"r18_m3":{"kw":["proces ustanowiony","pa 3.1","zdefiniowan"],"pulapka":"„Zdefiniowany proces” (COBIT 4.1, poziom 3) kusi skojarzeniem z PA 3.1 „Definicja procesu”; poziom 3 COBIT 5 nazywa się „proces ustanowiony”.","zycie":"Na lodówce wisi spisana instrukcja płacenia rachunków, wszyscy ją znają, ale nikt nie sprawdza, czy jej przestrzegają."},"r18_m4":{"kw":["proces przewidywalny","zarządzany","cobit 4.1"],"pulapka":"„Zarządzany i wymierny” to poziom 4 COBIT 4.1; nie myl go z poziomem 2 COBIT 5 „proces zarządzany”. Poziom 4 COBIT 5 to „proces przewidywalny”.","zycie":"Domowy skarbnik co miesiąc liczy, ile rachunków zapłacono po terminie, i reaguje, gdy jest ich za dużo."},"r18_m5":{"kw":["zoptymalizowan","optymalizując","poziom 5"],"pulapka":"Poziom 5 w obu modelach brzmi podobnie (4.1: zoptymalizowany; COBIT 5: proces optymalizujący), ale definicje i atrybuty są inne; wyników nie da się prosto przeliczyć.","zycie":"Rodzina porównuje swój sposób z sąsiadami, ustawia stałe przelewy i ciągle go ulepsza, żeby szybko reagować na zmiany."},"r18_mdl":{"kw":["model dojrzałości","cobit 4.1","15504"],"pulapka":"W COBIT 4.1 był osobny model dojrzałości dla każdego procesu; COBIT 5 ma jeden wspólny model zdolności oparty na ISO/IEC 15504 z 9 atrybutami.","zycie":"Dawniej każda potrawa w restauracji miała własną, osobną skalę ocen; trudno było porównać zupę z deserem, bo każda miała inne kryteria."},"r18_mk":{"kw":["mechanizm","cobit 4.1","poziom"],"pulapka":"Mechanizmy kontrolne procesów (PC) z COBIT 4.1 częściowo pokrywały się z atrybutami dojrzałości; w COBIT 5 te wspólne wymagania przeniesiono na poziomy 2–5 modelu oceny.","zycie":"Pilot przed każdym startem przechodzi tę samą listę: paliwo, klapy, hamulce. Te punkty sprawdza się przy każdym locie."},"r19_l0":{"kw":["proces niekompletny","poziom 0","15504"],"pulapka":"Poziom 0 nie znaczy „brak procesu”: proces może istnieć i działać chaotycznie, ale nie osiąga celu; proces z poziomem 1 w COBIT 4.1 może tu dostać 0.","zycie":"Pralnia osiedlowa ma szyld i przyjmuje ubrania, ale oddaje je brudne albo wcale: coś się niby dzieje, lecz celu nie osiąga."},"r19_l1":{"kw":["proces wykonywany","pa 1.1","poziom 1"],"pulapka":"Poziom 1 wymaga osiągnięcia PA 1.1 co najmniej w znacznym stopniu (L), nie w pełni; to jedyny poziom z jednym atrybutem i już ważne osiągnięcie.","zycie":"Babcia piecze sernik bez przepisu i bez planu, ale zawsze wychodzi pyszny: cel osiągnięty, choć nikt nie wie, jak to powtórzyć."},"r19_l2":{"kw":["proces zarządzany","pa 2.1","pa 2.2"],"pulapka":"Poziom 2 ma dwa atrybuty: PA 2.1 Zarządzanie wydajnością (planowanie, monitorowanie, dostosowanie) i PA 2.2 Zarządzanie produktami pracy; łatwo pomylić, który opis należy do którego.","zycie":"Trener planuje treningi, sprawdza frekwencję i zmienia plan, gdy zawodnicy nie nadążają, a przy tym prowadzi porządny dziennik meczów."},"r19_l3":{"kw":["proces ustanowiony","pa 3.1","pa 3.2"],"pulapka":"Poziom 3 to standardowy proces zdefiniowany (PA 3.1) i faktycznie wdrożony (PA 3.2); samo spisanie procedury bez jej stosowania nie wystarcza.","zycie":"Sieć piekarni ma jeden spisany przepis na chleb i każda filia rzeczywiście piecze według niego."},"r19_l4":{"kw":["proces przewidywalny","pa 4.1","pa 4.2"],"pulapka":"Poziom 4 to proces przewidywalny: działa w zdefiniowanych limitach dzięki pomiarowi (PA 4.1) i kontroli (PA 4.2); nie myl z poziomem 4 COBIT 4.1 „zarządzany i mierzalny”.","zycie":"Kierowca mierzy spalanie i pilnuje, żeby nie przekraczało 6 litrów na 100 km; gdy rośnie, od razu sprawdza przyczynę."},"r19_l5":{"kw":["proces zoptymalizowany","optymalizujący","pa 5.1"],"pulapka":"Egzamin mówi „proces zoptymalizowany” (podręcznik: optymalizujący); poziom docelowy wybiera się z rachunku kosztów i korzyści i bardzo rzadko jest nim poziom 5.","zycie":"Restauracja co miesiąc czyta opinie gości, testuje nowe dania i zostawia w karcie tylko te, które naprawdę podnoszą obroty."},"r19_pa11":{"kw":["pa 1.1","wykonanie procesu"],"pulapka":"PA 1.1 (egzamin: Wykonanie procesu, podręcznik: Sprawność procesu) ocenia się wskaźnikami wydajności, czyli praktykami bazowymi i produktami pracy, a nie typowymi praktykami.","zycie":"Hydraulik ma naprawić kran: liczy się, czy po jego wizycie przestało kapać, a nie jak ładnie wypełnił zlecenie."},"r19_pa21":{"kw":["pa 2.1","zarządzanie wydajnością"],"pulapka":"PA 2.1 dotyczy zarządzania samym wykonaniem (planowanie, monitorowanie, dostosowanie, przydział obowiązków); dbanie o produkty pracy to PA 2.2.","zycie":"Przed przeprowadzką rodzina układa harmonogram pakowania, dzieli zadania, sprawdza postęp i przesuwa terminy, gdy coś się opóźnia."},"r19_pa22":{"kw":["pa 2.2","produktami pracy"],"pulapka":"PA 2.2 sprawdza, czy produkty pracy są właściwie określone, kontrolowane i utrzymywane; mimo nazwy ocenia się go wskaźnikami potencjału, nie praktykami bazowymi.","zycie":"Kucharz pilnuje, żeby każda karta przepisu i lista zakupów była aktualna, sprawdzona i trzymana w jednym segregatorze."},"r19_pa31":{"kw":["pa 3.1","definicja procesu"],"pulapka":"PA 3.1 to istnienie i utrzymanie standardowego procesu; jego faktyczne stosowanie przez kompetentnych ludzi z potrzebną infrastrukturą to PA 3.2.","zycie":"Związek piłkarski spisuje jeden regulamin rozgrzewki dla wszystkich drużyn i co sezon go poprawia."},"r19_pa32":{"kw":["pa 3.2","wdrożenie procesu"],"pulapka":"PA 3.2 to wdrożenie standardowego procesu w każdym wykonaniu (ludzie, role, zasoby, infrastruktura); samo zdefiniowanie standardu to PA 3.1.","zycie":"W każdej kawiarni sieci barista naprawdę parzy kawę według firmowej instrukcji, jest przeszkolony i ma właściwy ekspres."},"r19_pa41":{"kw":["pa 4.1","miara procesu"],"pulapka":"Egzamin: Miara procesu (podręcznik: Pomiar procesu); PA 4.1 to zbieranie i analiza pomiarów, a utrzymywanie procesu w limitach to PA 4.2 Kontrola procesu.","zycie":"Biegacz zapisuje czas i tętno z każdego treningu, żeby wiedzieć, czy idzie zgodnie z planem."},"r19_pa42":{"kw":["pa 4.2","kontrola procesu"],"pulapka":"PA 4.2 utrzymuje proces w ustalonych limitach na podstawie pomiarów; to nie sam pomiar (PA 4.1) ani wprowadzanie zmian doskonalących (PA 5.2).","zycie":"Gdy termometr w lodówce sklepowej pokaże ponad 5 stopni, właściciel od razu reguluje chłodzenie, żeby wrócić do normy."},"r19_pa51":{"kw":["pa 5.1","innowacja procesu"],"pulapka":"PA 5.1 (egzamin: Innowacja procesu) to wybór zmian na podstawie danych i nowych podejść; ich kontrolowane wprowadzenie i sprawdzenie skutku to PA 5.2.","zycie":"Właściciel warsztatu analizuje, gdzie mechanicy tracą czas, i wybiera nowy sposób ustawiania aut do sprawdzenia."},"r19_pa52":{"kw":["pa 5.2","optymalizacja procesu"],"pulapka":"PA 5.2 to przemyślane wdrażanie wybranych zmian i sprawdzanie ich skutku; nie myl z PA 4.2, które tylko utrzymuje proces w limitach.","zycie":"Ogrodnik stosuje nowy nawóz najpierw na jednej grządce, mierzy plony i dopiero potem wysypuje go w całym ogrodzie."},"r19_wpod":{"kw":["praktyki bazowe","podstawowe praktyki"],"pulapka":"Praktyki bazowe (podręcznik: podstawowe) to praktyki Ładu lub Zarządzania danego procesu; nie myl z typowymi (ogólnymi) praktykami, wspólnymi dla wszystkich procesów.","zycie":"Przy wymianie opon mechanik wykonuje stałe kroki: podnosi auto, odkręca koła, zakłada nowe i dokręca je kluczem."},"r19_wpot":{"kw":["wymiar zdolności","wskaźniki potencjału"],"pulapka":"Wskaźniki potencjału (egzamin: Wymiar Zdolności) są wspólne dla wszystkich procesów i służą ocenie atrybutów PA 2.1–PA 5.2, czyli poziomów 2–5, nie poziomu 1.","zycie":"Inspektor ocenia szkołę jazdy, piekarnię i salon fryzjerski tą samą listą: czy planują, mierzą i poprawiają swoją pracę."},"r19_wprd":{"kw":["produkty pracy","dane wejściowe"],"pulapka":"Produkty pracy (podręcznik: produkty działań) odpowiadają danym wejściowym i wynikom praktyk COBIT 5; razem z praktykami bazowymi należą do Wymiaru Procesu.","zycie":"W remoncie kuchni na wejściu jest projekt i lista zakupów, a na wyjściu protokół odbioru i rachunki."},"r19_wtp":{"kw":["typowe praktyki","praktyki ogólne","ogólne praktyki"],"pulapka":"„Typowe” to tłumaczenie generic, czyli „ogólne”: te same praktyki dla wszystkich procesów, a nie praktyki najczęściej spotykane w danym procesie.","zycie":"Każdy kierownik budowy, niezależnie od tego, co stawia, musi zaplanować prace, rozdzielić zadania i pilnować postępu."},"r19_wtpd":{"kw":["typowe produkty","produkty pracy","wymiar zdolności"],"pulapka":"Typowe produkty działań są wspólne dla wszystkich procesów (Wymiar Zdolności); nie myl ich z produktami pracy konkretnego procesu z Wymiaru Procesu.","zycie":"W każdym przedsięwzięciu, od wesela po przeprowadzkę, powstaje harmonogram, lista zadań i notatka z podsumowania."},"r19_wtz":{"kw":["typowe zasoby","ogólne praktyki, zasoby"],"pulapka":"Typowe zasoby to ogólne zasoby (ludzie, narzędzia, infrastruktura) oceniane na poziomach 2–5 w każdym procesie; nie są wskaźnikiem wydajności poziomu 1.","zycie":"Do każdego remontu, łazienki czy pokoju, potrzebni są fachowcy, narzędzia i miejsce na materiały."},"r19_wwyd":{"kw":["wymiar procesu","wskaźniki wydajności","praktyki bazowe"],"pulapka":"Wskaźniki wydajności (egzamin: Wymiar Procesu) są specyficzne dla danego procesu i służą ocenie poziomu 1; poziomy 2–5 ocenia się wskaźnikami potencjału.","zycie":"Sprawdzając malarza, oglądasz konkretne ściany w tym mieszkaniu: czy są pomalowane, jakie kroki wykonał i co po nim zostało."},"r19_wwyn":{"kw":["wyniki procesu","rezultaty procesu"],"pulapka":"Wyniki procesu (rezultaty) wraz z celem tworzą opis procesu w modelu referencyjnym; są wskaźnikiem wydajności poziomu 1, nie wskaźnikiem potencjału.","zycie":"Po wizycie u fryzjera liczy się efekt: włosy są krótsze i równo przycięte."},"r25_apo":{"kw":["apo","dostosuj, planuj i organizuj"],"pulapka":"APO (egzamin: Dostosuj, Planuj i Organizuj) to Zarządzanie z 13 procesami; na Rysunku 25 obejmują je m.in. TOGAF, PRINCE2/PMBOK i ISO/IEC 31000, nie ISO/IEC 38500.","zycie":"Przed remontem ustalasz plan, budżet, ekipę i zasady współpracy z wykonawcami."},"r25_bai":{"kw":["bai","twórz, nabywaj i wdrażaj"],"pulapka":"BAI (egzamin: Twórz, Nabywaj i Wdrażaj) ma 10 procesów; na Rysunku 25 odpowiadają mu głównie CMMI, PRINCE2/PMBOK i TOGAF, a ITIL jest najszerzej w DSS.","zycie":"Ekipa kupuje materiały, buduje nową łazienkę i podłącza ją, żeby dało się z niej korzystać."},"r25_dss":{"kw":["dss","dostarczaj, obsługuj i wspieraj"],"pulapka":"DSS (egzamin: Dostarczaj, Obsługuj i Wspieraj) ma 6 procesów codziennej pracy; Rysunek 25 przypisuje mu najszerzej ITIL V3 2011 i ISO/IEC 20000.","zycie":"Po remoncie codziennie korzystasz z łazienki, a gdy cieknie kran, wzywasz hydraulika."},"r25_edm":{"kw":["edm","38500","oszacuj, kieruj i monitoruj"],"pulapka":"EDM (egzamin: Oszacuj, Kieruj i Monitoruj) to jedyna domena Ładu; na Rysunku 25 tylko przy niej stoi ISO/IEC 38500, a ISO/IEC 31000 sięga też APO.","zycie":"Rada rodziny decyduje, na co idą pieniądze, wyznacza kierunek i sprawdza, czy wszystko idzie zgodnie z planem."},"r25_mea":{"kw":["mea","monitoruj, oszacuj i oceń"],"pulapka":"MEA (egzamin: Monitoruj, Oszacuj i Oceń) to Zarządzanie, nie Ład, mimo słowa „monitoruj”; EDM też monitoruje, ale z poziomu organu Ładu.","zycie":"Raz w roku sprawdzasz rachunki, przegląd instalacji gazowej i czy wszystko jest zgodne z przepisami."},"r25_s27000":{"kw":["27001","apo13","dss05"],"pulapka":"Seria ISO/IEC 27000 to bezpieczeństwo informacji, na Rysunku 25 od APO do DSS (APO13, DSS05); nie myl z ISO/IEC 31000 o ryzyku.","zycie":"Zasady domowego bezpieczeństwa: zamki, sejf na dokumenty i kto zna kod do alarmu."},"r25_s31000":{"kw":["zarządzanie ryzykiem","apo12"],"pulapka":"ISO/IEC 31000 to norma zarządzania ryzykiem, na Rysunku 25 w obszarze EDM i APO (EDM03, APO12); nie myl z ISO/IEC 27000 o bezpieczeństwie informacji.","zycie":"Poradnik, jak rodzina ma ocenić, co może pójść źle, i jak się przed tym zabezpieczyć."},"r25_s38500":{"kw":["38500","15504"],"pulapka":"ISO/IEC 38500 to podstawa koncepcji procesów Ładu (EDM); podstawą oceny zdolności procesów jest ISO/IEC 15504, nie 38500.","zycie":"Poradnik dobrego gospodarza mówi, jak rada wspólnoty ma nadzorować zarządcę, a nie jak naprawić windę."},"r25_scmmi":{"kw":["bai03","15504"],"pulapka":"CMMI (rozwój) obejmuje głównie budowanie i nabywanie aplikacji w BAI oraz część procesów organizacyjnych i jakości w APO; normą oceny procesów COBIT 5 jest ISO/IEC 15504.","zycie":"Instrukcja dla stolarni, jak krok po kroku doskonalić robienie mebli na zamówienie."},"r25_sitil":{"kw":["itil","dss"],"pulapka":"ITIL V3 2011 i ISO/IEC 20000 na Rysunku 25 zaczynają się w APO, a najszerzej obejmują DSS; ITIL to usługi, nie zarządzanie projektami (PRINCE2/PMBOK).","zycie":"Poradnik dla hotelu, jak codziennie obsługiwać gości, przyjmować skargi i naprawiać usterki w pokojach."},"r25_sprince":{"kw":["prince2","pmbok"],"pulapka":"Załącznik E wiąże PRINCE2/PMBOK z obszarem APO i BAI. Te wytyczne dotyczą zarządzania projektami; samo takie mapowanie nie czyni z nich pełnej metody zarządzania portfelem lub programami. COBIT 5 korzysta z powiązanych wytycznych i ich nie zastępuje.","zycie":"Plan wesela z etapami, budżetem i osobą odpowiedzialną za każde zadanie."},"r25_stogaf":{"kw":["togaf","apo03"],"pulapka":"TOGAF 9 dotyczy architektury korporacyjnej (APO03) i daje techniczny model referencyjny; projektowanie i wykonywanie usług opisuje ITIL, a nie TOGAF.","zycie":"Książka z gotowymi projektami domów i zasadami ich rysowania, zanim zawołasz ekipę."},"sC":{"kw":["częściowy","partially"],"pulapka":"Na egzaminie PL C = Częściowy (>15–50%); w podręczniku i po angielsku to P (Partially), a P na egzaminie PL oznacza Pełny.","zycie":"Rozgrzewkę według planu robi mniej więcej co trzeci zawodnik; reszta od razu zaczyna grać."},"sN":{"kw":["nieosiągnięty","0–15%"],"pulapka":"N to 0–15%: dokładnie 15% to jeszcze N, a nie C. Ocena N dotyczy atrybutu, a nie tego, czy proces w ogóle istnieje.","zycie":"Na treningu nikt nie robi rozgrzewki według planu; jeden zawodnik czasem trochę się porozciąga i tyle."},"sP":{"kw":["pełny","fully","w pełni"],"pulapka":"P w PL to Pełny, EN F: ponad 85% do 100%, z dowodami kompletnego i systematycznego osiągania oraz bez istotnych słabości. Nie wymaga zawsze 100%. Przykład rozgrzewki ilustruje jeden aspekt; ocena atrybutu wymaga odpowiednich dowodów. Do wyższego poziomu wszystkie niższe atrybuty muszą mieć P.","zycie":"Cała drużyna przed każdym meczem i treningiem robi rozgrzewkę według planu, bez wyjątków."},"sW":{"kw":["większościowy","largely"],"pulapka":"W (>50–85%, EN: L – Largely) wystarcza dla atrybutów bieżącego poziomu, ale atrybuty wszystkich niższych poziomów muszą mieć P.","zycie":"Prawie cała drużyna robi rozgrzewkę według planu, tylko dwóch spóźnialskich zwykle ją pomija."},"wart":{"kw":["tworzenie wartości","realizacja korzyści","optymalizacja ryzyka"],"pulapka":"Tworzenie wartości równoważy realizację korzyści, optymalizację ryzyka i optymalizację zasobów. Sama redukcja kosztów lub minimalizacja ryzyka nie jest pełną definicją tworzenia wartości, choć konkretna decyzja może obejmować takie działania.","zycie":"Kupując pralkę, rodzina chce, żeby dobrze prała (korzyść), nie zalała łazienki (ryzyko) i nie zjadła całej pensji (zasoby)."},"ws1":{"kw":["wskaźniki wykonania","praktyki bazowe","wymiar procesu"],"pulapka":"Wymiar procesu wykorzystuje rezultaty procesu, praktyki bazowe i produkty pracy jako wskaźniki osiągania jego przeznaczenia. Wspierają ocenę PA 1.1; nie są po prostu trzema osobnymi poziomami zdolności.","zycie":"Czy obiad jest na stole? Sprawdzasz, czy zrobiono kroki z przepisu i czy powstało danie; nie pytasz jeszcze, czy kuchnia jest dobrze zorganizowana."},"ws2":{"kw":["wymiar zdolności","wskaźniki zdolności","wskaźniki potencjału"],"pulapka":"Typowe praktyki, zasoby i produkty pracy pomagają oceniać ogólne atrybuty poziomów 2–5 na Rysunku 19. Cały wymiar zdolności obejmuje także PA 1.1, oceniany z wykorzystaniem wskaźników wykonania procesu.","zycie":"Oceniasz sposób prowadzenia pracy: planowanie zadań, kontrolowanie zapisów, wdrożenie uzgodnionego standardu oraz pomiar i kontrolę. Poszukujesz odpowiednich dowodów dla ocenianych atrybutów."},"wym0":{"kw":["wymiar","wydajnością aktywatora","rysunek 13"],"pulapka":"Wymiary są cztery: interesariusze, cele, cykl życia, dobre praktyki; zarządzanie wydajnością (podręcznik: sprawnością) aktywatora to pomiar, a nie piąty wymiar.","zycie":"Każdą rzecz w domu, od pralki po grafik sprzątania, ocenisz tymi samymi pytaniami: dla kogo, po co, na jakim etapie życia i czy robimy to dobrze."},"wym1":{"kw":["interesariusze wewnętrzni","potrzeby interesariuszy","uwzględniono potrzeby"],"pulapka":"Interesariusze aktywatora są wewnętrzni i zewnętrzni; pytanie „Czy uwzględniono potrzeby interesariuszy?” mierzą wskaźniki opóźnione, a nie wiodące.","zycie":"Nowa kuchnia ma zadowolić tego, kto gotuje, domowników, którzy jedzą, i sąsiada, któremu nie może przeszkadzać hałas okapu."},"wym2":{"kw":["jakość wewnętrzna","jakość kontekstowa","dostęp i bezpieczeństwo"],"pulapka":"Na egzaminie „jakość wewnętrzna” (podręcznik: rzeczywista); „dostęp i bezpieczeństwo” to kategoria celów w wymiarze Cele, a nie piąty wymiar aktywatora.","zycie":"Dobra zupa: składniki są świeże, smak pasuje do gości, a przepis leży pod ręką kucharza, ale schowany przed konkurencją."},"wym3":{"kw":["cykl życia","zarządzanie cyklem życia"],"pulapka":"Cykl życia aktywatora obejmuje planowanie, projektowanie, tworzenie lub nabycie, użytkowanie, ocenę i aktualizację lub wycofanie. Proces jest aktywatorem i ma taki cykl życia. Odróżnij go od siedmiu faz wdrożenia COBIT oraz od pojedynczego wykonania procesu.","zycie":"Samochód rodziny: wybór modelu, zakup, codzienna jazda, przeglądy, a na końcu sprzedaż i kupno następnego."},"wym4":{"kw":["dobre praktyki","stosowane są dobre praktyki","produkty pracy"],"pulapka":"Dobre praktyki to praktyki i produkty pracy (dane wejściowe i wyniki), czyli sugestie, jak wdrożyć aktywator; nie myl ich z celami, które opisują oczekiwane rezultaty.","zycie":"Babcina książka kucharska: sprawdzone sposoby przyrządzania oraz spis, co wkładamy do garnka i co z niego wychodzi."},"wynik":{"kw":["analiza luk","luk","szybkie korzyści"],"pulapka":"Lukę między stanem docelowym i obecnym analizuje faza 3. W fazie 4 rozwija się projekty i ich uzasadnienia biznesowe; wstępne uzasadnienie powstaje już wcześniej i jest aktualizowane przez cały cykl.","zycie":"Celem jest regularne przygotowywanie dziesięciu zamówień na godzinę, a dziś zespół przygotowuje cztery. Analiza luki ustala brakujące możliwości i przyczyny; dopiero potem dobiera się działania usprawniające."},"z1":{"kw":["realizacja potrzeb interesariusza","tworzenie wartości","optymalizacja ryzyka"],"pulapka":"Tworzenie wartości to korzyści przy optymalnym ryzyku i optymalnym wykorzystaniu zasobów; podchwytliwe są „maksymalne korzyści” albo „minimalne ryzyko”.","zycie":"Rodzina remontuje dom tak, żeby każdy dostał to, czego potrzebuje, w rozsądnej cenie i bez ryzykownych pomysłów."},"z23":{"kw":["pokrycie całej organizacji","pojedyncza zintegrowana"],"pulapka":"Zasada 2: Ład IT jest częścią ładu korporacyjnego i obejmuje całą organizację; prosta architektura porządkująca wytyczne i spinanie innych standardów to już zasada 3.","zycie":"Zasady domu obowiązują w całym mieszkaniu, nie tylko w kuchni, a jeden plan remontu łączy porady hydraulika, elektryka i malarza."},"z4":{"kw":["holistycznego podejścia","aktywator"],"pulapka":"Zasada 4 mówi o siedmiu aktywatorach działających razem; „Zasady, polityki i struktury ramowe” to aktywator, a nie zasada, mimo słowa „zasady”.","zycie":"Dobra drużyna to nie tylko zawodnicy: potrzebni są też trener, taktyka, boisko, sprzęt i duch zespołu."},"z5":{"kw":["oddzielenie ładu od zarządzania","zasada 5"],"pulapka":"Ład i Nadzór są odpowiednikami tłumaczenia Governance. W Referencyjnym Modelu Procesu EDM obejmuje procesy Ładu, a APO, BAI, DSS i MEA procesy Zarządzania. Prawidłowy synonim nie staje się błędem tylko przez inną wersję tłumaczenia.","zycie":"Właściciel restauracji ustala kierunek i sprawdza wyniki, a szef kuchni planuje i prowadzi codzienną pracę."},"zarz":{"kw":["pbrm","zarządzani","planuj"],"pulapka":"Zarządzanie planuje, tworzy, realizuje i monitoruje działania zgodnie z kierunkiem Ładu. W modelu procesów obejmuje 32 procesy APO, BAI, DSS i MEA. Ład i Zarządzanie wykorzystują również pozostałe aktywatory, nie same procesy.","zycie":"Ekipa remontowa sama planuje kolejność prac, buduje, oddaje łazienkę do użytku i sprawdza, czy wszystko działa."},"zi":{"kw":["zdarzenie wyzwalające","zdarzenia wyzwalające"],"pulapka":"Podręcznik: „zdarzenia inicjujące”, egzamin: „zdarzenia wyzwalające”; to zmiany (fuzja, nowe przepisy, nowy CEO), a stałe warunki, jak apetyt na ryzyko, to czynniki środowiska.","zycie":"Do domu wprowadza się teściowa i rodzina nagle musi przemeblować mieszkanie, choć wcześniej wszystko działało."},"f1":{"kw":["faza 1"],"zycie":"Ustalasz potrzebę działania i rozpoczynasz program.","pulapka":"To faza 1, nie ocena stanu obecnego."},"f2":{"kw":["faza 2"],"zycie":"Rozpoznajesz stan obecny i zakres inicjatywy.","pulapka":"Stan docelowy określisz dopiero w fazie 3."},"f3":{"kw":["faza 3"],"zycie":"Ustalasz stan docelowy, luki i mapę działań.","pulapka":"Stan docelowy to pierścień doskonalenia; komunikacja wyniku to pierścień zmiany."},"f4":{"kw":["faza 4"],"zycie":"Planujesz program, wskazujesz role i budujesz usprawnienia.","pulapka":"Budowanie usprawnień w fazie 4 odróżnij od ich wdrażania w fazie 5."},"f5":{"kw":["faza 5"],"zycie":"Realizujesz plan i wdrażasz usprawnienia z udziałem ludzi.","pulapka":"Nie myl fazy 5 z pomiarem i obsługą z fazy 6."},"f6":{"kw":["faza 6"],"zycie":"Sprawdzasz korzyści, utrwalasz podejście, obsługujesz i mierzysz.","pulapka":"Obsługa i pomiar to faza 6, a nie 4."},"f7":{"kw":["faza 7"],"zycie":"Przeglądasz skuteczność programu i podtrzymujesz doskonalenie.","pulapka":"Monitorowanie i ocena w wewnętrznym pierścieniu to faza 7."}};
